@SubscribeEvent
    public void submitCustomGeometry(SubmitCustomGeometryEvent event) {
        var levelRenderState = event.getLevelRenderState();
        var visibleAreas = levelRenderState.getRenderDataOrDefault(OVERLAY_AREAS, List.of());

        if (visibleAreas.isEmpty()) {
            return;
        }

        var collector = event.getSubmitNodeCollector();
        PoseStack poseStack = event.getPoseStack();

        poseStack.pushPose();

        Vec3 projectedView = levelRenderState.cameraRenderState.pos;
        poseStack.translate(-projectedView.x, -projectedView.y, -projectedView.z);

        var viewMatrix = new Matrix4f(levelRenderState.cameraRenderState.viewRotationMatrix);
        for (var visibleArea : visibleAreas) {
            submit(visibleArea, poseStack, viewMatrix, collector);
        }

        poseStack.popPose();
    }

private void render(int minY, int maxY, Collection<ChunkPos> allChunks, PoseStack.Pose pose,
            Matrix4fc viewMatrix, VertexConsumer builder, boolean renderLines, int color) {
        for (ChunkPos pos : allChunks) {
            Matrix4f posMat = new Matrix4f(pose.pose()).translate(pos.getMinBlockX(), 0, pos.getMinBlockZ());
            // Clipping lines against the camera plane requires knowing their position in view-space
            Matrix4f viewSpaceMat = renderLines ? new Matrix4f(viewMatrix).mul(posMat) : null;
            var edges = new EdgeWriter(builder, posMat, viewSpaceMat, color);
            addVertices(minY, maxY, allChunks, edges, pos, renderLines);
        }
    }

private boolean renderEmptyingTooltip(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY) {
        // See if we should offer the left-/right-click differentiation for setting a different filter
        var emptyingAction = getEmptyingAction(this.hoveredSlot, menu.getCarried());
        if (emptyingAction != null) {
            drawTooltip(
                    guiGraphics,
                    mouseX,
                    mouseY,
                    Tooltips.getEmptyingTooltip(ButtonToolTips.SetAction, menu.getCarried(), emptyingAction));
            return true;
        }

        return false;
    }

private void drawText(GuiGraphicsExtractor guiGraphics, Text text, @Nullable TextOverride override) {
        // Don't draw if the screen decided to hide this
        if (override != null && override.isHidden()) {
            return;
        }

        int color = style.getColor(text.getColor()).toARGB();

        Point pos = text.getPosition().resolve(getBounds(false));

        float scale = text.getScale();

        // Allow overrides for which content is shown
        Component content = text.getText();
        if (override != null && override.getContent() != null) {
            content = override.getContent().copy().withStyle(content.getStyle());
        }

        // Account for max width and split into lines
        List<FormattedCharSequence> lines;
        if (text.getMaxWidth() <= 0) {
            var line = content.getVisualOrderText();
            lines = List.of(line);
        } else {
            lines = this.font.split(content, text.getMaxWidth());
        }

        int y = pos.getY();
        for (var line : lines) {
            int lineWidth = this.font.width(line);
            int x = pos.getX();
            if (text.getAlign() == TextAlignment.CENTER) {
                int textWidth = Math.round(lineWidth * scale);
                x -= textWidth / 2;
            } else if (text.getAlign() == TextAlignment.RIGHT) {
                int textWidth = Math.round(lineWidth * scale);
                x -= textWidth;
            }

            if (text.getScale() == 1) {
                guiGraphics.text(font, line, x, y, color, false);
            } else {
                guiGraphics.pose().pushMatrix();
                guiGraphics.pose().translate(x, y);
                guiGraphics.pose().scale(scale);
                guiGraphics.text(
                        font,
                        line,
                        0,
                        0,
                        color,
                        false);
                guiGraphics.pose().popMatrix();
            }
            y += text.getScale() * this.font.lineHeight;
        }
    }

public Tooltip(List<Component> unprocessedLines) {
        this.content = new ArrayList<>(unprocessedLines.size());

        // Split translated lines at line-breaks found in the translated text
        for (Component unprocessedLine : unprocessedLines) {
            splitLine(unprocessedLine, this.content);
        }
    }

void populateScreen(Consumer<AbstractWidget> addWidget, Rect2i bounds, AEBaseScreen<?> screen) {
        for (var entry : widgets.entrySet()) {
            var widget = entry.getValue();
            if (widget.isFocused()) {
                widget.setFocused(false); // Minecraft already cleared focus on the screen
            }

            // Position the widget
            WidgetStyle widgetStyle = style.getWidget(entry.getKey());
            Point pos = widgetStyle.resolve(bounds);
            if (widget instanceof IResizableWidget resizableWidget) {
                resizableWidget.move(pos);
            } else {
                widget.setX(pos.getX());
                widget.setY(pos.getY());
            }

            addWidget.accept(widget);
        }

        // For composite widgets, just position them. Positions for these widgets are generally relative to the dialog
        Rect2i relativeBounds = new Rect2i(0, 0, bounds.getWidth(), bounds.getHeight());
        for (var entry : compositeWidgets.entrySet()) {
            var widget = entry.getValue();
            var widgetStyle = style.getWidget(entry.getKey());
            widget.setPosition(widgetStyle.resolve(relativeBounds));

            widget.populateScreen(addWidget, bounds, screen);
        }

        tooltips.clear();
        for (var entry : style.getTooltips().entrySet()) {
            var pos = entry.getValue().resolve(relativeBounds);
            var area = new Rect2i(
                    pos.getX(), pos.getY(),
                    entry.getValue().getWidth(),
                    entry.getValue().getHeight());
            tooltips.put(entry.getKey(), new ResolvedTooltipArea(
                    area, new Tooltip(entry.getValue().getTooltip())));
        }
    }

public void setTooltipAreaEnabled(String id, boolean enabled) {
        var tooltip = tooltips.get(id);
        Preconditions.checkArgument(tooltip != null, "No tooltip with id '%s' is defined", id);
        tooltip.enabled = enabled;
    }

@Nullable
    public Tooltip getTooltip(int mouseX, int mouseY) {
        for (var c : this.compositeWidgets.values()) {
            if (!c.isVisible()) {
                continue;
            }

            Rect2i bounds = c.getBounds();
            if (mouseX >= bounds.getX() && mouseX < bounds.getX() + bounds.getWidth()
                    && mouseY >= bounds.getY() && mouseY < bounds.getY() + bounds.getHeight()) {
                Tooltip tooltip = c.getTooltip(mouseX, mouseY);
                if (tooltip != null) {
                    return tooltip;
                }
            }
        }

        for (var tooltipArea : tooltips.values()) {
            if (tooltipArea.enabled && contains(tooltipArea.area, mouseX, mouseY)) {
                return tooltipArea.tooltip;
            }
        }

        return null;
    }

public CellWorkbenchScreen(CellWorkbenchMenu menu, Inventory playerInventory,
            Component title, ScreenStyle style) {
        super(menu, playerInventory, title, style);

        this.fuzzyMode = addToLeftToolbar(
                new SettingToggleButton<>(Settings.FUZZY_MODE, FuzzyMode.IGNORE_ALL, this::toggleFuzzyMode));
        this.addToLeftToolbar(new ActionButton(ActionItems.COG, act -> menu.partition()));
        this.addToLeftToolbar(new ActionButton(ActionItems.CLOSE, act -> menu.clear()));
        this.copyMode = this.addToLeftToolbar(new ToggleButton(Icon.COPY_MODE_ON, Icon.COPY_MODE_OFF,
                GuiText.CopyMode.text(), GuiText.CopyModeDesc.text(), act -> menu.nextWorkBenchCopyMode()));
    }

@Override
    protected List<Component> getTooltipFromContainerItem(ItemStack stack) {
        var cell = getMenu().getWorkbenchItem();
        if (cell.isEmpty()) {
            return super.getTooltipFromContainerItem(stack);
        }

        // Don't show the tooltip for the cell itself
        if (cell == stack) {
            return super.getTooltipFromContainerItem(stack);
        }

        AEKey what;
        var genericStack = GenericStack.unwrapItemStack(stack);
        if (genericStack != null) {
            what = genericStack.what();
        } else {
            what = AEItemKey.of(stack);
        }

        if (what == null) {
            return super.getTooltipFromContainerItem(stack);
        }

        // Is it allowed in any slot?
        var configInventory = getMenu().getHost().getCell().getConfigInventory(cell);

        // Check if the type is supported at all
        if (!configInventory.isSupportedType(what.getType())) {
            var lines = new ArrayList<>(super.getTooltipFromContainerItem(stack));
            lines.add(GuiText.IncompatibleWithCell.text().withStyle(ChatFormatting.RED));
            return lines;
        }

        var filter = configInventory.getFilter();
        if (filter != null) {
            boolean anySlotMatches = false;
            for (int i = 0; i < configInventory.size(); i++) {
                if (configInventory.isAllowedIn(i, what)) {
                    anySlotMatches = true;
                    break;
                }
            }

            if (!anySlotMatches) {
                var lines = new ArrayList<>(super.getTooltipFromContainerItem(stack));
                lines.add(GuiText.IncompatibleWithCell.text().withStyle(ChatFormatting.RED));
                return lines;
            }
        }

        return super.getTooltipFromContainerItem(stack);
    }

