@Override
    public List<Component> getTooltipMessage() {

        if (this.buttonSetting == null || this.currentValue == null) {
            return Collections.emptyList();
        }

        var buttonAppearance = appearances.get(new EnumPair<>(this.buttonSetting, this.currentValue));
        if (buttonAppearance == null) {
            return Collections.singletonList(ButtonToolTips.NoSuchMessage.text());
        }

        return buttonAppearance.tooltipLines;
    }

@Override
    public @Nullable SceneAnnotation getAnnotation(GuidebookLevel level, BlockState blockState,
            BlockHitResult blockHitResult) {
        var pos = blockHitResult.getBlockPos();
        var be = level.getBlockEntity(pos);
        if (!(be instanceof IPartHost partHost)) {
            return null;
        }

        var partResult = partHost.selectPartWorld(blockHitResult.getLocation());
        if (partResult != null) {
            var part = partResult.part;
            var facade = partResult.facade;
            AABB aabb = null;
            Component description = Component.empty();
            if (part != null) {
                aabb = getAABB(partResult.side, partResult.part::getBoxes);
                description = partResult.part.getPartItem().asItem().getDefaultInstance().getItemName();
            } else if (facade != null) {
                aabb = getAABB(partResult.side, bch -> partResult.facade.getBoxes(bch, false));
                description = GuiText.Facade.text(partResult.facade.getItem().getDefaultInstance().getItemName());
            }

            if (aabb != null) {
                var annotation = new InWorldBoxAnnotation(
                        new Vector3f(pos.getX() + (float) aabb.minX, pos.getY() + (float) aabb.minY,
                                pos.getZ() + (float) aabb.minZ),
                        new Vector3f(pos.getX() + (float) aabb.maxX, pos.getY() + (float) aabb.maxY,
                                pos.getZ() + (float) aabb.maxZ),
                        SymbolicColor.IN_WORLD_BLOCK_HIGHLIGHT);
                annotation.setTooltipContent(description);
                return annotation;
            }
        }
        return null;
    }

private static LytStandardRecipeBox<TransformRecipe> transform(RecipeHolder<TransformRecipe> holder) {
        var recipe = holder.value();

        var builder = LytStandardRecipeBox.builder()
                .input(LytSlotGrid.columnFromIngredients(recipe.ingredients(), true))
                .output(LytSlotGrid.columnFromStacks(List.of(recipe.result()), true));

        if (recipe.circumstance.isExplosion()) {
            builder.icon(Blocks.TNT);
            builder.title(GuiText.TransformTypeExplode.text().getString());
        } else if (recipe.circumstance.isFluid()) {
            Fluid fluid = Fluids.EMPTY;
            // Special-case water since a lot of mods add their fluids to the tag
            if (recipe.circumstance.isFluidTag(FluidTags.WATER)) {
                fluid = Fluids.WATER;
            } else {
                var fluidsForRendering = recipe.circumstance.getFluidsForRendering();
                if (!fluidsForRendering.isEmpty()) {
                    var cycle = System.currentTimeMillis() / 1500;
                    fluid = fluidsForRendering.get((int) (cycle % fluidsForRendering.size()));
                }
            }

            builder.icon(new FluidIcon(fluid));
            builder.title(GuiText.TransformTypeThrowInFluid.text(Platform.getFluidDisplayName(fluid)).getString());
        }

        return builder.build(holder);
    }

private static void renderBoxes(PoseStack poseStack,
            SubmitNodeCollector collector,
            boolean afterTerrain,
            Vec3 cameraRelativePos,
            List<AABB> boxes,
            RenderType renderType,
            int color,
            float lineWidth) {
        poseStack.pushPose();
        poseStack.translate(cameraRelativePos.x, cameraRelativePos.y, cameraRelativePos.z);
        for (var box : boxes) {
            collector.submitShapeOutline(poseStack, Shapes.create(box), renderType, color, lineWidth, afterTerrain);
        }
        poseStack.popPose();
    }

private static void setupOrthographicProjection(PoseStack poseStack) {
        // Set up orthographic rendering for the block
        float angle = 36;
        float rotation = 45;

        poseStack.scale(1, 1, -1);
        poseStack.rotate(new Quaternionf().rotationY(Mth.DEG_TO_RAD * -180));

        Quaternionf flip = new Quaternionf().rotationZ(Mth.DEG_TO_RAD * 180);
        flip.mul(new Quaternionf().rotationX(Mth.DEG_TO_RAD * angle));

        Quaternionf rotate = new Quaternionf().rotationY(Mth.DEG_TO_RAD * rotation);
        poseStack.rotate(flip);
        poseStack.rotate(rotate);

        // Move into the center of the block for the transforms
        poseStack.translate(-0.5f, -0.5f, -0.5f);
    }

