@Override
    public void submit(SkyStoneTankRenderState state, PoseStack poseStack, SubmitNodeCollector nodes,
            CameraRenderState cameraRenderState) {

        if (state.sprite == null) {
            return;
        }

        /*
         *
         * // Uncomment to allow the liquid to rotate with the tank ms.pushPose(); ms.translate(0.5, 0.5, // 0.5);
         * FacingToRotation.get(tank.getForward(), tank.getUp()).push(ms); ms.translate(-0.5, -0.5, -0.5);
         */

        // From Modern Industrialization
        nodes.submitCustomGeometry(poseStack, Sheets.translucentBlockItemSheet(), (pose, consumer) -> {
            var fill = state.fill;

            var fillY = Mth.lerp(Mth.clamp(fill, 0, 1), TANK_W, 1 - TANK_W);

            // Top and bottom positions of the fluid inside the tank
            float topHeight = fillY;
            float bottomHeight = TANK_W;

            // Render gas from top to bottom
            if (state.lighterThanAir) {
                topHeight = 1 - TANK_W;
                bottomHeight = 1 - fillY;
            }

            var qi = new QuadInstance();
            qi.setColor(state.color);
            qi.setLightCoords(state.lightCoords);
            var builder = new CubeBuilder(bakedQuad -> {
                consumer.putBakedQuad(pose, bakedQuad, qi);
            });
            builder.setTexture(state.sprite);

            var x1 = TANK_W * 16;
            var z1 = TANK_W * 16;
            var x2 = (1 - TANK_W) * 16;
            var z2 = (1 - TANK_W) * 16;
            var y1 = bottomHeight * 16;
            var y2 = topHeight * 16;
            builder.addCube(x1, y1, z1, x2, y2, z2);
        });
    }

@Override
    public void submit(TntRenderState renderState, PoseStack poseStack, SubmitNodeCollector nodes,
            CameraRenderState cameraRenderState) {
        poseStack.pushPose();
        poseStack.translate(0, 0.5F, 0);
        float f2;

        if (renderState.fuseRemainingInTicks - renderState.partialTick + 1.0F < 10.0F) {
            f2 = 1.0F - (renderState.fuseRemainingInTicks - renderState.partialTick + 1.0F) / 10.0F;

            if (f2 < 0.0F) {
                f2 = 0.0F;
            }

            if (f2 > 1.0F) {
                f2 = 1.0F;
            }

            f2 *= f2;
            f2 *= f2;
            final float f3 = 1.0F + f2 * 0.3F;
            poseStack.scale(f3, f3, f3);
        }

        poseStack.rotate(new Quaternionf().rotationY(Mth.DEG_TO_RAD * -90.0F));
        poseStack.translate(-0.5D, -0.5D, 0.5D);
        poseStack.rotate(new Quaternionf().rotationY(Mth.DEG_TO_RAD * 90.0F));
        if (!renderState.blockState.isEmpty()) {
            TntMinecartRenderer.submitWhiteSolidBlock(
                    renderState.blockState,
                    poseStack,
                    nodes,
                    renderState.lightCoords,
                    renderState.fuseRemainingInTicks / 5 % 2 == 0,
                    renderState.outlineColor);
        }
        poseStack.popPose();

        super.submit(renderState, poseStack, nodes, cameraRenderState);
    }

@Override
    public void submit(PoseStack poseStack, RenderState state, SubmitNodeCollector nodes, int lightCoords) {

        poseStack.pushPose();
        // Push it out of the block face a bit to avoid z-fighting
        poseStack.translate(0, 0, 0.01f);

        // y is flipped here
        var x0 = -1 / 2f;
        var y0 = 1 / 2f;
        var x1 = 1 / 2f;
        var y1 = -1 / 2f;

        var color = ARGB.opaque(state.color);
        var sprite = state.sprite;

        // We have to use "solid" here because we don't actually want to alpha blend
        // the semi-transparent fluid textures onto a fake screen.
        nodes.submitCustomGeometry(poseStack, RenderTypes.entitySolid(state.sprite.atlasLocation()), (pose, buffer) -> {
            buffer.addVertex(pose, x0, y1, 0)
                    .setColor(color)
                    .setUv(sprite.getU0(), sprite.getV1())
                    .setOverlay(OverlayTexture.NO_OVERLAY)
                    .setLight(lightCoords)
                    .setNormal(0, 0, 1);
            buffer.addVertex(pose, x1, y1, 0)
                    .setColor(color)
                    .setUv(sprite.getU1(), sprite.getV1())
                    .setOverlay(OverlayTexture.NO_OVERLAY)
                    .setLight(lightCoords)
                    .setNormal(0, 0, 1);
            buffer.addVertex(pose, x1, y0, 0)
                    .setColor(color)
                    .setUv(sprite.getU1(), sprite.getV0())
                    .setOverlay(OverlayTexture.NO_OVERLAY)
                    .setLight(lightCoords)
                    .setNormal(0, 0, 1);
            buffer.addVertex(pose, x0, y0, 0)
                    .setColor(color)
                    .setUv(sprite.getU0(), sprite.getV0())
                    .setOverlay(OverlayTexture.NO_OVERLAY)
                    .setLight(lightCoords)
                    .setNormal(0, 0, 1);
        });

        poseStack.popPose();
    }

@Override
    public void submit(PoseStack poseStack, ItemStackRenderState state, SubmitNodeCollector nodes, int lightCoords) {
        poseStack.pushPose();
        // Push it out of the block face a bit to avoid z-fighting
        poseStack.translate(0, 0, 0.01f);
        // The Z-scaling by 0.001 causes the model to be visually "flattened"
        // This cannot replace a proper projection, but it's cheap and gives the desired effect.
        // We don't scale the normal matrix to avoid lighting issues.
        poseStack.mulPose(new Matrix4f().scale(1, 1, 0.001f));
        // Rotate the normal matrix a little for nicer lighting.
        poseStack.last().normal().rotateX(Mth.DEG_TO_RAD * -45f);

        state.submit(poseStack, nodes, lightCoords, OverlayTexture.NO_OVERLAY, 0);

        poseStack.popPose();
    }

@Override
    public void submit(MonitorRenderState state, PoseStack poseStack, SubmitNodeCollector nodes,
            CameraRenderState cameraRenderState) {
        if (state.what.isEmpty()) {
            return;
        }

        poseStack.pushPose();
        poseStack.translate(0.5, 0.5, 0.5); // Move to the center of the block
        BlockEntityRenderHelper.rotateToFace(poseStack, state.orientation);
        // Move to the "front" of the face.
        poseStack.translate(0, 0, 0.5);

        float itemScale = 6 / 16f;

        BlockEntityRenderHelper.submitItem2dWithAmount(
                poseStack,
                state.what,
                state.text,
                state.textColor,
                state.textWidth,
                nodes,
                itemScale);

        poseStack.popPose();
    }

private static List<Component> createTooltipLinesForCard(Item card) {
        var associations = new ArrayList<>(ASSOCIATIONS.getOrDefault(card, Collections.emptyList()));
        associations.sort(Comparator.comparingInt(o -> o.maxCount));
        var supportedTooltipLines = new ArrayList<Component>(associations.size());

        // Use a separate set because the final text will include numbers
        Set<Component> namesAdded = new HashSet<>();

        for (int i = 0; i < associations.size(); i++) {
            var association = associations.get(i);
            Component name = association.upgradableItem().getDefaultInstance().getItemName();

            // If the group was already added by a previous item, skip this
            if (association.tooltipGroup() != null && namesAdded.contains(association.tooltipGroup())) {
                continue;
            }

            // If any of the following items would be of the same group, use the group name
            // instead
            if (association.tooltipGroup() != null) {
                for (int j = i + 1; j < associations.size(); j++) {
                    var otherGroup = associations.get(j).tooltipGroup();
                    if (association.tooltipGroup().equals(otherGroup)) {
                        name = association.tooltipGroup();
                        break;
                    }
                }
            }

            if (namesAdded.add(name)) {
                // append the supported count only if its > 1
                Component base = (name.copy().withStyle(Tooltips.NORMAL_TOOLTIP_TEXT));
                Component main = base;

                if (association.maxCount() > 1) {
                    main = Tooltips.of(base, Tooltips.of(" ("),
                            Tooltips.ofUnformattedNumber(association.maxCount()), Tooltips.of(")"));

                }
                supportedTooltipLines.add(main);
            }
        }

        return supportedTooltipLines;
    }

