public static void addIEManualEntries()
	{
		IEManualInstance ieMan = (IEManualInstance)ManualHelper.getManual();
		InnerNode<ResourceLocation, ManualEntry> resourcesCat = ieMan.getRoot().getOrCreateSubnode(IEApi.ieLoc(ManualHelper.CAT_RESOURCES), 0);
		InnerNode<ResourceLocation, ManualEntry> toolsCat = ieMan.getRoot().getOrCreateSubnode(IEApi.ieLoc(ManualHelper.CAT_TOOLS), 50);

		{
			ManualEntry.ManualEntryBuilder builder = new ManualEntry.ManualEntryBuilder(ManualHelper.getManual());
			builder.readFromFile(IEApi.ieLoc("mineral_deposits"));
			builder.appendText(IEManual::getMineralVeinTexts);
			ieMan.addEntry(resourcesCat, builder.create(), ieMan.atOffsetFrom(resourcesCat, "ores", 0.5));
		}
		{
			ManualEntry.ManualEntryBuilder builder = new ManualEntryBuilder(ieMan);
			builder.setContent(
					//TODO translation
					() -> "Shader list",
					() -> "",
					() -> {
						StringBuilder content = new StringBuilder();
						for(ShaderRegistryEntry shader : ShaderRegistry.shaderRegistry.values())
						{
							String key = shader.name.getPath();
							content.append("<&").append(key).append(">").append("<np>");
						}
						int last = content.lastIndexOf("<np>");
						content.delete(last, last+4);
						return content.toString();
					}
			);
			for(ShaderRegistryEntry shader : ShaderRegistry.shaderRegistry.values())
			{
				String key = shader.name.getPath();
				builder.addSpecialElement(new SpecialElementData(key, 0, new ShaderManualElement(ieMan, shader)));
			}
			builder.setLocation(IEApi.ieLoc("shader_list"));
			ManualEntry e = builder.create();
			ieMan.addEntry(toolsCat, e);
			ieMan.hideEntry(e.getLocation());
		}

		addChangelogToManual();
	}

private static Pair<String, List<SpecialElementData>> getMineralVeinTexts()
	{
		StringBuilder text = new StringBuilder();
		List<SpecialElementData> specials = new ArrayList<>();

		List<RecipeHolder<MineralMix>> mineralsToAdd = new ArrayList<>(
				MineralMix.RECIPES.getRecipes(Minecraft.getInstance().level)
		);
		Function<RecipeHolder<MineralMix>, String> toName = mineral -> {
			String translationKey = MineralMix.getTranslationKey(mineral.id());
			String localizedName = I18n.get(translationKey);
			if(localizedName.equals(translationKey))
				localizedName = MineralMix.getPlainName(mineral.id());
			return localizedName;
		};
		mineralsToAdd.sort((i1, i2) -> toName.apply(i1).compareToIgnoreCase(toName.apply(i2)));
		for(RecipeHolder<MineralMix> holder : mineralsToAdd)
		{
			final MineralMix mineral = holder.value();
			// Assemble text for biome limitations
			String biomeText = mineral.biomeTagPredicates.stream().map(
					biomeTagPredicate -> biomeTagPredicate.tags().stream().map(biomeTagKey -> {
						// translate biome tags where possible, fall back to location path otherwise
						String key = biomeTagKey.location().toLanguageKey("tag.biome").replaceAll("/", ".");
						if(I18n.exists(key))
							return I18n.get(key);
						else
							return biomeTagKey.location().getPath();
					}).reduce((s, s2) -> I18n.get("ie.manual.entry.minerals.biomes_or", s, s2)).orElse("")
			).reduce((s, s2) -> I18n.get("ie.manual.entry.minerals.biomes_and", s, s2)).orElse("");
			// Combine it with the name of the vein
			String openingString = I18n.get(
					"ie.manual.entry.minerals.biomes",
					toName.apply(holder),
					biomeText
			);

			// Format output and spoils
			List<StackWithChance> formattedOutputs = new ArrayList<>(mineral.outputs);
			List<StackWithChance> formattedSpoils = new ArrayList<>(mineral.spoils);
			formattedOutputs.sort(Comparator.comparingDouble(i -> -i.chance()));
			formattedSpoils.sort(Comparator.comparingDouble(i -> -i.chance()));

			StringBuilder outputString = new StringBuilder();
			NonNullList<ItemStack> sortedOres = NonNullList.create();
			for(StackWithChance sorted : formattedOutputs)
			{
				outputString
						.append("\n")
						.append(
								new DecimalFormat("00.00")
										.format(sorted.chance()*100)
										.replaceAll("\\G0", "\u00A0")
						).append("% ")
						.append(sorted.stack().get().getHoverName().getString());
				sortedOres.add(sorted.stack().get());
			}

			StringBuilder spoilString = new StringBuilder();
			for(StackWithChance sorted : formattedSpoils)
			{
				spoilString
						.append("\n")
						.append(
								new DecimalFormat("00.00")
										.format(sorted.chance()*100)
										.replaceAll("\\G0", "\u00A0")
						).append("% ")
						.append(sorted.stack().get().getHoverName().getString());
				sortedOres.add(sorted.stack().get());
			}

			specials.add(new SpecialElementData(holder.id().toString(), 0, new ManualElementItem(ManualHelper.getManual(), sortedOres)));
			String desc = I18n.get(
					"ie.manual.entry.minerals_desc",
					openingString,
					outputString.toString(),
					spoilString.toString()
			);

			if(!text.isEmpty())
				text.append("<np>");
			text.append("<&")
					.append(holder.id())
					.append(">")
					.append(desc);
		}
		return Pair.of(text.toString(), specials);
	}

private static ManualEntry addVersionToManual(ComparableVersion currVer, ComparableVersion version, String changes, boolean ahead)
	{
		String text = changes.replace("\t", "  ");
		ManualEntry.ManualEntryBuilder builder = new ManualEntryBuilder(ManualHelper.getManual());
		builder.setContent(() -> {
			String title = version.toString();
			if(ahead)
				title += " - "+I18n.get("ie.manual.newerVersion");
			else if(currVer.equals(version))
				title += " - "+I18n.get("ie.manual.currentVersion");
			return title;
		}, () -> "", () -> text);
		builder.setLocation(IEApi.ieLoc("changelog_"+version.toString()));
		return builder.create();
	}

public static void handleTooltipOffset(GuiGraphics guiGraphics, boolean pre)
	{
		Player player = ClientUtils.mc().player;
		if(player==null)
			return;
		ItemStack rightHandItem = HumanoidArm.RIGHT==player.getMainArm()?player.getMainHandItem(): player.getOffhandItem();
		SUBTITLE_OFFSETS.forEach(c -> {
			if(c.cond.test(rightHandItem))
				guiGraphics.pose().translate(pre?-c.offset: c.offset, 0, 0);
		});
	}

private static void renderWireCoilOverlay(
			GuiGraphics graphics, ItemStack equipped, Player player, int scaledWidth, int scaledHeight
	)
	{
		if(!equipped.has(IEApiDataComponents.WIRE_LINK))
			return;
		WireLink link = equipped.get(IEApiDataComponents.WIRE_LINK);
		BlockPos pos = link.cp().position();
		String s = I18n.get(Lib.DESC_INFO+"attachedTo", pos.getX(), pos.getY(), pos.getZ());
		int col = WireType.ELECTRUM.getColour(null);
		if(equipped.getItem() instanceof IWireCoil)
		{
			//TODO use actual connection offset rather than pos
			HitResult rtr = ClientUtils.mc().hitResult;
			double d;
			if(rtr instanceof BlockHitResult)
				d = ((BlockHitResult)rtr).getBlockPos().distSqr(pos);
			else
				d = player.distanceToSqr(pos.getX(), pos.getY(), pos.getZ());
			int max = ((IWireCoil)equipped.getItem()).getWireType(equipped).getMaxLength();
			if(d > max*max)
				col = 0xdd3333;
		}
		graphics.drawCenteredString(ClientUtils.font(), s, scaledWidth/2, scaledHeight-20-leftHeight(), col);
	}

