@Override
	public String formatText(String s)
	{
		String splitKey = ";";

		s = s.replace("<br>", "\n");
		int start;
		int overflow = 0;
		while((start = s.indexOf("<config")) >= 0&&overflow < 50)
		{
			overflow++;
			int end = s.indexOf(">", start);
			String rep = s.substring(start, end+1);
			String result = formatConfigEntry(rep, splitKey);

			s = s.replaceFirst(rep, result);
		}
		overflow = 0;
		while((start = s.indexOf("<dim")) >= 0&&overflow < 50)
		{
			overflow++;
			int end = s.indexOf(">", start);
			String rep = s.substring(start, end+1);
			String[] segment = rep.substring(0, rep.length()-1).split(splitKey);
			if(segment.length < 2)
				break;
			ResourceLocation dimKey = ResourceLocation.parse(segment[1]);
			StringBuilder dimName = new StringBuilder();
			for(String ss : dimKey.getPath().split("_"))
				if(!"the".equalsIgnoreCase(ss))
					dimName.append(Utils.toCamelCase(ss)+" ");
			s = s.replaceFirst(rep, dimName.toString().trim());
		}

		overflow = 0;
		while((start = s.indexOf("<keybind")) >= 0&&overflow < 50)
		{
			overflow++;
			int end = s.indexOf(">", start);
			String rep = s.substring(start, end+1);
			String[] segment = rep.substring(0, rep.length()-1).split(splitKey);
			if(segment.length < 2)
				break;
			String result = "";
			for(KeyMapping kb : ClientUtils.mc().options.keyMappings)
				if(segment[1].equalsIgnoreCase(kb.getName()))
				{
					result = kb.getTranslatedKeyMessage().getString();
					if(result.length() > 1)
						result = Utils.toCamelCase(result);
					break;
				}
			s = s.replaceFirst(rep, Matcher.quoteReplacement(result));
		}

		return s;
	}

private void checkMaterials()
	{
		NonNullList<ItemStack> totalMaterials = this.renderProperties.getTotalMaterials();
		if(totalMaterials!=null)
		{
			componentTooltip = new ArrayList<>();
			componentTooltip.add(Component.translatable("desc.immersiveengineering.info.reqMaterial"));
			int maxOff = 1;
			boolean hasAnyItems = false;
			boolean[] hasItems = new boolean[totalMaterials.size()];
			for(int ss = 0; ss < totalMaterials.size(); ss++)
			{
				ItemStack req = totalMaterials.get(ss);
				int reqSize = req.getCount();
				for(int slot = 0; slot < ManualUtils.mc().player.getInventory().getContainerSize(); slot++)
				{
					ItemStack inSlot = ManualUtils.mc().player.getInventory().getItem(slot);
					if(!inSlot.isEmpty()&&ItemStack.isSameItem(inSlot, req))
						if((reqSize -= inSlot.getCount()) <= 0)
							break;
				}
				if(reqSize <= 0)
				{
					hasItems[ss] = true;
					if(!hasAnyItems)
						hasAnyItems = true;
				}
				maxOff = Math.max(maxOff, (""+req.getCount()).length());
			}
			for(int ss = 0; ss < totalMaterials.size(); ss++)
			{
				ItemStack req = totalMaterials.get(ss);
				int indent = maxOff-(""+req.getCount()).length();
				StringBuilder sIndent = new StringBuilder();
				if(indent > 0)
					sIndent.append("0".repeat(indent));
				MutableComponent s;
				if(hasItems[ss])
					s = greenTick.copy();
				else
					s = Component.literal(hasAnyItems?"   ": "");
				s.append(applyFormat(
						Component.literal(sIndent.toString()+req.getCount()+"x "), ChatFormatting.GRAY
				));
				if(!req.isEmpty())
					s.append(applyFormat(req.getHoverName().copy(), req.getRarity().color()));
				else
					s.append("???");
				componentTooltip.add(s);
			}
		}
	}

@Override
	public void render(GuiGraphics graphics, ManualScreen gui, int x, int y, int mouseX, int mouseY)
	{
		if(multiblock.getStructure(level)!=null)
		{
			PoseStack transform = graphics.pose();
			PoseStack.Pose lastEntryBeforeTry = transform.last();
			try
			{
				long currentTime = System.currentTimeMillis();
				if(lastStep < 0)
					lastStep = currentTime;
				else if(canTick&&currentTime-lastStep > 500)
				{
					renderInfo.step();
					lastStep = currentTime;
				}

				int structureLength = renderInfo.structureLength;
				int structureWidth = renderInfo.structureWidth;
				int structureHeight = renderInfo.structureHeight;

				transform.pushPose();

				final BlockRenderDispatcher blockRender = Minecraft.getInstance().getBlockRenderer();

				transform.translate(transX, transY, Math.max(structureHeight, Math.max(structureWidth, structureLength)));
				transform.scale(scale, -scale, 1);
				transform.pushTransformation(additionalTransform);
				transform.mulPose(new Quaternionf().rotateXYZ(0, Mth.HALF_PI, 0));

				transform.translate(structureLength/-2f, structureHeight/-2f, structureWidth/-2f);

				if(showCompleted&&renderProperties.canRenderFormedStructure())
				{
					transform.pushPose();
					renderProperties.renderFormedStructure(transform, graphics.bufferSource());
					transform.popPose();
				}
				else
				{
					TransformingVertexBuilder translucentFullbright = new TransformingVertexBuilder(
							graphics.bufferSource(), IERenderTypes.TRANSLUCENT_FULLBRIGHT
					);
					for(int h = 0; h < structureHeight; h++)
						for(int l = 0; l < structureLength; l++)
							for(int w = 0; w < structureWidth; w++)
							{
								BlockPos pos = new BlockPos(l, h, w);
								BlockState state = structureWorld.getBlockState(pos);
								if(!state.isAir())
								{
									transform.pushPose();
									transform.translate(l, h, w);
									int overlay;
									if(pos.equals(multiblock.getTriggerOffset()))
										overlay = OverlayTexture.pack(0, true);
									else
										overlay = OverlayTexture.NO_OVERLAY;
									translucentFullbright.setDefaultOverlay(overlay);
									ModelData modelData = ModelData.EMPTY;
									BlockEntity te = structureWorld.getBlockEntity(pos);
									if(te!=null)
										modelData = te.getModelData();
									final BakedModel model = blockRender.getBlockModel(state);
									modelData = model.getModelData(structureWorld, pos, state, modelData);
									blockRender.getModelRenderer().tesselateBlock(
											structureWorld, model, state, pos, transform,
											translucentFullbright, false, structureWorld.random, state.getSeed(pos),
											overlay, modelData, null
									);
									transform.popPose();
								}
							}
				}
				transform.popPose();
				transform.popPose();
			} catch(Exception e)
			{
				final long now = System.currentTimeMillis();
				if(now > lastPrintedErrorTimeMs+1000)
				{
					e.printStackTrace();
					lastPrintedErrorTimeMs = now;
				}
				while(lastEntryBeforeTry!=transform.last())
					transform.popPose();
			}

			if(componentTooltip!=null)
			{
				graphics.drawString(manual.fontRenderer(), "?", 116, yOffTotal/2-4, manual.getTextColour());
				if(mouseX >= 116&&mouseX < 122&&mouseY >= yOffTotal/2-4&&mouseY < yOffTotal/2+4)
					graphics.renderTooltip(manual.fontRenderer(), Language.getInstance().getVisualOrder(
							Collections.unmodifiableList(componentTooltip)
					), mouseX, mouseY);
			}
		}
	}

@Override
	public void onOpened(ManualScreen gui, int x, int y, List<Button> buttons)
	{
		Player player = mc().player;
		UUID uuid = player.getUUID();
		unlocked = ShaderRegistry.receivedShaders.get(uuid).contains(shader.getName());

		shaderItem = ShaderRegistry.makeShaderStack(shader.name);
		replicationCost = shader.replicationCost.get();

		if(unlocked)
		{
			ArrayList<ItemStack> list = new ArrayList<>();
			for(ItemStack is : ShaderRegistry.itemExamples)
			{
				ItemStack s = is.copy();
				ShaderWrapper wrapper = s.getCapability(CapabilityShader.ITEM);
				if(wrapper!=null)
				{
					wrapper.setShader(shader.name);
					list.add(s);
				}
			}
			exampleItems = list.toArray(new ItemStack[0]);
			example = 0;
			if(exampleItems.length > 1)
			{
				buttons.add(new GuiButtonManualNavigation(gui, x+50, y, 10, 16, 0, btn -> {
					example--;
					if(example < 0)
						example = this.exampleItems.length-1;
				}));
				buttons.add(new GuiButtonManualNavigation(gui, x+100, y, 10, 16, 1,
						btn -> example = (example+1)%exampleItems.length
				));
			}
		}
		else
			exampleItems = null;

		this.name = TextUtils.applyFormat(shaderItem.getHoverName(), ChatFormatting.BOLD);
		MutableComponent textAssembly = Component.literal("");
		textAssembly.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.level"), ChatFormatting.BOLD));
		textAssembly.append(Component.translatable("desc.immersiveengineering.info.shader.rarity."+shader.rarity.name().toLowerCase(Locale.US)));
		if(unlocked)
		{
			String set = shader.info_set==null||shader.info_set.isEmpty()?null: ManualUtils.attemptStringTranslation(Lib.DESC_INFO+"shader.set.%s", shader.info_set);
			String reference = shader.info_reference==null||shader.info_reference.isEmpty()?null: ManualUtils.attemptStringTranslation(Lib.DESC_INFO+"shader.reference.%s", shader.info_reference);
			String details = shader.info_details==null||shader.info_details.isEmpty()?null: ManualUtils.attemptStringTranslation(Lib.DESC_INFO+"shader.details.%s", shader.info_details);

			if(set!=null)
				textAssembly.append("\n")
						.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.set"), ChatFormatting.BOLD))
						.append(" "+set);
			if(reference!=null)
				textAssembly.append("\n")
						.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.reference"), ChatFormatting.BOLD))
						.append("\n"+reference);
			if(details!=null)
				textAssembly.append("\n")
						.append(TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.shader.details"), ChatFormatting.BOLD))
						.append("\n"+details);

			String cost = Integer.toString(replicationCost.getCount());
			if(!IngredientUtils.hasPlayerIngredient(mc().player, replicationCost)&&!mc().player.getAbilities().instabuild)
				cost = ChatFormatting.RED+cost;
			buttons.add(new GuiButtonManual(gui, x+50, y+120, 70, 12,
					Component.literal(I18n.get("ie.manual.entry.shaderList.order")+" "+cost+"x   ").withStyle(ChatFormatting.BOLD),
					btn -> {
						if(IngredientUtils.hasPlayerIngredient(mc().player, replicationCost)||mc().player.getAbilities().instabuild)
							PacketDistributor.sendToServer(
									new MessageShaderManual(MessageType.SPAWN, shader.getName())
							);
						gui.fullInit();
					})
					.setTextColour(gui.getManual().getTextColour(), gui.getManual().getHighlightColour()));
		}
		else
		{
			textAssembly.append("\n\n").append(Component.translatable("ie.manual.entry.shaderList.noInfo"));
			if(player.getAbilities().instabuild)
				buttons.add(new GuiButtonManual(gui, x+10, y+120, 100, 16,
						Component.translatable("ie.manual.entry.shaderList.unlock"),
						btn -> {
							UUID playerId = mc().player.getUUID();
							PacketDistributor.sendToServer(new MessageShaderManual(MessageType.UNLOCK, shader.getName()));
							ShaderRegistry.receivedShaders.put(playerId, shader.getName());
							gui.fullInit();
						})
						.setTextColour(gui.getManual().getTextColour(), gui.getManual().getHighlightColour())
				);
		}
		this.text = textAssembly;
	}

