public static void renderConnectionsInSection(
			BlockPos sectionOrigin, SectionRenderingContext context, List<ConnectionSegments> segments
	)
	{
		final VertexConsumer builder = context.getOrCreateChunkBuffer(RenderType.solid());
		final PoseStack transform = context.getPoseStack();
		for(ConnectionSegments connection : segments)
		{
			transform.pushPose();
			ConnectionPoint connectionOrigin = connection.connection().getEndA();
			transform.translate(
					connectionOrigin.getX()-sectionOrigin.getX(),
					connectionOrigin.getY()-sectionOrigin.getY(),
					connectionOrigin.getZ()-sectionOrigin.getZ()
			);
			renderSegments(builder, connection, context.getRegion(), transform);
			transform.popPose();
		}
	}

@Override
	@ParametersAreNonnullByDefault
	public void render(PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn, E living, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch)
	{
		ItemStack earmuffs = EarmuffsItem.EARMUFF_GETTERS.getFrom(living);
		if(!earmuffs.isEmpty())
		{
			earmuffModel.setupAnim(living, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
			RenderType type = earmuffModel.renderType(EARMUFF_OVERLAY);
			earmuffModel.renderToBuffer(matrixStackIn, bufferIn.getBuffer(type), packedLightIn, OverlayTexture.NO_OVERLAY, -1);
			int colour = ((IColouredItem)earmuffs.getItem()).getColourForIEItem(earmuffs, 0);
			type = earmuffModel.renderType(EARMUFF_TEXTURE);
			earmuffModel.renderToBuffer(matrixStackIn, bufferIn.getBuffer(type), packedLightIn, OverlayTexture.NO_OVERLAY, colour);
		}

		ItemStack powerpack = PowerpackItem.POWERPACK_GETTER.getFrom(living);
		if(!powerpack.isEmpty())
			renderPowerpack(powerpack, matrixStackIn, bufferIn, packedLightIn, living, limbSwing, limbSwingAmount, partialTicks, ageInTicks, netHeadYaw, headPitch);

		ItemStack chest = living.getItemBySlot(EquipmentSlot.CHEST);
		if(chest.getItem() instanceof GliderItem)
		{
			gliderModel.setupAnim(living, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
			gliderModel.body.getChild("glider").visible = living.isFallFlying();
			RenderType type = gliderModel.renderType(GLIDER_TEXTURE);
			gliderModel.renderToBuffer(matrixStackIn, bufferIn.getBuffer(type), packedLightIn, OverlayTexture.NO_OVERLAY, -1);
		}
		else if(chest.getItem() instanceof CrateItem crateItem && living instanceof Player player && player.isCrouching())
		{
			matrixStackIn.pushPose();
			matrixStackIn.translate(-.5f, -.3f, -.375f);
			ClientUtils.mc().getBlockRenderer().renderSingleBlock(crateItem.getBlock().defaultBlockState(), matrixStackIn, bufferIn, packedLightIn, OverlayTexture.NO_OVERLAY);
			matrixStackIn.popPose();
		}
	}

@Override
	public void render(FluorescentTubeEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn)
	{
		matrixStackIn.pushPose();
		matrixStackIn.translate(0, 1, 0);
		matrixStackIn.mulPose(new Quaternionf().rotateXYZ(0, Mth.DEG_TO_RAD * (entityYaw+90), 0));
		matrixStackIn.pushPose();
		matrixStackIn.translate(0, 0, .03125);
		matrixStackIn.mulPose(new Quaternionf().rotateXYZ(entity.angleHorizontal * Mth.DEG_TO_RAD, 0, 0));
		matrixStackIn.translate(0, -entity.TUBE_LENGTH/2, 0);
		drawTube(entity.active, entity.rgb, matrixStackIn, bufferIn, packedLightIn, OverlayTexture.NO_OVERLAY, entity.level());
		matrixStackIn.popPose();
		matrixStackIn.translate(-0.25, -1, 0);
		if(tex==null)
			tex = Minecraft.getInstance().getTextureAtlas(InventoryMenu.BLOCK_ATLAS)
					.apply(ResourceLocation.withDefaultNamespace("block/iron_block"));

		VertexConsumer builder = bufferIn.getBuffer(RenderType.solid());
		RenderUtils.renderTexturedBox(builder, matrixStackIn,
				0, 0, 0,
				.0625F, 1, .0625F,
				tex.getU0(), tex.getV0(), tex.getU1(), tex.getV1(),
				packedLightIn
		);
		RenderUtils.renderTexturedBox(builder, matrixStackIn,
				.0625F, .9375F, 0,
				.25F, 1, .0625F,
				tex.getU0(), tex.getV0(), tex.getU1(), tex.getV1(),
				packedLightIn
		);

		matrixStackIn.popPose();
	}

static void drawTube(
			boolean active, Color4 rgb,
			PoseStack matrixStack, MultiBufferSource buffer,
			int light, int overlay, Level level
	)
	{
		if(tube.isEmpty())
			tube = new ItemStack(Misc.FLUORESCENT_TUBE);
		if(tubeActive.isEmpty())
		{
			tubeActive = new ItemStack(Misc.FLUORESCENT_TUBE);
			FluorescentTubeItem.setLit(tubeActive, 0.6f);
		}
		matrixStack.translate(0, 0.75, 0);
		ItemStack renderStack = active?tubeActive: tube;
		FluorescentTubeItem.setRGB(renderStack, rgb);
		ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
		itemRenderer.renderStatic(renderStack, ItemDisplayContext.NONE, light, overlay, matrixStack, buffer, level, 0);
	}

@Override
	public void render(GunpowderBarrelEntity entity, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn)
	{
		if(entity.block==null)
			return;
		BlockRenderDispatcher blockrendererdispatcher = Minecraft.getInstance().getBlockRenderer();
		matrixStackIn.pushPose();
		matrixStackIn.translate(0, 0.5F, 0);
		if(entity.getFuse()-partialTicks+1 < 10)
		{
			float f = 1.0F-((float)entity.getFuse()-partialTicks+1.0F)/10.0F;
			f = Mth.clamp(f, 0.0F, 1.0F);
			f = f*f;
			f = f*f;
			float f1 = 1.0F+f*0.3F;
			matrixStackIn.scale(f1, f1, f1);
		}
		matrixStackIn.mulPose(new Quaternionf().rotateXYZ(0, -Mth.HALF_PI, 0));
		matrixStackIn.translate(-0.5D, -0.5D, 0.5D);
		matrixStackIn.mulPose(new Quaternionf().rotateXYZ(0, Mth.HALF_PI, 0));

		int overlay;
		if(entity.getFuse()/5%2==0)
			overlay = OverlayTexture.pack(OverlayTexture.u(1.0F), 10);
		else
			overlay = OverlayTexture.NO_OVERLAY;
		blockrendererdispatcher.renderSingleBlock(entity.block, matrixStackIn, bufferIn, packedLightIn, overlay);

		matrixStackIn.popPose();
		super.render(entity, entityYaw, partialTicks, matrixStackIn, bufferIn, packedLightIn);
	}

public static void renderRailgunProjectile(double yaw, double pitch, RailgunRenderColors colors,
											   PoseStack matrixStackIn, MultiBufferSource bufferIn, int light)
	{
		matrixStackIn.pushPose();
		matrixStackIn.mulPose(new Quaternionf()
				.rotateY((float)Math.toRadians(yaw))
				.rotateZ((float) Math.toRadians(pitch))
		);

		matrixStackIn.scale(.25f, .25f, .25f);

		float height = .1875f;
		float halfWidth = height/2;
		float length = 2;
		int colWidth = colors.getGradientLength();
		int colLength = colors.getRingCount();
		float widthStep = height/colWidth;
		float lengthStep = length/colLength;

		matrixStackIn.translate(-length*.85f, 0, 0);
		TransformingVertexBuilder builder = new TransformingVertexBuilder(
				bufferIn, IERenderTypes.POSITION_COLOR_LIGHTMAP, matrixStackIn
		);
		builder.setDefaultLight(light);
		int[] rgb;
		//Front&Back
		for(int i = 0; i < colWidth; i++)
		{
			rgb = colors.getFrontColor(i);
			builder.addVertex(0, height, -halfWidth+widthStep*i).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(0, 0, -halfWidth+widthStep*i).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(0, 0, -halfWidth+widthStep*(i+1)).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(0, height, -halfWidth+widthStep*(i+1)).setColor(rgb[0], rgb[1], rgb[2], 255);

			rgb = colors.getBackColor(i);
			builder.addVertex(length, 0, -halfWidth+widthStep*i).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(length, height, -halfWidth+widthStep*i).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(length, height, -halfWidth+widthStep*(i+1)).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(length, 0, -halfWidth+widthStep*(i+1)).setColor(rgb[0], rgb[1], rgb[2], 255);
		}
		//Sides
		for(int i = 0; i < colLength; i++)
		{
			rgb = colors.getRingColor(i, 0);
			builder.addVertex(lengthStep*i, 0, -halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(lengthStep*i, height, -halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(lengthStep*(i+1), height, -halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(lengthStep*(i+1), 0, -halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);

			rgb = colors.getRingColor(i, colWidth-1);
			builder.addVertex(lengthStep*i, height, halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(lengthStep*i, 0, halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(lengthStep*(i+1), 0, halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
			builder.addVertex(lengthStep*(i+1), height, halfWidth).setColor(rgb[0], rgb[1], rgb[2], 255);
		}
		//Top&Bottom
		for(int i = 0; i < colLength; i++)
			for(int j = 0; j < colWidth; j++)
			{
				rgb = colors.getRingColor(i, j);
				builder.addVertex(lengthStep*(i+1), height, -halfWidth+widthStep*j).setColor(rgb[0], rgb[1], rgb[2], 255);
				builder.addVertex(lengthStep*i, height, -halfWidth+widthStep*j).setColor(rgb[0], rgb[1], rgb[2], 255);
				builder.addVertex(lengthStep*i, height, -halfWidth+widthStep*(j+1)).setColor(rgb[0], rgb[1], rgb[2], 255);
				builder.addVertex(lengthStep*(i+1), height, -halfWidth+widthStep*(j+1)).setColor(rgb[0], rgb[1], rgb[2], 255);

				builder.addVertex(lengthStep*i, 0, -halfWidth+widthStep*j).setColor(rgb[0], rgb[1], rgb[2], 255);
				builder.addVertex(lengthStep*(i+1), 0, -halfWidth+widthStep*j).setColor(rgb[0], rgb[1], rgb[2], 255);
				builder.addVertex(lengthStep*(i+1), 0, -halfWidth+widthStep*(j+1)).setColor(rgb[0], rgb[1], rgb[2], 255);
				builder.addVertex(lengthStep*i, 0, -halfWidth+widthStep*(j+1)).setColor(rgb[0], rgb[1], rgb[2], 255);
			}

		matrixStackIn.popPose();
	}

private static void applyTransforms(PoseStack matrixStackIn, AbstractMinecart entityIn, float partialTicks, float entityYaw)
	{
		long i = (long)entityIn.getId()*493286711L;
		i = i*i*4392167121L+i*98761L;
		float f = (((float)(i >> 16&7L)+0.5F)/8.0F-0.5F)*0.004F;
		float f1 = (((float)(i >> 20&7L)+0.5F)/8.0F-0.5F)*0.004F;
		float f2 = (((float)(i >> 24&7L)+0.5F)/8.0F-0.5F)*0.004F;
		matrixStackIn.translate(f, f1, f2);
		double d0 = Mth.lerp(partialTicks, entityIn.xOld, entityIn.getX());
		double d1 = Mth.lerp(partialTicks, entityIn.yOld, entityIn.getY());
		double d2 = Mth.lerp(partialTicks, entityIn.zOld, entityIn.getZ());
		Vec3 vec3d = entityIn.getPos(d0, d1, d2);
		float f3 = Mth.lerp(partialTicks, entityIn.xRotO, entityIn.getXRot());
		if(vec3d!=null)
		{
			Vec3 vec3d1 = entityIn.getPosOffs(d0, d1, d2, 0.3F);
			Vec3 vec3d2 = entityIn.getPosOffs(d0, d1, d2, -0.3F);
			if(vec3d1==null)
				vec3d1 = vec3d;

			if(vec3d2==null)
				vec3d2 = vec3d;

			matrixStackIn.translate(vec3d.x-d0, (vec3d1.y+vec3d2.y)/2.0D-d1, vec3d.z-d2);
			Vec3 vec3d3 = vec3d2.add(-vec3d1.x, -vec3d1.y, -vec3d1.z);
			if(vec3d3.length()!=0.0D)
			{
				vec3d3 = vec3d3.normalize();
				entityYaw = (float)(Math.atan2(vec3d3.z, vec3d3.x)*180.0D/Math.PI);
				f3 = (float)(Math.atan(vec3d3.y)*73.0D);
			}
		}

		matrixStackIn.translate(0.0D, 0.375D, 0.0D);
		matrixStackIn.mulPose(
				new Quaternionf()
						.rotateY(Mth.PI - Mth.DEG_TO_RAD * entityYaw)
						.rotateZ(- Mth.DEG_TO_RAD * f3)
		);
		float f5 = (float)entityIn.getHurtTime()-partialTicks;
		float f6 = entityIn.getDamage()-partialTicks;
		if(f6 < 0.0F)
			f6 = 0.0F;

		if(f5 > 0.0F)
			matrixStackIn.mulPose(
					new Quaternionf().rotateZ(Mth.DEG_TO_RAD * Mth.sin(f5)*f5*f6/10.0F*(float)entityIn.getHurtDir())
			);
		matrixStackIn.scale(-1.0F, -1.0F, 1.0F);
	}

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn,
					   int combinedLightIn, int combinedOverlayIn)
	{
		final State state = ctx.getState();
		final Direction facing = ctx.getLevel().getOrientation().front();
		List<String> renderedParts = null;
		for(int i = 0; i < ArcFurnaceLogic.ELECTRODE_COUNT; i++)
			if((state.electrodePresence&(1<<i))!=0)
			{
				if(renderedParts==null)
					renderedParts = Lists.newArrayList("electrode"+(i+1));
				else
					renderedParts.add("electrode"+(i+1));
			}
		if(renderedParts==null)
			return;
		if(state.isClientActive())
			renderedParts.add("active");

		matrixStack.pushPose();
		List<BakedQuad> quads = ELECTRODES.get().getQuads(null, null, ApiUtils.RANDOM_SOURCE, ModelDataUtils.single(
				DynamicSubmodelCallbacks.getProperty(), VisibilityList.show(renderedParts)
		), RenderType.cutout());
		matrixStack.pushPose();
		rotateForFacing(matrixStack, facing);
		RenderUtils.renderModelTESRFast(
				quads, bufferIn.getBuffer(RenderType.solid()), matrixStack, combinedLightIn, combinedOverlayIn
		);
		matrixStack.popPose();
		matrixStack.translate(.5, .5, .5);

		if(state.pouringMetal > 0)
		{
			if(hotMetal_flow==null)
			{
				TextureAtlas blockMap = ClientUtils.mc().getModelManager().getAtlas(InventoryMenu.BLOCK_ATLAS);
				hotMetal_still = blockMap.getSprite(HOT_METLA_STILL);
				hotMetal_flow = blockMap.getSprite(HOT_METLA_FLOW);
			}
			rotateForFacingNoCentering(matrixStack, facing);
			int process = 40;
			float speed = 5f;
			int pour = process-state.pouringMetal;
			float h = (pour > (process-speed)?((process-pour)/speed*27): pour > speed?27: (pour/speed*27))/16f;
			matrixStack.translate(-.5f, 1.25-.6875f, 1.5f);
			VertexConsumer fullbright = bufferIn.getBuffer(IERenderTypes.SOLID_FULLBRIGHT);
			matrixStack.pushPose();
			if(pour > (process-speed))
				matrixStack.translate(0, -1.6875f+h, 0);
			if(h > 1)
			{
				matrixStack.translate(0, -h, 0);
				RenderUtils.renderTexturedBox(fullbright, matrixStack, .375F, 0, .375F, .625F, 1, .625F, hotMetal_flow, true);
				matrixStack.translate(0, 1, 0);
				RenderUtils.renderTexturedBox(fullbright, matrixStack, .375F, 0, .375F, .625F, h-1, .625F, hotMetal_flow, true);
				matrixStack.translate(0, -1, 0);
				matrixStack.translate(0, h, 0);
			}
			else
			{
				matrixStack.translate(0, -h, 0);
				RenderUtils.renderTexturedBox(fullbright, matrixStack, .375F, 0, .375F, .625F, h, .625F, hotMetal_flow, true);
				matrixStack.translate(0, h, 0);
			}
			if(pour > (process-speed))
				matrixStack.translate(0, 1.6875f-h, 0);
			if(pour > speed)
			{
				float h2 = (pour > (process-speed)?.625f: pour/(process-speed)*.625f);
				matrixStack.translate(0, -1.6875f, 0);
				RenderUtils.renderTexturedBox(fullbright, matrixStack, .125F, 0, .125F, .875F, h2, .875F, hotMetal_still, false);
				matrixStack.translate(0, 1.6875f, 0);
			}
			matrixStack.popPose();
		}
		matrixStack.popPose();
	}

@Override
	public void render(
			IMultiblockContext<State> ctx,
			float partialTicks,
			PoseStack matrixStack,
			MultiBufferSource bufferIn,
			int combinedLightIn,
			int combinedOverlayIn
	)
	{
		final BlockRenderDispatcher blockRenderer = Minecraft.getInstance().getBlockRenderer();
		BakedModel model = DYNAMIC.get();
		final State state = ctx.getState();

		//Item Displacement
		float[][] itemDisplays = new float[state.processor.getQueueSize()][];
		//Animations
		float drill = 0;
		float lift = 0;
		float press = 0;
		float liftPress = 0;

		Level level = ctx.getLevel().getRawLevel();
		for(int i = 0; i < itemDisplays.length; i++)
		{
			MultiblockProcess<?, ?> process = state.processor.getQueue().get(i);
			if(process==null||process.processTick <= 0||process.processTick==process.getMaxTicks(level))
				continue;
			//+partialTicks
			float processTimer = ((float)process.processTick)/process.getMaxTicks(level)*180;
			if(processTimer <= 9)
				continue;

			float itemX = -1;
			float itemY = -.34375f;
			float itemZ = -.9375f;
			float itemAngle = Mth.HALF_PI;

			if(processTimer <= 24)//slide
			{
				itemAngle = 67.5f * Mth.PI / 180;
				if(processTimer <= 19)
				{
					itemZ += .25+(19-processTimer)/10f*.5f;
					itemY += .25+(19-processTimer)/10f*.21875f;
				}
				else
				{
					itemZ += (24-processTimer)/5f*.25f;
					itemY += (24-processTimer)/5f*.25f;
				}
			}
			else if(processTimer <= 40)
			{
				itemX += (processTimer-24)/16f;
			}
			else if(processTimer <= 100)
			{
				itemX += 1;
				float drillStep = 0;
				if(processTimer <= 60)
				{
					lift = (processTimer-40)/20f*.3125f;
					drillStep = 4+(60-processTimer)*4;
				}
				else if(processTimer <= 80)
				{
					lift = .3125f;
					drillStep = 4;
				}
				else
				{
					lift = (100-processTimer)/20f*.3125f;
					drillStep = 4+(processTimer-80)*4;
				}
				if(drillStep > 0)
					drill = processTimer%drillStep/drillStep*2 * Mth.PI;
				itemY += Math.max(0, lift-.0625);
			}
			else if(processTimer <= 116)
			{
				itemX += 1;
				itemZ += (processTimer-100)/16f;
			}
			else if(processTimer <= 132)
			{
				itemX += 1+(processTimer-116)/16f;
				itemZ += 1;
			}
			else if(processTimer <= 172)
			{
				itemX += 2;
				itemZ += 1;
				if(processTimer <= 142)
					press = (processTimer-132)/10f;
				else if(processTimer <= 162)
					press = 1;
				else
					press = (172-processTimer)/10f;
				liftPress = press*.0625f;
				itemY += liftPress;
			}
			else if(processTimer <= 180)
			{
				itemX += 2+(processTimer-172)/16f;
				itemZ += 1;
			}
			itemDisplays[i] = new float[]{processTimer, itemX, itemY, itemZ, itemAngle};

		}

		final MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		bufferIn = BERenderUtils.mirror(orientation, matrixStack, bufferIn);
		Direction facing = orientation.front();
		if(orientation.mirrored())
		{
			if(facing.getAxis()==Axis.Z)
				matrixStack.translate(-1, 0, 0);
			else
				matrixStack.translate(0, 0, -1);
		}
		rotateForFacing(matrixStack, facing);
		matrixStack.translate(0.5, 0.5, 0.5);

		matrixStack.pushPose();
		ItemStack blueprintStack = state.inventory.getStackInSlot(AutoWorkbenchLogic.BLUEPRINT_SLOT);
		if(!blueprintStack.isEmpty())
			renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "blueprint");


		matrixStack.translate(0, lift, 0);
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "lift");
		matrixStack.translate(0, -lift, 0);

		float tx = 0;
		float tz = -.9375f;
		matrixStack.pushPose();
		matrixStack.translate(tx, 0, tz);
		matrixStack.mulPose(new Quaternionf().rotateXYZ(0, drill, 0));
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "drill");
		matrixStack.popPose();

		tx = 0;
		tz = -.59375f;
		matrixStack.pushPose();
		matrixStack.translate(tx, -.21875, tz);
		matrixStack.mulPose(new Quaternionf().rotateXYZ(press*Mth.HALF_PI, 0, 0));
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "press");
		matrixStack.popPose();

		matrixStack.translate(0, liftPress, 0);
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "pressLift");

		matrixStack.popPose();

		//DRAW ITEMS HERE
		for(int i = 0; i < itemDisplays.length; i++)
			if(itemDisplays[i]!=null)
			{
				MultiblockProcess<?, ?> process = state.processor.getQueue().get(i);
				if(!(process instanceof MultiblockProcessInWorld<?> inWorld))
					continue;

				float scale = .3125f;
				List<ItemStack> dList = inWorld.getDisplayItem(level);
				if(!dList.isEmpty())
					if(dList.size() < 2)
					{
						matrixStack.pushPose();
						matrixStack.translate(itemDisplays[i][1], itemDisplays[i][2], itemDisplays[i][3]);
						matrixStack.mulPose(new Quaternionf().rotateXYZ(itemDisplays[i][4], 0, 0));
						matrixStack.scale(scale, scale, .5f);
						ClientUtils.mc().getItemRenderer().renderStatic(
								dList.get(0), ItemDisplayContext.FIXED,
								combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
								level, 0
						);
						matrixStack.popPose();
					}
					else
					{
						int size = dList.size();
						int lines = (int)Math.ceil(size/2f);
						float spacer = (lines-1)*.234375f;
						for(int d = 0; d < size; d++)
						{
							float oX = (size > 2?-.3125f: 0)+(lines-d/2)*.0625f+d%2*.3125f;
							float oZ = -spacer/2f+d/2*.234375f;
							float oY = 0;

							float localItemX = itemDisplays[i][1]+oX;
							float localItemY = itemDisplays[i][2]+oY;
							float localItemZ = itemDisplays[i][3]+oZ;
							float subProcess = itemDisplays[i][0]-d/2*4;
							float localAngle = itemDisplays[i][4];
							if(subProcess <= 24)//slide
							{
								localAngle = 67.5f;
								if(subProcess <= 19)
								{
									localItemZ = -1+.25f+(19-subProcess)/10f*.5f;
									localItemY = -.34375f+.25f+(19-subProcess)/10f*.21875f;
								}
								else
								{
									localItemZ = -1+(oZ-(24-subProcess)/5f*oZ);
									localItemY = -.34375f+(24-subProcess)/5f*.25f;
								}
							}
							matrixStack.pushPose();
							matrixStack.translate(localItemX, localItemY, localItemZ);
							matrixStack.mulPose(new Quaternionf().rotateXYZ((float)Math.toRadians(localAngle), 0, 0));
							matrixStack.scale(scale, scale, .5f);
							ClientUtils.mc().getItemRenderer().renderStatic(
									dList.get(d), ItemDisplayContext.FIXED,
									combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
									level, 0
							);
							matrixStack.popPose();
						}
					}
			}

		//Blueprint
		double playerDistanceSq = ClientUtils.mc().player.distanceToSqr(Vec3.atCenterOf(
				ctx.getLevel().toAbsolute(IEMultiblockLogic.AUTO_WORKBENCH.masterPosInMB())
		));

		if(!blueprintStack.isEmpty()&&playerDistanceSq < 1000)
		{
			List<RecipeHolder<BlueprintCraftingRecipe>> recipes = BlueprintCraftingRecipe.findRecipes(level, IEApiDataComponents.getBlueprintType(blueprintStack));
			BlueprintCraftingRecipe recipe = (state.selectedRecipe < 0||state.selectedRecipe >= recipes.size())?null: recipes.get(state.selectedRecipe).value();
			BlueprintLines blueprint = recipe==null?null: getBlueprintDrawable(recipe, level);
			if(blueprint!=null)
			{
				matrixStack.pushPose();
				matrixStack.translate(-.195, .125, .97);
				matrixStack.mulPose(new Quaternionf().rotateXYZ(-Mth.PI / 4, 0, 0));
				float scale = .5f/blueprint.textureScale;
				matrixStack.scale(scale, -scale, scale);
				matrixStack.translate(0.5, 0.5, 0.5);
				blueprint.draw(matrixStack, bufferIn, combinedLightIn);
				matrixStack.popPose();
			}
		}
		matrixStack.popPose();
	}

public static void renderModelPart(
			PoseStack matrix, final BlockRenderDispatcher blockRenderer, MultiBufferSource buffers,
			BakedModel model, int light, int overlay, String parts
	)
	{
		matrix.pushPose();
		matrix.translate(-0.5, -0.5, -0.5);
		ModelData data = ModelDataUtils.single(DynamicSubmodelCallbacks.getProperty(), VisibilityList.show(parts));

		blockRenderer.getModelRenderer().renderModel(
				matrix.last(), buffers.getBuffer(RenderType.solid()), null, model,
				1, 1, 1,
				light, overlay, data, RenderType.solid()
		);
		matrix.popPose();
	}

@Override
	public void render(
			@Nonnull BlastFurnacePreheaterBlockEntity bEntity,
			float partial, @Nonnull PoseStack transform, @Nonnull MultiBufferSource buffers, int light, int overlay
	)
	{
		transform.pushPose();
		transform.translate(0.5, 0.5, 0.5);
		rotateForFacingNoCentering(transform, bEntity.getFacing());
		final float angle = bEntity.angle+BlastFurnacePreheaterBlockEntity.ANGLE_PER_TICK*(bEntity.active?partial: 0);
		Vector3f axis = new Vector3f(0, 0, 1);
		transform.mulPose(new Quaternionf().rotateAxis(angle, axis));
		transform.translate(-0.5, -0.5, -0.5);
		RenderUtils.renderModelTESRFast(
				MODEL.getNullQuads(), buffers.getBuffer(RenderType.solid()), transform, light, overlay
		);
		transform.popPose();
	}

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		final State state = ctx.getState();
		Direction facing = orientation.front();

		final float pixelHeight = 1f/16f;

		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);
		final MultiBufferSource originalBuffer = bufferIn;
		bufferIn = BERenderUtils.mirror(orientation, matrixStack, bufferIn);

		//Item Displacement
		record ItemDisplay(float itemFill, Vector3f translation, BottlingProcess process)
		{
		}
		List<ItemDisplay> itemDisplays = new ArrayList<>();
		//Animations
		float lift = 0;

		Level level = ctx.getLevel().getRawLevel();
		VertexConsumer solidBuilder = bufferIn.getBuffer(RenderType.solid());
		for(int i = 0; i < state.processor.getQueueSize(); i++)
		{
			BottlingProcess process = (BottlingProcess)state.processor.getQueue().get(i);
			if(process==null)
				continue;
			float processMaxTicks = process.getMaxTicks(level);
			float transportTime = BottlingMachineLogic.getTransportTime(processMaxTicks);
			float liftTime = BottlingMachineLogic.getLiftTime(processMaxTicks);
			float fProcess = process.processTick;

			float itemX;
			float itemY = 0;
			float itemFill = 0;

			if(fProcess < transportTime)
				itemX = .5f*fProcess/transportTime;
			else if(fProcess < (processMaxTicks-transportTime))
			{
				itemX = .5f;
				if(fProcess < transportTime+liftTime)
					lift = (fProcess-transportTime)/liftTime;
				else if(fProcess < processMaxTicks-(transportTime+liftTime))
				{
					lift = 1;
					itemFill = (fProcess-(transportTime+liftTime))/(processMaxTicks-2*(transportTime+liftTime));
				}
				else
				{
					lift = 1-(fProcess-(processMaxTicks-transportTime-liftTime))/liftTime;
					itemFill = 1;
				}
				lift *= .125f;
				if(lift > pixelHeight)
					itemY += lift-pixelHeight;
			}
			else
			{
				itemX = .5f+.5f*(fProcess-(processMaxTicks-transportTime))/transportTime;
				itemFill = 1;
			}
			itemDisplays.add(new ItemDisplay(
					itemFill,
					new Vector3f((itemX-0.5f)*BottlingMachineLogic.TRANSLATION_DISTANCE, itemY-.15625f, 1),
					process
			));
		}

		matrixStack.pushPose();

		matrixStack.translate(0, lift, 0);
		renderModelPart(matrixStack, solidBuilder, facing, combinedLightIn, combinedOverlayIn, "lift");
		matrixStack.translate(0, -lift, 0);

		matrixStack.popPose();

		float dir = facing==Direction.SOUTH?Mth.PI: facing==Direction.NORTH?0: facing==Direction.EAST?-Mth.HALF_PI: Mth.HALF_PI;
		matrixStack.mulPose(new Quaternionf().rotateY(dir));

		FluidStack fs = state.tank.getFluid();
		if(!fs.isEmpty())
		{
			final float tankWidth = 7;
			matrixStack.pushPose();
			float fluidLevel = fs.getAmount()/(float)state.tank.getCapacity();
			matrixStack.translate(-.21875, .376, 1.21875);
			matrixStack.scale(pixelHeight, pixelHeight, pixelHeight);
			matrixStack.translate(tankWidth/2, 0, -tankWidth/2);
			float h = fluidLevel*9;
			// TODO does not work on fabulous
			VertexConsumer builder = originalBuffer.getBuffer(RenderType.translucent());
			for(int i = 0; i < 4; ++i)
			{
				matrixStack.pushPose();
				matrixStack.translate(0, 0, -tankWidth/2);
				GuiHelper.drawRepeatedFluidSprite(builder, matrixStack, fs, -tankWidth/2, 0, tankWidth, h);
				matrixStack.popPose();
				matrixStack.mulPose(new Quaternionf().rotateY(Mth.HALF_PI));
			}

			matrixStack.mulPose(new Quaternionf().rotateX(-Mth.HALF_PI));
			GuiHelper.drawRepeatedFluidSprite(builder, matrixStack, fs, -tankWidth/2, -tankWidth/2, tankWidth, tankWidth);
			matrixStack.mulPose(new Quaternionf().rotateX(Mth.PI));
			matrixStack.translate(0, 0, -h);
			GuiHelper.drawRepeatedFluidSprite(builder, matrixStack, fs, -tankWidth/2, -tankWidth/2, tankWidth, tankWidth);

			matrixStack.popPose();
		}


		//DRAW ITEMS HERE
		for(ItemDisplay item : itemDisplays)
		{
			List<ItemStack> display = item.process.getDisplayItem(level);

			matrixStack.pushPose();
			matrixStack.translate(item.translation.x(), item.translation.y(), item.translation.z());
			matrixStack.scale(.4375f, .4375f, .4375f);

			if(!ClientUtils.mc().getMainRenderTarget().isStencilEnabled())
			{
				for(ItemStack displayS : display)
					ClientUtils.mc().getItemRenderer().renderStatic(
							displayS, ItemDisplayContext.FIXED,
							combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
							level, 0
					);
			}
			else
			{
				float h0 = -.5f;
				float h1 = h0+item.itemFill;

				for(ItemStack inputS : item.process.inputItems)
					renderItemPart(bufferIn, matrixStack, inputS, h0, h1, combinedLightIn, combinedOverlayIn, 0, level);
				for(ItemStack displayS : display)
					renderItemPart(bufferIn, matrixStack, displayS, h0, h1, combinedLightIn, combinedOverlayIn, 1, level);
			}

			matrixStack.popPose();
		}
		matrixStack.popPose();
	}

public static void renderModelPart(PoseStack matrixStack, VertexConsumer builder, Direction facing,
									   int combinedLightIn, int combinedOverlayIn, String... parts)
	{
		ModelData data = ModelDataUtils.single(DynamicSubmodelCallbacks.getProperty(), VisibilityList.show(parts));
		matrixStack.pushPose();
		matrixStack.translate(-.5, -.5, -.5);
		List<BakedQuad> quads = DYNAMIC.getNullQuads(data);
		rotateForFacing(matrixStack, facing);
		RenderUtils.renderModelTESRFast(quads, builder, matrixStack, combinedLightIn, combinedOverlayIn);
		matrixStack.popPose();
	}

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final Direction facing = ctx.getLevel().getOrientation().front();
		final State state = ctx.getState();
		final boolean mirrored = state.reverseRotation;
		matrixStack.pushPose();

		matrixStack.translate(.5, .5, .5);
		matrixStack.mulPose(new Quaternionf().rotateY(Mth.HALF_PI)); //to mirror different plane. compensate on dir rotate
		bufferIn = BERenderUtils.mirror(new MultiblockOrientation(facing, mirrored), matrixStack, bufferIn);
		float dir = facing==Direction.SOUTH?0: facing==Direction.NORTH?Mth.PI: facing==Direction.EAST?Mth.HALF_PI: -Mth.HALF_PI;
		matrixStack.mulPose(new Quaternionf().rotateY(dir));
		float rot = state.rotation+(float)(state.active?IEServerConfig.MACHINES.excavator_speed.get()*partialTicks: 0);
		matrixStack.mulPose(new Quaternionf().rotateX(rot*Mth.DEG_TO_RAD));

		matrixStack.translate(-.5, -.5, -.5);
		try
		{
			BucketWheelCallbacks.Key key = BucketWheelCallbacks.INSTANCE.extractKey(state);
			ModelData extraData = ModelDataUtils.single(IEOBJCallbacks.getModelProperty(BucketWheelCallbacks.INSTANCE), key);

			CACHED_BUFFERS.get(key, () -> IVertexBufferHolder.create(
					() -> WHEEL.get().getQuads(null, null, ApiUtils.RANDOM_SOURCE, extraData, RenderType.solid())
			)).render(RenderType.solid(), combinedLightIn, combinedOverlayIn, bufferIn, matrixStack, state.reverseRotation);
		} catch(ExecutionException ex)
		{
			throw new RuntimeException(ex);
		}
		matrixStack.popPose();
	}

