public static Transformation fromItemTransform(ItemTransform transform, boolean leftHand)
	{
		Vector3f translate = transform.translation;
		if(leftHand)
		{
			translate = new Vector3f(translate);
			translate.setComponent(0, -translate.x());
		}

		float leftRX = transform.rotation.x();
		float leftRY = transform.rotation.y();
		float leftRZ = transform.rotation.z();
		if(leftHand)
		{
			leftRY = -leftRY;
			leftRZ = -leftRZ;
		}
		Quaternionf leftRotation = new Quaternionf().rotateXYZ(
				Mth.DEG_TO_RAD * leftRX, Mth.DEG_TO_RAD * leftRY, Mth.DEG_TO_RAD * leftRZ
		);

		float rightRX = transform.rightRotation.x();
		float rightRY = transform.rightRotation.y()*(leftHand?-1: 1);
		float rightRZ = transform.rightRotation.z()*(leftHand?-1: 1);
		Quaternionf rightRotation = new Quaternionf().rotateXYZ(
				Mth.DEG_TO_RAD * rightRX, Mth.DEG_TO_RAD * rightRY, Mth.DEG_TO_RAD * rightRZ
		);

		return new Transformation(translate, leftRotation, transform.scale, rightRotation);
	}

public static void drawBlockDamageTexture(PoseStack matrix, MultiBufferSource buffers, Level world, Collection<BlockPos> blocks)
	{
		MultiPlayerGameMode controller = Minecraft.getInstance().gameMode;
		int progress = (int)(((PlayerControllerAccess)controller).getDestroyProgress()*10f)-1; // 0-10
		if(progress < 0||progress >= ModelBakery.DESTROY_TYPES.size())
			return;
		BlockRenderDispatcher blockrendererdispatcher = Minecraft.getInstance().getBlockRenderer();
		for(BlockPos blockpos : blocks)
		{
			matrix.pushPose();
			matrix.translate(blockpos.getX(), blockpos.getY(), blockpos.getZ());
			VertexConsumer worldRendererIn = buffers.getBuffer(ModelBakery.DESTROY_TYPES.get(progress));
			worldRendererIn = new SheetedDecalTextureGenerator(worldRendererIn, matrix.last(), 1);
			Block block = world.getBlockState(blockpos).getBlock();
			boolean hasBreak = block instanceof ChestBlock||block instanceof EnderChestBlock
					||block instanceof SignBlock||block instanceof SkullBlock;
			if(!hasBreak)
			{
				BlockState iblockstate = world.getBlockState(blockpos);
				if(!iblockstate.isAir())
					blockrendererdispatcher.renderBreakingTexture(iblockstate, blockpos, world, matrix, worldRendererIn);
			}
			matrix.popPose();
		}
	}

