private static SuperByteBuffer buildStructureBuffer(Contraption contraption, VirtualRenderWorld renderWorld, RenderType layer) {
		BlockRenderDispatcher dispatcher = Minecraft.getInstance().getBlockRenderer();
		ModelBlockRenderer renderer = dispatcher.getModelRenderer();
		ThreadLocalObjects objects = THREAD_LOCAL_OBJECTS.get();

		PoseStack poseStack = objects.poseStack;
		RandomSource random = objects.random;
		var clientContraption = contraption.getOrCreateClientContraptionLazy();
		RenderedBlocks blocks = clientContraption.getRenderedBlocks();

		ShadedBlockSbbBuilder sbbBuilder = objects.sbbBuilder;
		sbbBuilder.begin();

		ModelBlockRenderer.enableCaching();
		for (BlockPos pos : blocks.positions()) {
			BlockState state = blocks.lookup().apply(pos);
			if (state.getRenderShape() == RenderShape.MODEL) {
				BakedModel model = dispatcher.getBlockModel(state);
				ModelData modelData = renderWorld.getModelData(pos);
				modelData = model.getModelData(renderWorld, pos, state, modelData);
				long randomSeed = state.getSeed(pos);
				random.setSeed(randomSeed);
				if (model.getRenderTypes(state, random, modelData).contains(layer)) {
					poseStack.pushPose();
					poseStack.translate(pos.getX(), pos.getY(), pos.getZ());
					renderer.tesselateBlock(renderWorld, model, state, pos, poseStack, sbbBuilder, true, random, randomSeed, OverlayTexture.NO_OVERLAY, modelData, layer);
					poseStack.popPose();
				}
			}
		}
		ModelBlockRenderer.clearCache();

		return sbbBuilder.end();
	}

private static void renderActors(Level level, VirtualRenderWorld renderWorld, Contraption c,
		ContraptionMatrices matrices, MultiBufferSource buffer) {
		PoseStack m = matrices.getModel();

		for (Pair<StructureTemplate.StructureBlockInfo, MovementContext> actor : c.getActors()) {
			MovementContext context = actor.getRight();
			if (context == null)
				continue;
			if (context.world == null)
				context.world = level;
			StructureTemplate.StructureBlockInfo blockInfo = actor.getLeft();

			MovementBehaviour movementBehaviour = MovementBehaviour.REGISTRY.get(blockInfo.state());
			if (movementBehaviour != null) {
				if (c.isHiddenInPortal(blockInfo.pos()))
					continue;
				m.pushPose();
				TransformStack.of(m)
					.translate(blockInfo.pos());
				movementBehaviour.renderInContraption(context, renderWorld, matrices, buffer);
				m.popPose();
			}
		}
	}

@Override
	protected void renderWindow(GuiGraphics graphics, int mouseX, int mouseY, float partialTicks) {
		int x = this.width / 2;
		int y = this.height / 2;

		PoseStack ms = graphics.pose();

		ms.pushPose();
		ms.translate(x, y, 0);

		RenderSystem.enableBlend();
		RenderSystem.defaultBlendFunc();

		int mouseOffsetX = mouseX - this.width / 2;
		int mouseOffsetY = mouseY - this.height / 2;

		if (Mth.length(mouseOffsetX, mouseOffsetY) > innerRadius - 5) {
			double theta = Mth.atan2(mouseOffsetX, mouseOffsetY);

			float sectorSize = 360f / allStates.size();

			selectedStateIndex = (int) Math.floor(
				((-AngleHelper.deg(Mth.atan2(mouseOffsetX, mouseOffsetY)) + 180 + sectorSize / 2) % 360)
					/ sectorSize
			);

			renderDirectionIndicator(graphics, theta);
		}

		renderRadialSectors(graphics);

		UIRenderHelper.streak(graphics, 0, 0, 0, 32, 65, Color.BLACK.setAlpha(0.8f));
		UIRenderHelper.streak(graphics, 180, 0, 0, 32, 65, Color.BLACK.setAlpha(0.8f));

		if (selectedPropertyIndex > 0) {
			iconScroll.at(-14, -46).render(graphics);
			iconUp.at(-1, -46).render(graphics);
			graphics.drawCenteredString(font, propertiesForState.get(selectedPropertyIndex - 1).getValue(), 0, -30, UIRenderHelper.COLOR_TEXT.getFirst().getRGB());
		}

		if (selectedPropertyIndex < propertiesForState.size() - 1) {
			iconScroll.at(-14, 30).render(graphics);
			iconDown.at(-1, 30).render(graphics);
			graphics.drawCenteredString(font, propertiesForState.get(selectedPropertyIndex + 1).getValue(), 0, 22, UIRenderHelper.COLOR_TEXT.getFirst().getRGB());
		}

		graphics.drawCenteredString(font, "Currently", 0, -13, UIRenderHelper.COLOR_TEXT.getFirst().getRGB());
		graphics.drawCenteredString(font, "Changing:", 0, -3, UIRenderHelper.COLOR_TEXT.getFirst().getRGB());
		graphics.drawCenteredString(font, propertyLabel, 0, 7, UIRenderHelper.COLOR_TEXT.getFirst().getRGB());

		ms.popPose();

	}

private void renderRadialSectors(GuiGraphics graphics) {
		int sectors = allStates.size();
		if (sectors < 2)
			return;

		PoseStack poseStack = graphics.pose();
		LocalPlayer player = Minecraft.getInstance().player;
		if (player == null)
			return;

		float sectorAngle = 360f / sectors;
		int sectorWidth = outerRadius - innerRadius;

		poseStack.pushPose();

		for (int i = 0; i < sectors; i++) {
			Color innerColor = Color.WHITE.setAlpha(0.05f);
			Color outerColor = Color.WHITE.setAlpha(0.3f);
			BlockState blockState = allStates.get(i);
			Property<?> property = propertiesForState.get(selectedPropertyIndex).getKey();

			poseStack.pushPose();

			if (i == selectedStateIndex) {
				innerColor.mixWith(new Color(0.8f, 0.8f, 0.2f, 0.2f), 0.5f);
				outerColor.mixWith(new Color(0.8f, 0.8f, 0.2f, 0.6f), 0.5f);

				UIRenderHelper.drawRadialSector(graphics, outerRadius + 2, outerRadius + 3, -(sectorAngle / 2 + 90), sectorAngle, outerColor, outerColor);
			}

			UIRenderHelper.drawRadialSector(graphics, innerRadius, outerRadius, -(sectorAngle / 2 + 90), sectorAngle, innerColor, outerColor);
			Color c = innerColor.copy().setAlpha(0.5f);
			UIRenderHelper.drawRadialSector(graphics, innerRadius - 3, innerRadius - 2, -(sectorAngle / 2 + 90), sectorAngle, c, c);

			TransformStack.of(poseStack)
				.translateY(-(sectorWidth / 2f + innerRadius))
				.rotateZDegrees(-i * sectorAngle);

			poseStack.translate(0, 0, 100);

			try {
				withLevel(blockEntity, nonVisualizationLevel,
					() -> GuiGameElement.of(blockState, blockEntity)
						.rotateBlock(player.getXRot(), player.getYRot() + 180, 0f)
						.scale(24)
						.at(-12, 12)
						.render(graphics)
				);
			} catch (Exception e) {
				Create.LOGGER.warn("Failed to render blockstate in RadialWrenchMenu", e);
				allStates.remove(i);
				selectedStateIndex = 0;
				return;
			}

			poseStack.translate(0, 0, 50);

			if (i == selectedStateIndex) {
				graphics.drawCenteredString(font, blockState.getValue(property).toString(), 0, 15, UIRenderHelper.COLOR_TEXT.getFirst().getRGB());
			}

			poseStack.popPose();

			poseStack.pushPose();

			TransformStack.of(poseStack)
				.rotateZDegrees(sectorAngle / 2);

			poseStack.translate(0, -innerRadius - 20, 10);

			UIRenderHelper.angledGradient(graphics, -90, 0, 0, 0.5f, sectorWidth - 10, Color.WHITE.setAlpha(0.5f), Color.WHITE.setAlpha(0.15f));
			UIRenderHelper.angledGradient(graphics, 90, 0, 0, 0.5f, 25, Color.WHITE.setAlpha(0.5f), Color.WHITE.setAlpha(0.15f));
			poseStack.popPose();

			TransformStack.of(poseStack)
				.rotateZDegrees(sectorAngle);
		}

		poseStack.popPose();

	}

private void renderDirectionIndicator(GuiGraphics graphics, double theta) {
		PoseStack poseStack = graphics.pose();

		float r = 0.8f;
		float g = 0.8f;
		float b = 0.8f;

		poseStack.pushPose();
		TransformStack.of(poseStack)
			.rotateZ((float) -theta)
			.translateY(innerRadius + 3)
			.translateZ(15);

		RenderSystem.setShader(GameRenderer::getPositionColorShader);

		Tesselator tesselator = Tesselator.getInstance();
		BufferBuilder bufferbuilder = tesselator.begin(Mode.TRIANGLE_FAN, DefaultVertexFormat.POSITION_COLOR);

		Matrix4f mat = poseStack.last().pose();

		bufferbuilder.addVertex(mat, 0, 0, 0).setColor(r, g, b, 0.75f);

		bufferbuilder.addVertex(mat, 5, -5, 0).setColor(r, g, b, 0.4f);
		bufferbuilder.addVertex(mat, 3, -4.5f, 0).setColor(r, g, b, 0.4f);
		bufferbuilder.addVertex(mat, 0, -4.2f, 0).setColor(r, g, b, 0.4f);
		bufferbuilder.addVertex(mat, -3, -4.5f, 0).setColor(r, g, b, 0.4f);
		bufferbuilder.addVertex(mat, -5, -5, 0).setColor(r, g, b, 0.4f);

		BufferUploader.drawWithShader(bufferbuilder.buildOrThrow());

		poseStack.popPose();
	}

@Nullable
	public BlockPlaceContext updatePlacementContext(BlockPlaceContext pContext) { // TODO replace with placement helper
		BlockPos blockpos = pContext.getClickedPos();
		Level level = pContext.getLevel();
		BlockState blockstate = level.getBlockState(blockpos);
		Block block = this.getBlock();
		if (!blockstate.is(block))
			return pContext;

		Direction direction;
		if (pContext.isSecondaryUseActive()) {
			direction = pContext.isInside() ? pContext.getClickedFace()
				.getOpposite() : pContext.getClickedFace();
		} else {
			direction = pContext.getClickedFace() == Direction.UP ? pContext.getHorizontalDirection() : Direction.UP;
		}

		int i = 0;
		BlockPos.MutableBlockPos blockpos$mutableblockpos = blockpos.mutable()
			.move(direction);

		while (i < 7) {
			if (!level.isClientSide && !level.isInWorldBounds(blockpos$mutableblockpos)) {
				Player player = pContext.getPlayer();
				int j = level.getMaxBuildHeight();
				if (player instanceof ServerPlayer sp && blockpos$mutableblockpos.getY() >= j)
					sp.sendSystemMessage(Component.translatable("build.tooHigh", j - 1)
						.withStyle(ChatFormatting.RED), true);
				break;
			}

			blockstate = level.getBlockState(blockpos$mutableblockpos);
			if (!blockstate.is(this.getBlock())) {
				if (blockstate.canBeReplaced(pContext)) {
					return BlockPlaceContext.at(pContext, blockpos$mutableblockpos, direction);
				}
				break;
			}

			blockpos$mutableblockpos.move(direction);
			if (direction.getAxis()
				.isHorizontal()) {
				++i;
			}
		}

		return null;
	}

public @NonnullType BlockBuilder<B, CreateRegistrate> create(String variantName, PaletteBlockPattern pattern,
																 BlockEntry<? extends Block> block, AllPaletteStoneTypes variant) {
		String patternName = Lang.nonPluralId(pattern.createName(variantName));
		String blockName = patternName + "_" + this.name;

		BlockBuilder<B, CreateRegistrate> blockBuilder = Create.registrate()
			.block(blockName, p -> createBlock(block))
			.blockstate((c, p) -> generateBlockState(c, p, variantName, pattern, block))
			.recipe((c, p) -> createRecipes(variant, block, c, p))
			.transform(b -> transformBlock(b, variantName, pattern));

		ItemBuilder<BlockItem, BlockBuilder<B, CreateRegistrate>> itemBuilder = blockBuilder.item()
			.transform(b -> transformItem(b, variantName, pattern));

		if (canRecycle())
			itemBuilder.tag(variant.materialTag);

		return itemBuilder.build();
	}

@Override
	protected void renderSafe(PlacardBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay) {
		ItemStack heldItem = be.getHeldItem();
		if (heldItem.isEmpty())
			return;

		BlockState blockState = be.getBlockState();
		Direction facing = blockState.getValue(PlacardBlock.FACING);
		AttachFace face = blockState.getValue(PlacardBlock.FACE);

		ItemRenderer itemRenderer = Minecraft.getInstance()
			.getItemRenderer();
		BakedModel bakedModel = itemRenderer.getModel(heldItem, null, null, 0);
		boolean blockItem = bakedModel.isGui3d();

		ms.pushPose();
		TransformStack.of(ms)
			.center()
			.rotate((face == AttachFace.CEILING ? Mth.PI : 0) + AngleHelper.rad(180 + AngleHelper.horizontalAngle(facing)),
				Direction.UP)
			.rotate(face == AttachFace.CEILING ? -Mth.PI / 2 : face == AttachFace.FLOOR ? Mth.PI / 2 : 0,
				Direction.EAST)
			.translate(0, 0, 4.5 / 16f)
			.scale(blockItem ? .5f : .375f);

		itemRenderer.render(heldItem, ItemDisplayContext.FIXED, false, ms, buffer, light, overlay, bakedModel);
		ms.popPose();
	}

@OnlyIn(Dist.CLIENT)
	public static Pair<ScrollInput, Label> createWidget(int x, int y, Consumer<DoorControl> callback,
