public static void renderOverlay(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
		Minecraft mc = Minecraft.getInstance();
		if (mc.options.hideGui || mc.gameMode.getPlayerMode() == GameType.SPECTATOR)
			return;

		HitResult objectMouseOver = mc.hitResult;
		if (!(objectMouseOver instanceof BlockHitResult result)) {
			lastHovered = null;
			hoverTicks = 0;
			return;
		}

		for (OutlineEntry entry : outlines.values()) {
			if (!entry.isAlive())
				continue;
			Outline outline = entry.getOutline();
			if (outline instanceof ValueBox && !((ValueBox) outline).isPassive)
				return;
		}

		ClientLevel world = mc.level;
		BlockPos pos = result.getBlockPos();

		int prevHoverTicks = hoverTicks;
		hoverTicks++;
		lastHovered = pos;

		pos = proxiedOverlayPosition(world, pos);

		BlockEntity be = world.getBlockEntity(pos);
		boolean wearingGoggles = GogglesItem.isWearingGoggles(mc.player);

		boolean isShifting = mc.player.isShiftKeyDown();

		boolean hasGoggleInformation = be instanceof IHaveGoggleInformation;
		boolean hasHoveringInformation = be instanceof IHaveHoveringInformation;

		boolean goggleAddedInformation = false;
		boolean hoverAddedInformation = false;

		ItemStack item = AllItems.GOGGLES.asStack();
		List<Component> tooltip = new ArrayList<>();

		if (be instanceof IHaveCustomOverlayIcon customOverlayIcon)
			item = customOverlayIcon.getIcon(isShifting);

		if (hasGoggleInformation && wearingGoggles) {
			IHaveGoggleInformation gte = (IHaveGoggleInformation) be;
			goggleAddedInformation = gte.addToGoggleTooltip(tooltip, isShifting);
		}

		if (hasHoveringInformation) {
			if (!tooltip.isEmpty())
				tooltip.add(CommonComponents.EMPTY);
			IHaveHoveringInformation hte = (IHaveHoveringInformation) be;
			hoverAddedInformation = hte.addToTooltip(tooltip, isShifting);

			if (goggleAddedInformation && !hoverAddedInformation)
				tooltip.remove(tooltip.size() - 1);
		}

		if (be instanceof IDisplayAssemblyExceptions) {
			boolean exceptionAdded = ((IDisplayAssemblyExceptions) be).addExceptionToTooltip(tooltip);
			if (exceptionAdded) {
				hasHoveringInformation = true;
				hoverAddedInformation = true;
			}
		}

		if (!hasHoveringInformation)
			if (hasHoveringInformation =
				hoverAddedInformation = TrainRelocator.addToTooltip(tooltip, isShifting))
				hoverTicks = prevHoverTicks + 1;

		// break early if goggle or hover returned false when present
		if ((hasGoggleInformation && !goggleAddedInformation) && (hasHoveringInformation && !hoverAddedInformation)) {
			hoverTicks = 0;
			return;
		}

		// check for piston poles if goggles are worn
		BlockState state = world.getBlockState(pos);
		if (wearingGoggles && AllBlocks.PISTON_EXTENSION_POLE.has(state)) {
			Direction[] directions = Iterate.directionsInAxis(state.getValue(PistonExtensionPoleBlock.FACING)
				.getAxis());
			int poles = 1;
			boolean pistonFound = false;
			for (Direction dir : directions) {
				int attachedPoles = PistonExtensionPoleBlock.PlacementHelper.get()
					.attachedPoles(world, pos, dir);
				poles += attachedPoles;
				pistonFound |= world.getBlockState(pos.relative(dir, attachedPoles + 1))
					.getBlock() instanceof MechanicalPistonBlock;
			}

			if (!pistonFound) {
				hoverTicks = 0;
				return;
			}
			if (!tooltip.isEmpty())
				tooltip.add(CommonComponents.EMPTY);

			CreateLang.translate("gui.goggles.pole_length")
				.text(" " + poles)
				.forGoggles(tooltip);
		}

		if (tooltip.isEmpty()) {
			hoverTicks = 0;
			return;
		}

		PoseStack poseStack = guiGraphics.pose();
		poseStack.pushPose();

		int tooltipTextWidth = 0;
		for (FormattedText textLine : tooltip) {
			int textLineWidth = mc.font.width(textLine);
			if (textLineWidth > tooltipTextWidth)
				tooltipTextWidth = textLineWidth;
		}

		int tooltipHeight = 8;
		if (tooltip.size() > 1) {
			tooltipHeight += 2; // gap between title lines and next lines
			tooltipHeight += (tooltip.size() - 1) * 10;
		}

		int width = guiGraphics.guiWidth();
		int height = guiGraphics.guiHeight();

		CClient cfg = AllConfigs.client();
		int posX = width / 2 + cfg.overlayOffsetX.get();
		int posY = height / 2 + cfg.overlayOffsetY.get();

		posX = Math.min(posX, width - tooltipTextWidth - 20);
		posY = Math.min(posY, height - tooltipHeight - 20);

		float fade = Mth.clamp((hoverTicks + deltaTracker.getGameTimeDeltaPartialTick(false)) / 24f, 0, 1);
		Boolean useCustom = cfg.overlayCustomColor.get();
		Color colorBackground = useCustom ? new Color(cfg.overlayBackgroundColor.get())
			: BoxElement.COLOR_VANILLA_BACKGROUND.scaleAlpha(.75f);
		Color colorBorderTop = useCustom ? new Color(cfg.overlayBorderColorTop.get())
			: BoxElement.COLOR_VANILLA_BORDER.getFirst().copy();
		Color colorBorderBot = useCustom ? new Color(cfg.overlayBorderColorBot.get())
			: BoxElement.COLOR_VANILLA_BORDER.getSecond().copy();

		if (fade < 1) {
			poseStack.translate(Math.pow(1 - fade, 3) * Math.signum(cfg.overlayOffsetX.get() + .5f) * 8, 0, 0);
			colorBackground.scaleAlpha(fade);
			colorBorderTop.scaleAlpha(fade);
			colorBorderBot.scaleAlpha(fade);
		}

		GuiGameElement.of(item)
			.at(posX + 10, posY - 16, 450)
			.render(guiGraphics);

		if (!Mods.MODERNUI.isLoaded()) {
			// default tooltip rendering when modernUI is not loaded
			RemovedGuiUtils.drawHoveringText(guiGraphics, tooltip, posX, posY, width, height, -1, colorBackground.getRGB(),
				colorBorderTop.getRGB(), colorBorderBot.getRGB(), mc.font);

			poseStack.popPose();

			return;
		}

		/*
		 * special handling for modernUI
		 *
		 * their tooltip handler causes the overlay to jiggle each frame,
		 * if the mouse is moving, guiScale is anything but 1 and exactPositioning is enabled
		 *
		 * this is a workaround to fix this behavior
		 */
		MouseHandler mouseHandler = Minecraft.getInstance().mouseHandler;
		Window window = Minecraft.getInstance().getWindow();
		double guiScale = window.getGuiScale();
		double cursorX = mouseHandler.xpos();
		double cursorY = mouseHandler.ypos();
		((MouseHandlerAccessor) mouseHandler).create$setXPos(Math.round(cursorX / guiScale) * guiScale);
		((MouseHandlerAccessor) mouseHandler).create$setYPos(Math.round(cursorY / guiScale) * guiScale);

		RemovedGuiUtils.drawHoveringText(guiGraphics, tooltip, posX, posY, width, height, -1, colorBackground.getRGB(),
			colorBorderTop.getRGB(), colorBorderBot.getRGB(), mc.font);

		((MouseHandlerAccessor) mouseHandler).create$setXPos(cursorX);
		((MouseHandlerAccessor) mouseHandler).create$setYPos(cursorY);
		poseStack.popPose();

	}

public void render(PoseStack ms, MultiBufferSource buffer, int light, LivingEntity entity, float limbSwing, float limbSwingAmount,
					   float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
		PartialModel hat = EntityHats.getHatFor(entity);
		if (hat == null)
			return;

		M entityModel = getParentModel();
		ms.pushPose();

		var msr = TransformStack.of(ms);
		TrainHatInfo info = TrainHatInfoReloadListener.getHatInfoFor(entity);
		List<ModelPart> partsToHead = new ArrayList<>();

		if (entityModel instanceof AgeableListModel<?> model) {
			if (model.young) {
				if (model.scaleHead) {
					float f = 1.5F / model.babyHeadScale;
					ms.scale(f, f, f);
				}
				ms.translate(0.0D, model.babyYHeadOffset / 16.0F, model.babyZHeadOffset / 16.0F);
			}

			ModelPart head = getHeadPart(model);
			if (head != null) {
				partsToHead.addAll(TrainHatInfo.getAdjustedPart(info, head, ""));
			}
		} else if (entityModel instanceof HierarchicalModel<?> model) {
			partsToHead.addAll(TrainHatInfo.getAdjustedPart(info, model.root(), "head"));
		}

		if (!partsToHead.isEmpty()) {
			partsToHead.forEach(part -> part.translateAndRotate(ms));

			ModelPart lastChild = partsToHead.get(partsToHead.size() - 1);
			if (!lastChild.isEmpty()) {
				Cube cube = lastChild.cubes.get(Mth.clamp(info.cubeIndex(), 0, lastChild.cubes.size() - 1));
				ms.translate(info.offset().x() / 16.0F, (cube.minY - cube.maxY + info.offset().y()) / 16.0F, info.offset().z() / 16.0F);
				float max = Math.max(cube.maxX - cube.minX, cube.maxZ - cube.minZ) / 8.0F * info.scale();
				ms.scale(max, max, max);
			}

			ms.scale(1, -1, -1);
			ms.translate(0, -2.25F / 16.0F, 0);
			msr.rotateXDegrees(-8.5F);
			BlockState air = Blocks.AIR.defaultBlockState();
			CachedBuffers.partial(hat, air)
				.disableDiffuse()
				.light(light)
				.renderInto(ms, buffer.getBuffer(Sheets.cutoutBlockSheet()));
		}

		ms.popPose();
	}

@Override
	@OnlyIn(Dist.CLIENT)
	public void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltip, TooltipFlag flag) {
		LocalPlayer player = Minecraft.getInstance().player;
		if (player == null) {
			super.appendHoverText(stack, context, tooltip, flag);
			return;
		}

		Ammo ammo = getAmmo(player, stack);
		if (ammo == null) {
			super.appendHoverText(stack, context, tooltip, flag);
			return;
		}
		ItemStack ammoStack = ammo.stack();
		PotatoCannonProjectileType type = ammo.type();

		HolderLookup.Provider registries = context.registries();
		if (registries == null)
			return;

		HolderLookup<Enchantment> lookup = registries.lookupOrThrow(Registries.ENCHANTMENT);
		int power = stack.getEnchantmentLevel(lookup.getOrThrow(Enchantments.POWER));
		int punch = stack.getEnchantmentLevel(lookup.getOrThrow(Enchantments.PUNCH));
		final float additionalDamageMult = 1 + power * .2f;
		final float additionalKnockback = punch * .5f;

		String _attack = "potato_cannon.ammo.attack_damage";
		String _reload = "potato_cannon.ammo.reload_ticks";
		String _knockback = "potato_cannon.ammo.knockback";

		tooltip.add(CommonComponents.EMPTY);
		tooltip.add(Component.translatable(ammoStack.getDescriptionId()).append(Component.literal(":"))
			.withStyle(ChatFormatting.GRAY));
		MutableComponent spacing = CommonComponents.space();
		ChatFormatting green = ChatFormatting.GREEN;
		ChatFormatting darkGreen = ChatFormatting.DARK_GREEN;

		float damageF = type.damage() * additionalDamageMult;
		MutableComponent damage = Component.literal(damageF == Mth.floor(damageF) ? "" + Mth.floor(damageF) : "" + damageF);
		MutableComponent reloadTicks = Component.literal("" + type.reloadTicks());
		MutableComponent knockback =
			Component.literal("" + (type.knockback() + additionalKnockback));

		damage = damage.withStyle(additionalDamageMult > 1 ? green : darkGreen);
		knockback = knockback.withStyle(additionalKnockback > 0 ? green : darkGreen);
		reloadTicks = reloadTicks.withStyle(darkGreen);

		tooltip.add(spacing.plainCopy()
			.append(CreateLang.translateDirect(_attack, damage)
				.withStyle(darkGreen)));
		tooltip.add(spacing.plainCopy()
			.append(CreateLang.translateDirect(_reload, reloadTicks)
				.withStyle(darkGreen)));
		tooltip.add(spacing.plainCopy()
			.append(CreateLang.translateDirect(_knockback, knockback)
				.withStyle(darkGreen)));
	}

@Override
	protected void render(ItemStack stack, CustomRenderedItemModel model, PartialItemModelRenderer renderer,
						  ItemDisplayContext transformType, PoseStack ms, MultiBufferSource buffer, int light, int overlay) {
		renderer.render(model.getOriginalModel(), light);
		Minecraft mc = Minecraft.getInstance();
		LocalPlayer player = mc.player;

		float angle = AnimationTickHolder.getRenderTime() * -2.5f;

		if (player != null) {
			boolean inMainHand = player.getMainHandItem() == stack;
			boolean inOffHand = player.getOffhandItem() == stack;

			if (inMainHand || inOffHand) {
				boolean leftHanded = player.getMainArm() == HumanoidArm.LEFT;
				float speed = CreateClient.POTATO_CANNON_RENDER_HANDLER.getAnimation(inMainHand ^ leftHanded,
					AnimationTickHolder.getPartialTicks());
				angle += 360 * Mth.clamp(speed * 5, 0, 1);
			}
		}

		angle %= 360;
		float offset = .5f / 16;

		ms.pushPose();
		ms.translate(0, offset, 0);
		ms.mulPose(Axis.ZP.rotationDegrees(angle));
		ms.translate(0, -offset, 0);
		renderer.render(COG.get(), light);
		ms.popPose();
	}

@Override
	public void render(PotatoProjectileEntity entity, float yaw, float pt, PoseStack ms, MultiBufferSource buffer,
		int light) {
		ItemStack item = entity.getItem();
		if (item.isEmpty())
			return;
		ms.pushPose();
		ms.translate(0, entity.getBoundingBox()
			.getYsize() / 2 - 1 / 8f, 0);
		entity.getRenderMode()
			.transform(ms, entity, pt);

		Minecraft.getInstance()
			.getItemRenderer()
			.renderStatic(item, ItemDisplayContext.GROUND, light, OverlayTexture.NO_OVERLAY, ms, buffer, entity.level(),
				0);
		ms.popPose();
	}

@Override
	protected void render(ItemStack stack, CustomRenderedItemModel model, PartialItemModelRenderer renderer,
		ItemDisplayContext transformType, PoseStack ms, MultiBufferSource buffer, int light, int overlay) {
		Minecraft mc = Minecraft.getInstance();
		ItemRenderer itemRenderer = mc.getItemRenderer();
		LocalPlayer player = mc.player;
		float partialTicks = AnimationTickHolder.getPartialTicks();

		boolean leftHand = transformType == ItemDisplayContext.FIRST_PERSON_LEFT_HAND;
		boolean firstPerson = leftHand || transformType == ItemDisplayContext.FIRST_PERSON_RIGHT_HAND;

		boolean jeiMode = stack.has(AllDataComponents.SAND_PAPER_JEI);

		ms.pushPose();

		if (stack.has(AllDataComponents.SAND_PAPER_POLISHING)) {
			ms.pushPose();

			if (transformType == ItemDisplayContext.GUI) {
				ms.translate(0.0F, .2f, 1.0F);
				ms.scale(.75f, .75f, .75f);
			} else {
				int modifier = leftHand ? -1 : 1;
				ms.mulPose(Axis.YP.rotationDegrees(modifier * 40));
			}

			// Reverse bobbing
			float time = (float) (!jeiMode ? player.getUseItemRemainingTicks()
					: (-AnimationTickHolder.getTicks()) % stack.getUseDuration(player)) - partialTicks + 1.0F;
			if (time / (float) stack.getUseDuration(player) < 0.8F) {
				float bobbing = -Mth.abs(Mth.cos(time / 4.0F * (float) Math.PI) * 0.1F);

				if (transformType == ItemDisplayContext.GUI)
					ms.translate(bobbing, bobbing, 0.0F);
				else
					ms.translate(0.0f, bobbing, 0.0F);
			}

			ItemStack toPolish = stack.get(AllDataComponents.SAND_PAPER_POLISHING).item();
			//noinspection DataFlowIssue - We call .has, toPolish won't be null
			itemRenderer.renderStatic(toPolish, ItemDisplayContext.GUI, light, overlay, ms, buffer, player.level(), 0);

			ms.popPose();
		}

		if (firstPerson) {
			int itemInUseCount = player.getUseItemRemainingTicks();
			if (itemInUseCount > 0) {
				int modifier = leftHand ? -1 : 1;
				ms.translate(modifier * .5f, 0, -.25f);
				ms.mulPose(Axis.ZP.rotationDegrees(modifier * 40));
				ms.mulPose(Axis.XP.rotationDegrees(modifier * 10));
				ms.mulPose(Axis.YP.rotationDegrees(modifier * 90));
			}
		}

		itemRenderer.render(stack, ItemDisplayContext.NONE, false, ms, buffer, light, overlay, model.getOriginalModel());

		ms.popPose();
	}

@OnlyIn(Dist.CLIENT)
	@SubscribeEvent
	public static void onRenderWorld(RenderLevelStageEvent event) {
		if (event.getStage() != Stage.AFTER_PARTICLES)
			return;

		Minecraft mc = Minecraft.getInstance();
		LocalPlayer player = mc.player;
		RandomSource random = RandomSource.create();

		for (int i = 0; i < Inventory.getSelectionSize(); i++) {
			ItemStack stackInSlot = player.getInventory()
				.getItem(i);
			if (!AllItems.WAND_OF_SYMMETRY.isIn(stackInSlot))
				continue;
			if (!SymmetryWandItem.isEnabled(stackInSlot))
				continue;
			SymmetryMirror mirror = SymmetryWandItem.getMirror(stackInSlot);
			if (mirror instanceof EmptyMirror)
				continue;

			BlockPos pos = BlockPos.containing(mirror.getPosition());

			float yShift = 0;
			double speed = 1 / 16d;
			yShift = Mth.sin((float) (AnimationTickHolder.getRenderTime() * speed)) / 5f;

			MultiBufferSource.BufferSource buffer = mc.renderBuffers()
				.bufferSource();
			Camera info = mc.gameRenderer.getMainCamera();
			Vec3 view = info.getPosition();

			PoseStack ms = event.getPoseStack();
			ms.pushPose();
			ms.translate(pos.getX() - view.x(), pos.getY() - view.y(), pos.getZ() - view.z());
			ms.translate(0, yShift + .2f, 0);
			mirror.applyModelTransform(ms);
			BakedModel model = mirror.getModel()
				.get();
			VertexConsumer builder = buffer.getBuffer(RenderType.solid());

			mc.getBlockRenderer()
				.getModelRenderer()
