public static void renderItem(ChuteBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay) {
		ItemRenderer itemRenderer = Minecraft.getInstance()
			.getItemRenderer();
		var msr = TransformStack.of(ms);
		ms.pushPose();
		msr.center();
		float itemScale = .5f;
		float itemPosition = be.itemPosition.getValue(partialTicks);
		ms.translate(0, -.5 + itemPosition, 0);
		if (PackageItem.isPackage(be.item)) {
			ms.scale(1.5f, 1.5f, 1.5f);
		} else {
			ms.scale(itemScale, itemScale, itemScale);
			msr.rotateXDegrees(itemPosition * 180);
			msr.rotateYDegrees(itemPosition * 180);
		}
		itemRenderer.renderStatic(be.item, ItemDisplayContext.FIXED, light, overlay, ms, buffer, be.getLevel(), 0);
		ms.popPose();
	}

public static void renderItemsOf(SmartBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay, DepotBehaviour depotBehaviour) {

		TransportedItemStack transported = depotBehaviour.heldItem;
		var msr = TransformStack.of(ms);
		Vec3 itemPosition = VecHelper.getCenterOf(be.getBlockPos());

		ms.pushPose();
		ms.translate(.5f, 15 / 16f, .5f);

		if (transported != null)
			depotBehaviour.incoming.add(transported);

		// Render main items
		for (TransportedItemStack tis : depotBehaviour.incoming) {
			ms.pushPose();
			msr.nudge(0);
			float offset = Mth.lerp(partialTicks, tis.prevBeltPosition, tis.beltPosition);
			float sideOffset = Mth.lerp(partialTicks, tis.prevSideOffset, tis.sideOffset);

			if (tis.insertedFrom.getAxis()
				.isHorizontal()) {
				Vec3 offsetVec = Vec3.atLowerCornerOf(tis.insertedFrom.getOpposite()
					.getNormal())
					.scale(.5f - offset);
				ms.translate(offsetVec.x, offsetVec.y, offsetVec.z);
				boolean alongX = tis.insertedFrom.getClockWise()
					.getAxis() == Direction.Axis.X;
				if (!alongX)
					sideOffset *= -1;
				ms.translate(alongX ? sideOffset : 0, 0, alongX ? 0 : sideOffset);
			}

			ItemStack itemStack = tis.stack;
			int angle = tis.angle;
			Random r = new Random(0);
			renderItem(ms, buffer, light, overlay, itemStack, angle, r, itemPosition, false);
			ms.popPose();
		}

		if (transported != null)
			depotBehaviour.incoming.remove(transported);

		// Render output items
		for (int i = 0; i < depotBehaviour.processingOutputBuffer.getSlots(); i++) {
			ItemStack stack = depotBehaviour.processingOutputBuffer.getStackInSlot(i);
			if (stack.isEmpty())
				continue;
			ms.pushPose();
			msr.nudge(i);

			boolean renderUpright = BeltHelper.isItemUpright(stack);
			msr.rotateYDegrees(360 / 8f * i);
			ms.translate(.35f, 0, 0);
			if (renderUpright)
				msr.rotateYDegrees(-(360 / 8f * i));
			Random r = new Random(i + 1);
			int angle = (int) (360 * r.nextFloat());
			renderItem(ms, buffer, light, overlay, stack, renderUpright ? angle + 90 : angle, r,
				itemPosition, false);
			ms.popPose();
		}

		ms.popPose();
	}

public static void renderItem(PoseStack ms, MultiBufferSource buffer, int light, int overlay,
								  ItemStack itemStack, int angle, Random r, Vec3 itemPosition, boolean alwaysUpright) {
		ItemRenderer itemRenderer = Minecraft.getInstance()
			.getItemRenderer();
		var msr = TransformStack.of(ms);
		int count = Mth.log2((itemStack.getCount())) / 2;
		BakedModel bakedModel = itemRenderer.getModel(itemStack, null, null, 0);
		boolean blockItem = bakedModel.isGui3d();
		boolean renderUpright = BeltHelper.isItemUpright(itemStack) || alwaysUpright && !blockItem;

		ms.pushPose();
		msr.rotateYDegrees(angle);

		if (renderUpright) {
			Vec3 cameraPosition = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
			Vec3 diff = itemPosition.subtract(cameraPosition);
			float yRot = (float) (Mth.atan2(diff.x, diff.z) + Math.PI);
			ms.mulPose(Axis.YP.rotation(yRot));
			ms.translate(0, 3 / 32d, -1 / 16f);
		}

		for (int i = 0; i <= count; i++) {
			ms.pushPose();
			if (blockItem && r != null)
				ms.translate(r.nextFloat() * .0625f * i, 0, r.nextFloat() * .0625f * i);

			if (PackageItem.isPackage(itemStack) && !alwaysUpright) {
				ms.translate(0, 4 / 16f, 0);
				ms.scale(1.5f, 1.5f, 1.5f);
			} else if (blockItem && alwaysUpright) {
				ms.translate(0, 1 / 16f, 0);
				ms.scale(.755f, .755f, .755f);
			} else
				ms.scale(.5f, .5f, .5f);

			if (!blockItem && !renderUpright) {
				ms.translate(0, -3 / 16f, 0);
				msr.rotateXDegrees(90);
			}
			itemRenderer.render(itemStack, ItemDisplayContext.FIXED, false, ms, buffer, light, overlay, bakedModel);
			ms.popPose();

			if (!renderUpright) {
				if (!blockItem)
					msr.rotateYDegrees(10);
				ms.translate(0, blockItem ? 1 / 64d : 1 / 16d, 0);
			} else
				ms.translate(0, 0, -1 / 16f);
		}

		ms.popPose();
	}

@Override
	protected void renderSafe(EjectorBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay) {
		super.renderSafe(be, partialTicks, ms, buffer, light, overlay);

		float lidProgress = be.getLidProgress(partialTicks);
		float angle = lidProgress * 70;

		if (!VisualizationManager.supportsVisualization(be.getLevel())) {
			SuperByteBuffer model = CachedBuffers.partial(AllPartialModels.EJECTOR_TOP, be.getBlockState());
			applyLidAngle(be, angle, model);
			model.light(light)
					.renderInto(ms, buffer.getBuffer(RenderType.solid()));
		}

		var msr = TransformStack.of(ms);

		float maxTime =
				(float) (be.earlyTarget != null ? be.earlyTargetTime : be.launcher.getTotalFlyingTicks());
		for (IntAttached<ItemStack> intAttached : be.launchedItems) {
			float time = intAttached.getFirst() + partialTicks;
			if (time > maxTime)
				continue;

			ms.pushPose();
			Vec3 launchedItemLocation = be.getLaunchedItemLocation(time);
			msr.translate(launchedItemLocation.subtract(Vec3.atLowerCornerOf(be.getBlockPos())));
			Vec3 itemRotOffset = VecHelper.voxelSpace(0, 2, -1);
			msr.translate(itemRotOffset);

			if (PackageItem.isPackage(intAttached.getValue())) {
				ms.translate(0, 4 / 16f, 0);
				ms.scale(1.5f, 1.5f, 1.5f);
				msr.rotateYDegrees(time * 20);
			} else {
				ms.scale(.5f, .5f, .5f);
				msr.rotateYDegrees(AngleHelper.horizontalAngle(be.getFacing()));
				msr.rotateXDegrees(time * 40);
			}
			msr.translateBack(itemRotOffset);
			Minecraft.getInstance()
				.getItemRenderer()
				.renderStatic(intAttached.getValue(), ItemDisplayContext.FIXED, light, overlay, ms, buffer, be.getLevel(), 0);
			ms.popPose();
		}

		DepotBehaviour behaviour = be.getBehaviour(DepotBehaviour.TYPE);
		if (behaviour == null || behaviour.isEmpty())
			return;

		ms.pushPose();
		applyLidAngle(be, angle, msr);
		msr.center()
			.rotateYDegrees(-180 - AngleHelper.horizontalAngle(be.getBlockState()
				.getValue(EjectorBlock.HORIZONTAL_FACING)))
			.uncenter();
		DepotRenderer.renderItemsOf(be, partialTicks, ms, buffer, light, overlay, behaviour);
		ms.popPose();
	}

public static void renderBulb(FactoryPanelBehaviour behaviour, float partialTicks, PoseStack ms,
		MultiBufferSource buffer, int light, int overlay) {
		BlockState blockState = behaviour.blockEntity.getBlockState();

		float xRot = FactoryPanelBlock.getXRot(blockState) + Mth.PI / 2;
		float yRot = FactoryPanelBlock.getYRot(blockState);
		float glow = behaviour.bulb.getValue(partialTicks);

		boolean missingAddress = behaviour.isMissingAddress();
		PartialModel partial = behaviour.redstonePowered || missingAddress ? AllPartialModels.FACTORY_PANEL_RED_LIGHT
			: AllPartialModels.FACTORY_PANEL_LIGHT;

		CachedBuffers.partial(partial, blockState)
			.rotateCentered(yRot, Direction.UP)
			.rotateCentered(xRot, Direction.EAST)
			.rotateCentered(Mth.PI, Direction.UP)
			.translate(behaviour.slot.xOffset * .5, 0, behaviour.slot.yOffset * .5)
			.light(glow > 0.125f ? LightTexture.FULL_BRIGHT : light)
			.overlay(overlay)
			.renderInto(ms, buffer.getBuffer(RenderType.translucent()));

		if (glow < .125f)
			return;

		glow = (float) (1 - (2 * Math.pow(glow - .75f, 2)));
		glow = Mth.clamp(glow, -1, 1);
		int color = (int) (200 * glow);

		CachedBuffers.partial(partial, blockState)
			.rotateCentered(yRot, Direction.UP)
			.rotateCentered(xRot, Direction.EAST)
			.rotateCentered(Mth.PI, Direction.UP)
			.translate(behaviour.slot.xOffset * .5, 0, behaviour.slot.yOffset * .5)
			.light(LightTexture.FULL_BRIGHT)
			.color(color, color, color, 255)
			.overlay(overlay)
			.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));
	}

public static void renderPath(FactoryPanelBehaviour behaviour, FactoryPanelConnection connection,
		float partialTicks, PoseStack ms, MultiBufferSource buffer, int light, int overlay) {
		BlockState blockState = behaviour.blockEntity.getBlockState();
		List<Direction> path = connection.getPath(behaviour.getWorld(), blockState, behaviour.getPanelPosition());

		float xRot = FactoryPanelBlock.getXRot(blockState) + Mth.PI / 2;
		float yRot = FactoryPanelBlock.getYRot(blockState);
		float glow = behaviour.bulb.getValue(partialTicks);

		FactoryPanelSupportBehaviour sbe = FactoryPanelBehaviour.linkAt(behaviour.getWorld(), connection);
		boolean displayLinkMode = sbe != null && sbe.blockEntity instanceof DisplayLinkBlockEntity;
		boolean redstoneLinkMode = sbe != null && sbe.blockEntity instanceof RedstoneLinkBlockEntity;
		boolean pathReversed = sbe != null && !sbe.isOutput();

		int color = 0;
		float yOffset = 0;
		boolean success = connection.success;
		boolean dots = false;

		if (displayLinkMode) {
			// Display status
			color = 0x3C9852;
			dots = true;

		} else if (redstoneLinkMode) {
			// Link status
			color = pathReversed ? (behaviour.count == 0 ? 0x888898 : behaviour.satisfied ? 0xEF0000 : 0x580101)
				: (behaviour.redstonePowered ? 0xEF0000 : 0x580101);
			yOffset = 0.5f;

		} else {
			// Regular ingredient status
			color = behaviour.getIngredientStatusColor();

			yOffset = 1;
			yOffset += behaviour.promisedSatisfied ? 1 : behaviour.satisfied ? 0 : 2;

			if (!behaviour.redstonePowered && !behaviour.waitingForNetwork && glow > 0 && !behaviour.satisfied) {
				float p = (1 - (1 - glow) * (1 - glow));
				color = Color.mixColors(color, success ? 0xEAF2EC : 0xE5654B, p);
				if (!behaviour.satisfied && !behaviour.promisedSatisfied)
					yOffset += (success ? 1 : 2) * p;
			}
		}

		float currentX = 0;
		float currentZ = 0;

		for (int i = 0; i < path.size(); i++) {
			Direction direction = path.get(i);

			if (!pathReversed) {
				currentX += direction.getStepX() * .5;
				currentZ += direction.getStepZ() * .5;
			}

			boolean isArrowSegment = pathReversed ? i == path.size() - 1 : i == 0;
			PartialModel partial = (dots ? AllPartialModels.FACTORY_PANEL_DOTTED
				: isArrowSegment ? AllPartialModels.FACTORY_PANEL_ARROWS : AllPartialModels.FACTORY_PANEL_LINES)
					.get(pathReversed ? direction : direction.getOpposite());
			SuperByteBuffer connectionSprite = CachedBuffers.partial(partial, blockState)
				.rotateCentered(yRot, Direction.UP)
				.rotateCentered(xRot, Direction.EAST)
				.rotateCentered(Mth.PI, Direction.UP)
				.translate(behaviour.slot.xOffset * .5 + .25, 0, behaviour.slot.yOffset * .5 + .25)
				.translate(currentX, (yOffset + (direction.get2DDataValue() % 2) * 0.125f) / 512f, currentZ);

			if (!displayLinkMode && !redstoneLinkMode && !behaviour.isMissingAddress() && !behaviour.waitingForNetwork
				&& !behaviour.satisfied && !behaviour.redstonePowered)
				connectionSprite.shiftUV(AllSpriteShifts.FACTORY_PANEL_CONNECTIONS);

			connectionSprite.color(color)
				.light(light)
				.overlay(overlay)
				.renderInto(ms, buffer.getBuffer(RenderType.cutoutMipped()));

			if (pathReversed) {
				currentX += direction.getStepX() * .5;
				currentZ += direction.getStepZ() * .5;
			}
		}
	}

