@Override
	protected void renderSafe(LinkWithBulbBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay) {
		float glow = be.getGlow(partialTicks);
		if (glow < .125f)
			return;

		glow = (float) (1 - (2 * Math.pow(glow - .75f, 2)));
		glow = Mth.clamp(glow, -1, 1);

		int color = (int) (200 * glow);

		BlockState blockState = be.getBlockState();
		var msr = TransformStack.of(ms);

		Direction face = be.getBulbFacing(blockState);

		ms.pushPose();

		msr.center()
			.rotateYDegrees(AngleHelper.horizontalAngle(face) + 180)
			.rotateXDegrees(-AngleHelper.verticalAngle(face) - 90)
			.uncenter();

		CachedBuffers.partial(AllPartialModels.DISPLAY_LINK_TUBE, blockState)
			.translate(be.getBulbOffset(blockState))
			.light(LightTexture.FULL_BRIGHT)
			.renderInto(ms, buffer.getBuffer(RenderType.translucent()));

		CachedBuffers.partial(AllPartialModels.DISPLAY_LINK_GLOW, blockState)
			.translate(be.getBulbOffset(blockState))
			.light(LightTexture.FULL_BRIGHT)
			.color(color, color, color, 255)
			.disableDiffuse()
			.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));

		ms.popPose();
	}

private Stream<List<MutableComponent>> getComponents(DisplayLinkContext context, boolean forFlapDisplay) {
		BlockEntity sourceBE = context.getSourceBlockEntity();
		if (!(sourceBE instanceof FluidTankBlockEntity tankBlockEntity))
			return Stream.of(EMPTY);

		tankBlockEntity = tankBlockEntity.getControllerBE();
		if (tankBlockEntity == null)
			return Stream.of(EMPTY);

		BoilerData boiler = tankBlockEntity.boiler;

		int totalTankSize = tankBlockEntity.getTotalTankSize();

		boiler.calcMinMaxForSize(totalTankSize);

		String label = forFlapDisplay ? "boiler.status" : "boiler.status_short";
		MutableComponent size = labelOf(forFlapDisplay ? "size" : "");
		MutableComponent water = labelOf(forFlapDisplay ? "water" : "");
		MutableComponent heat = labelOf(forFlapDisplay ? "heat" : "");

		int lw = labelWidth();
		if (forFlapDisplay) {
			size = Component.literal(Strings.repeat(' ', lw - labelWidthOf("size"))).append(size);
			water = Component.literal(Strings.repeat(' ', lw - labelWidthOf("water"))).append(water);
			heat = Component.literal(Strings.repeat(' ', lw - labelWidthOf("heat"))).append(heat);
		}

		return Stream.of(List.of(CreateLang.translateDirect(label, boiler.getHeatLevelTextComponent())),
			List.of(size, boiler.getSizeComponent(!forFlapDisplay, forFlapDisplay, ChatFormatting.RESET)),
			List.of(water, boiler.getWaterComponent(!forFlapDisplay, forFlapDisplay, ChatFormatting.RESET)),
			List.of(heat, boiler.getHeatComponent(!forFlapDisplay, forFlapDisplay, ChatFormatting.RESET)));
	}

private MutableComponent labelOf(String label) {
		if (label.isBlank())
            return Component.empty();
		return CreateLang.translateDirect("boiler." + label);
	}

