public static void tick() {
		LinkedControllerItemRenderer.tick();

		if (MODE == Mode.IDLE)
			return;
		if (packetCooldown > 0)
			packetCooldown--;

		Minecraft mc = Minecraft.getInstance();
		LocalPlayer player = mc.player;
		ItemStack heldItem = player.getMainHandItem();

		if (player.isSpectator()) {
			MODE = Mode.IDLE;
			onReset();
			return;
		}

		if (!inLectern() && !AllItems.LINKED_CONTROLLER.isIn(heldItem)) {
			heldItem = player.getOffhandItem();
			if (!AllItems.LINKED_CONTROLLER.isIn(heldItem)) {
				MODE = Mode.IDLE;
				onReset();
				return;
			}
		}

		if (inLectern() && AllBlocks.LECTERN_CONTROLLER.get()
			.getBlockEntityOptional(mc.level, lecternPos)
			.map(be -> !be.isUsedBy(mc.player))
			.orElse(true)) {
			deactivateInLectern();
			return;
		}

		if (mc.screen != null) {
			MODE = Mode.IDLE;
			onReset();
			return;
		}

		if (InputConstants.isKeyDown(mc.getWindow()
			.getWindow(), GLFW.GLFW_KEY_ESCAPE)) {
			MODE = Mode.IDLE;
			onReset();
			return;
		}

		List<KeyMapping> controls = ControlsUtil.getControls();
		Collection<Integer> pressedKeys = new HashSet<>();
		for (int i = 0; i < controls.size(); i++) {
			if (ControlsUtil.isActuallyPressed(controls.get(i)))
				pressedKeys.add(i);
		}

		Collection<Integer> newKeys = new HashSet<>(pressedKeys);
		Collection<Integer> releasedKeys = currentlyPressed;
		newKeys.removeAll(releasedKeys);
		releasedKeys.removeAll(pressedKeys);

		if (MODE == Mode.ACTIVE) {
			// Released Keys
			if (!releasedKeys.isEmpty()) {
				CatnipServices.NETWORK.sendToServer(new LinkedControllerInputPacket(releasedKeys, false, lecternPos));
				AllSoundEvents.CONTROLLER_CLICK.playAt(player.level(), player.blockPosition(), 1f, .5f, true);
			}

			// Newly Pressed Keys
			if (!newKeys.isEmpty()) {
				CatnipServices.NETWORK.sendToServer(new LinkedControllerInputPacket(newKeys, true, lecternPos));
				packetCooldown = PACKET_RATE;
				AllSoundEvents.CONTROLLER_CLICK.playAt(player.level(), player.blockPosition(), 1f, .75f, true);
			}

			// Keepalive Pressed Keys
			if (packetCooldown == 0) {
				if (!pressedKeys.isEmpty()) {
					CatnipServices.NETWORK.sendToServer(new LinkedControllerInputPacket(pressedKeys, true, lecternPos));
					packetCooldown = PACKET_RATE;
				}
			}
		}

		if (MODE == Mode.BIND) {
			VoxelShape shape = mc.level.getBlockState(selectedLocation)
				.getShape(mc.level, selectedLocation);
			if (!shape.isEmpty())
				Outliner.getInstance().showAABB("controller", shape.bounds()
						.move(selectedLocation))
					.colored(0xB73C2D)
					.lineWidth(1 / 16f);

			for (Integer integer : newKeys) {
				LinkBehaviour linkBehaviour = BlockEntityBehaviour.get(mc.level, selectedLocation, LinkBehaviour.TYPE);
				if (linkBehaviour != null) {
					CatnipServices.NETWORK.sendToServer(new LinkedControllerBindPacket(integer, selectedLocation));
					CreateLang.translate("linked_controller.key_bound", controls.get(integer)
							.getTranslatedKeyMessage()
							.getString())
						.sendStatus(mc.player);
				}
				MODE = Mode.IDLE;
				break;
			}
		}

		currentlyPressed = pressedKeys;
		controls.forEach(kb -> kb.setDown(false));
	}

public static void renderOverlay(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
		int width1 = guiGraphics.guiWidth();
									 int height1 = guiGraphics.guiHeight();
		Minecraft mc = Minecraft.getInstance();
		if (mc.options.hideGui)
			return;

		if (MODE != Mode.BIND)
			return;

		PoseStack poseStack = guiGraphics.pose();
		poseStack.pushPose();
		Screen tooltipScreen = new Screen(CommonComponents.EMPTY) {
		};
		tooltipScreen.init(mc, width1, height1);

		Object[] keys = new Object[6];
		List<KeyMapping> controls = ControlsUtil.getControls();
		for (int i = 0; i < controls.size(); i++) {
			KeyMapping keyBinding = controls.get(i);
			keys[i] = keyBinding.getTranslatedKeyMessage()
				.getString();
		}

		List<Component> list = new ArrayList<>();
		list.add(CreateLang.translateDirect("linked_controller.bind_mode")
			.withStyle(ChatFormatting.GOLD));
		list.addAll(TooltipHelper.cutTextComponent(CreateLang.translateDirect("linked_controller.press_keybind", keys),
			Palette.ALL_GRAY));

		int width = 0;
		int height = list.size() * mc.font.lineHeight;
		for (Component iTextComponent : list)
			width = Math.max(width, mc.font.width(iTextComponent));
		int x = (width1 / 3) - width / 2;
		int y = height1 - height - 24;

		// TODO
		guiGraphics.renderComponentTooltip(Minecraft.getInstance().font, list, x, y);

		poseStack.popPose();
	}

protected static void render(ItemStack stack, CustomRenderedItemModel model,
								 PartialItemModelRenderer renderer, ItemDisplayContext transformType, PoseStack ms,
								 int light, RenderType renderType, boolean active, boolean renderDepression) {
		float pt = AnimationTickHolder.getPartialTicks();
		var msr = TransformStack.of(ms);

		ms.pushPose();

		if (renderType == RenderType.NORMAL) {
			Minecraft mc = Minecraft.getInstance();
			boolean rightHanded = mc.options.mainHand().get() == HumanoidArm.RIGHT;
			ItemDisplayContext mainHand =
				rightHanded ? ItemDisplayContext.FIRST_PERSON_RIGHT_HAND : ItemDisplayContext.FIRST_PERSON_LEFT_HAND;
			ItemDisplayContext offHand =
				rightHanded ? ItemDisplayContext.FIRST_PERSON_LEFT_HAND : ItemDisplayContext.FIRST_PERSON_RIGHT_HAND;

			active = false;
			boolean noControllerInMain = !AllItems.LINKED_CONTROLLER.isIn(mc.player.getMainHandItem());

			if (transformType == mainHand || (transformType == offHand && noControllerInMain)) {
				float equip = equipProgress.getValue(pt);
				int handModifier = transformType == ItemDisplayContext.FIRST_PERSON_LEFT_HAND ? -1 : 1;
				msr.translate(0, equip / 4, equip / 4 * handModifier);
				msr.rotateYDegrees(equip * -30 * handModifier);
				msr.rotateZDegrees(equip * -30);
				active = true;
			}

			if (transformType == ItemDisplayContext.GUI) {
				if (stack == mc.player.getMainHandItem())
					active = true;
				if (stack == mc.player.getOffhandItem() && noControllerInMain)
					active = true;
			}

			active &= LinkedControllerClientHandler.MODE != Mode.IDLE;

			renderDepression = true;
		}

		renderer.render(active ? POWERED.get() : model.getOriginalModel(), light);

		if (!active) {
			ms.popPose();
			return;
		}

		BakedModel button = BUTTON.get();
		float s = 1 / 16f;
		float b = s * -.75f;
		int index = 0;

		if (renderType == RenderType.NORMAL) {
			if (LinkedControllerClientHandler.MODE == Mode.BIND) {
				int i = (int) Mth.lerp((Mth.sin(AnimationTickHolder.getRenderTime() / 4f) + 1) / 2, 5, 15);
				light = i << 20;
			}
		}

		ms.pushPose();
		msr.translate(2 * s, 0, 8 * s);
		renderButton(renderer, ms, light, pt, button, b, index++, renderDepression);
		msr.translate(4 * s, 0, 0);
		renderButton(renderer, ms, light, pt, button, b, index++, renderDepression);
		msr.translate(-2 * s, 0, 2 * s);
		renderButton(renderer, ms, light, pt, button, b, index++, renderDepression);
		msr.translate(0, 0, -4 * s);
		renderButton(renderer, ms, light, pt, button, b, index++, renderDepression);
		ms.popPose();

		msr.translate(3 * s, 0, 3 * s);
		renderButton(renderer, ms, light, pt, button, b, index++, renderDepression);
		msr.translate(2 * s, 0, 0);
		renderButton(renderer, ms, light, pt, button, b, index++, renderDepression);

		ms.popPose();
	}

protected static void renderButton(PartialItemModelRenderer renderer, PoseStack ms, int light, float pt, BakedModel button,
									   float b, int index, boolean renderDepression) {
		ms.pushPose();
		if (renderDepression) {
			float depression = b * buttons.get(index).getValue(pt);
			ms.translate(0, depression, 0);
		}
		renderer.renderSolid(button, light);
		ms.popPose();
	}

private List<Component> addToTooltip(List<Component> list, int slot) {
		if (slot < 0 || slot >= 12)
			return list;
		list.add(CreateLang.translateDirect("linked_controller.frequency_slot_" + ((slot % 2) + 1), ControlsUtil.getControls()
			.get(slot / 2)
			.getTranslatedKeyMessage()
			.getString())
			.withStyle(ChatFormatting.GOLD));
		return list;
	}

@Override
	protected void renderSafe(NixieTubeBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay) {
		ms.pushPose();
		BlockState blockState = be.getBlockState();
		DoubleAttachFace face = blockState.getValue(NixieTubeBlock.FACE);
		float yRot = AngleHelper.horizontalAngle(blockState.getValue(NixieTubeBlock.FACING)) - 90
			+ (face == DoubleAttachFace.WALL_REVERSED ? 180 : 0);
		float xRot = face == DoubleAttachFace.WALL ? -90 : face == DoubleAttachFace.WALL_REVERSED ? 90 : 0;

		var msr = TransformStack.of(ms);
		msr.center()
			.rotateYDegrees(yRot)
			.rotateZDegrees(xRot)
			.uncenter();

		if (be.signalState != null || be.computerSignal != null) {
			renderAsSignal(be, partialTicks, ms, buffer, light, overlay);
			ms.popPose();
			return;
		}

		msr.center();

		float height = face == DoubleAttachFace.CEILING ? 5 : 3;
		float scale = 1 / 20f;

		Couple<String> s = be.getDisplayedStrings();
		DyeColor color = NixieTubeBlock.colorOf(be.getBlockState());
		RandomSource random = be.getLevel().getRandom();

		ms.pushPose();
		ms.translate(-4 / 16f, 0, 0);
		ms.scale(scale, -scale, scale);
		drawTube(ms, buffer, s.getFirst(), height, color, random);
		ms.popPose();

		ms.pushPose();
		ms.translate(4 / 16f, 0, 0);
		ms.scale(scale, -scale, scale);
		drawTube(ms, buffer, s.getSecond(), height, color, random);
		ms.popPose();

		ms.popPose();
	}

public static void drawTube(PoseStack ms, MultiBufferSource buffer, String c, float height, DyeColor color, RandomSource random) {
		Font fontRenderer = Minecraft.getInstance().font;
		float charWidth = fontRenderer.width(c);
		float shadowOffset = .5f;
		float flicker = random.nextFloat();
		Couple<Integer> couple = DyeHelper.getDyeColors(color);
		int brightColor = couple.getFirst();
		int darkColor = couple.getSecond();
		int flickeringBrightColor = Color.mixColors(brightColor, darkColor, flicker / 4);

		ms.pushPose();
		ms.translate((charWidth - shadowOffset) / -2f, -height, 0);
		drawInWorldString(ms, buffer, c, flickeringBrightColor);
		ms.pushPose();
		ms.translate(shadowOffset, shadowOffset, -1 / 16f);
		drawInWorldString(ms, buffer, c, darkColor);
		ms.popPose();
		ms.popPose();

		ms.pushPose();
		ms.scale(-1, 1, 1);
		ms.translate((charWidth - shadowOffset) / -2f, -height, 0);
		drawInWorldString(ms, buffer, c, darkColor);
		ms.pushPose();
		ms.translate(-shadowOffset, shadowOffset, -1 / 16f);
		drawInWorldString(ms, buffer, c, Color.mixColors(darkColor, 0, .35f));
		ms.popPose();
		ms.popPose();
	}

private void renderAsSignal(NixieTubeBlockEntity be, float partialTicks, PoseStack ms, MultiBufferSource buffer,
		int light, int overlay) {
		BlockState blockState = be.getBlockState();
		Direction facing = NixieTubeBlock.getFacing(blockState);
		Vec3 observerVec = Minecraft.getInstance().cameraEntity.getEyePosition(partialTicks);
		var msr = TransformStack.of(ms);

		if (facing == Direction.DOWN)
			msr.center()
				.rotateZDegrees(180)
				.uncenter();

		boolean invertTubes =
			facing == Direction.DOWN || blockState.getValue(NixieTubeBlock.FACE) == DoubleAttachFace.WALL_REVERSED;

		CachedBuffers.partial(AllPartialModels.SIGNAL_PANEL, blockState)
			.light(light)
			.renderInto(ms, buffer.getBuffer(RenderType.solid()));

		ms.pushPose();
		ms.translate(1 / 2f, 7.5f / 16f, 1 / 2f);
		float renderTime = AnimationTickHolder.getRenderTime(be.getLevel());
		Vec3 lampVec = Vec3.atCenterOf(be.getBlockPos());
		Vec3 diff = lampVec.subtract(observerVec);

		if (be.signalState != null) {
			for (boolean first : Iterate.trueAndFalse) {
				if (first && !be.signalState.isRedLight(renderTime))
					continue;
				if (!first && !be.signalState.isGreenLight(renderTime) && !be.signalState.isYellowLight(renderTime))
					continue;

				boolean flip = first == invertTubes;
				boolean yellow = be.signalState.isYellowLight(renderTime);

				ms.pushPose();
				ms.translate(flip ? 4 / 16f : -4 / 16f, 0, 0);

				if (diff.lengthSqr() < GLOW_VIEW_DISTANCE * GLOW_VIEW_DISTANCE) {
					boolean vert = first ^ facing.getAxis()
						.isHorizontal();
					float longSide = yellow ? 1 : 4;
					float longSideGlow = yellow ? 2 : 5.125f;

					CachedBuffers.partial(AllPartialModels.SIGNAL_WHITE_CUBE, blockState)
						.light(0xf000f0)
						.disableDiffuse()
						.scale(vert ? longSide : 1, vert ? 1 : longSide, 1)
						.renderInto(ms, buffer.getBuffer(RenderType.translucent()));

					CachedBuffers
						.partial(
							first ? AllPartialModels.SIGNAL_RED_GLOW
								: yellow ? AllPartialModels.SIGNAL_YELLOW_GLOW : AllPartialModels.SIGNAL_WHITE_GLOW,
							blockState)
						.light(0xf000f0)
						.disableDiffuse()
						.scale(vert ? longSideGlow : 2, vert ? 2 : longSideGlow, 2)
						.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));
				}

				CachedBuffers
					.partial(first ? AllPartialModels.SIGNAL_RED
						: yellow ? AllPartialModels.SIGNAL_YELLOW : AllPartialModels.SIGNAL_WHITE, blockState)
					.light(0xF000F0)
					.disableDiffuse()
					.scale(1 + 1 / 16f)
					.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));

				ms.popPose();
			}
		} else if (be.computerSignal != null) {
			for (boolean first : Iterate.trueAndFalse) {
				NixieTubeBlockEntity.ComputerSignal.TubeDisplay tubeDisplay = first ?
					be.computerSignal.first : be.computerSignal.second;
				if (tubeDisplay.blinkPeriod == 0 || tubeDisplay.blinkPeriod > 1 && renderTime % tubeDisplay.blinkPeriod < tubeDisplay.blinkOffTime)
					continue;

				boolean flip = first == invertTubes;

				ms.pushPose();
				ms.translate(flip ? 4 / 16f : -4 / 16f, 0, 0);

				if (diff.lengthSqr() < GLOW_VIEW_DISTANCE * GLOW_VIEW_DISTANCE) {
					boolean horiz = facing.getAxis().isHorizontal();
					float width = horiz ? tubeDisplay.glowWidth : tubeDisplay.glowHeight;
					float height = horiz ? tubeDisplay.glowHeight : tubeDisplay.glowWidth;

					CachedBuffers.partial(AllPartialModels.SIGNAL_COMPUTER_WHITE_CUBE, blockState)
						.light(0xf000f0)
						.disableDiffuse()
						.scale(width, height,  1)
						.renderInto(ms, buffer.getBuffer(RenderType.translucent()));

					CachedBuffers
						.partial(AllPartialModels.SIGNAL_COMPUTER_WHITE_GLOW, blockState)
						.light(0xf000f0)
						.color(
							Math.min(((tubeDisplay.r & 0xFF) * 6 + 256) >> 3, 255),
							Math.min(((tubeDisplay.g & 0xFF) * 6 + 256) >> 3, 255),
							Math.min(((tubeDisplay.b & 0xFF) * 6 + 256) >> 3, 255),
							255)
						.disableDiffuse()
						.scale(width + 1.125f, height + 1.125f, 2)
						.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));
				}

				CachedBuffers
					.partial(AllPartialModels.SIGNAL_COMPUTER_WHITE_BASE, blockState)
					.light(0xF000F0)
					.color(12, 12, 12, 255)
					.disableDiffuse()
					.scale(1 + 1.25f / 16f)
					.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));

				CachedBuffers
					.partial(AllPartialModels.SIGNAL_COMPUTER_WHITE, blockState)
					.light(0xF000F0)
					.color(tubeDisplay.r, tubeDisplay.g, tubeDisplay.b, 255)
					.disableDiffuse()
					.scale(1 + 1 / 16f)
					.renderInto(ms, buffer.getBuffer(RenderTypes.additive()));

				ms.popPose();
			}
		}

		ms.popPose();

	}

public ThresholdSwitchScreen(ThresholdSwitchBlockEntity be) {
		super(CreateLang.translateDirect("gui.threshold_switch.title"));
		background = AllGuiTextures.THRESHOLD_SWITCH;
		this.blockEntity = be;
		lastModification = -1;
	}

@Override
	protected void init() {
		setWindowSize(background.getWidth(), background.getHeight());
		setWindowOffset(-20, 0);
		super.init();

		int x = guiLeft;
		int y = guiTop;

		inStacks = (SelectionScrollInput) new SelectionScrollInput(x + 100, y + 23, 52, 42)
			.forOptions(List.of(CreateLang.translateDirect("schedule.condition.threshold.items"),
				CreateLang.translateDirect("schedule.condition.threshold.stacks")))
			.titled(CreateLang.translateDirect("schedule.condition.threshold.item_measure"))
			.setState(blockEntity.inStacks ? 1 : 0);

		offBelow = new ScrollInput(x + 48, y + 47, 1, 18)
			.withRange(blockEntity.getMinLevel(), blockEntity.getMaxLevel() + 1 - getValueStep())
			.titled(CreateLang.translateDirect("gui.threshold_switch.lower_threshold"))
			.calling(state -> {
				lastModification = 0;
				int valueStep = getValueStep();

				if (onAbove.getState() / valueStep == 0 && state / valueStep == 0)
					return;

				if (onAbove.getState() / valueStep <= state / valueStep) {
					onAbove.setState((state + valueStep) / valueStep * valueStep);
					onAbove.onChanged();
				}
			})
			.withStepFunction(sc -> sc.shift ? 10 * getValueStep() : getValueStep())
			.setState(blockEntity.offWhenBelow);

		onAbove = new ScrollInput(x + 48, y + 23, 1, 18)
			.withRange(blockEntity.getMinLevel() + getValueStep(), blockEntity.getMaxLevel() + 1)
			.titled(CreateLang.translateDirect("gui.threshold_switch.upper_threshold"))
			.calling(state -> {
				lastModification = 0;
				int valueStep = getValueStep();

				if (offBelow.getState() / valueStep == 0 && state / valueStep == 0)
					return;

				if (offBelow.getState() / valueStep >= state / valueStep) {
					offBelow.setState((state - valueStep) / valueStep * valueStep);
					offBelow.onChanged();
				}
			})
			.withStepFunction(sc -> sc.shift ? 10 * getValueStep() : getValueStep())
			.setState(blockEntity.onWhenAbove);

		onAbove.onChanged();
		offBelow.onChanged();

		addRenderableWidget(onAbove);
		addRenderableWidget(offBelow);
		addRenderableWidget(inStacks);

		confirmButton =
			new IconButton(x + background.getWidth() - 33, y + background.getHeight() - 24, AllIcons.I_CONFIRM);
		confirmButton.withCallback(() -> onClose());
		addRenderableWidget(confirmButton);

		flipSignals = new IconButton(x + background.getWidth() - 62, y + background.getHeight() - 24, AllIcons.I_FLIP);
		flipSignals.withCallback(() -> send(!blockEntity.isInverted()));
		flipSignals.setToolTip(invertSignal);
		addRenderableWidget(flipSignals);

		updateInputBoxes();
	}

@Override
	protected void renderWindow(GuiGraphics graphics, int mouseX, int mouseY, float partialTicks) {
		int x = guiLeft;
		int y = guiTop;

		background.render(graphics, x, y);
		graphics.drawString(font, title, x + background.getWidth() / 2 - font.width(title) / 2, y + 4, 0x592424, false);

		ThresholdType typeOfCurrentTarget = blockEntity.getTypeOfCurrentTarget();
		boolean forItems = typeOfCurrentTarget == ThresholdType.ITEM;
		AllGuiTextures inputBg =
			forItems ? AllGuiTextures.THRESHOLD_SWITCH_ITEMCOUNT_INPUTS : AllGuiTextures.THRESHOLD_SWITCH_MISC_INPUTS;

		inputBg.render(graphics, x + 44, y + 21);
		inputBg.render(graphics, x + 44, y + 21 + 24);

		int valueStep = 1;
		boolean stacks = inStacks.getState() == 1;
		if (typeOfCurrentTarget == ThresholdType.FLUID)
			valueStep = 1000;

		if (forItems) {
			Component suffix =
				inStacks.getState() == 0 ? CreateLang.translateDirect("schedule.condition.threshold.items")
					: CreateLang.translateDirect("schedule.condition.threshold.stacks");
			valueStep = inStacks.getState() == 0 ? 1 : 64;
			graphics.drawString(font, suffix, x + 105, y + 28, 0xFFFFFFFF, true);
			graphics.drawString(font, suffix, x + 105, y + 28 + 24, 0xFFFFFFFF, true);

		}

		graphics.drawString(font,
			Component.literal("\u2265 " + (typeOfCurrentTarget == ThresholdType.UNSUPPORTED ? ""
				: forItems ? onAbove.getState() / valueStep
				: blockEntity.format(onAbove.getState() / valueStep, stacks)
				.getString())),
			x + 53, y + 28, 0xFFFFFFFF, true);
		graphics.drawString(font,
			Component.literal("\u2264 " + (typeOfCurrentTarget == ThresholdType.UNSUPPORTED ? ""
				: forItems ? offBelow.getState() / valueStep
				: blockEntity.format(offBelow.getState() / valueStep, stacks)
				.getString())),
			x + 53, y + 28 + 24, 0xFFFFFFFF, true);

		GuiGameElement.of(renderedItem).<GuiGameElement
				.GuiRenderBuilder>at(x + background.getWidth() + 6, y + background.getHeight() - 56, -200)
			.scale(5)
			.render(graphics);

		int itemX = x + 13;
		int itemY = y + 80;

		ItemStack displayItem = blockEntity.getDisplayItemForScreen();
		GuiGameElement.of(displayItem.isEmpty() ? new ItemStack(Items.BARRIER) : displayItem).<GuiGameElement
				.GuiRenderBuilder>at(itemX, itemY, 0)
			.render(graphics);

		int torchX = x + 23;
		int torchY = y + 24;

		boolean highlightTopRow = blockEntity.isInverted() ^ blockEntity.isPowered();
		AllGuiTextures.THRESHOLD_SWITCH_CURRENT_STATE.render(graphics, torchX - 3,
			torchY - 4 + (highlightTopRow ? 0 : 24));

		PoseStack ms = graphics.pose();
		ms.pushPose();
		ms.translate(torchX - 5, torchY + 14, 200);
		TransformStack.of(ms)
			.rotateXDegrees(-22.5f)
			.rotateYDegrees(45);

		for (boolean power : Iterate.trueAndFalse) {
			GuiGameElement.of(Blocks.REDSTONE_TORCH.defaultBlockState()
					.setValue(RedstoneTorchBlock.LIT, blockEntity.isInverted() ^ power))
				.scale(20)
				.render(graphics);
			ms.translate(0, 26, 0);
		}

		ms.popPose();

		if (mouseX >= itemX && mouseX < itemX + 16 && mouseY >= itemY && mouseY < itemY + 16) {
			ArrayList<Component> list = new ArrayList<>();
			if (displayItem.isEmpty()) {
				list.add(CreateLang.translateDirect("gui.threshold_switch.not_attached"));
				list.add(CreateLang.translateDirect("display_link.view_compatible")
					.withStyle(ChatFormatting.DARK_GRAY));
				graphics.renderComponentTooltip(font, list, mouseX, mouseY);
				return;
			}

			list.add(displayItem.getHoverName());
			if (typeOfCurrentTarget == ThresholdType.UNSUPPORTED) {
				list.add(CreateLang.translateDirect("gui.threshold_switch.incompatible")
					.withStyle(ChatFormatting.GRAY));
				list.add(CreateLang.translateDirect("display_link.view_compatible")
					.withStyle(ChatFormatting.DARK_GRAY));
				graphics.renderComponentTooltip(font, list, mouseX, mouseY);
				return;
			}

			CreateLang
				.translate("gui.threshold_switch.currently",
					blockEntity.format(blockEntity.currentLevel / valueStep, stacks))
				.style(ChatFormatting.DARK_AQUA)
				.addTo(list);

			if (blockEntity.currentMinLevel / valueStep == 0)
				CreateLang
					.translate("gui.threshold_switch.range_max",
						blockEntity.format(blockEntity.currentMaxLevel / valueStep, stacks))
					.style(ChatFormatting.GRAY)
					.addTo(list);
			else
				CreateLang
					.translate("gui.threshold_switch.range", blockEntity.currentMinLevel / valueStep,
						blockEntity.format(blockEntity.currentMaxLevel / valueStep, stacks))
					.style(ChatFormatting.GRAY)
					.addTo(list);

			list.add(CreateLang.translateDirect("display_link.view_compatible")
				.withStyle(ChatFormatting.DARK_GRAY));

			graphics.renderComponentTooltip(font, list, mouseX, mouseY);
			return;
		}

		for (boolean power : Iterate.trueAndFalse) {
			int thisTorchY = power ? torchY : torchY + 26;
			if (mouseX >= torchX && mouseX < torchX + 16 && mouseY >= thisTorchY && mouseY < thisTorchY + 16) {
				graphics.renderComponentTooltip(font,
					List.of(CreateLang
						.translate(power ^ blockEntity.isInverted() ? "gui.threshold_switch.power_on_when"
							: "gui.threshold_switch.power_off_when")
						.color(AbstractSimiWidget.HEADER_RGB)
						.component()),
					mouseX, mouseY);
				return;
			}
		}
	}

