protected List<Component> getFuelLevelTooltip(SchematicannonBlockEntity be) {
		int shotsLeft = be.remainingFuel;
		int shotsLeftWithItems = shotsLeft + be.inventory.getStackInSlot(4)
			.getCount() * be.getShotsPerGunpowder();
		List<Component> tooltip = new ArrayList<>();

		if (be.hasCreativeCrate) {
			tooltip.add(CreateLang.translateDirect(_gunpowderLevel, "" + 100));
			tooltip.add(Component.literal("(").append(AllBlocks.CREATIVE_CRATE.get()
					.getName())
				.append(")")
				.withStyle(DARK_PURPLE));
			return tooltip;
		}

		int fillPercent = (int) ((be.remainingFuel / (float) be.getShotsPerGunpowder()) * 100);
		tooltip.add(CreateLang.translateDirect(_gunpowderLevel, fillPercent));
		tooltip.add(CreateLang.translateDirect(_shotsRemaining, Component.literal(Integer.toString(shotsLeft)).withStyle(BLUE))
			.withStyle(GRAY));
		if (shotsLeftWithItems != shotsLeft) {
			tooltip.add(CreateLang
				.translateDirect(_shotsRemainingWithBackup,
					Component.literal(Integer.toString(shotsLeftWithItems)).withStyle(BLUE))
				.withStyle(GRAY));
		}

		return tooltip;
	}

public void startNewUpload(String schematic) {
		Path path = CreatePaths.SCHEMATICS_DIR.resolve(schematic);

		if (!Files.exists(path)) {
			Create.LOGGER.error("Missing Schematic file: {}", path);
			return;
		}

		InputStream in;
		try {
			long size = Files.size(path);

			// Too big
			if (!validateSizeLimitation(size))
				return;

			// Validate if the file is encoded in a GZIP compatible format
			if (!isGZIPEncoded(path.toFile())) {
				LocalPlayer player = Minecraft.getInstance().player;
				if (player != null)
					player.displayClientMessage(CreateLang.translateDirect("schematics.wrongFormat"), false);
				return;
			}

			in = Files.newInputStream(path, StandardOpenOption.READ);
			activeUploads.put(schematic, in);
			CatnipServices.NETWORK.sendToServer(SchematicUploadPacket.begin(schematic, size));
		} catch (IOException e) {
			Create.LOGGER.error("Encountered an error while starting schematic upload", e);
		}
	}

public static boolean validateSizeLimitation(long size) {
		if (Minecraft.getInstance().hasSingleplayerServer())
			return true;
		long maxSize = AllConfigs.server().schematics.maxTotalSchematicSize.get();
		if (size > maxSize * 1000) {
			LocalPlayer player = Minecraft.getInstance().player;
			if (player != null) {
				player.displayClientMessage(CreateLang.translateDirect("schematics.uploadTooLarge").append(" (" + size / 1000 + " KB)."), false);
				player.displayClientMessage(CreateLang.translateDirect("schematics.maxAllowedSize").append(" " + maxSize + " KB"), false);
			}
			return false;
		}
		return true;
	}

public boolean mouseScrolled(double delta) {
		if (!isActive())
			return false;
		if (!AllKeys.ctrlDown())
			return false;
		if (secondPos == null)
			range = (int) Mth.clamp(range + delta, 1, 100);
		if (selectedFace == null)
			return true;

		AABB bb = new AABB(Vec3.atLowerCornerOf(firstPos), Vec3.atLowerCornerOf(secondPos));
		Vec3i vec = selectedFace.getNormal();
		Vec3 projectedView = Minecraft.getInstance().gameRenderer.getMainCamera()
			.getPosition();
		if (bb.contains(projectedView))
			delta *= -1;

		// Round away from zero to avoid an implicit floor
		int intDelta = (int) (delta > 0 ? Math.ceil(delta) : Math.floor(delta));

		int x = vec.getX() * intDelta;
		int y = vec.getY() * intDelta;
		int z = vec.getZ() * intDelta;

		AxisDirection axisDirection = selectedFace.getAxisDirection();
		if (axisDirection == AxisDirection.NEGATIVE)
			bb = bb.move(-x, -y, -z);

		double maxX = Math.max(bb.maxX - x * axisDirection.getStep(), bb.minX);
		double maxY = Math.max(bb.maxY - y * axisDirection.getStep(), bb.minY);
		double maxZ = Math.max(bb.maxZ - z * axisDirection.getStep(), bb.minZ);
		bb = new AABB(bb.minX, bb.minY, bb.minZ, maxX, maxY, maxZ);

		firstPos = BlockPos.containing(bb.minX, bb.minY, bb.minZ);
		secondPos = BlockPos.containing(bb.maxX, bb.maxY, bb.maxZ);
		LocalPlayer player = Minecraft.getInstance().player;
		CreateLang.translate("schematicAndQuill.dimensions", (int) bb.getXsize() + 1, (int) bb.getYsize() + 1,
				(int) bb.getZsize() + 1)
			.sendStatus(player);

		return true;
	}

public boolean onMouseInput(int button, boolean pressed) {
		if (!pressed || button != 1)
			return false;
		if (!isActive())
			return false;

		LocalPlayer player = Minecraft.getInstance().player;

		if (player.isShiftKeyDown()) {
			discard();
			return true;
		}

		if (secondPos != null) {
			ScreenOpener.open(new SchematicPromptScreen());
			return true;
		}

		if (selectedPos == null) {
			CreateLang.translate("schematicAndQuill.noTarget")
				.sendStatus(player);
			return true;
		}

		if (firstPos != null) {
			secondPos = selectedPos;
			CreateLang.translate("schematicAndQuill.secondPos")
				.sendStatus(player);
			return true;
		}

		firstPos = selectedPos;
		CreateLang.translate("schematicAndQuill.firstPos")
			.sendStatus(player);
		return true;
	}

public void discard() {
		LocalPlayer player = Minecraft.getInstance().player;
		firstPos = null;
		secondPos = null;
		CreateLang.translate("schematicAndQuill.abort")
			.sendStatus(player);
	}

public void saveSchematic(String string, boolean convertImmediately) {
		SchematicExportResult result = SchematicExport.saveSchematic(
			CreatePaths.SCHEMATICS_DIR, string, false,
			Minecraft.getInstance().level, firstPos, secondPos
		);
		LocalPlayer player = Minecraft.getInstance().player;
		if (result == null) {
			CreateLang.translate("schematicAndQuill.failed")
				.style(ChatFormatting.RED)
				.sendStatus(player);
			return;
		}
		Path file = result.file();
		CreateLang.translate("schematicAndQuill.saved", file.getFileName().toString())
			.sendStatus(player);
		firstPos = null;
		secondPos = null;
		if (!convertImmediately)
			return;
		try {
			if (!ClientSchematicLoader.validateSizeLimitation(Files.size(file)))
				return;
			CatnipServices.NETWORK.sendToServer(new InstantSchematicPacket(result.fileName(), result.origin(), result.bounds()));
		} catch (IOException e) {
			Create.LOGGER.error("Error instantly uploading Schematic file: " + file, e);
		}
	}

private void setupRenderer() {
		Level clientWorld = Minecraft.getInstance().level;
		StructureTemplate schematic =
			SchematicItem.loadSchematic(clientWorld, activeSchematicItem);
		Vec3i size = schematic.getSize();
		if (size.equals(Vec3i.ZERO))
			return;

		SchematicLevel w = new SchematicLevel(clientWorld);
		SchematicLevel wMirroredFB = new SchematicLevel(clientWorld);
		SchematicLevel wMirroredLR = new SchematicLevel(clientWorld);
		StructurePlaceSettings placementSettings = new StructurePlaceSettings();
		StructureTransform transform;
		BlockPos pos;

		pos = BlockPos.ZERO;

		try {
			schematic.placeInWorld(w, pos, pos, placementSettings, w.getRandom(), Block.UPDATE_CLIENTS);
			for (BlockEntity blockEntity : w.getBlockEntities())
				blockEntity.setLevel(w);
			fixControllerBlockEntities(w);
		} catch (Exception e) {
			Minecraft.getInstance().player.displayClientMessage(CreateLang.translate("schematic.error")
				.component(), false);
			Create.LOGGER.error("Failed to load Schematic for Previewing", e);
			return;
		}

		placementSettings.setMirror(Mirror.FRONT_BACK);
		pos = BlockPos.ZERO.east(size.getX() - 1);
		schematic.placeInWorld(wMirroredFB, pos, pos, placementSettings, wMirroredFB.getRandom(), Block.UPDATE_CLIENTS);
		transform = new StructureTransform(placementSettings.getRotationPivot(), Axis.Y, Rotation.NONE,
			placementSettings.getMirror());
		for (BlockEntity be : wMirroredFB.getRenderedBlockEntities())
			transform.apply(be);
		fixControllerBlockEntities(wMirroredFB);

		placementSettings.setMirror(Mirror.LEFT_RIGHT);
		pos = BlockPos.ZERO.south(size.getZ() - 1);
		schematic.placeInWorld(wMirroredLR, pos, pos, placementSettings, wMirroredFB.getRandom(), Block.UPDATE_CLIENTS);
		transform = new StructureTransform(placementSettings.getRotationPivot(), Axis.Y, Rotation.NONE,
			placementSettings.getMirror());
		for (BlockEntity be : wMirroredLR.getRenderedBlockEntities())
			transform.apply(be);
		fixControllerBlockEntities(wMirroredLR);

		renderers[0] = new SchematicRenderer(w);
		renderers[1] = new SchematicRenderer(wMirroredFB);
		renderers[2] = new SchematicRenderer(wMirroredLR);
	}

