protected SuperByteBuffer drawLayer(RenderType layer) {
		BlockRenderDispatcher dispatcher = Minecraft.getInstance().getBlockRenderer();
		ModelBlockRenderer renderer = dispatcher.getModelRenderer();
		ThreadLocalObjects objects = THREAD_LOCAL_OBJECTS.get();

		PoseStack poseStack = objects.poseStack;
		RandomSource random = objects.random;
		BlockPos.MutableBlockPos mutableBlockPos = objects.mutableBlockPos;
		SchematicLevel renderWorld = schematic;
		BoundingBox bounds = renderWorld.getBounds();

		ShadedBlockSbbBuilder sbbBuilder = objects.sbbBuilder;
		sbbBuilder.begin();

		renderWorld.renderMode = true;
		ModelBlockRenderer.enableCaching();
		for (BlockPos localPos : BlockPos.betweenClosed(bounds.minX(), bounds.minY(), bounds.minZ(), bounds.maxX(), bounds.maxY(), bounds.maxZ())) {
			BlockPos pos = mutableBlockPos.setWithOffset(localPos, anchor);
			BlockState state = renderWorld.getBlockState(pos);

			if (state.getRenderShape() == RenderShape.MODEL) {
				BakedModel model = dispatcher.getBlockModel(state);
				BlockEntity blockEntity = renderWorld.getBlockEntity(localPos);
				ModelData modelData = blockEntity != null ? blockEntity.getModelData() : ModelData.EMPTY;
				modelData = model.getModelData(renderWorld, pos, state, modelData);
				long seed = state.getSeed(pos);
				random.setSeed(seed);
				if (model.getRenderTypes(state, random, modelData).contains(layer)) {
					poseStack.pushPose();
					poseStack.translate(localPos.getX(), localPos.getY(), localPos.getZ());

					renderer.tesselateBlock(renderWorld, model, state, pos, poseStack, sbbBuilder, true,
						random, seed, OverlayTexture.NO_OVERLAY, modelData, layer);

					poseStack.popPose();
				}
			}
		}
		ModelBlockRenderer.clearCache();
		renderWorld.renderMode = false;

		return sbbBuilder.end();
	}

public void applyTransformations(PoseStack ms, Vec3 camera) {
		float pt = AnimationTickHolder.getPartialTicks();

		// Translation
		TransformStack.of(ms)
			.translate(VecHelper.lerp(pt, prevChasingPos, chasingPos)
				.subtract(camera));
		Vec3 rotationOffset = getRotationOffset(true);

		// Rotation & Mirror
		float fb = getScaleFB().getValue(pt);
		float lr = getScaleLR().getValue(pt);
		float rot = rotation.getValue(pt) + ((fb < 0 && lr < 0) ? 180 : 0);
		ms.translate(xOrigin, 0, zOrigin);
		TransformStack.of(ms)
			.translate(rotationOffset)
			.rotateYDegrees(rot)
			.translateBack(rotationOffset);
		ms.scale(abs(fb), 1, abs(lr));
		ms.translate(-xOrigin, 0, -zOrigin);

	}

private void draw(GuiGraphics graphics, float partialTicks) {
		PoseStack matrixStack = graphics.pose();
		Window mainWindow = minecraft.getWindow();
		if (!initialized)
			init(minecraft, mainWindow.getGuiScaledWidth(), mainWindow.getGuiScaledHeight());

		int x = (mainWindow.getGuiScaledWidth() - w) / 2 + 15;
		int y = mainWindow.getGuiScaledHeight() - h - 75;

		matrixStack.pushPose();
		matrixStack.translate(0, -yOffset, focused ? 100 : 0);

		AllGuiTextures gray = AllGuiTextures.HUD_BACKGROUND;
		RenderSystem.enableBlend();
		RenderSystem.setShaderColor(1, 1, 1, focused ? 7 / 8f : 1 / 2f);

		graphics.blit(gray.location, x - 15, y, gray.getStartX(), gray.getStartY(), w, h, gray.getWidth(), gray.getHeight());

		float toolTipAlpha = yOffset / 10;
		List<Component> toolTip = tools.get(selection)
			.getDescription();
		int stringAlphaComponent = ((int) (toolTipAlpha * 0xFF)) << 24;

		if (toolTipAlpha > 0.25f) {
			RenderSystem.setShaderColor(.7f, .7f, .8f, toolTipAlpha);
			graphics.blit(gray.location, x - 15, y + 33, gray.getStartX(), gray.getStartY(), w, h + 22, gray.getWidth(), gray.getHeight());
			RenderSystem.setShaderColor(1, 1, 1, 1);

			if (toolTip.size() > 0)
				graphics.drawString(font, toolTip.get(0), x - 10, y + 38, 0xEEEEEE + stringAlphaComponent, false);
			if (toolTip.size() > 1)
				graphics.drawString(font, toolTip.get(1), x - 10, y + 50, 0xCCDDFF + stringAlphaComponent, false);
			if (toolTip.size() > 2)
				graphics.drawString(font, toolTip.get(2), x - 10, y + 60, 0xCCDDFF + stringAlphaComponent, false);
			if (toolTip.size() > 3)
				graphics.drawString(font, toolTip.get(3), x - 10, y + 72, 0xCCCCDD + stringAlphaComponent, false);
		}

		RenderSystem.setShaderColor(1, 1, 1, 1);
		if (tools.size() > 1) {
			String keyName = AllKeys.TOOL_MENU.getBoundKey();
			int width = minecraft.getWindow()
				.getGuiScaledWidth();
			if (!focused)
				graphics.drawCenteredString(minecraft.font, CreateLang.translateDirect(holdToFocus, keyName), width / 2,
					y - 10, 0xCCDDFF);
			else
				graphics.drawCenteredString(minecraft.font, scrollToCycle, width / 2, y - 10, 0xCCDDFF);
		} else {
			x += 65;
		}


		for (int i = 0; i < tools.size(); i++) {
			RenderSystem.enableBlend();
			matrixStack.pushPose();

			float alpha = focused ? 1 : .2f;
			if (i == selection) {
				matrixStack.translate(0, -10, 0);
				RenderSystem.setShaderColor(1, 1, 1, 1);
				graphics.drawCenteredString(minecraft.font, tools.get(i)
					.getDisplayName()
					.getString(), x + i * 50 + 24, y + 28, 0xCCDDFF);
				alpha = 1;
			}
			RenderSystem.setShaderColor(0, 0, 0, alpha);
			tools.get(i)
				.getIcon()
				.render(graphics, x + i * 50 + 16, y + 12);
			RenderSystem.setShaderColor(1, 1, 1, alpha);
			tools.get(i)
				.getIcon()
				.render(graphics, x + i * 50 + 16, y + 11);

			matrixStack.popPose();
		}

		RenderSystem.setShaderColor(1, 1, 1, 1);
		RenderSystem.disableBlend();
		matrixStack.popPose();
	}

@Override
	public void renderTool(PoseStack ms, SuperRenderTypeBuffer buffer, Vec3 camera) {
		super.renderTool(ms, buffer, camera);

		if (selectedPos == null)
			return;

		ms.pushPose();
		float pt = AnimationTickHolder.getPartialTicks();
		double x = Mth.lerp(pt, lastChasingSelectedPos.x, chasingSelectedPos.x);
		double y = Mth.lerp(pt, lastChasingSelectedPos.y, chasingSelectedPos.y);
		double z = Mth.lerp(pt, lastChasingSelectedPos.z, chasingSelectedPos.z);

		SchematicTransformation transformation = schematicHandler.getTransformation();
		AABB bounds = schematicHandler.getBounds();
		Vec3 center = bounds.getCenter();
		Vec3 rotationOffset = transformation.getRotationOffset(true);
		int centerX = (int) center.x;
		int centerZ = (int) center.z;
		double xOrigin = bounds.getXsize() / 2f;
		double zOrigin = bounds.getZsize() / 2f;
		Vec3 origin = new Vec3(xOrigin, 0, zOrigin);

		ms.translate(x - centerX - camera.x, y - camera.y, z - centerZ - camera.z);
		TransformStack.of(ms)
			.translate(origin)
			.translate(rotationOffset)
			.rotateYDegrees(transformation.getCurrentRotation())
			.translateBack(rotationOffset)
			.translateBack(origin);

		AABBOutline outline = schematicHandler.getOutline();
		outline.render(ms, buffer, Vec3.ZERO, pt);
		outline.getParams()
			.clearTextures();
		ms.popPose();
	}

private static void renderOverlay(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
		float partialTicks = deltaTracker.getGameTimeDeltaPartialTick(false);
		Minecraft mc = Minecraft.getInstance();
		if (mc.options.hideGui || mc.gameMode.getPlayerMode() == GameType.SPECTATOR)
			return;

		if (!(ControlsHandler.getContraption() instanceof CarriageContraptionEntity cce))
			return;
		Carriage carriage = cce.getCarriage();
		if (carriage == null)
			return;
		Entity cameraEntity = Minecraft.getInstance()
			.getCameraEntity();
		if (cameraEntity == null)
			return;
		BlockPos localPos = ControlsHandler.getControlsPos();
		if (localPos == null)
			return;

		PoseStack poseStack = guiGraphics.pose();
		poseStack.pushPose();
		poseStack.translate(guiGraphics.guiWidth() / 2 - 91, guiGraphics.guiHeight() - 29, 0);

		// Speed, Throttle

		AllGuiTextures.TRAIN_HUD_FRAME.render(guiGraphics, -2, 1);
		AllGuiTextures.TRAIN_HUD_SPEED_BG.render(guiGraphics, 0, 0);

		int w = (int) (AllGuiTextures.TRAIN_HUD_SPEED.getWidth() * displayedSpeed.getValue(partialTicks));
		int h = AllGuiTextures.TRAIN_HUD_SPEED.getHeight();

		guiGraphics.blit(AllGuiTextures.TRAIN_HUD_SPEED.location, 0, 0, 0, AllGuiTextures.TRAIN_HUD_SPEED.getStartX(),
			AllGuiTextures.TRAIN_HUD_SPEED.getStartY(), w, h, 256, 256);

		int promptSize = (int) displayedPromptSize.getValue(partialTicks);
		if (promptSize > 1) {

			poseStack.pushPose();
			poseStack.translate(promptSize / -2f + 91, -27, 0);

			AllGuiTextures.TRAIN_PROMPT_L.render(guiGraphics, -3, 0);
			AllGuiTextures.TRAIN_PROMPT_R.render(guiGraphics, promptSize, 0);
			guiGraphics.blit(AllGuiTextures.TRAIN_PROMPT.location, 0, 0, 0, AllGuiTextures.TRAIN_PROMPT.getStartX() + (128 - promptSize / 2f),
				AllGuiTextures.TRAIN_PROMPT.getStartY(), promptSize, AllGuiTextures.TRAIN_PROMPT.getHeight(), 256, 256);

			poseStack.popPose();

			Font font = mc.font;
			if (currentPrompt != null && font.width(currentPrompt) < promptSize - 10) {
				poseStack.pushPose();
				poseStack.translate(font.width(currentPrompt) / -2f + 82, -27, 100);
				if (currentPromptShadow)
					guiGraphics.drawString(font, currentPrompt, 9, 4, 0x544D45);
				else
					guiGraphics.drawString(font, currentPrompt, 9, 4, 0x544D45, false);
				poseStack.popPose();
			}
		}

		AllGuiTextures.TRAIN_HUD_DIRECTION.render(guiGraphics, 77, -20);

		w = (int) (AllGuiTextures.TRAIN_HUD_THROTTLE.getWidth() * (1 - displayedThrottle.getValue(partialTicks)));
		int invW = AllGuiTextures.TRAIN_HUD_THROTTLE.getWidth() - w;
		guiGraphics.blit(AllGuiTextures.TRAIN_HUD_THROTTLE.location, invW, 0, 0, AllGuiTextures.TRAIN_HUD_THROTTLE.getStartX() + invW,
			AllGuiTextures.TRAIN_HUD_THROTTLE.getStartY(), w, h, 256, 256);
		AllGuiTextures.TRAIN_HUD_THROTTLE_POINTER.render(guiGraphics,
			Math.max(1, AllGuiTextures.TRAIN_HUD_THROTTLE.getWidth() - w) - 3, -2);

		// Direction

		StructureBlockInfo info = cce.getContraption()
			.getBlocks()
			.get(localPos);
		Direction initialOrientation = cce.getInitialOrientation()
			.getCounterClockWise();
		boolean inverted = false;
		if (info != null && info.state().hasProperty(ControlsBlock.FACING))
			inverted = !info.state().getValue(ControlsBlock.FACING)
				.equals(initialOrientation);

		boolean reversing = ControlsHandler.currentlyPressed.contains(1);
		inverted ^= reversing;
		int angleOffset = (ControlsHandler.currentlyPressed.contains(2) ? -45 : 0)
			+ (ControlsHandler.currentlyPressed.contains(3) ? 45 : 0);
		if (reversing)
			angleOffset *= -1;

		float snapSize = 22.5f;
		float diff = AngleHelper.getShortestAngleDiff(cameraEntity.getYRot(), cce.yaw) + (inverted ? -90 : 90);
		if (Math.abs(diff) < 60)
			diff = 0;

		float angle = diff + angleOffset;
		float snappedAngle = (snapSize * Math.round(angle / snapSize)) % 360f;

		poseStack.translate(91, -9, 0);
		poseStack.scale(0.925f, 0.925f, 1);
		PlacementClient.textured(poseStack, 0, 0, 1, snappedAngle);

		poseStack.popPose();
	}

