protected <T extends Block> BlockEntry<?> createEntry(AbstractRegistrate<?> registrate, Variant<T> variant,
														  WeatherState state, boolean waxed) {
		String name = "";
		if (waxed) {
			name += "waxed_";
		}
		name += getWeatherStatePrefix(state);
		name += this.name;

		String suffix = variant.getSuffix();
		if (!suffix.equals(""))
			name = Lang.nonPluralId(name);

		name += suffix;

		Supplier<Block> baseBlock = BASE_BLOCKS.get(state);
		BlockBuilder<T, ?> builder = registrate.block(name, variant.getFactory(this, state, waxed))
			.initialProperties(() -> baseBlock.get())
			.loot((lt, block) -> variant.generateLootTable(lt, block, this, state, waxed))
			.blockstate((ctx, prov) -> variant.generateBlockState(ctx, prov, this, state, waxed))
			.transform(TagGen.pickaxeOnly())
			.onRegister(block -> onRegister.accept(state, block))
			.tag(BlockTags.NEEDS_STONE_TOOL)
			.simpleItem();

		if (variant == BlockVariant.INSTANCE && state == WeatherState.UNAFFECTED && !waxed) {
			builder.recipe(mainBlockRecipe::accept);
		} else {
			builder.recipe((ctx, prov) -> {
				if (waxed) {
					Block unwaxed = get(variant, state, false).get();
					ShapelessRecipeBuilder.shapeless(RecipeCategory.BUILDING_BLOCKS, ctx.get())
						.requires(unwaxed)
						.requires(Items.HONEYCOMB)
						.unlockedBy("has_unwaxed", RegistrateRecipeProvider.has(unwaxed))
						.save(prov, ResourceLocation.fromNamespaceAndPath(ctx.getId()
							.getNamespace(), "crafting/" + generalDirectory + ctx.getName() + "_from_honeycomb"));
				}

				variant.generateRecipes(get(BlockVariant.INSTANCE, state, waxed), ctx, prov);
			});
		}

		if (variant == StairVariant.INSTANCE)
			builder.tag(BlockTags.STAIRS);

		if (variant == SlabVariant.INSTANCE)
			builder.tag(BlockTags.SLABS);

		return builder.register();
	}

@Override
	public void render(PoseStack ms, SuperRenderTypeBuffer buffer, Vec3 camera, float pt) {
		boolean hasTransform = transform != null;
		if (transform instanceof Sided && params.getHighlightedFace() != null)
			((Sided) transform).fromSide(params.getHighlightedFace());

		LevelAccessor levelAccessor = level.get();
		if (hasTransform && !transform.shouldRender(levelAccessor, pos, blockState))
			return;

		ms.pushPose();
		ms.translate(pos.getX() - camera.x, pos.getY() - camera.y, pos.getZ() - camera.z);
		if (hasTransform)
			transform.transform(levelAccessor, pos, blockState, ms);

		if (!isPassive) {
			ms.pushPose();
			ms.scale(-2.01f, -2.01f, 2.01f);
			ms.translate(-8 / 16.0, -8 / 16.0, -.5 / 16.0);
			getOutline().render(ms, buffer, 0xffffff);
			ms.popPose();
		}

		float fontScale = hasTransform ? -transform.getFontScale() : -1 / 64f;
		ms.scale(fontScale, fontScale, fontScale);
		renderContents(ms, buffer);

		ms.popPose();
	}

@Override
