public void render(BakedModel model, RenderType type, int light) {
		if (stack.isEmpty())
			return;

		ms.pushPose();
		ms.translate(-0.5D, -0.5D, -0.5D);

		if (!model.isCustomRenderer()) {
			VertexConsumer vc = ItemRenderer.getFoilBufferDirect(buffer, type, true, stack.hasFoil());
			for (BakedModel pass : model.getRenderPasses(stack, false)) {
				renderBakedItemModel(pass, light, ms, vc);
			}
		} else
			IClientItemExtensions.of(stack)
				.getCustomRenderer()
				.renderByItem(stack, transformType, ms, buffer, light, overlay);

		ms.popPose();
	}

@Override
	public boolean render(MapDecoration decoration, PoseStack poseStack, MultiBufferSource bufferSource, @NotNull MapItemSavedData mapData, MapDecorationTextureManager decorationTextures, boolean inItemFrame, int packedLight, int index) {
		poseStack.pushPose();

		poseStack.translate(decoration.x() / 2D + 64.0, decoration.y() / 2D + 64.0, -0.02D);

		poseStack.pushPose();

		poseStack.translate(0.5f, 0f, 0);
		poseStack.scale(4.5F, 4.5F, 3.0F);

		TextureAtlasSprite sprite = decorationTextures.get(decoration);
		float U0 = sprite.getU0();
		float V0 = sprite.getV0();
		float U1 = sprite.getU1();
		float V1 = sprite.getV1();
		VertexConsumer buffer = bufferSource.getBuffer(RenderType.text(sprite.atlasLocation()));
		Matrix4f mat = poseStack.last().pose();
		float zOffset = -0.001f;
		buffer.addVertex(mat, -1.0F, 1.0F, index * zOffset).setColor(-1).setUv(U0, V0).setLight(packedLight);
		buffer.addVertex(mat, 1.0F, 1.0F, index * zOffset).setColor(-1).setUv(U1, V0).setLight(packedLight);
		buffer.addVertex(mat, 1.0F, -1.0F, index * zOffset).setColor(-1).setUv(U1, V1).setLight(packedLight);
		buffer.addVertex(mat, -1.0F, -1.0F, index * zOffset).setColor(-1).setUv(U0, V1).setLight(packedLight);

		poseStack.popPose();

		if (decoration.name().isPresent()) {
			Font font = Minecraft.getInstance().font;
			Component component = decoration.name().get();
			float f6 = (float)font.width(component);
//			float f7 = Mth.clamp(25.0F / f6, 0.0F, 6.0F / 9.0F);
			poseStack.pushPose();
//			poseStack.translate((double)(0.0F + (float)getX() / 2.0F + 64.0F / 2.0F), (double)(0.0F + (float)getY() / 2.0F + 64.0F + 4.0F), (double)-0.025F);
			poseStack.translate(0, 6.0D, -0.005F);

			poseStack.scale(0.8f, 0.8f, 1.0F);
			poseStack.translate(-f6 / 2f + .5f, 0, 0);
//			poseStack.scale(f7, f7, 1.0F);
			font.drawInBatch(component, 0.0F, 0.0F, -1, false, poseStack.last()
					.pose(), bufferSource, Font.DisplayMode.NORMAL, Integer.MIN_VALUE, packedLight);
			poseStack.popPose();
		}

		poseStack.popPose();

		return true;
	}

public static void renderBlockEntities(List<BlockEntity> blockEntities, BitSet shouldRenderBEs, BitSet erroredBEsOut, @javax.annotation.Nullable VirtualRenderWorld renderLevel, Level realLevel, PoseStack ms, @javax.annotation.Nullable Matrix4f lightTransform, MultiBufferSource buffer,
										   float pt) {
		for (int i = shouldRenderBEs.nextSetBit(0); i >= 0 && i < blockEntities.size(); i = shouldRenderBEs.nextSetBit(i + 1)) {
			BlockEntity blockEntity = blockEntities.get(i);
			if (VisualizationManager.supportsVisualization(realLevel) && VisualizationHelper.skipVanillaRender(blockEntity))
				continue;

			BlockEntityRenderer<BlockEntity> renderer = Minecraft.getInstance()
				.getBlockEntityRenderDispatcher()
				.getRenderer(blockEntity);
			if (renderer == null) {
				// Don't bother looping over it again if we can't do anything with it.
				erroredBEsOut.set(i);
				continue;
			}

			BlockPos pos = blockEntity.getBlockPos();
			ms.pushPose();
			TransformStack.of(ms)
				.translate(pos);

			try {
				int realLevelLight = LevelRenderer.getLightColor(realLevel, getLightPos(lightTransform, pos));

				int light;
				if (renderLevel != null) {
					renderLevel.setExternalLight(realLevelLight);
					light = LevelRenderer.getLightColor(renderLevel, pos);
				} else {
					light = realLevelLight;
				}

				renderer.render(blockEntity, pt, ms, buffer, light, OverlayTexture.NO_OVERLAY);

			} catch (Exception e) {
				// Prevent this BE from causing more issues in the future.
				erroredBEsOut.set(i);

				String message = "BlockEntity " + RegisteredObjectsHelper.getKeyOrThrow(blockEntity.getType()) + " could not be rendered virtually.";
				if (AllConfigs.client().explainRenderErrors.get()) Create.LOGGER.error(message, e);
				else Create.LOGGER.error(message);
			}

			ms.popPose();
		}

		if (renderLevel != null) {
			renderLevel.resetExternalLight();
		}
	}

@Override
	protected void renderWindow(GuiGraphics graphics, int mouseX, int mouseY, float partialTicks) {
		float f = (float) (Util.getMillis() - this.firstRenderTime) / 1000.0F;
		float alpha = Mth.clamp(f, 0.0F, 1.0F);
		float elapsedPartials = minecraft.getTimer().getGameTimeDeltaPartialTick(false);

		if (parent instanceof TitleScreen) {
			if (alpha < 1)
				vanillaPanorama.render(graphics, this.width, this.height, 1, elapsedPartials);
			PANORAMA.render(graphics, this.width, this.height, 1, elapsedPartials);

			RenderSystem.enableBlend();
			RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA,
				GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			graphics.blit(PANORAMA_OVERLAY_TEXTURES, 0, 0, this.width, this.height, 0.0F, 0.0F, 16, 128, 16, 128);
		}

		RenderSystem.enableDepthTest();

		PoseStack ms = graphics.pose();

		for (int side : Iterate.positiveAndNegative) {
			ms.pushPose();
			ms.translate(width / 2, 60, 200);
			ms.scale(24 * side, 24 * side, 32);
			ms.translate(-1.75 * ((alpha * alpha) / 2f + .5f), .25f, 0);
			TransformStack.of(ms)
				.rotateXDegrees(45);
			GuiGameElement.of(AllBlocks.LARGE_COGWHEEL.getDefaultState())
				.rotateBlock(0, Util.getMillis() / 32f * side, 0)
				.render(graphics);
			ms.translate(-1, 0, -1);
			GuiGameElement.of(AllBlocks.COGWHEEL.getDefaultState())
				.rotateBlock(0, Util.getMillis() / -16f * side + 22.5f, 0)
				.render(graphics);
			ms.popPose();
		}

		RenderSystem.enableBlend();

		ms.pushPose();
		ms.translate(width / 2 - 32, 32, -10);
		ms.pushPose();
		ms.scale(0.25f, 0.25f, 0.25f);
		AllGuiTextures.LOGO.render(graphics, 0, 0);
		ms.popPose();
		new BoxElement().withBackground(0x88_000000)
			.flatBorder(new Color(0x01_000000))
			.at(-32, 56, 100)
			.withBounds(128, 11)
			.render(graphics);
		ms.popPose();

		ms.pushPose();
		ms.translate(0, 0, 200);
		graphics.drawCenteredString(font, Component.literal(Create.NAME).withStyle(ChatFormatting.BOLD)
				.append(
					Component.literal(" v" + CreateBuildInfo.VERSION).withStyle(ChatFormatting.BOLD, ChatFormatting.WHITE)),
			width / 2, 89, 0xFF_E4BB67);
		ms.popPose();

		RenderSystem.disableDepthTest();
	}

