public EditConfigScreen(EditableConfigGroup configGroup, boolean readOnly) {
        super();

        this.readOnly = readOnly;
        group = configGroup;
        MutableComponent baseTitle = configGroup.getName().copy().withStyle(ChatFormatting.BOLD);
        title = readOnly ? baseTitle.append(" (").append(Component.translatable("ftblibrary.read_only")).append(")") : baseTitle;
        allConfigButtons = new ArrayList<>();

        List<EditableConfigValue<?>> list = new ArrayList<>();
        collectAllConfigValues(group, list);

        if (!list.isEmpty()) {
            ConfigGroupButton group = null;

            for (var value : list) {
                if (group == null || group.group != value.getGroup()) {
                    allConfigButtons.add(new VerticalSpaceWidget(mainPanel, 4));
                    group = new ConfigGroupButton(mainPanel, value.getGroup());
                    allConfigButtons.add(group);
                    groupSize++;
                }

                ConfigEntryButton<?> btn = new ConfigEntryButton<>(mainPanel, group, value);
                allConfigButtons.add(btn);
            }

            if (groupSize == 1) {
                allConfigButtons.remove(group);
            }
        }

        buttonExpandAll = new SimpleButton(topPanel, List.of(Component.translatable("gui.expand_all"), hotkeyTooltip("="), hotkeyTooltip("+")), Icons.EXPAND,
                (_, _) -> toggleAll(false));
        buttonCollapseAll = new SimpleButton(topPanel, List.of(Component.translatable("gui.collapse_all"), hotkeyTooltip("-")), Icons.COLLAPSE,
                (_, _) -> toggleAll(true));
    }

public ConfigGroupButton(Panel panel, EditableConfigGroup g) {
            super(panel);
            setHeight(14);
            group = g;

            if (group.getParent() != null) {
                List<EditableConfigGroup> groups = new ArrayList<>();
                while (g.getParent() != null) {
                    groups.add(g);
