                graphics.pose().scale(scale, scale);

                for (i = 0; i < getDisplayedText().length; ++i) {
                    theme.drawString(graphics, formattedText[i], 0, i * textSpacing, col, textFlags);
                }

                graphics.pose().popMatrix();
            }
        }
    }

