@Override
    public void renderBloomEffect(PoseStack poseStack, BufferBuilder buffer, EffectRenderContext context) {
        float red = ((color >> 16) & 0xFF) / 255f;
        float green = ((color >> 8) & 0xFF) / 255f;
        float blue = (color & 0xFF) / 255f;

        poseStack.pushPose();
        poseStack.translate(posX, posY, posZ);
        pipeShape.forAllBoxes((x1, y1, z1, x2, y2, z2) -> {
            RenderBufferHelper.renderColorCube(buffer, poseStack,
                    (float) x1 - 0.001f, (float) y1 - 0.001f, (float) z1 - 0.001f,
                    (float) x2 + 0.001f, (float) y2 + 0.001f, (float) z2 + 0.001f,
                    red, green, blue, alpha, true);
        });
        poseStack.popPose();
    }

@SubscribeEvent(priority = EventPriority.HIGH)
    public void renderParticles(RenderLevelStageEvent event) {
        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES) return;
        if (this.depthEnabledParticles.isEmpty() && this.depthDisabledParticles.isEmpty()) return;

        Camera camera = event.getCamera();

        PoseStack poseStack = event.getPoseStack();
        poseStack.pushPose();
        poseStack.translate(-camera.getPosition().x, -camera.getPosition().y, -camera.getPosition().z);

        EffectRenderContext instance = EffectRenderContext.getInstance()
                .update(camera, event.getFrustum(), event.getPartialTick());

        if (!this.depthDisabledParticles.isEmpty()) {
            RenderSystem.depthMask(false);
            renderParticlesInLayer(poseStack, this.depthDisabledParticles, instance);
            RenderSystem.depthMask(true);
        }
        renderParticlesInLayer(poseStack, this.depthEnabledParticles, instance);

        poseStack.popPose();
    }

public void tick(PoseStack stack, MultiBufferSource.BufferSource multiBuf, Camera camera) {
        if (GameRenderer.getPositionColorShader() == null || !camera.isInitialized()) return;
        Vec3 offset = camera.getPosition().reverse();

        RenderSystem.disableDepthTest();
        RenderSystem.enableBlend();
        RenderSystem.setShader(GameRenderer::getPositionColorShader);
        RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
        RenderSystem.disableCull();

        stack.pushPose();
        stack.translate(offset.x, offset.y, offset.z);
        VertexConsumer buffer = multiBuf.getBuffer(GTRenderTypes.blockHighlightQuads());

        long time = System.currentTimeMillis();
        highlights.forEach(h -> h.render(buffer, stack, time));

        stack.popPose();
        multiBuf.endBatch();

        RenderSystem.enableCull();
        RenderSystem.enableDepthTest();
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();
    }

public static void renderBlockHighlight(PoseStack poseStack, Camera camera, BlockHitResult target,
                                            MultiBufferSource multiBufferSource, float partialTick) {
        var mc = Minecraft.getInstance();
        var level = mc.level;
        var player = mc.player;
        if (level != null && player != null) {
            ItemStack held = player.getMainHandItem();
            BlockPos blockPos = target.getBlockPos();
            Vector3fc blockCenter = blockPos.getCenter().toVector3f();

            Set<GTToolType> toolType = ToolHelper.getToolTypes(held);
            BlockEntity blockEntity = level.getBlockEntity(blockPos);

            Vec3 cameraPos = camera.getPosition();
            // draw tool grid highlight
            if ((!toolType.isEmpty()) || (held.isEmpty() && player.isShiftKeyDown())) {
                IToolGridHighlight gridHighlight = null;
                if (blockEntity instanceof IToolGridHighlight highLight) {
                    gridHighlight = highLight;
                } else if (level.getBlockState(blockPos).getBlock() instanceof IToolGridHighlight highLight) {
                    gridHighlight = highLight;
                } else if (toolType.contains(GTToolType.WRENCH)) {
                    var behavior = CustomBlockRotations.getCustomRotation(level.getBlockState(blockPos).getBlock());
                    if (behavior != null && behavior.showGrid()) {
                        gridHighlight = new IToolGridHighlight() {

                            @Override
                            public @Nullable UITexture sideTips(@NotNull Player player, @NotNull BlockPos pos,
                                                                @NotNull BlockState state,
                                                                @NotNull Set<GTToolType> toolTypes,
                                                                ItemStack held, @NotNull Direction side) {
                                return behavior.showSideTip(state, side) ? GTGuiTextures.TOOL_FRONT_FACING_ROTATION :
                                        null;
                            }
                        };
                    }
                }
                if (gridHighlight == null) {
                    return;
                }
                BlockState state = level.getBlockState(blockPos);
                poseStack.pushPose();
                if (gridHighlight.shouldRenderGrid(player, blockPos, state, held, toolType)) {
                    final IToolGridHighlight finalGridHighlight = gridHighlight;
                    drawGridOverlays(poseStack, multiBufferSource, cameraPos, target,
                            side -> finalGridHighlight.sideTips(player, blockPos, state, toolType, held, side));
                } else {
                    Direction facing = target.getDirection();
                    var texture = gridHighlight.sideTips(player, blockPos, state, toolType, held, facing);
                    if (texture != null) {
                        RenderSystem.disableDepthTest();
                        RenderSystem.enableBlend();
                        RenderSystem.defaultBlendFunc();

                        poseStack.translate(facing.getStepX() * 0.01f, facing.getStepY() * 0.01f,
                                facing.getStepZ() * 0.01f);
                        poseStack.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());

                        RenderUtil.moveToFace(poseStack, blockCenter, facing);
                        if (facing.getAxis() == Direction.Axis.Y) {
                            RenderUtil.rotateToFace(poseStack, facing, Direction.SOUTH);
                        } else {
                            RenderUtil.rotateToFace(poseStack, facing, Direction.NORTH);
                        }
                        poseStack.scale(1f / 16, 1f / 16, 0);
                        poseStack.translate(-8, -8, 0);

                        drawOverlayTexture(poseStack, multiBufferSource, texture, 0xffffffff,
                                4, 4, 8, 8);

                        RenderSystem.disableBlend();
                        RenderSystem.enableDepthTest();
                    }
                }
                poseStack.popPose();
                return;
            }

            // draw cover grid highlight
            ICoverable coverable = GTCapabilityHelper.getCoverable(level, blockPos, target.getDirection());
            if (coverable != null && CoverPlaceBehavior.isCoverBehaviorItem(held, coverable::hasAnyCover,
                    coverDef -> ICoverable.canPlaceCover(coverDef, coverable))) {
                poseStack.pushPose();

                drawGridOverlays(poseStack, multiBufferSource, cameraPos, target,
                        side -> coverable.hasCover(side) ? null : GTGuiTextures.TOOL_ATTACH_COVER);

                poseStack.popPose();
            }

            // draw pipe connection grid highlight
            var pipeType = held.getItem() instanceof PipeBlockItem pipeBlockItem ? pipeBlockItem.getBlock().pipeType :
                    null;
            if (pipeType instanceof IPipeType<?> type && blockEntity instanceof PipeBlockEntity<?, ?> pipeBlockEntity &&
                    pipeBlockEntity.getPipeType().type().equals(type.type())) {
                poseStack.pushPose();

                drawGridOverlays(poseStack, multiBufferSource, cameraPos, target,
                        side -> level.isEmptyBlock(blockPos.relative(side)) ?
                                pipeBlockEntity.getPipeTexture(true) : null);

                poseStack.popPose();
            }
        }
    }

private static void drawGridOverlays(PoseStack poseStack, MultiBufferSource bufferSource, Vec3 cameraPos,
                                         BlockHitResult blockHitResult, Function<Direction, UITexture> texture) {
        rColour = gColour = 0.2F + (float) Math.sin((System.currentTimeMillis() % (Mth.PI * 800)) / 800) / 2;
        bColour = 1f;
        BlockPos blockPos = blockHitResult.getBlockPos();
        float minX = blockPos.getX();
        float maxX = blockPos.getX() + 1;
        float minY = blockPos.getY();
        float maxY = blockPos.getY() + 1;
        float maxZ = blockPos.getZ() + 1.01f;
        Direction attachSide = ICoverable.traceCoverSide(blockHitResult);
        Vector3f topRight = new Vector3f(maxX, maxY, maxZ);
        Vector3f bottomRight = new Vector3f(maxX, minY, maxZ);
        Vector3f bottomLeft = new Vector3f(minX, minY, maxZ);
        Vector3f topLeft = new Vector3f(minX, maxY, maxZ);
        Vector3f shiftX = new Vector3f(0.25f, 0, 0);
        Vector3f shiftY = new Vector3f(0, 0.25f, 0);

        Vector3f cubeCenter = blockPos.getCenter().toVector3f();

        topRight.sub(cubeCenter);
        bottomRight.sub(cubeCenter);
        bottomLeft.sub(cubeCenter);
        topLeft.sub(cubeCenter);

        Direction front = blockHitResult.getDirection();
        Direction back = front.getOpposite();
        Direction left = RelativeDirection.LEFT.applyDirection(front);
        Direction right = RelativeDirection.RIGHT.applyDirection(front);
        Direction top = RelativeDirection.UP.applyDirection(front);
        Direction bottom = RelativeDirection.DOWN.applyDirection(front);
        if (front.getAxis() == Direction.Axis.Y) {
            Direction tmp = left;
            left = right;
            right = tmp;
        }

        Quaternionfc rotation = getRotation(Direction.SOUTH, front);
        topRight.rotate(rotation);
        bottomRight.rotate(rotation);
        bottomLeft.rotate(rotation);
        topLeft.rotate(rotation);
        shiftX.rotate(rotation);
        shiftY.rotate(rotation);

        UITexture leftBlocked = texture.apply(left);
        UITexture rightBlocked = texture.apply(right);
        UITexture topBlocked = texture.apply(top);
        UITexture bottomBlocked = texture.apply(bottom);
        UITexture frontBlocked = texture.apply(front);
        UITexture backBlocked = texture.apply(back);

        topRight.add(cubeCenter);
        bottomRight.add(cubeCenter);
        bottomLeft.add(cubeCenter);
        topLeft.add(cubeCenter);

        poseStack.pushPose();
        poseStack.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());

        VertexConsumer buffer = bufferSource.getBuffer(RenderType.lines());
        RenderSystem.lineWidth(3);
        PoseStack.Pose pose = poseStack.last();
        // straight top bottom lines
        drawLine(pose, buffer, new Vector3f(topRight).sub(shiftX), new Vector3f(bottomRight).sub(shiftX));
        drawLine(pose, buffer, new Vector3f(bottomLeft).add(shiftX), new Vector3f(topLeft).add(shiftX));
        // straight side to side lines
        drawLine(pose, buffer, new Vector3f(topLeft).sub(shiftY), new Vector3f(topRight).sub(shiftY));
        drawLine(pose, buffer, new Vector3f(bottomLeft).add(shiftY), new Vector3f(bottomRight).add(shiftY));

        RenderSystem.disableDepthTest();
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();

        poseStack.pushPose();
        poseStack.translate(front.getStepX() * 0.01f, front.getStepY() * 0.01f, front.getStepZ() * 0.01f);

        RenderUtil.moveToFace(poseStack, cubeCenter, front);
        RenderUtil.rotateToFace(poseStack, front, Direction.SOUTH);
        poseStack.scale(1f / 16, 1f / 16, 0);
        poseStack.translate(-8, -8, 0);

        // set margin to 1/18 of scaled texture edge length
        float MARGIN = 0.2f;

        if (leftBlocked != null) {
            int color = attachSide == left ? 0xffffffff : 0x44ffffff;
            drawOverlayTextureWithMargin(poseStack, bufferSource, leftBlocked, color, 0, 6, MARGIN);
        }
        if (topBlocked != null) {
            int color = attachSide == top ? 0xffffffff : 0x44ffffff;
            drawOverlayTextureWithMargin(poseStack, bufferSource, topBlocked, color, 6, 12, MARGIN);
        }
        if (rightBlocked != null) {
            int color = attachSide == right ? 0xffffffff : 0x44ffffff;
            drawOverlayTextureWithMargin(poseStack, bufferSource, rightBlocked, color, 12, 6, MARGIN);
        }
        if (bottomBlocked != null) {
            int color = attachSide == bottom ? 0xffffffff : 0x44ffffff;
            drawOverlayTextureWithMargin(poseStack, bufferSource, bottomBlocked, color, 6, 0, MARGIN);
        }
        if (frontBlocked != null) {
            int color = attachSide == front ? 0xffffffff : 0x44ffffff;
            drawOverlayTextureWithMargin(poseStack, bufferSource, frontBlocked, color, 6, 6, MARGIN);
        }
        if (backBlocked != null) {
            int color = attachSide == back ? 0xffffffff : 0x44ffffff;
            drawOverlayTextureWithMargin(poseStack, bufferSource, backBlocked, color, 0, 0, MARGIN);
            drawOverlayTextureWithMargin(poseStack, bufferSource, backBlocked, color, 12, 0, MARGIN);
            drawOverlayTextureWithMargin(poseStack, bufferSource, backBlocked, color, 0, 12, MARGIN);
            drawOverlayTextureWithMargin(poseStack, bufferSource, backBlocked, color, 12, 12, MARGIN);
        }
        RenderSystem.disableBlend();
        RenderSystem.enableDepthTest();

        poseStack.popPose();
        poseStack.popPose();
    }

public void draw(PoseStack poseStack, MultiBufferSource.BufferSource bufferSource, Camera camera,
                     RenderLevelStageEvent.Stage stage, float partialTick) {
        if (timeout.get() <= 0) return;
        if (this.schema == null || this.controllerPos == null) return;
        if (!camera.isInitialized()) return;

        RenderType renderType = STAGE_RENDER_TYPES.get(stage);
        if (renderType == null && stage != RenderLevelStageEvent.Stage.AFTER_BLOCK_ENTITIES) return;

        poseStack.pushPose();
        poseStack.translate(controllerPos.getX(), controllerPos.getY(), controllerPos.getZ());

        Vec3 cameraPos = camera.getPosition();
        if (renderType != null) {
            // render the appropriate chunk layer if renderType is a chunk render layer
            renderBlocks(renderType, poseStack, cameraPos);
        } else {
            // render block entities if renderType==null
            renderBlockEntities(poseStack, bufferSource, partialTick, cameraPos);
        }

        poseStack.popPose();
    }

protected void renderBlockEntities(PoseStack poseStack, MultiBufferSource.BufferSource bufferSource,
                                       float partialTick, Vec3 cameraPos) {
        RenderCompileResults compileResults = checkRecompile(cameraPos);
        if (compileResults == null) return;

        for (BlockEntity blockEntity : compileResults.blockEntities) {
            if (blockEntity == null) {
                continue;
            }
            BlockPos pos = blockEntity.getBlockPos();
            poseStack.pushPose();
            poseStack.translate(pos.getX() - cameraPos.x, pos.getY() - cameraPos.y, pos.getZ() - cameraPos.z);

            Minecraft.getInstance().getBlockEntityRenderDispatcher()
                    .render(blockEntity, partialTick, poseStack, bufferSource);

            poseStack.popPose();
        }

        bufferSource.endBatch(RenderType.solid());
        bufferSource.endBatch(RenderType.endPortal());
        bufferSource.endBatch(RenderType.endGateway());
        bufferSource.endBatch(Sheets.solidBlockSheet());
        bufferSource.endBatch(Sheets.cutoutBlockSheet());
        bufferSource.endBatch(Sheets.bedSheet());
        bufferSource.endBatch(Sheets.shulkerBoxSheet());
        bufferSource.endBatch(Sheets.signSheet());
        bufferSource.endBatch(Sheets.hangingSignSheet());
        bufferSource.endBatch(Sheets.chestSheet());
    }

protected CompletableFuture<RenderCompileResults> compileBlockBuffers(RenderCompileResults compileResults,
                                                                              Vec3 cameraPos) {
            if (this.isCanceled.get()) {
                return CompletableFuture.completedFuture(compileResults.withStatus(CompileStatus.CANCELED));
            }
            if (PatternPreviewRenderer.this.schema == null || PatternPreviewRenderer.this.renderLevel == null) {
                return CompletableFuture.completedFuture(compileResults.withStatus(CompileStatus.CANCELED));
            }
            RenderLevel fakeLevel = PatternPreviewRenderer.this.renderLevel;

            var blockRenderDispatcher = Minecraft.getInstance().getBlockRenderer();
            ChunkBufferBuilderPack chunkBufferBuilders = PatternPreviewRenderer.this.chunkBufferBuilders;

            RandomSource randomSource = RandomSource.create();
            PoseStack poseStack = new PoseStack();
            Set<RenderType> startedBuffers = new ReferenceArraySet<>(RenderType.chunkBufferLayers().size());

            ModelBlockRenderer.enableCaching();
            for (var blockEntry : PatternPreviewRenderer.this.schema) {
                BlockPos pos = blockEntry.getKey();
                BlockState blockState = fakeLevel.getBlockState(pos);
                if (blockState.isAir()) continue;
                FluidState fluidState = blockState.getFluidState();

                if (blockState.hasBlockEntity()) {
                    BlockEntity blockEntity = fakeLevel.getBlockEntity(pos);
                    if (blockEntity != null) {
                        compileResults.blockEntities.add(blockEntity);
                    }
                }

                if (!fluidState.isEmpty()) {
                    RenderType renderType = ItemBlockRenderTypes.getRenderLayer(fluidState);
                    BufferBuilder builder = chunkBufferBuilders.builder(renderType);
                    if (startedBuffers.add(renderType)) {
                        if (builder.building()) {
                            GTCEu.LOGGER.warn("Buffer is already building for RenderType: {}!", renderType);
                            return CompletableFuture.completedFuture(compileResults.withStatus(CompileStatus.CANCELED));
                        }
                        builder.begin(renderType.mode(), renderType.format());
                    }

                    SectionPos sectionPos = SectionPos.of(pos);
                    VertexConsumer vertexConsumer = new LiquidVertexConsumer(builder, sectionPos);
                    blockRenderDispatcher.renderLiquid(pos, fakeLevel, vertexConsumer,
                            blockState, fluidState);

                    markFluidSpritesActive(compileResults, fluidState);
                }

                if (blockState.getRenderShape() != RenderShape.INVISIBLE) {
                    BakedModel model = blockRenderDispatcher.getBlockModel(blockState);

                    BlockEntity blockEntity = fakeLevel.getBlockEntity(pos);
                    ModelData modelData = ModelData.EMPTY;
                    if (blockEntity != null) {
                        modelData = blockEntity.getModelData();
                    }
                    modelData = model.getModelData(fakeLevel, pos, blockState, modelData);

                    randomSource.setSeed(blockState.getSeed(pos));

                    for (RenderType renderType : model.getRenderTypes(blockState, randomSource, modelData)) {
                        BufferBuilder builder = chunkBufferBuilders.builder(renderType);
                        if (startedBuffers.add(renderType)) {
                            builder.begin(renderType.mode(), renderType.format());
                        }

                        poseStack.pushPose();
                        poseStack.translate(pos.getX(), pos.getY(), pos.getZ());

                        // scale the rendered model down by a bit
                        poseStack.translate(0.5f, 0.5f, 0.5f);
                        poseStack.scale(0.8f, 0.8f, 0.8f);
                        poseStack.translate(-0.5f, -0.5f, -0.5f);

                        // disable culling as all sides will be visible (they're scaled down)
                        blockRenderDispatcher.renderBatched(blockState, pos, fakeLevel, poseStack, builder, false,
                                randomSource, modelData, renderType);
                        poseStack.popPose();
                    }
                }
            }

            if (startedBuffers.contains(RenderType.translucent())) {
                BufferBuilder bufferBuilder = chunkBufferBuilders.builder(RenderType.translucent());
                if (!bufferBuilder.isCurrentBatchEmpty()) {
                    bufferBuilder.setQuadSorting(
                            VertexSorting.byDistance((float) cameraPos.x, (float) cameraPos.y, (float) cameraPos.z));
                }
            }

            for (RenderType renderType : startedBuffers) {
                BufferBuilder.RenderedBuffer renderedBuffer = chunkBufferBuilders.builder(renderType)
                        .endOrDiscardIfEmpty();
                if (renderedBuffer != null) {
                    compileResults.renderedLayers.put(renderType, renderedBuffer);
                }
            }
            ModelBlockRenderer.clearCache();

            if (this.isCanceled.get()) {
                compileResults.renderedLayers.values().forEach(BufferBuilder.RenderedBuffer::release);
                return CompletableFuture.completedFuture(compileResults.withStatus(CompileStatus.CANCELED));
            }

            List<CompletableFuture<Void>> uploads = new ArrayList<>();
            compileResults.renderedLayers.forEach((renderType, buffer) -> {
                uploads.add(uploadChunkLayer(compileResults, buffer, renderType));
                compileResults.hasBlocks.add(renderType);
            });
            return Util.sequenceFailFast(uploads).handle((result, error) -> {
                if (error != null && !(error instanceof CancellationException) &&
                        !(error instanceof InterruptedException)) {
                    Minecraft.getInstance().delayCrash(CrashReport.forThrowable(error, "Rendering chunk"));
                }
                if (this.isCanceled.get()) {
                    return compileResults.withStatus(CompileStatus.CANCELED);
                } else {
                    return compileResults.withStatus(CompileStatus.SUCCESS);
                }
            });
        }

public void drawBlocks(Set<BlockPos> offsets, PoseStack poseStack, VertexConsumer consumer,
                           Fluid fluid, RenderUtil.FluidTextureType texture,
                           int combinedOverlay, int combinedLight) {
        var fluidClientInfo = IClientFluidTypeExtensions.of(fluid);
        var sprite = texture.map(fluidClientInfo);
        float u0 = sprite.getU0(), v0 = sprite.getV0(), u1 = sprite.getU1(), v1 = sprite.getV1();
        int color = fluidClientInfo.getTintColor();

        for (var pos : offsets) {
            poseStack.pushPose();
            poseStack.translate(pos.getX(), pos.getY(), pos.getZ());

            for (var direction : GTUtil.DIRECTIONS) {
                if (offsets.contains(pos.relative(direction))) continue;
                if (direction.getAxis() != Direction.Axis.Y) direction = direction.getOpposite();

                drawFace(poseStack.last(), consumer,
                        transformVertices(getVertices(direction), direction), getNormal(direction),
                        u0, u1, v0, v1, color, combinedOverlay, combinedLight);
            }
            poseStack.popPose();
        }
    }

