                    itemStack, storedAmount, ItemStack.EMPTY, stack.is(CREATIVE_CHEST_ITEM));

            poseStack.popPose();
        }
        super.renderByItem(stack, displayContext, poseStack, buffer, packedLight, packedOverlay);
    }

@OnlyIn(Dist.CLIENT)
    public void renderChestItem(PoseStack poseStack, MultiBufferSource buffer, float totalTick, Direction frontFacing,
                                ItemStack stored, long storedAmount, ItemStack locked, boolean isCreative) {
        ItemStack itemStack = !stored.isEmpty() ? stored : locked;
        if (itemStack.isEmpty()) return;
        var itemRenderer = Minecraft.getInstance().getItemRenderer();

        poseStack.pushPose();
        poseStack.translate(0.5f, 0.5f, 0.5f);
        if (frontFacing.getAxis() == Direction.Axis.Y) {
            Quaternionf rotation = getRotation(Direction.NORTH, frontFacing);
            poseStack.mulPose(rotation);
        }
        poseStack.mulPose(new Quaternionf().rotateY(totalTick * Mth.TWO_PI / 80));
        poseStack.scale(0.6f, 0.6f, 0.6f);

        itemRenderer.renderStatic(itemStack, ItemDisplayContext.FIXED,
                LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY,
                poseStack, buffer, Minecraft.getInstance().level,
                Item.getId(itemStack.getItem()) + itemStack.getDamageValue());
        poseStack.popPose();

        drawAmountText(poseStack, buffer, frontFacing, storedAmount, isCreative);
    }

public static void setupModelRotation(MetaMachine machine, PoseStack poseStack) {
        var frontFacing = machine.getFrontFacing();
        var upwardFacing = machine.getUpwardsFacing();

        poseStack.translate(0.5f, 0.5f, 0.5f);
        float roll = frontFacing.getAxis().isHorizontal() ?
                frontAxisRollAngle(frontFacing, upwardFacing, Direction.UP) :
                upwardFacingAngle(upwardFacing) + (upwardFacing.getAxis() == Direction.Axis.X ? Mth.PI : 0);
        rotateMatrix(poseStack.last().pose(), roll, getDirectionAxis(frontFacing));
        poseStack.translate(-0.5f, -0.5f, -0.5f);
    }

public static void drawAmountText(PoseStack poseStack, MultiBufferSource buffer, Direction frontFacing,
                                      long storedAmount, boolean isCreative) {
        poseStack.pushPose();
        RenderSystem.disableDepthTest();
        poseStack.translate(frontFacing.getStepX() * -1 / 16f, frontFacing.getStepY() * -1 / 16f,
                frontFacing.getStepZ() * -1 / 16f);

        RenderUtil.moveToFace(poseStack, 0.5f, 0.5f, 0.5f, frontFacing);
        Direction spin = frontFacing.getAxis() == Direction.Axis.Y ? Direction.SOUTH : Direction.NORTH;
        RenderUtil.rotateToFace(poseStack, frontFacing, spin);
        poseStack.scale(1f / 64, 1f / 64, 0);
        poseStack.translate(-32, -32, 0);

        String text;
        int x = 0, y = 24;
        int w = 64, h = 28;
        float textX = x + w / 2.0f;
        float textY = y + h / 2.0f;

        poseStack.pushPose();
        if (isCreative) {
            text = "∞";
            poseStack.translate(textX, textY, 0);
            poseStack.scale(3.0f, 3.0f, 1.0f);
            poseStack.translate(-textX, -textY, 0);
        } else {
            text = storedAmount <= 0 ? "*" : FormattingUtil.formatNumberReadable(storedAmount, false);
        }

        Font font = Minecraft.getInstance().font;
        font.drawInBatch(text, textX - font.getSplitter().stringWidth(text) / 2.0f, textY - font.lineHeight / 2.0f,
                0xffffffff, false,
                poseStack.last().pose(), buffer, Font.DisplayMode.NORMAL, 0, LightTexture.FULL_BRIGHT);
        poseStack.popPose();
        RenderSystem.enableDepthTest();
        poseStack.popPose();
    }

@Override
    public void render(CentralMonitorMachine machine, MonitorGroup group, float partialTick, PoseStack poseStack,
                       MultiBufferSource buffer, int packedLight, int packedOverlay) {
        if (screen == null || group.isEmpty()) return;
        BlockPos rel = group.getRow(0, machine::toRelative).get(0);
        BlockPos size = GTUtil.getLast(group.getRow(-1, machine::toRelative))
                .offset(-rel.getX() + 1, -rel.getY() + 1, -rel.getZ() + 1);
        poseStack.translate(rel.getX(), rel.getY(), rel.getZ());
        Player player = MCHelper.getPlayer();
        HitResult hit = player.pick(player.getAttributeValue(ForgeMod.BLOCK_REACH.get()), partialTick, false);
        double mouseX = -1, mouseY = -1;
        if (hit instanceof BlockHitResult blockHit) {
            BlockPos pos = blockHit.getBlockPos();
            BlockPos relPos = machine.toRelative(pos);
            if (MetaMachine.getMachine(player.level(), pos) instanceof MonitorPartMachine monitor) {
                Vector2d monitorMousePos = monitor.getMousePos(hit);
                mouseX = relPos.getX() - rel.getX() + monitorMousePos.x();
                mouseY = relPos.getY() - rel.getY() + 1 - monitorMousePos.y();
                if (monitor instanceof AdvancedMonitorPartMachine advancedMonitor && mouseX >= 0 && mouseY >= 0 &&
                        mouseX <= width && mouseY <= height) {
                    if (advancedMonitor.isClickedThisFrame()) {
                        this.screen.mousePressed(GLFW.GLFW_MOUSE_BUTTON_LEFT);
                        this.vanillaScreen.mouseClicked(mouseX * 256, mouseY * 256, GLFW.GLFW_MOUSE_BUTTON_LEFT);
                        advancedMonitor.setClickedThisFrame(false);
                    }
                }
            }
        }
        if (mouseX >= 0 && mouseY >= 0 && mouseX * 256 <= width && mouseY * 256 <= height) {
            this.mouseX = (int) (mouseX * 256);
            this.mouseY = (int) (mouseY * 256);
        }
        // renderGui(size.getX(), size.getY(), poseStack, buffer, partialTick, (int) (mouseX * 256), (int) (mouseY *
        // 256));
    }

@Override
    public void render(CentralMonitorMachine machine, MonitorGroup group, float partialTick, PoseStack poseStack,
                       MultiBufferSource buffer, int packedLight, int packedOverlay) {
        if (group.isEmpty()) return;
        BlockPos rel = group.getRow(0, machine::toRelative).get(0);
        BlockPos size = GTUtil.getLast(group.getRow(-1, machine::toRelative))
                .offset(-rel.getX() + 1, -rel.getY() + 1, -rel.getZ() + 1);

        poseStack.translate(rel.getX(), rel.getY(), rel.getZ());

        ResourceLocation textureId = ClientImageCache.getOrLoadTexture(url);
        if (textureId == null) return;

        VertexConsumer consumer = buffer.getBuffer(GTRenderTypes.guiTexture(textureId));
        Matrix4f pose = poseStack.last().pose();

        float minX = 0, maxX = size.getX();
        float minY = 0, maxY = size.getY();

        consumer.vertex(pose, minX, maxY, 0).color(0xFFFFFFFF).uv(0, 1).uv2(LightTexture.FULL_BRIGHT).endVertex();
        consumer.vertex(pose, maxX, maxY, 0).color(0xFFFFFFFF).uv(1, 1).uv2(LightTexture.FULL_BRIGHT).endVertex();
        consumer.vertex(pose, maxX, minY, 0).color(0xFFFFFFFF).uv(1, 0).uv2(LightTexture.FULL_BRIGHT).endVertex();
        consumer.vertex(pose, minX, minY, 0).color(0xFFFFFFFF).uv(0, 0).uv2(LightTexture.FULL_BRIGHT).endVertex();
    }

@Override
    public void render(CentralMonitorMachine machine, MonitorGroup group, float partialTick, PoseStack poseStack,
                       MultiBufferSource buffer, int packedLight, int packedOverlay) {
        if (group.isEmpty()) return;
        BlockPos rel = group.getRow(0, machine::toRelative).get(0);
        int row = 0;
        int columns = group.getRow(0, machine::toRelative).size();
        poseStack.translate(rel.getX(), rel.getY(), rel.getZ());
        int layer = 0;
        for (GraphicsComponent graphics : text.getGraphics()) {
            if (graphics.x() < 0 || graphics.y() < 0) continue;
            float maxX = graphics.x2();
            float maxY = graphics.y2();
            if (maxX == Math.floor(maxX)) maxX--;
            if (maxY == Math.floor(maxY)) maxY--;
            BlockPos relativePos = rel.offset(Mth.floor(maxX), Mth.floor(maxY), 0);
            if (!group.getMonitorPositions().stream().map(machine::toRelative).toList().contains(relativePos))
                continue;
            poseStack.pushPose();
            poseStack.translate(graphics.x(), graphics.y(), layer * .001f);
            graphics.get().render(machine, group, partialTick, poseStack, buffer, packedLight, packedOverlay);
            poseStack.popPose();
            layer++;
        }
        poseStack.translate(0, 0, layer * .001f);
        poseStack.scale(TEXT_SCALE * scale, TEXT_SCALE * scale, TEXT_SCALE * scale);
        float y = 9;
        for (Component s : text) {
            boolean didAnything = false;
            for (FormattedCharSequence line : Minecraft.getInstance().font.split(s,
                    Math.round(columns * 135 / scale))) {
                if (y >= 144) {
                    try {
                        row++;
                        columns = group.getRow(row, machine::toRelative).size();
                        y -= 144;
                        poseStack.translate(-rel.getX() / (TEXT_SCALE * scale), -rel.getY() / (TEXT_SCALE * scale),
                                -rel.getZ() / (TEXT_SCALE * scale));
                        rel = group.getRow(row, machine::toRelative).get(0);
                        poseStack.translate(rel.getX() / (TEXT_SCALE * scale), rel.getY() / (TEXT_SCALE * scale),
                                rel.getZ() / (TEXT_SCALE * scale));
                    } catch (IndexOutOfBoundsException e) {
                        return;
                    }
                }
                Minecraft.getInstance().font.drawInBatch(
                        line,
                        9, y,
                        0xFFFFFF,
                        false,
                        poseStack.last().pose(),
                        buffer,
                        Font.DisplayMode.NORMAL,
                        0,
                        LightTexture.FULL_BRIGHT);
                y += Minecraft.getInstance().font.lineHeight * scale;
                didAnything = true;
            }
            if (!didAnything) {
                y += Minecraft.getInstance().font.lineHeight * scale;
            }
        }
    }

public static void renderInWorldText(MultiBufferSource multiBuf, PoseStack stack, Camera camera, String text,
                                         float scale, int colorARGB, Vec3 pos) {
        Font fontRender = Minecraft.getInstance().font;
        Vec3 c = pos.subtract(camera.getPosition());
        float stringMiddle = (float) fontRender.width(text) / 2.0F;
        stack.pushPose();
        stack.translate(c.x, c.y, c.z);
        stack.mulPose(camera.rotation());
        stack.scale(-scale, -scale, scale);
        Matrix4f mat = stack.last().pose();
        fontRender.drawInBatch(text, -stringMiddle, 0.0F, colorARGB, false, mat, multiBuf, Font.DisplayMode.SEE_THROUGH,
                0, 15728880);
        stack.popPose();
    }

