@Override
    protected void addTooltip(CompoundTag data, ITooltip tooltip, Player player, BlockAccessor block,
                              BlockEntity blockEntity, IPluginConfig config) {
        CompoundTag container = data.getCompound("energy");
        long changed = container.getLong("changed"), stored = container.getLong("stored"),
                capacity = container.getLong("capacity");
        tooltip.add(Component.translatable("gtceu.jade.changes_eu_tick",
                FormattingUtil.formatNumbers(((double) changed) / 20.0)));
        if (changed > 0L) {
            tooltip.add(Component
                    .translatable("gtceu.jade.remaining_charge_time",
                            getStringRemainTime((capacity - stored) / changed)));
        } else if (changed < 0L) {
            tooltip.add(Component.translatable("gtceu.jade.remaining_discharge_time",
                    getStringRemainTime((stored) / -changed)));
        }
        if (GTUtil.isShiftDown()) {
            CustomItemStackHandler handler = new CustomItemStackHandler();
            handler.deserializeNBT(data.getCompound("storage"));
            IElementHelper helper = tooltip.getElementHelper();
            for (int i = 0; i < handler.getSlots(); i++) {
                if (handler.getStackInSlot(i).getCount() != 0) {
                    ItemStack stack = handler.getStackInSlot(i);
                    tooltip.add(helper.smallItem(stack));
                    IElectricItem item = GTCapabilityHelper.getElectricItem(stack);
                    if (item == null) continue;
                    tooltip.append(Component.literal(
                            GTValues.VNF[item.getTier()] + "§r " + formatLongNumber(item.getCharge()) +
                                    " / " + formatLongNumber(item.getMaxCharge()) + " EU"));
                }
            }
        }
    }

@Override
    public void appendTooltip(ITooltip iTooltip, BlockAccessor blockAccessor, IPluginConfig iPluginConfig) {
        BlockEntity be = blockAccessor.getBlockEntity();
        if (be != null) {
            CompoundTag data = blockAccessor.getServerData().getCompound(getUid().toString());
            if (data.contains("cableData", Tag.TAG_COMPOUND)) {
                var tag = data.getCompound("cableData");
                long voltage = tag.getLong("currentVoltage");
                double amperage = tag.getDouble("currentAmperage");
                int temperature = tag.getInt("temperature");
                iTooltip.add(Component.translatable("gtceu.top.cable_voltage"));
                if (voltage != 0) {
                    iTooltip.append(Component.literal(GTValues.VNF[GTUtil.getTierByVoltage(voltage)]));
                    iTooltip.append(Component.literal(" / "));
                }
                iTooltip.append(Component.literal(GTValues.VNF[GTUtil.getTierByVoltage(tag.getLong("maxVoltage"))]));

                iTooltip.add(Component.translatable("gtceu.top.cable_amperage"));
                if (amperage != 0) {
                    iTooltip.append(Component.literal(DECIMAL_FORMAT_1F.format(amperage) + "A / "));
                }
                iTooltip.append(Component.translatable("gtceu.jade.amperage_use",
                        DECIMAL_FORMAT_1F.format(tag.getDouble("maxAmperage"))));

                if (temperature != CableBlockEntity.getDefaultTemp()) {
                    iTooltip.add(Component.translatable("gtceu.top.cable_overloaded", progressToFailure(
                            CableBlockEntity.getDefaultTemp(), CableBlockEntity.getMeltTemp(), temperature)));
                }
            }
        }
    }

