                            amp +
                            "A)")));
        } else {
            tooltip.add(Component.translatable("gtceu.top.transform_down",
                    (GTValues.VNF[voltage + 1] + " §r(" + amp + "A) -> " + GTValues.VNF[voltage] + " §r(" +
                            amp * 4 +
                            "A)")));
        }

        if (block.getHitResult().getDirection() ==
                Direction.from3DDataValue(data.getInt("side"))) {
            tooltip.add(
