private void addPages(SectionData section, JsonElement element) {
    try {
      JsonObject json = GsonHelper.convertToJsonObject(element, KEY.toString());
      String path = GsonHelper.getAsString(json, "path");
      // so, originally I considered designing a super fancy setup for sorting all the fluids
      // however, such system either requires additional serverside data keys for one time use sort, or creating pages for every fluid
      // list in presorted order is just simpler; as addon stuff makes the most sense at the end anyway
      List<String> presorted = StringLoadable.DEFAULT.list(0).getOrDefault(json, "order", List.of());

      // setup the index
      List<FluidEffects.Entry> effects = FluidEffectManager.INSTANCE.getFluids();
      if (effects.isEmpty()) {
        return;
      }

      // sort the fluid effects
      Map<ResourceLocation, PageWithIcon> newPages = new HashMap<>();
      for (FluidEffects.Entry entry : effects) {
        FluidEffects effect = entry.effects();
        // skip hidden effects
        if (effect.hidden()) {
          continue;
        }
        // skip effects with no fluids - usually means empty tag for compat
        List<FluidStack> fluids = effect.ingredient().getFluids();
        if (fluids.isEmpty()) {
          return;
        }

        // start building the page
        ResourceLocation name = entry.name();
        PageData newPage = new PageData(true);
        newPage.parent = section;
        newPage.source = section.source;
        newPage.type = FluidEffectContent.ID;
        newPage.name = name.getNamespace() + "." + name.getPath();
        String data = path + "/" + name.getNamespace() + "_" + name.getPath() + ".json";

        // if the path exists load the page, otherwise use a fallback option
        if (section.source.resourceExists(section.source.getResourceLocation(data))) {
          newPage.data = data;
        } else {
          newPage.content = new FluidEffectContent();
        }
        newPage.load();

        // set fluid effect properties into the page
        List<ItemStack> displayStacks = FluidItemElement.createItemList(fluids);
        if (newPage.content instanceof FluidEffectContent fluidEffectContent) {
          fluidEffectContent.loadEffectData(name, effect, fluids, displayStacks);
        }

        // build the icon
        SizedBookElement icon = new ItemElement(0, 0, 1f, displayStacks);
        newPages.put(name, new PageWithIcon(icon, newPage));
      }

      // add the pages and the indexes
      List<ContentPageIconList> listPages = ContentPageIconList.getPagesNeededForItemCount(
        newPages.size(), section,
        section.parent.translate(section.name),
        section.parent.strings.get(String.format("%s.subtext", section.name)));


      // add each page from the requested sorted order
      List<PageWithIcon> sortedPages = new ArrayList<>();
      for (String name : presorted) {
        // since this feature is just for us, automatically prefix IDs
        // though for the sake of pack makers we allow other domains if they contain :
        ResourceLocation id = null;
        if (name.contains(":")) {
          id = ResourceLocation.tryParse(name);
        } else if (ResourceLocation.isValidPath(name)) {
          id = TConstruct.getResource(name);
        }
        if (id == null) {
          continue;
        }
        PageWithIcon page = newPages.get(id);
        if (page != null) {
          sortedPages.add(page);
          newPages.remove(id);
        }
      }
      // sort remaining pages by title
      sortedPages.addAll(newPages.values().stream().sorted(Comparator.comparing(pair -> pair.page().getTitle())).toList());

      // add all sorted pages
      ContentPageIconList.addPages(section, listPages, sortedPages);
    } catch (JsonParseException e) {
      TConstruct.LOG.error("Failed to parse tag for book page injecting", e);
    }
  }

public static MaterialTier deserialize(JsonObject json) throws JsonSyntaxException {
      // we handle tier range outside of predicate for efficiency, since the predicates have to refetch materials otherwise
      IntRange tier = TIER.getOrDefault(json, "tier");

      // load in predicate
      IJsonPredicate<MaterialVariantId> predicate = MaterialPredicate.ANY;
      if (json.has("predicate")) {
        predicate = MaterialPredicate.LOADER.getIfPresent(json, "predicate", CONTEXT);
      } else if (json.has("tag")) {
        // shortcut for simple tag predicates
        predicate = MaterialPredicate.tag(TinkerLoadables.MATERIAL_TAGS.getIfPresent(json, "tag"));
      }

      // load in type specific data
      ResourceLocation type = JsonHelper.getResourceLocation(json, "type");
      MaterialType typeData = MATERIAL_TYPES.get(type);
      if (typeData == null) {
        throw new JsonSyntaxException("Invalid material section type " + type);
      }
      Function<MaterialVariantId,AbstractMaterialContent> pageBuilder = typeData.getMapping(GsonHelper.getAsBoolean(json, "detailed", false));

      String name;
      if (json.has("name")) {
        name = GsonHelper.getAsString(json, "name");
      } else {
        name = type.getPath();
      }

      Component titleSuffix = null;
      if (json.has("suffix")) {
        titleSuffix = Component.translatable(GsonHelper.getAsString(json, "suffix"));
      }

      // create final pages
      return new MaterialTier(name, new ValidMaterial(typeData.visibleStats(), tier, predicate), pageBuilder, typeData.sortComparator, titleSuffix);
    }

public void createPages(BookData book, SectionData sectionData) {
      sectionData.source = BookRepository.DUMMY;
      sectionData.parent = book;

      List<IMaterial> materialList = getMaterials();
      if (materialList.isEmpty()) {
        return;
      }

      // calculate pages needed
      List<ContentPageIconList> listPages = ContentPageIconList.getPagesNeededForItemCount(materialList.size(), sectionData, book.translate(sectionData.name), book.strings.get(String.format("%s.subtext", sectionData.name)));

      // create pages and add to index
      ListIterator<ContentPageIconList> iter = listPages.listIterator();
      List<PageData> newPages = new ArrayList<>(materialList.size());
      addPages(sectionData, "", newPages, iter.next(), iter, materialList);
      // insert new pages at the beginning after index, ensures its before any padding from the next section
      sectionData.pages.addAll(listPages.size(), newPages);
    }

public static void createPages(BookData book, SectionData sectionData, List<MaterialTier> tiers) {
      sectionData.source = BookRepository.DUMMY;
      sectionData.parent = book;

      List<List<IMaterial>> materials = tiers.stream().map(MaterialTier::getMaterials).toList();
      int size = 0;
      for (List<?> list : materials) {
        size += list.size();
      }
      if (size == 0) {
        return;
      }

      // calculate pages needed
      List<ContentPageIconList> listPages = ContentPageIconList.getPagesNeededForItemCount(size, sectionData, book.translate(sectionData.name), book.strings.get(String.format("%s.subtext", sectionData.name)));

      // create pages and add to index
      ListIterator<ContentPageIconList> iter = listPages.listIterator();
      ContentPageIconList overview = iter.next();

      List<PageData> newPages = new ArrayList<>(size);
      for (int i = 0; i < tiers.size(); i++) {
        MaterialTier tier = tiers.get(i);
        overview = tier.addPages(sectionData, tier.name + '.', newPages, overview, iter, materials.get(i));
      }
      // insert new pages at the beginning after index, ensures its before any padding from the next section
      sectionData.pages.addAll(listPages.size(), newPages);
    }

@Override
  public boolean applyForgeHandTransform(PoseStack poseStack, LocalPlayer player, HumanoidArm arm, ItemStack stack, float partialTicks, float equipProgress, float swingProgress) {
    // forge: why don't you give me the arm that is used on the next line???
    InteractionHand hand = arm == player.getMainArm() ? InteractionHand.MAIN_HAND : InteractionHand.OFF_HAND;
    // this code is copied from ItemInHandRenderer#renderArmWithItem with changes made for Tinker tools
    // to avoid redundant operations, we copied even methods that are unmodified, changes are noted below
    int sideOffset = arm == HumanoidArm.RIGHT ? 1 : -1;
    if (player.isUsingItem() && player.getUseItemRemainingTicks() > 0 && player.getUsedItemHand() == hand) {
      UseAnim anim = stack.getUseAnimation();
      switch (anim) {
        // merged BLOCK and NONE - same code
        case NONE, BLOCK:
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          break;

        case EAT:
        case DRINK:
          // start: applyEatTransform
          float timeLeft = player.getUseItemRemainingTicks() - partialTicks + 1;
          float percentage = timeLeft / stack.getUseDuration();
          if (percentage < 0.8f) {
            poseStack.translate(0, Mth.abs(Mth.cos(timeLeft / 4f * PI) * 0.1f), 0);
          }

          float speed = 1 - (float)Math.pow(percentage, 27);
          int sideOffset1 = arm == HumanoidArm.RIGHT ? 1 : -1;
          poseStack.translate(speed * 0.6F * (float) sideOffset1, speed * -0.5f, speed * 0);
          poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset1 * speed * 90));
          poseStack.mulPose(Axis.XP.rotationDegrees(speed * 10));
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset1 * speed * 30));
          // end: applyEatTransform
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          break;

        // crossbow is moved from the vanilla special case to a general animation
        case BOW:
        case CROSSBOW: {
          boolean isBow = anim == UseAnim.BOW;
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          // change: merged in crossbow
          if (isBow) {
            poseStack.translate(sideOffset * -0.2785682f, 0.18344387f, 0.15731531f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-13.935f));
            poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 35.3f));
          } else {
            poseStack.translate(sideOffset * -0.4785682f, -0.094387f, 0.05731531f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-11.935f));
            poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 65.3f));
          }
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -9.785f));

          float remainingTime = (float) stack.getUseDuration() - ((float) player.getUseItemRemainingTicks() - partialTicks + 1);
          // change: scale charge by drawtime instead of a flat 20f or the crossbow enchantment
          float charge = remainingTime / ModifierUtil.getPersistentInt(stack, GeneralInteractionModifierHook.KEY_DRAWTIME, 20);
          // only bows do this weird charge formula
          if (isBow) {
            charge = (charge * charge + charge * 2) / 3;
          }
          if (charge > 1) {
            charge = 1;
          }

          if (charge > 0.1f) {
            // change: inlined expressions, replaced (value * 0) with 0
            poseStack.translate(0, Mth.sin((remainingTime - 0.1f) * 1.3f) * (charge - 0.1f) * 0.004f, 0);
          }
          // change: replaced (value * 0) with 0
          poseStack.translate(0, 0, charge * 0.04f);
          poseStack.scale(1, 1, 1 + charge * 0.2f);
          poseStack.mulPose(Axis.YN.rotationDegrees(sideOffset * 45));
          break;
        }

        case SPEAR:
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          poseStack.translate(sideOffset * -0.5f, 0.7f, 0.1f);
          // change: added 45 degrees to take into account tools being diagonal
          poseStack.mulPose(Axis.XP.rotationDegrees(-90));
          poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 35.3f));
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -9.785f));
          float sRemainingTime = stack.getUseDuration() - (player.getUseItemRemainingTicks() - partialTicks + 1);
          // change: scale charge by drawtime instead of a flat 10f, tridents have 2.0 drawspeed I decided
          float sCharge = sRemainingTime / ModifierUtil.getPersistentInt(stack, GeneralInteractionModifierHook.KEY_DRAWTIME, 20);
          if (sCharge > 1) {
            sCharge = 1;
          }

          if (sCharge > 0.1F) {
            // change: inlined expressions, replaced (value * 0) with 0
            poseStack.translate(0, Mth.sin((sRemainingTime - 0.1F) * 1.3F) * (sCharge - 0.1F) * 0.004F, 0);
          }
          poseStack.translate(0, 0, sCharge * 0.2f);
          poseStack.scale(1, 1, 1 + sCharge * 0.2f);
          poseStack.mulPose(Axis.YN.rotationDegrees(sideOffset * 45));
          break;

        case BRUSH:
          // start: applyBrushTransform
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          float xRot = -15 + 75 * Mth.cos((1 - ((float) (player.getUseItemRemainingTicks() % 10) - partialTicks + 1) / 10) * 2 * PI);
          if (arm != HumanoidArm.RIGHT) {
            poseStack.translate(0.1, 0.83, 0.35);
            poseStack.mulPose(Axis.XP.rotationDegrees(-80));
            poseStack.mulPose(Axis.YP.rotationDegrees(-90));
            poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
            poseStack.translate(-0.3, 0.22, 0.35);
          } else {
            poseStack.translate(-0.25, 0.22, 0.35);
            poseStack.mulPose(Axis.XP.rotationDegrees(-80));
            poseStack.mulPose(Axis.YP.rotationDegrees(90));
            poseStack.mulPose(Axis.ZP.rotationDegrees(0));
            poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
          }
          // end: applyBrushTransform
      }
    } else if (player.isAutoSpinAttack()) {
      applyItemArmTransform(poseStack, equipProgress, sideOffset);
      poseStack.translate(sideOffset * -0.4f, 0.8f, 0.3f);
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 105));
      poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -85));
    } else {
      poseStack.translate(
        sideOffset * -0.4f * Mth.sin(Mth.sqrt(swingProgress) * PI),
        0.2f * Mth.sin(Mth.sqrt(swingProgress) * PI * 2),
        -0.2f * Mth.sin(swingProgress * PI));
      applyItemArmTransform(poseStack, equipProgress, sideOffset);
      // begin: applyItemArmAttackTransform
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * (45 + Mth.sin(swingProgress * swingProgress * (float)Math.PI) * -20)));
      float rotation = Mth.sin(Mth.sqrt(swingProgress) * PI);
      poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * rotation * -20));
      poseStack.mulPose(Axis.XP.rotationDegrees(rotation * -80));
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * -45));
      // end: applyItemArmAttackTransform
    }
    return true;
  }

