@Nullable
  @Override
  public IRecipeTransferError transferRecipe(TinkerStationContainerMenu container, T recipe, IRecipeSlotsView recipeSlotsView, Player player, boolean maxTransfer, boolean doTransfer) {
    // must have server support
    if (!handlerHelper.recipeTransferHasServerSupport()) {
      return handlerHelper.createUserErrorWithTooltip(Component.translatable("jei.tooltip.error.recipe.transfer.no.server"));
    }

    // ensure we have space for the entire recipe
    List<IRecipeSlotView> slotViews = recipeSlotsView.getSlotViews(RecipeIngredientRole.INPUT);
    int size = container.getInputSlots().size();
    if (!validateRecipeFits(slotViews, size)) {
      return this.handlerHelper.createUserErrorWithTooltip(Component.translatable("jei.tconstruct.tinker_station.too_large"));
    }

    // filter down the recipe slots to fit within the station slots
    IRecipeSlotsView filteredSlotView = recipeSlotsView;
    if (slotViews.size() > size) {
      filteredSlotView = handlerHelper.createRecipeSlotsView(slotViews.subList(0, size));
    }
    return this.handler.transferRecipe(container, recipe, filteredSlotView, player, maxTransfer, doTransfer);
  }

@Nullable
  @Override
  public IRecipeTransferError transferRecipe(ToolContainerMenu container, CraftingRecipe recipe, IRecipeSlotsView recipeSlotsView, Player player, boolean maxTransfer, boolean doTransfer) {
    // if we have no crafting slots, nothing to do
    int slots = container.getToolInventoryStart() - 1;
    if (slots <= 0) {
      return handlerHelper.createInternalError();
    }
    // must have server support
    if (!handlerHelper.recipeTransferHasServerSupport()) {
      Component tooltipMessage = Component.translatable("jei.tooltip.error.recipe.transfer.no.server");
      return handlerHelper.createUserErrorWithTooltip(tooltipMessage);
    }

    // if we have a full crafting grid, just do the normal transfer
    if (slots >= 9) {
      return handler.transferRecipe(container, recipe, recipeSlotsView, player, maxTransfer, doTransfer);
    }

    // if we have a small grid, recipe must fit in the 2x2
    List<IRecipeSlotView> slotViews = recipeSlotsView.getSlotViews(RecipeIngredientRole.INPUT);
    if (!validateIngredientsOutsidePlayerGridAreEmpty(slotViews)) {
      Component tooltipMessage = Component.translatable(
        "jei.tooltip.error.recipe.transfer.too.large.player.inventory"
      );
      return this.handlerHelper.createUserErrorWithTooltip(tooltipMessage);
    }

    // filter the crafting table input slots to player inventory input slots
    List<IRecipeSlotView> filteredSlotViews = filterSlots(slotViews);
    IRecipeSlotsView filteredRecipeSlots = this.handlerHelper.createRecipeSlotsView(filteredSlotViews);
    return this.handler.transferRecipe(container, recipe, filteredRecipeSlots, player, maxTransfer, doTransfer);
  }

@Override
  default void onTooltip(IRecipeSlotView recipeSlotView, List<Component> tooltip) {
    ListIterator<Component> listIterator = tooltip.listIterator();
    while (listIterator.hasNext()) {
      Component component = listIterator.next();
      if (component.getContents() instanceof TranslatableContents translatable && AMOUNT_KEY.equals(translatable.getKey())) {
        listIterator.remove();
        FluidStack fluid = recipeSlotView.getDisplayedIngredient(ForgeTypes.FLUID_STACK).orElse(FluidStack.EMPTY);
        List<Component> newTooltip = new ArrayList<>();
        onFluidTooltip(fluid, recipeSlotView, newTooltip);
        tooltip.addAll(listIterator.nextIndex(), newTooltip);
        return;
      }
    }
    // failed to find the tooltip to replace, so just append our stuff at the end
    FluidStack fluid = recipeSlotView.getDisplayedIngredient(ForgeTypes.FLUID_STACK).orElse(FluidStack.EMPTY);
    onFluidTooltip(fluid, recipeSlotView, tooltip);
  }

@Override
  default void onRichTooltip(IRecipeSlotView recipeSlotView, ITooltipBuilder tooltip) {
    ListIterator<Either<FormattedText,TooltipComponent>> listIterator = tooltip.getLines().listIterator();
    while (listIterator.hasNext()) {
      FormattedText line = listIterator.next().left().orElse(null);
      if (line instanceof Component component && component.getContents() instanceof TranslatableContents translatable && AMOUNT_KEY.equals(translatable.getKey())) {
        listIterator.remove();
        FluidStack fluid = recipeSlotView.getDisplayedIngredient(ForgeTypes.FLUID_STACK).orElse(FluidStack.EMPTY);
        onFluidTooltip(fluid, recipeSlotView, tooltip);
        return;
      }
    }
    // failed to find the tooltip to replace, so just append our stuff at the end
    recipeSlotView.getDisplayedIngredient(ForgeTypes.FLUID_STACK)
      .ifPresent(fluid -> onFluidTooltip(fluid, recipeSlotView, tooltip));
  }

