    long time = System.nanoTime();
    try {
      ResourceManager manager = Minecraft.getInstance().getResourceManager();
      // the forge mod bus is annoying, but stuck using it due to the normal bus not existing at datagen time
      MaterialPartTextureGenerator.runCallbacks(null, manager);

      Player player = Minecraft.getInstance().player;

      // get the list of sprites
      GeneratorConfiguration generatorConfig = loadGeneratorConfig(manager);
      if (generatorConfig.sprites.isEmpty()) {
        if (player != null) {
          player.displayClientMessage(NO_PARTS, false);
        }
        return;
      }

      // Predicate to check if a material ID is valid
      // TODO: variant filter?
      Predicate<MaterialVariantId> validMaterialId = loc -> (modId.isEmpty() || modId.equals(loc.getId().getNamespace())) && (materialPath.isEmpty() || materialPath.equals(loc.getId().getPath()));

      // get all materials, filtered by the given parameters
      List<MaterialSpriteInfo> materialSprites = loadMaterialRenderInfoGenerators(manager, validMaterialId);
      if (materialSprites.isEmpty()) {
        if (player != null) {
          player.displayClientMessage(NO_MATERIALS, false);
        }
        return;
      }

      // prepare the output directory
      Path path = Minecraft.getInstance().getResourcePackDirectory().resolve(PACK_NAME);
      BiConsumer<ResourceLocation, NativeImage> saver = (outputPath, image) -> saveImage(path, outputPath, image);
      BiConsumer<ResourceLocation, JsonObject> metaSaver = (outputPath, image) -> saveMetadata(path, outputPath, image);

      // create a pack.mcmeta so its a valid resource pack
      GeneratePackHelper.saveMcmeta(path, PackType.CLIENT_RESOURCES, "Generated Resources from the Tinkers' Construct Part Texture Generator");

      // predicate for whether we should generate the texture
      AbstractSpriteReader spriteReader = new ResourceManagerSpriteReader(manager, MaterialPartTextureGenerator.FOLDER);
      MutableInt generated = new MutableInt(0); // keep track of how many generated
      Predicate<ResourceLocation> shouldGenerate;
      if (operation == Operation.ALL) {
        shouldGenerate = exists -> {
          generated.add(1);
          return true;
        };
      } else {
        shouldGenerate = loc -> {
          if (!spriteReader.exists(loc)) {
            generated.add(1);
            return true;
          }
          return false;
        };
      }

      // at this point in time we have all our materials, time to generate our sprites
      for (MaterialSpriteInfo material : materialSprites) {
        for (PartSpriteInfo part : generatorConfig.sprites) {
          // if the part skips variants and the material is a variant, skip
          if (!material.isVariant() || !part.isSkipVariants()) {
            for (MaterialStatsId statType : part.getStatTypes()) {
              if (material.supportStatType(statType) || generatorConfig.statOverrides.hasOverride(statType, material.getTexture())) {
                ResourceLocation spritePath = MaterialPartTextureGenerator.outputPath(part, material);
                if (shouldGenerate.test(spritePath)) {
                  MaterialPartTextureGenerator.generateSprite(spriteReader, material, part, spritePath, saver, metaSaver);
                }
                break;
              }
            }
          }
        }
      }
      spriteReader.closeAll();

      // success message
      long deltaTime = System.nanoTime() - time;
      int count = generated.getValue();
      MaterialPartTextureGenerator.runCallbacks(null, null);
      log.info("Finished generating {} textures in {} ms", count, deltaTime / 1000000f);
      if (Minecraft.getInstance().player != null) {
        Minecraft.getInstance().player.displayClientMessage(Component.translatable(SUCCESS_KEY, count, (deltaTime / 1000000) / 1000f, GeneratePackHelper.getOutputComponent(path.toFile())), false);
      }
    } catch (Exception e) {
      long deltaTime = System.nanoTime() - time;
      log.error("Failed to generate part textures after {} ms", deltaTime / 1000000f, e);
      if (Minecraft.getInstance().player != null) {
        Minecraft.getInstance().player.displayClientMessage(Component.translatable(FAILURE_KEY, (deltaTime / 1000000) / 1000f, e.getMessage()).withStyle(ChatFormatting.RED), false);
      }
    }
  }

private static int update(CommandContext<CommandSourceStack> context, Type type, Operation op) throws CommandSyntaxException {
    // simplifies later operations if we skip operations that do nothing
    List<LivingEntity> successes;
    IToolStat<?> stat = ToolStatArgument.getStat(context, type.stat);
    Object display;
    if (op == Operation.SET && type == Type.BONUS) {
      Tag tag = NbtTagArgument.getNbtTag(context, "value");
      successes = setStat(context, stat, tag);
      display = tag;
    } else {
      float value = FloatArgumentType.getFloat(context, "value");
      if (op == Operation.MODIFY) {
        if (value == 0 && type == Type.BONUS) {
          throw INVALID_ADD.create();
        }
        if (value == 1 && type == Type.MULTIPLY) {
          throw INVALID_MULTIPLY.create();
        }
      }
      INumericToolStat<?> numeric = (INumericToolStat<?>)stat;
      if (type == Type.BONUS) {
        successes = updateEntities(context, (tool, stats) -> stats.addBonus(tool, numeric, value));
      } else if (op == Operation.SET) {
        successes = updateEntities(context, (tool, stats) -> stats.setMultiplier(tool, numeric, value));
      } else {
        successes = updateEntities(context, (tool, stats) -> stats.multiply(tool, numeric, value));
      }
      display = value;
    }

    // success message
    CommandSourceStack source = context.getSource();
    int size = successes.size();
    String successKey = SUCCESS_KEY_PREFIX + type.key + "." + op.key + ".";
    if (size == 1) {
      source.sendSuccess(() -> Component.translatable(successKey + "single", stat.getPrefix(), display, successes.get(0).getDisplayName()), true);
    } else {
      source.sendSuccess(() -> Component.translatable(successKey + "multiple", stat.getPrefix(), display, size), true);
    }
    return size;
  }

@Override
  public void render(HeatingStructureBlockEntity smeltery, float partialTicks, PoseStack matrices, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
    Level world = smeltery.getLevel();
    if (world == null) return;
    BlockState state = smeltery.getBlockState();
    StructureData structure = smeltery.getStructure();
    boolean structureValid = state.getValue(ControllerBlock.IN_STRUCTURE) && structure != null;

    // render erroring block, done whether in the structure or not
    BlockPos errorPos = smeltery.getErrorPos();
    if (errorPos != null && Minecraft.getInstance().player != null) {
      // either we must be holding the book, or the structure must be erroring and it be within 10 seconds of last update
      boolean highlightError = smeltery.isHighlightError();
      if ((!structureValid && highlightError) || smeltery.showDebugBlockBorder(Minecraft.getInstance().player)) {
        // distance check, 512 is the squared length of the diagonal of a max size structure
        BlockPos pos = smeltery.getBlockPos();
        BlockPos playerPos = Minecraft.getInstance().player.blockPosition();
        int dx = playerPos.getX() - pos.getX();
        int dz = playerPos.getZ() - pos.getZ();
        if ((dx * dx + dz * dz) < 512) {
          // color will be yellow if the structure is valid (expanding), red if invalid
          VertexConsumer vertexBuilder = buffer.getBuffer(highlightError ? TinkerRenderTypes.ERROR_BLOCK : RenderType.LINES);
          LevelRenderer.renderShape(matrices, vertexBuilder, Shapes.block(), errorPos.getX() - pos.getX(), errorPos.getY() - pos.getY(), errorPos.getZ() - pos.getZ(), 1f, structureValid ? 1f : 0f, 0f, 0.5f);
        }
      }
    }

    // if no structure, nothing else to do
    if (!structureValid) {
      return;
    }

    // relevant positions
    BlockPos pos = smeltery.getBlockPos();
    BlockPos minPos = structure.getMinInside();
    BlockPos maxPos = structure.getMaxInside();

    // offset to make rendering min pos relative
    matrices.pushPose();
    matrices.translate(minPos.getX() - pos.getX(), minPos.getY() - pos.getY(), minPos.getZ() - pos.getZ());
    // render tank fluids, use minPos for brightness
    SmelteryTankRenderer.renderFluids(matrices, buffer, smeltery.getTank(), minPos, maxPos, LevelRenderer.getLightColor(world, minPos));

    // render items
    int xd = 1 + maxPos.getX() - minPos.getX();
    int zd = 1 + maxPos.getZ() - minPos.getZ();
    int layer = xd * zd;
    Direction facing = state.getValue(ControllerBlock.FACING);
    Quaternionf itemRotation = Axis.YP.rotationDegrees(-90.0F * (float)facing.get2DDataValue());
    MeltingModuleInventory inventory = smeltery.getMeltingInventory();
    Minecraft mc = Minecraft.getInstance();
    ItemRenderer itemRenderer = mc.getItemRenderer();
    int max = Config.CLIENT.maxSmelteryItemQuads.get();
    if (max != 0) {
      int quadsRendered = 0;
      for (int i = 0; i < inventory.getSlots(); i++) {
        ItemStack stack = inventory.getStackInSlot(i);
        if (!stack.isEmpty()) {
          // calculate position inside the smeltery from slot index
          int height = i / layer;
          int layerIndex = i % layer;
          int offsetX = layerIndex % xd;
          int offsetZ = layerIndex / xd;
          BlockPos itemPos = minPos.offset(offsetX, height, offsetZ);

          // offset to the slot position in the structure, scale, and rotate the item
          matrices.pushPose();
          matrices.translate(offsetX + 0.5f, height + 0.5f, offsetZ + 0.5f);
          matrices.mulPose(itemRotation);
          matrices.scale(ITEM_SCALE, ITEM_SCALE, ITEM_SCALE);
          BakedModel model = itemRenderer.getModel(stack, world, null, 0);
          itemRenderer.render(stack, TinkerItemDisplays.MELTER, false, matrices, buffer, LevelRenderer.getLightColor(world, itemPos), OverlayTexture.NO_OVERLAY, model);
          matrices.popPose();

          // done as quads rather than items as its not that expensive to draw blocks, items are the problem
          if (max != -1) {
            // builtin has no quads, lets pretend its 100 as they are more expensive
            if (model.isCustomRenderer()) {
              quadsRendered += 100;
            } else {
              RandomSource random = smeltery.getLevel().getRandom();
              // not setting the seed on the random and ignoring the forge layered model stuff means this is just an estimate, but since this is for the sake of performance its not a huge deal for it to be exact
              for (Direction direction : Direction.values()) {
                quadsRendered += model.getQuads(null, direction, random, ModelData.EMPTY, null).size();
              }
              quadsRendered += model.getQuads(null, null, random, ModelData.EMPTY, null).size();
            }
            if (quadsRendered > max) {
              break;
            }
          }
        }
      }
    }

    matrices.popPose();
  }

public void addTooltip(GuiGraphics graphics, int mouseX, int mouseY, boolean hasTank) {
    int checkX = mouseX - screen.leftPos;
    int checkY = mouseY - screen.topPos;

    if (isHovered(checkX, checkY)) {
      List<Component> tooltip;
      // if an item or we have a fuel slot, do item tooltip
      if (hasFuelSlot || fuelInfo.isItem()) {
        // if there is a fuel slot, start below the fuel slot
        if (!hasFuelSlot || checkY > y + 18) {
          if (hasTank) {
            // no invalid fuel, we assume the slot is validated (hasFuelSlot is only true for the heater which validates)
            int temperature = fuelModule.getTemperature();
            if (temperature > 0) {
              tooltip = Arrays.asList(TOOLTIP_SOLID_FUEL, Component.translatable(TOOLTIP_TEMPERATURE, temperature).withStyle(ChatFormatting.GRAY, ChatFormatting.ITALIC));
            } else {
              tooltip = TOOLTIP_NO_FUEL;
            }
          } else {
            tooltip = TOOLTIP_NO_TANK;
          }
        } else {
          tooltip = Collections.emptyList();
        }
      } else if (!fuelInfo.isEmpty()) {
        FluidStack fluid = fuelInfo.getFluid();
        tooltip = FluidTooltipHandler.getFluidTooltip(fluid, fuelInfo.getTotalAmount());
        int temperature = fuelInfo.getTemperature();
        if (temperature > 0) {
          tooltip.add(1, Component.translatable(TOOLTIP_TEMPERATURE, temperature).withStyle(ChatFormatting.GRAY, ChatFormatting.ITALIC));
        } else {
          tooltip.add(1, TOOLTIP_INVALID_FUEL);
        }
      } else {
        tooltip = hasTank ? TOOLTIP_NO_FUEL : TOOLTIP_NO_TANK;
      }

      graphics.renderComponentTooltip(screen.font, tooltip, mouseX, mouseY);
    }
  }

