public static void onKeyPressed(int action) {
		Minecraft mc = Minecraft.getInstance();
		while (JadeKeys.openConfig().consumeClick()) {
			Jade.invalidateConfig();
			ItemStorageProvider.targetCache.invalidateAll();
			ItemStorageProvider.containerCache.invalidateAll();
			mc.gui.setScreen(new HomeConfigScreen(null));
		}

		while (JadeKeys.showOverlay().consumeClick()) {
			IWailaConfig.General general = IWailaConfig.get().general();
			DisplayMode mode = general.getDisplayMode();
			if (mode == DisplayMode.TOGGLE) {
				general.setDisplayTooltip(!general.shouldDisplayTooltip());
				if (!general.shouldDisplayTooltip() && Jade.history().hintOverlayToggle) {
					mc.gui.chatListener().handleSystemMessage(Component.translatable("toast.jade.toggle_hint.1"), false);
					mc.gui.chatListener().handleSystemMessage(
							Component.translatable(
									"toast.jade.toggle_hint.2",
									JadeKeys.showOverlay().getTranslatedKeyMessage()), false);
					Jade.history().hintOverlayToggle = false;
				}
				narrateKey("show_overlay", general.shouldDisplayTooltip());
				IWailaConfig.get().save();
			}
		}

		while (JadeKeys.toggleLiquid().consumeClick()) {
			IWailaConfig.General general = IWailaConfig.get().general();
			general.setDisplayFluids(!general.shouldDisplayFluids());
			narrateKey("toggle_liquid", general.shouldDisplayFluids());
			IWailaConfig.get().save();
		}

		while (JadeKeys.narrate().consumeClick()) {
			IWailaConfig.Accessibility accessibility = IWailaConfig.get().accessibility();
			if (accessibility.getTTSMode() == TTSMode.TOGGLE) {
				accessibility.toggleTTS();
				if (accessibility.shouldEnableTextToSpeech() && Jade.history().hintNarratorToggle) {
					mc.gui.chatListener().handleSystemMessage(Component.translatable("toast.jade.tts_hint.1"), false);
					mc.gui.chatListener().handleSystemMessage(
							Component.translatable(
									"toast.jade.tts_hint.2",
									JadeKeys.narrate().getTranslatedKeyMessage()), false);
					Jade.history().hintNarratorToggle = false;
				}
				IWailaConfig.get().save();
			} else if (tickHandler.rootElement != null) {
				tickHandler.narrate(tickHandler.rootElement, false);
			}
		}

		if (Jade.rootConfig().isEnableProfiles()) {
			for (int i = 0; i < 4; i++) {
				while (profiles[i].consumeClick()) {
					Jade.useProfile(i);
					if (IWailaConfig.get().accessibility().getNarrateKeys()) {
						tickHandler.narrate(I18n.get("narration.jade.key.profile", profiles[i].getName()), false);
					}
				}
			}
		}

		while (JadeKeys.showUses().consumeClick()) {
			lookupRecipes(true, getLookupItemStack());
		}

		while (JadeKeys.showRecipes().consumeClick()) {
			lookupRecipes(false, getLookupItemStack());
		}
	}

public static void narrateKey(String key, boolean bl) {
		if (IWailaConfig.get().accessibility().getNarrateKeys()) {
			key = "narration.jade.key.%s.%s".formatted(key, bl ? "on" : "off");
			tickHandler.narrate(I18n.get(key), false);
		}
	}

public static void onGui(Screen screen) {
		if (!translationChecked && screen instanceof TitleScreen && CommonProxy.isDevEnv()) {
			translationChecked = true;
			List<String> keys = Lists.newArrayList();
			for (Identifier id : WailaClientRegistration.instance().getConfigKeys()) {
				String key = "config.jade.plugin_%s.%s".formatted(id.getNamespace(), id.getPath());
				if (!JadeUI.hasTranslation(key)) {
					keys.add(key);
				}
			}
			if (!keys.isEmpty()) {
				throw new AssertionError("Missing config translation: %s".formatted(String.join(",", keys)));
			}
		}
	}

public static String formatString(String s, Object... objects) {
		try {
			for (int i = 0; i < objects.length; i++) {
				if (objects[i] instanceof Component component) {
					objects[i] = component.getString();
				}
			}
			return MessageFormat.format(I18n.get(s), objects);
		} catch (Exception e) {
			return I18n.get(s, objects);
		}
	}

@Override
	public void appendTooltip(ITooltip tooltip, BlockAccessor accessor, IPluginConfig config) {
		BlockState blockState = accessor.getBlockState();
		Block block = blockState.getBlock();
		if (block instanceof RedstoneWireBlock) {
			List<Component> list = Lists.newArrayListWithExpectedSize(4);
			for (Map.Entry<Direction, EnumProperty<RedstoneSide>> entry : RedstoneWireBlock.PROPERTY_BY_DIRECTION.entrySet()) {
				RedstoneSide side = blockState.getValue(entry.getValue());
				if (side != RedstoneSide.NONE) {
					list.add(BlockFaceProvider.directionName(entry.getKey()));
				}
			}
			if (list.isEmpty()) {
				tooltip.add(Component.translatable("jade.access.block.redstone_wire.dot"));
			} else {
				tooltip.add(Component.translatable(
						"jade.access.block.redstone_wire",
						ComponentUtils.formatList(list, ComponentUtils.DEFAULT_NO_STYLE_SEPARATOR)));
			}
			return;
		}
		//TODO client tags?
		if (block instanceof FlowerBedBlock || block instanceof CampfireBlock || block instanceof DecoratedPotBlock ||
				block instanceof SmallDripleafBlock || block instanceof BigDripleafBlock || block instanceof BigDripleafStemBlock) {
			return;
		}

		RailShape railShape = null;
		if (blockState.hasProperty(BlockStateProperties.RAIL_SHAPE)) {
			railShape = blockState.getValue(BlockStateProperties.RAIL_SHAPE);
		} else if (blockState.hasProperty(BlockStateProperties.RAIL_SHAPE_STRAIGHT)) {
			railShape = blockState.getValue(BlockStateProperties.RAIL_SHAPE_STRAIGHT);
		}
		if (railShape != null) {
			tooltip.add(Component.translatable("jade.access.block.rail.%s".formatted(railShape.getSerializedName())));
		}

		Direction facing = null;
		if (blockState.hasProperty(BlockStateProperties.FACING)) {
			facing = blockState.getValue(BlockStateProperties.FACING);
		} else if (blockState.hasProperty(BlockStateProperties.HORIZONTAL_FACING)) {
			facing = blockState.getValue(BlockStateProperties.HORIZONTAL_FACING);
		} else if (blockState.hasProperty(BlockStateProperties.FACING_HOPPER)) {
			facing = blockState.getValue(BlockStateProperties.FACING_HOPPER);
		}
		if (facing != null) {
			tooltip.add(Component.translatable("jade.access.block.facing", BlockFaceProvider.directionName(facing)));
		}
	}

@Override
	public void appendTooltip(ITooltip tooltip, EntityAccessor accessor, IPluginConfig config) {
		if (!config.get(JadeIds.ACCESS_ENTITY_DETAILS)) {
			return;
		}
		Entity entity = accessor.getEntity();
		int poseId = getPoseId(entity);
		if (poseId != Pose.STANDING.id()) {
			String key = "jade.access.entity.pose.%s".formatted(poseId);
			if (JadeUI.hasTranslation(key)) {
				tooltip.add(Component.translatable("jade.access.entity.pose", Component.translatable(key)));
			}
		}
		int passengers = entity.getPassengers().size();
		if (passengers > 0) {
			tooltip.add(JadeClient.format("jade.access.entity.passengers", passengers));
		}
		if (entity instanceof Leashable leashable) {
			if (leashable.isLeashed()) {
				Entity holder = leashable.getLeashHolder();
				if (holder instanceof LeashFenceKnotEntity knot) {
					TextElement text = DistanceProvider.xyz(knot.blockPosition());
					tooltip.add(JadeUI
							.text(Component.translatable("jade.access.entity.leashed_to", text.getString()))
							.narration(Component.translatable("jade.access.entity.leashed_to", text.getString())));
				} else if (holder != null) {
					tooltip.add(Component.translatable("jade.access.entity.leashed_to", holder.getName()));
				}
			}
			List<Leashable> leashables = Leashable.leashableLeashedTo(entity);
			if (!leashables.isEmpty()) {
				tooltip.add(Component.translatable(
						"jade.access.entity.is_leashing",
						ComponentUtils.formatList(
								leashables,
								Component.literal(ComponentUtils.DEFAULT_SEPARATOR_TEXT),
								$ -> ((Entity) $).getDisplayName())));
			}
		}
	}

@Override
	public void appendTooltip(ITooltip tooltip, EntityAccessor accessor, IPluginConfig config) {
		Entity entity = accessor.getEntity();
		Either<String, Component> variantName = EntityVariantHelper.getVariantName(entity, false);
		if (variantName == null) {
			return;
		}
		variantName.ifLeft(s -> {
			String type = BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toShortLanguageKey();
			String key = "jade.access.entity.%s.%s".formatted(type, s);
			if (JadeUI.hasTranslation(key) || (config.get(JadeIds.DEBUG_SPECIAL_REGISTRY_NAME) && !accessor.showDetails())) {
				s = I18n.get(key);
			} else {
				s = s.replace('.', ' ').replace('_', ' ');
			}
			tooltip.add(Component.translatable("jade.access.entity.variant", s));
		}).ifRight(component -> tooltip.add(Component.translatable("jade.access.entity.variant", component)));
		if (entity instanceof Horse horse) {
			Markings markings = horse.getMarkings();
			String s = MARKINGS.get(markings);
			if (s == null) {
				s = markings.name();
			}
			String key = "jade.access.entity.horse_markings.%s".formatted(s);
			if (JadeUI.hasTranslation(key) || (config.get(JadeIds.DEBUG_SPECIAL_REGISTRY_NAME) && !accessor.showDetails())) {
				s = I18n.get(key);
			} else {
				s = s.replace('_', ' ');
			}
			tooltip.add(Component.translatable("jade.access.entity.horse_markings", s));
		}
	}

