@Override
	public void appendTooltip(ITooltip tooltip, BlockAccessor accessor, IPluginConfig config) {
		Player player = accessor.getPlayer();
		if (!config.get(JadeIds.MC_HARVEST_TOOL_CREATIVE) && (player.isCreative() || player.isSpectator())) {
			return;
		}
		Level level = accessor.getLevel();
		BlockPos pos = accessor.getPosition();
		GameType gameType = ClientProxy.getGameMode();
		if (gameType == GameType.ADVENTURE && player.blockActionRestricted(level, pos, gameType)) {
			return;
		}
		BlockState state = accessor.getBlockState();
		try {
			if (state.getDestroyProgress(player, level, pos) <= 0) {
				if (!accessor.isServersideContent() && config.get(JadeIds.MC_SHOW_UNBREAKABLE)) {
					Component text = IThemeHelper.get().failure(Component.translatable("jade.harvest_tool.unbreakable"));
					tooltip.add(JadeUI.text(text).narration(""));
				}
				//TODO: high priority handlers?
				return;
			}
		} catch (Exception ignored) {
			return;
		}

		boolean newLine = config.get(JadeIds.MC_HARVEST_TOOL_NEW_LINE);
		List<Element> elements = getText(accessor, config);
		if (elements.isEmpty()) {
			return;
		}
		elements.forEach(e -> e.narration(""));
		if (newLine) {
			tooltip.add(elements);
		} else {
			tooltip.append(0, elements);
		}
	}

@Override
		public void appendTooltip(ITooltip tooltip, T accessor, IPluginConfig config) {
			if ((!accessor.showDetails() && config.get(JadeIds.UNIVERSAL_ENERGY_STORAGE_DETAILED))) {
				return;
			}

			List<ClientViewGroup<EnergyView>> groups = ClientProxy.mapToClientGroups(
					accessor,
					JadeIds.UNIVERSAL_ENERGY_STORAGE,
					STREAM_CODEC,
					WailaClientRegistration.instance().energyStorageProviders::get,
					tooltip);
			if (groups == null || groups.isEmpty()) {
				return;
			}

			boolean renderGroup = groups.size() > 1 || groups.getFirst().shouldRenderGroup();
			ClientViewGroup.tooltip(
					tooltip, groups, renderGroup, (theTooltip, group) -> {
						if (renderGroup) {
							group.renderHeader(theTooltip);
						}
						for (var view : group.views) {
							IWailaConfig.HandlerDisplayStyle style = config.getEnum(JadeIds.UNIVERSAL_ENERGY_STORAGE_STYLE);
							Component text;
							if (view.overrideText != null) {
								text = view.overrideText;
							} else {
								String current = view.current;
								if (style == IWailaConfig.HandlerDisplayStyle.PROGRESS_BAR) {
									current = ChatFormatting.WHITE + current;
								}
								text = Component.translatable("jade.fe", current, view.max);
							}

							switch (style) {
								case PLAIN_TEXT -> theTooltip.add(Component.translatable("jade.energy.text", text));
								case ICON -> {
									theTooltip.add(JadeUI.sprite(JadeIds.JADE("energy"), 10, 10)
											.size(10, 9)
											.offset(0, -1));
									theTooltip.append(text);
								}
								case PROGRESS_BAR -> {
									ProgressView progressView = new ProgressView(
											ProgressView.Part.of(Mth.clamp(view.ratio, 0, 1), PROGRESS_OVERLAY),
											text,
											JadeUI.progressStyle(),
											BoxStyle.nestedBox());
									theTooltip.add(JadeUI.progress(progressView));
								}
							}
						}
					});
		}

@Override
		public void appendTooltip(ITooltip tooltip, T accessor, IPluginConfig config) {
