@Override
		public void appendTooltip(ITooltip tooltip, BlockAccessor accessor, IPluginConfig config) {
			BlockState state = accessor.getBlockState();
			Block block = state.getBlock();
			IThemeHelper t = IThemeHelper.get();
			if (block instanceof LeverBlock) {
				Component info;
				if (state.getValue(BlockStateProperties.POWERED)) {
					info = t.success(Component.translatable("tooltip.jade.state_on"));
				} else {
					info = t.danger(Component.translatable("tooltip.jade.state_off"));
				}
				tooltip.add(Component.translatable("tooltip.jade.state", info));
				return;
			}

			if (block == Blocks.REPEATER) {
				int delay = state.getValue(BlockStateProperties.DELAY);
				tooltip.add(Component.translatable("tooltip.jade.delay", t.info(delay)));
				return;
			}

			Optional<Integer> signal = RedstoneProvider.INSTANCE.decodeFromData(accessor);
			if (block == Blocks.COMPARATOR) {
				ComparatorMode mode = state.getValue(BlockStateProperties.MODE_COMPARATOR);
				Component modeInfo = t.info(Component.translatable(
						"tooltip.jade.mode_" + (mode == ComparatorMode.COMPARE ? "comparator" : "subtractor")));
				tooltip.add(Component.translatable("tooltip.jade.mode", modeInfo));
				signal.ifPresent(i -> tooltip.add(Component.translatable("tooltip.jade.power", t.info(i))));
				return;
			}

			if (block instanceof CalibratedSculkSensorBlock && signal.isPresent()) {
				tooltip.add(Component.translatable("jade.input_signal", t.info(signal.get())));
			}

			if (state.hasProperty(BlockStateProperties.POWER)) {
				tooltip.add(Component.translatable("tooltip.jade.power", t.info(state.getValue(BlockStateProperties.POWER))));
			}
		}

@Override
		public void appendTooltip(ITooltip tooltip, EntityAccessor accessor, IPluginConfig config) {
			List<Effect> effects = StatusEffectsProvider.INSTANCE.decodeFromData(accessor).orElse(List.of());
			if (effects.isEmpty()) {
				return;
			}
			ITooltip box = JadeUI.tooltip();
			IThemeHelper t = IThemeHelper.get();
			long current = System.currentTimeMillis();
			effects = effects.stream().filter($ -> {
				if (WailaCommonRegistration.instance().mobEffectOperations().shouldHide($.effect())) {
					return false;
				}
				long ms = current - $.addTime() - 20;
				return ms > 0;
			}).sorted().limit(config.getInt(JadeIds.MC_POTION_EFFECTS_LIMIT)).toList();
			float scale = effects.size() > 2 ? 0.75F : 1F;
			boolean animation = IWailaConfig.get().overlay().getAnimation();
			for (var data : effects) {
				long ms = current - data.addTime() - 20;
				float alpha = 1F;
				if (animation && ms < 480) {
					alpha = ms / 480F;
				}
				MobEffectInstance effect = data.effect();
				Component name = getEffectName(effect);
				String duration;
				if (effect.isInfiniteDuration()) {
					duration = INFINITE.getString();
				} else {
					duration = StringUtil.formatTickDuration(effect.getDuration(), accessor.tickRate());
				}
				MutableComponent s = Component.translatable("jade.potion", name, duration);
				s = switch (effect.getEffect().value().getCategory()) {
					case BENEFICIAL -> t.success(s);
					case HARMFUL -> t.danger(s);
					case NEUTRAL -> t.info(s);
				};
				box.add(JadeUI.text(s).scale(scale).alpha(alpha));
			}
			tooltip.add(JadeUI.box(box, BoxStyle.nestedBox()).flexGrow(1));
		}

