@Override
	protected void extractContents(GuiGraphicsExtractor guiGraphics, int i, int j, float partialTicks) {
		boolean hovered = isHoveredOrFocused();
		if (!oldHovered && hovered) {
			progress.target(1);
		} else if (!hovered) {
			progress.target(0);
		} else if (progress.value > 0.5F) {
			progress.target(0);
			onHover.onPress(this);
		}
		progress.tick(partialTicks);
		progress.value = Math.min(0.6F, progress.value);
		float alpha = hovered ? 170 : 85;
		if (showTranslators && !translators.isEmpty()) {
			int cycleTime = 60;
			translatorTime += partialTicks;
			if (translatorTime > cycleTime) {
				nextTranslator();
			}
			if (!hovered && translators.size() > 1) {
				if (translatorTime < 5) {
					alpha *= translatorTime / 5;
				} else if (cycleTime - translatorTime < 5) {
					alpha *= (cycleTime - translatorTime) / 5;
				}
				alpha = Math.max(alpha, 17);
			}
		}
		guiGraphics.pose().pushMatrix();
		guiGraphics.pose().translate(getX() + width * 0.5F, getY());
		float scale = 1 + progress.value * 0.2F;
		guiGraphics.pose().scale(scale);
		Component credit = hovered ? hoveredTitle : getMessage();
		Font font = Minecraft.getInstance().font;
		guiGraphics.pose().translate(font.width(credit) * -0.5F, 0);
		guiGraphics.text(font, credit, 0, 0, 0xFFFFFF | (int) alpha << 24);
		guiGraphics.pose().popMatrix();
		oldHovered = hovered;
		if (isHovered()) {
			guiGraphics.requestCursor(CursorTypes.POINTING_HAND);
		}
	}

public void showTranslators() {
		if (showTranslators) {
			return;
		}
		showTranslators = true;
		if (!JadeUI.hasTranslation("gui.jade.translators") || "placeholder ".equals(I18n.get("gui.jade.translated_by", ""))) {
			return;
		}
		String s = I18n.get("gui.jade.translators");
		if ("Bob, Alice, Charlie".equals(s)) {
			return;
		}
		translators = Stream.of(StringUtils.split(s, ',')).map(String::trim).filter(StringUtils::isNotEmpty).toList();
		if (translators.size() > 1) {
			translatorIndex = RandomSource.create().nextInt(translators.size());
		}
		nextTranslator();
	}

private void nextTranslator() {
		setMessage(Component.translatable("gui.jade.translated_by", translators.get(translatorIndex)));
		if (translators.size() <= 1) {
			return;
		}
		translatorIndex++;
		if (translatorIndex >= translators.size()) {
			translatorIndex = 0;
		}
		translatorTime = 0;
	}

public HomeConfigScreen(@Nullable Screen parent) {
		super(Component.translatable("gui.jade.configuration"));
		this.parent = parent;
		titleY = new SmoothChasingValue().start(8).target(32).withSpeed(0.1F);

		if (!WailaClientRegistration.instance().maybeLowVisionUser()) {
			LocalDate now = LocalDate.now();
			int month = now.getMonthValue();
			int day = now.getDayOfMonth();
			if (month == 12 && day >= 24 && day <= 26) {
				festival = 1;
			} else if (month == 6 && (day == 1 || day == 28)) {
				festival = 2;
			} else if (month <= 2 && isLunarNewYear(now)) {
				festival = 99;
			}
		}
	}

