public List<Category> getConfigListView(boolean enableAccessibilityPlugins) {
		Multimap<String, ConfigEntry<?>> categoryMap = ArrayListMultimap.create();
		configCategoryOverrides.forEach((key, component) -> {
			categoryMap.put(component.getString(), Objects.requireNonNull(getConfigEntry(key)));
		});
		configEntries.forEach((key, entry) -> {
			if (configCategoryOverrides.containsKey(key)) {
				return;
			}
			if (!enableAccessibilityPlugins && JadeIds.isAccess(key)) {
				return;
			}
			if (!IPluginConfig.isPrimaryKey(key)) {
				Identifier primaryKey = IPluginConfig.getPrimaryKey(key);
				Collection<Component> components = configCategoryOverrides.get(primaryKey);
				if (!components.isEmpty()) {
					for (Component component : components) {
						categoryMap.put(component.getString(), entry);
					}
					return;
				}
			}
			String namespace = key.getNamespace();
			Optional<String> modName = ModIdentification.getModFullName(namespace);
			if (!Jade.ID.equals(namespace) && modName.isPresent()) {
				categoryMap.put(modName.get(), entry);
			} else {
				categoryMap.put(I18n.get(OptionsList.Entry.makeKey(Jade.ID, "plugin_" + namespace)), entry);
			}
		});

		return categoryMap.asMap().entrySet().stream()
				.map(e -> new Category(
						Component.literal(e.getKey()), e.getValue().stream()
						.sorted(Comparator.comparingInt($ -> WailaCommonRegistration.instance().priorities.getSortedList()
								.indexOf($.id())))
						.toList()
				))
				.sorted(Comparator.comparingInt(specialOrder()).thenComparing($ -> $.title().getString()))
				.toList();
	}

private static ToIntFunction<Category> specialOrder() {
		String core = I18n.get(OptionsList.Entry.makeKey(Jade.ID, "plugin_" + Jade.ID));
		String debug = I18n.get(OptionsList.Entry.makeKey(Jade.ID, "plugin_" + Jade.ID + ".debug"));
		// core is always the first, debug is always the last
		return category -> {
			String title = category.title().getString();
			if (core.equals(title)) {
				return -1;
			}
			if (debug.equals(title)) {
				return 1;
			}
			return 0;
		};
	}

@Override
	public void extractRenderState(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		int x = textLeft();
		int normalColor = IWailaConfig.Overlay.applyAlpha(IThemeHelper.get().getNormalColor(), alpha);
		boolean scaled = scale != 1;
		Matrix3x2fStack matrixStack = graphics.pose();
		if (scaled) {
			matrixStack.pushMatrix();
			matrixStack.translate(x, getY() + scale);
			matrixStack.scale(scale);
			DisplayHelper.INSTANCE.drawText(graphics, text, 0, 0, normalColor);
		} else {
			DisplayHelper.INSTANCE.drawText(graphics, text, x, getY(), normalColor);
		}
		if (mouseX != -1 && getRectangle().containsPoint(mouseX, mouseY)) {
//			int highlightColor = IThemeHelper.get().theme().text.colors().info();
			ActiveTextCollector collector = graphics.textRenderer(GuiGraphicsExtractor.HoveredTextEffects.TOOLTIP_AND_CURSOR);
			textCollector(collector);
		}
		if (scaled) {
			matrixStack.popMatrix();
		}
	}

public static void handle(ClientHandshakePacket message, ServerPayloadContext context) {
		context.execute(() -> {
			ServerPlayer player = context.player();
			if (!Jade.PROTOCOL_VERSION.equals(message.protocolVersion)) {
				String version = CommonProxy.getModVersion(Jade.ID).orElse("UNKNOWN");
				player.sendSystemMessage(Component.translatable("jade.protocolMismatch", version), false);
				return;
			}
			((JadeServerPlayer) player).jade$setConnected(true);
			Map<Identifier, Object> configs = ServerPluginConfig.instance().values();
			List<Block> shearableBlocks = LootTableMineableCollector.getShearableBlocks();
			if (!configs.isEmpty()) {
				Jade.LOGGER.debug("Syncing config to {} ({})", player.getPlainTextName(), player.getGameProfile().id());
			}
			List<Identifier> blockProviderIds = WailaCommonRegistration.instance().blockDataProviders.mappedIds();
			List<Identifier> entityProviderIds = WailaCommonRegistration.instance().entityDataProviders.mappedIds();
			CommonProxy.sendPacket(player, new ServerHandshakePacket(configs, shearableBlocks, blockProviderIds, entityProviderIds));
		});
	}

