private static void renderBar(CapacitorBankBlockEntity blockEntity, PoseStack poseStack, MultiBufferSource bufferSource, Direction facing) {
        if (getDisplayModeRelative(blockEntity, facing, new Vector2i(0,-1)) == DisplayMode.BAR) {
            return;
        }
        int length = 1;
        //some random limit
        while(length < 16) {
            if (getDisplayModeRelative(blockEntity, facing, new Vector2i(0, length)) == DisplayMode.BAR) {
                length++;
            } else {
                break;
            }
        }
        for (int i = 0; i < length; i++) {
            poseStack.pushPose();
            poseStack.translate(0, -i, 0);
            VertexConsumer buffer = bufferSource.getBuffer(RenderType.cutout());
            PoseStack.Pose last = poseStack.last();
            renderTopHalf(last, buffer, facing, i == 0);
            renderBottomHalf(last, buffer, facing, i == length - 1);
            poseStack.popPose();
        }
        CapacitorBankManager.CapacitorSyncData data = CapacitorBankManager.getData(blockEntity.getUuid());
        if (data != null && data.capacity() > 0) {
            float f = data.storedEnergy() / (float) data.capacity();
            int filledPixels = Math.round(f * (10 + (length-1)*16));
            for (int i = length - 1; i >= 0; i--) {
                if (filledPixels <= 0) {
                    break;
                }

                poseStack.pushPose();
                poseStack.translate(0, -i, 0);
                VertexConsumer buffer = bufferSource.getBuffer(RenderType.cutout());
                PoseStack.Pose last = poseStack.last();
                boolean isBottomEnd = i == length - 1;
                renderEnergy(last, buffer, facing, filledPixels, isBottomEnd);
                filledPixels -= isBottomEnd ? 13 : 16;
                poseStack.popPose();
            }
        }
    }

private static void renderIO(CapacitorBankBlockEntity capacitorBank, PoseStack poseStack, MultiBufferSource bufferSource, Direction facing) {
        int light = LightTexture.FULL_BRIGHT;
        if (capacitorBank.getLevel() != null) {
            light = LevelRenderer.getLightColor(capacitorBank.getLevel(), capacitorBank.getBlockPos().relative(facing));
        }

        CapacitorBankManager.CapacitorSyncData data = CapacitorBankManager.getData(capacitorBank.getUuid());
        if (data == null) {
            return;
        }

        Size size = findSize(capacitorBank, facing);
        renderTexture(poseStack.last(), bufferSource.getBuffer(RenderType.cutout()), facing, size.getTexture(), light);
        if ((-size.x0 == size.x1 || -size.x0 +1 == size.x1)
            && (-size.y0 == size.y1 || -size.y0 +1 == size.y1)) {
            int height = size.y1 - size.y0 + 1;
            int width = size.x1 - size.x0 + 1;
            boolean isLongInformation = height > 1.4f * width;
            poseStack.pushPose();
            poseStack.translate(0.5, 0.5, 0.5);
            poseStack.mulPose(Axis.YN.rotationDegrees(facing.get2DDataValue()*90));
            poseStack.translate(width%2 == 0 ? 0.5f : 0, height%2 == 0 ? -0.5f : 0,0.502f);
            poseStack.scale(1/16f,-1/16f,1/16f);
            Font font = Minecraft.getInstance().font;
            float fontWidthScale = width / (float)font.width("OutputOutput");
            float fontHeightScale = height / (float)(font.lineHeight * 5);
            float scale = Math.min(fontWidthScale, fontHeightScale) * 16;
            poseStack.scale(scale,scale,scale);
            if (!isLongInformation) {
                poseStack.pushPose();
                poseStack.translate(-font.width("I/0") / 2f, -font.lineHeight * 1.5f, 0);
                font.drawInBatch("I/0", 0, 0, 0xFF000000, false, poseStack.last().pose(), bufferSource, Font.DisplayMode.NORMAL, 0, light, false);
                poseStack.popPose();
                poseStack.pushPose();
                long energySurplus = data.added() - data.send();
                int color = 0;
                if (energySurplus > 0) {
                    color = 0xFF00FF00;
                }

                if (energySurplus < 0) {
                    color = 0xFFFF0000;
                }

                poseStack.translate(-font.width(String.valueOf(energySurplus)) / 2f, font.lineHeight * 0.5f, 0);
                font.drawInBatch(String.valueOf(energySurplus), 0, 0, color, false, poseStack.last().pose(), bufferSource, Font.DisplayMode.NORMAL, 0, light, false);
                poseStack.popPose();
            } else {
                poseStack.pushPose();
                poseStack.translate(-font.width("Input") / 2f, -font.lineHeight * 3.5f, 0);
                font.drawInBatch("Input", 0, 0, 0xFF000000, false, poseStack.last().pose(), bufferSource, Font.DisplayMode.NORMAL, 0, light, false);
                poseStack.popPose();
                poseStack.pushPose();
                poseStack.translate(-font.width(String.valueOf(data.added())) / 2f, -font.lineHeight * 1.5f, 0);
                font.drawInBatch(String.valueOf(data.added()), 0, 0, 0xFF00FF00, false, poseStack.last().pose(), bufferSource, Font.DisplayMode.NORMAL, 0, light, false);
                poseStack.popPose();
                poseStack.pushPose();
                poseStack.translate(-font.width("Output") / 2f, font.lineHeight * 0.5f, 0);
                font.drawInBatch("Output", 0, 0, 0xFF000000, false, poseStack.last().pose(), bufferSource, Font.DisplayMode.NORMAL, 0, light, false);
                poseStack.popPose();
                poseStack.pushPose();
                poseStack.translate(-font.width(String.valueOf(data.send())) / 2f, font.lineHeight * 2.5f, 0);
                font.drawInBatch(String.valueOf(data.send()), 0, 0, 0xFFFF0000, false, poseStack.last().pose(), bufferSource, Font.DisplayMode.NORMAL, 0, light, false);
                poseStack.popPose();

            }
            poseStack.popPose();
        }
    }

@Override
    public void render(BlockEntity blockEntity, float partialTick, PoseStack poseStack, MultiBufferSource buffer,
            int packedLight, int packedOverlay) {
        poseStack.pushPose();
        poseStack.translate(0.5, 0.75, 0.5);
        poseStack.scale(0.5f, 0.5f, 0.5f);
        Minecraft minecraft = Minecraft.getInstance();
        Vec3 position = minecraft.player.position();
        float f1 = (float) (Mth.atan2(position.z - blockEntity.getBlockPos().getZ() - 0.5D,
                position.x - blockEntity.getBlockPos().getX() - 0.5D) * 180.0f / Math.PI + 90);
        poseStack.mulPose(Axis.YP.rotationDegrees(-f1 + 180));
        ItemStack stack = new ItemStack(supplier.get());
        BakedModel bakedmodel = minecraft.getItemRenderer().getModel(stack, blockEntity.getLevel(), null, 0);
        if (stack.getItem() instanceof BlockItem) { //Blocks are in iso, let's correct that
            poseStack.mulPose(Axis.YP.rotationDegrees(45));
            poseStack.mulPose(Axis.XP.rotationDegrees(-30));
            poseStack.scale(1.2f, 1.2f, 1.2f);
        }
        minecraft.getItemRenderer()
                .render(stack, ItemDisplayContext.GUI, true, poseStack, buffer, packedLight, packedOverlay, bakedmodel);
        poseStack.popPose();
    }

@Override
    public void render(FallingBlockEntity entity, float entityYaw, float partialTicks, PoseStack matrixStack, MultiBufferSource buffer, int packedLight) {
        Block paintBlock = entity instanceof PaintedSandEntity paintedSandEntity ? paintedSandEntity.getPaint() : null;

        // See FallingBlockRenderer#render for reference.
        BlockState renderBlockState = paintBlock != null ? paintBlock.defaultBlockState() : entity.getBlockState();
        if (renderBlockState.getRenderShape() == RenderShape.MODEL) {
            Level level = entity.level();

            if (renderBlockState != level.getBlockState(entity.blockPosition()) && renderBlockState.getRenderShape() != RenderShape.INVISIBLE) {
                matrixStack.pushPose();
                BlockPos blockpos = new BlockPos((int) entity.getX(), (int) entity.getBoundingBox().maxY, (int) entity.getZ());
                matrixStack.translate(-0.5D, 0.0D, -0.5D);
                BlockRenderDispatcher blockrenderdispatcher = Minecraft.getInstance().getBlockRenderer();
                BakedModel model = blockrenderdispatcher.getBlockModel(renderBlockState);

                for (RenderType type : model.getRenderTypes(renderBlockState, RandomSource.create(renderBlockState.getSeed(entity.blockPosition())), ModelData.EMPTY)) {
                    blockrenderdispatcher
                        .getModelRenderer()
                        .tesselateBlock(level, blockrenderdispatcher.getBlockModel(renderBlockState), renderBlockState, blockpos, matrixStack, buffer.getBuffer(type),
                            false, RandomSource.create(), renderBlockState.getSeed(entity.getStartPos()), OverlayTexture.NO_OVERLAY, ModelData.EMPTY, type);
                }

                matrixStack.popPose();
                super.render(entity, entityYaw, partialTicks, matrixStack, buffer, packedLight);
            }
        }
    }

