@Override
    public @Nullable IRecipeTransferError transferRecipe(FluidTankMenu container, RecipeHolder<TankRecipe> recipe, IRecipeSlotsView recipeSlots, Player player,
        boolean maxTransfer, boolean doTransfer) {

        boolean hasFluid = true;
        if (recipe.value().mode() == TankRecipe.Mode.FILL) {
            // Check if the tank contains a fluid that matches the ingredient
            hasFluid = recipe.value().fluid().test(container.getFluidTank().contents());
        }

        boolean hasItem = recipe.value().input().test(container.slots.get(0).getItem());
        Ingredient item = getIngredientItem(player, recipe.value().input());

        if (!hasItem || !hasFluid) {
            Component message = Component.translatable("jei.tooltip.error.recipe.transfer.missing");
            List<IRecipeSlotView> empty = new ArrayList<>();
            if (!hasItem && item.isEmpty()) {
                empty.add(recipeSlots.getSlotViews().get(0));
            }
            if (!hasFluid) {
                empty.add(recipeSlots.getSlotViews().get(2));
            }
            if (!empty.isEmpty()) {
                return handlerHelper.createUserErrorForMissingSlots(message, empty);
            }
        }

        if (doTransfer) {
            List<Ingredient> toSend = NonNullList.withSize(4, Ingredient.EMPTY);
            if (recipe.value().mode() == TankRecipe.Mode.EMPTY) {
                toSend.set(0, item);
            } else {
                toSend.set(2, item);
            }
            PacketDistributor.sendToServer(new ServerboundTransferItemsPacket(toSend, 0,3 + 1, maxTransfer));
        }
        return null;
    }

@Override
    public @Nullable IRecipeTransferError transferRecipe(VatMenu container, RecipeHolder<FermentingRecipe> recipe, IRecipeSlotsView recipeSlots, Player player,
        boolean maxTransfer, boolean doTransfer) {

        boolean hasFluid = recipe.value().input().ingredient().test(new FluidStack(container.getInputTank().contents().getFluid(), container.getInputTank().contents().getAmount()));
        boolean hasLeft = container.slots.get(VatMenu.INPUTS_INDEX).getItem().is(recipe.value().firstReagent());
        boolean hasRight = container.slots.get(VatMenu.INPUTS_INDEX + 1).getItem().is(recipe.value().secondReagent());
        Ingredient left = getIngredientItem(player, Ingredient.of(recipe.value().firstReagent()));
        Ingredient right = getIngredientItem(player, Ingredient.of(recipe.value().secondReagent()));

        if (!hasLeft || !hasRight || !hasFluid) {
            Component message = Component.translatable("jei.tooltip.error.recipe.transfer.missing");
            List<IRecipeSlotView> empty = new ArrayList<>();
            if (!hasLeft && left.isEmpty()) {
                empty.add(recipeSlots.getSlotViews().get(VatMenu.INPUTS_INDEX));
            }
            if (!hasRight && right.isEmpty()) {
                empty.add(recipeSlots.getSlotViews().get(VatMenu.INPUTS_INDEX + 1));
            }
            if (!hasFluid) {
                empty.add(recipeSlots.getSlotViews().get(VatMenu.INPUTS_INDEX + 2));
            }
            if (!empty.isEmpty()) {
                return handlerHelper.createUserErrorForMissingSlots(message, empty);
            }
        }

        if (doTransfer) {
            PacketDistributor.sendToServer(new ServerboundTransferItemsPacket(List.of(left, right), VatMenu.INPUTS_INDEX,VatMenu.LAST_INDEX + 1, maxTransfer));
        }
        return null;
    }

