@Override
    public void tickClient(ICommonArmorHandler armorHandler, boolean isEnabled) {
        if (!isEnabled) return;

        ticksExisted++;

        if ((ticksExisted & 0xf) == 0) {
            // block tracker: count up all items in tracked inventories, and cull any inventories with no matching items
            int rangeUpgrades = armorHandler.getUpgradeCount(EquipmentSlot.HEAD, ModUpgrades.RANGE.get());
            int blockSearchCount = trackInventoryCounts(rangeUpgrades);

            // entity tracker: handle tracking for item entities
            if (armorHandler.upgradeUsable(CommonUpgradeHandlers.entityTrackerHandler, true)) {
                trackItemEntities(rangeUpgrades);
            }
            searchedItems.entrySet().removeIf(e -> !e.getKey().isAlive());
            totalSearchedItemCount = itemSearchCount + blockSearchCount;
        }

        Item item = PneumaticArmorItem.getSearchedItem(ClientUtils.getWornArmor(EquipmentSlot.HEAD));
        List<Component> textList = new ArrayList<>();
        if (item == null || item == Items.AIR) {
            textList.add(xlate("pneumaticcraft.armor.search.configure", KeyHandler.getInstance().keybindOpenOptions.getTranslatedKeyMessage()));
        } else {
            if (searchedStack.getItem() != item) searchedStack = new ItemStack(item);
            textList.add(searchedStack.getHoverName().copy().append(xlate("pneumaticcraft.armor.search.found", totalSearchedItemCount)));
        }
        searchInfo.setText(textList);
    }

@Override
    public void renderByItem(ItemStack stack, ItemDisplayContext displayContext, PoseStack matrixStack, MultiBufferSource buffer, int combinedLightIn, int combinedOverlayIn) {
        if (stack.getItem() instanceof MinigunItem itemMinigun && stack.has(ModDataComponents.OWNER_ENTITY_ID)) {
            Minecraft mc = Minecraft.getInstance();
            int id = stack.getOrDefault(ModDataComponents.OWNER_ENTITY_ID, 0);
            if (ClientUtils.getClientLevel().getEntity(id) instanceof Player player) {
                Minigun minigun = itemMinigun.getMinigun(stack, player);
                matrixStack.pushPose();
                boolean thirdPerson = displayContext == ItemDisplayContext.THIRD_PERSON_RIGHT_HAND || displayContext == ItemDisplayContext.THIRD_PERSON_LEFT_HAND;
                if (thirdPerson) {
                    if (mc.screen instanceof InventoryScreen) {
                        // our own gun in the rendered player model in inventory screen
                        matrixStack.mulPose(Axis.XP.rotationDegrees(-180f));
                        matrixStack.translate(0.5, -1, -0.5);
                    } else {
                        // rendering our own gun in 3rd person, or rendering someone else's gun
                        matrixStack.scale(1f, -1f, -1f);
                        matrixStack.mulPose(Axis.XP.rotationDegrees(75f));
                        matrixStack.mulPose(Axis.YP.rotationDegrees(180));
                        matrixStack.mulPose(Axis.ZP.rotationDegrees(0f));
                        matrixStack.translate(-0.5, -2, -0.3);
                    }
                } else {
                    // Hides minigun in first person if in offhand because it's not usable in offhand anyway
                    if(player.getOffhandItem() == stack) {
                        matrixStack.scale(0f, 0f, 0f);
                    }

                    // Shows minigun in main hand appropriate to which side is set as the main hand
                    else {
                        // our own gun in 1st person
                        matrixStack.scale(1.5f, 1.5f, 1.5f);
                        matrixStack.mulPose(Axis.XP.rotationDegrees(0));
                        matrixStack.mulPose(Axis.YP.rotationDegrees(0));
                        matrixStack.mulPose(Axis.ZP.rotationDegrees(180));
                        if (mc.options.mainHand().get() == HumanoidArm.RIGHT) {
                            matrixStack.translate(-1, -1.7, 0.1);
                        } else {
                            matrixStack.translate(0.4, -1.7, 0.1);
                        }
                    }
                }
                model.renderMinigun(matrixStack, buffer, combinedLightIn, combinedOverlayIn, minigun, mc.getTimer().getGameTimeDeltaPartialTick(true), false);
                matrixStack.popPose();
            }
        }
    }

@SubscribeEvent
    public void renderLevelStageEvent(RenderLevelStageEvent event) {
        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES) return;

        Player player = ClientUtils.getClientPlayer();

        MultiBufferSource.BufferSource buffer = Minecraft.getInstance().renderBuffers().bufferSource();
        PoseStack matrixStack = event.getPoseStack();

        matrixStack.pushPose();

        Vec3 projectedView = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        matrixStack.translate(-projectedView.x, -projectedView.y, -projectedView.z);

        // block entity controlled renderers
        for (AreaRenderer handler : showHandlers.values()) {
            handler.render(matrixStack, buffer);
        }

        // some special rendering for certain items
        maybeRenderPositionProvider(matrixStack, buffer, player);
        maybeRenderCamo(matrixStack, buffer, player);
        maybeRenderDroneDebug(matrixStack, buffer, player);
        maybeRenderAreaTool(matrixStack, buffer, player);
        maybeRenderJackhammer(matrixStack, buffer, player);
        maybeRenderCoordinateTracker(matrixStack, buffer, player, event.getPartialTick());

        matrixStack.popPose();
    }

private void maybeRenderCoordinateTracker(PoseStack matrixStack, MultiBufferSource.BufferSource buffer, Player player, DeltaTracker partialTicks) {
        CoordTrackerHandler handler = CommonUpgradeHandlers.coordTrackerHandler;
        if (CommonArmorHandler.getHandlerForPlayer().upgradeUsable(handler, true)) {
            BlockPos pos = ClientArmorRegistry.getInstance().getClientHandler(handler, CoordTrackClientHandler.class).getTrackedPos();
            if (pos != null) {
                float progress = (player.level().getGameTime() % 20 + partialTicks.getGameTimeDeltaPartialTick(false)) / 20;
                float g = progress < 0.5F ? progress + 0.5F : 1.5F - progress;
                int col = 0xA00000FF | (int)(g * 255) << 8;
                Vec3 targetVec = Vec3.atCenterOf(pos);
                float size = ClientUtils.calculateViewScaling(targetVec);
                float textSize = size * 0.02f;
                matrixStack.pushPose();
                matrixStack.translate(targetVec.x(), targetVec.y(), targetVec.z());
                matrixStack.scale(textSize, textSize, textSize);
                RenderUtils.rotateToPlayerFacing(matrixStack);
                RenderUtils.renderString3d(Component.literal(PneumaticCraftUtils.posToString(pos)), 0, 0, 0xFFFFFFFF, matrixStack, buffer, true, true);
                matrixStack.popPose();
                AreaRenderer.builder().withColor(col).xray().withSize(size / 2f).build(pos).render(matrixStack, buffer);
            }
        }
    }

private void render(PoseStack matrixStack, VertexConsumer builder) {
        int[] cols = RenderUtils.decomposeColor(color);
        for (BlockPos pos : showingPositions) {
            matrixStack.pushPose();
            if (drawShapes) {
                matrixStack.translate(pos.getX(), pos.getY(), pos.getZ());
            } else {
                double start = (1 - size) / 2.0;
                matrixStack.translate(pos.getX() + start, pos.getY() + start, pos.getZ() + start);
            }
            Matrix4f posMat = matrixStack.last().pose();
            addVertices(builder, posMat, pos, cols);
            matrixStack.popPose();
        }
    }

