        RenderSystem.setShaderTexture(0, texture);
        RenderSystem.setShader(GameRenderer::getPositionTexShader);

        graphics.pose().pushPose();
        graphics.pose().translate(x, y, z);

        Matrix4f posMat = graphics.pose().last().pose();

        int centreWidth = texWidth - corner * 2;
        int centreHeight = texHeight - corner * 2;

        drawWithTesselator(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX, wr -> {
            // corners
            addQuad(wr, posMat, 0, 0, 0, 0, corner, corner);
            addQuad(wr, posMat, width - corner, 0, texWidth - corner, 0, corner, corner);
            addQuad(wr, posMat, 0, height - corner, 0, texHeight - corner, corner, corner);
            addQuad(wr, posMat, width - corner, height - corner, texWidth - corner, texHeight - corner, corner, corner);

            // top & bottom edges
            for (int i = 0; i <= width / centreWidth; i++) {
                int x1 = corner + centreWidth * i;
                int w1 = Math.min(centreWidth, width - (i * centreWidth) - (corner * 2));
                addQuad(wr, posMat, x1, 0, corner, 0, w1, corner);
                addQuad(wr, posMat, x1, height - corner, corner, texHeight - corner, w1, corner);
            }
            // left & right edges
            for (int i = 0; i <= height / centreHeight; i++) {
                int y1 = corner + centreHeight * i;
                int h1 = Math.min(centreHeight, height - (i * centreHeight) - (corner * 2));
                addQuad(wr, posMat, 0, y1, 0, corner, corner, h1);
                addQuad(wr, posMat, width - corner, y1, texWidth - corner, corner, corner, h1);
            }

            // centre
            int cw = (width - (corner * 2)) / texWidth;
            int ch = (height - (corner * 2)) / texHeight;
            for (int ix = 0; ix <= cw; ix++) {
                for (int iy = 0; iy <= ch; iy++) {
                    int x1 = corner + (ix * centreWidth);
                    int y1 = corner + (iy * centreHeight);
                    int w1 = Math.min(centreWidth, width - (ix * centreWidth) - (corner * 2));
                    int h1 = Math.min(centreHeight, height - (iy * centreHeight) - (corner * 2));
                    addQuad(wr, posMat, x1, y1, corner, corner, w1, h1);
                }
            }
        });

        graphics.pose().popPose();
    }

public static float rotateMatrixForDirection(PoseStack matrixStack, Direction facing) {
        float yRotation;
        switch (facing) {
            case UP -> {
                yRotation = 0;
                matrixStack.mulPose(Axis.XP.rotationDegrees(90f));
                matrixStack.translate(0, -1, -1);
            }
            case DOWN -> {
                yRotation = 0;
                matrixStack.mulPose(Axis.XP.rotationDegrees(-90f));
                matrixStack.translate(0, -1, 1);
            }
            case NORTH -> yRotation = 0;
            case EAST -> yRotation = 90;
            case SOUTH -> yRotation = 180;
            default -> yRotation = 270;
        }
        matrixStack.mulPose(Axis.YP.rotationDegrees(yRotation));
        return yRotation;
    }

public static void renderRing(ProgressingLine line, ProgressingLine lastLine, PoseStack poseStack, MultiBufferSource bufferIn, float partialTick, float rotationYaw, float rotationPitch, int color) {
        poseStack.pushPose();

        double renderProgress = lerp(partialTick, lastLine.progress, line.progress);
        poseStack.translate(
                (line.endX - line.startX) * renderProgress,
                (line.endY - line.startY) * renderProgress,
                (line.endZ - line.startZ) * renderProgress
        );
        poseStack.mulPose(Axis.YP.rotationDegrees(rotationYaw - 90));
        poseStack.mulPose(Axis.ZP.rotationDegrees(rotationPitch));

        VertexConsumer builder = bufferIn.getBuffer(ModRenderTypes.getLineLoops(1.0));

        int[] cols = RenderUtils.decomposeColor(0xFF000000 | color);
        double size = (1 + 4 * renderProgress) / 16;
        Matrix4f posMat = poseStack.last().pose();
        for (float i = 0; i < FULL_CIRCLE; i += STEP) {
            Vec3 v1 = new Vec3(0, Mth.sin(i) * size, Mth.cos(i) * size);
            Vec3 v2 = new Vec3(0, Mth.sin(i + STEP) * size, Mth.cos(i + STEP) * size);
            RenderUtils.posF(builder, posMat, 0f, v1.y(), v1.z())
                    .setColor(cols[1], cols[2], cols[3], cols[0])
                    .setNormal(poseStack.last(), 0f, (float) (v2.y() - v1.y()), (float) (v2.z() - v1.z()));
        }
        poseStack.popPose();
    }

public static int HSBtoRGB(float hue, float saturation, float brightness) {
        int r = 0, g = 0, b = 0;
        if (saturation == 0) {
            r = g = b = (int) (brightness * 255.0f + 0.5f);
        } else {
            float h = (hue - (float)Math.floor(hue)) * 6.0f;
            float f = h - (float)java.lang.Math.floor(h);
            float p = brightness * (1.0f - saturation);
            float q = brightness * (1.0f - saturation * f);
            float t = brightness * (1.0f - (saturation * (1.0f - f)));
            switch ((int) h) {
                case 0 -> {
                    r = (int) (brightness * 255.0f + 0.5f);
                    g = (int) (t * 255.0f + 0.5f);
                    b = (int) (p * 255.0f + 0.5f);
                }
                case 1 -> {
                    r = (int) (q * 255.0f + 0.5f);
                    g = (int) (brightness * 255.0f + 0.5f);
                    b = (int) (p * 255.0f + 0.5f);
                }
                case 2 -> {
                    r = (int) (p * 255.0f + 0.5f);
                    g = (int) (brightness * 255.0f + 0.5f);
                    b = (int) (t * 255.0f + 0.5f);
                }
                case 3 -> {
                    r = (int) (p * 255.0f + 0.5f);
                    g = (int) (q * 255.0f + 0.5f);
                    b = (int) (brightness * 255.0f + 0.5f);
                }
                case 4 -> {
                    r = (int) (t * 255.0f + 0.5f);
                    g = (int) (p * 255.0f + 0.5f);
                    b = (int) (brightness * 255.0f + 0.5f);
                }
                case 5 -> {
                    r = (int) (brightness * 255.0f + 0.5f);
                    g = (int) (p * 255.0f + 0.5f);
                    b = (int) (q * 255.0f + 0.5f);
                }
            }
        }
        return 0xff000000 | (r << 16) | (g << 8) | b;
    }

