				Class.forName("optifine.Installer");
				Minecraft.getInstance().player.sendSystemMessage(Component.translatable("botaniamisc.optifine_warning"));
			} catch (ClassNotFoundException ignored) {}
			didOptifineDetection = true;
		}
	}

