public void renderMultiblock(Level world, PoseStack ms, Matrix4fc pose) {
		ms.pushPose();
		ms.mulPose(pose);
		Minecraft mc = Minecraft.getInstance();
		if (!isAnchored) {
			facingRotation = getRotation(mc.player);
			if (mc.hitResult instanceof BlockHitResult) {
				pos = ((BlockHitResult) mc.hitResult).getBlockPos();
			}
		} else if (pos.distToCenterSqr(mc.player.position()) > 64 * 64) {
			return;
		}

		if (pos == null) {
			return;
		}
		if (multiblock.isSymmetrical()) {
			facingRotation = Rotation.NONE;
		}

		ms.pushPose();
		Vec3 cameraPosition = mc.getEntityRenderDispatcher().camera.position();
		ms.translate(cameraPosition.multiply(-1, -1, -1));

		BlockPos checkPos = null;
		if (mc.hitResult instanceof BlockHitResult blockRes) {
			checkPos = blockRes.getBlockPos().relative(blockRes.getDirection());
		}

		blocks = blocksDone = airFilled = 0;
		lookingState = null;
		lookingPos = checkPos;

		SubmitNodeStorage submitNodeStorage = mc.gameRenderer.getFeatureRenderDispatcher().getSubmitNodeStorage();

		Pair<BlockPos, Collection<IMultiblock.SimulateResult>> sim = multiblock.simulate(world, getStartPos(), getFacingRotation(), true);
		for (IMultiblock.SimulateResult r : sim.getSecond()) {
			float alpha = 0.3F;
			if (Objects.equals(r.getWorldPosition(), checkPos)) {
				lookingState = r.getStateMatcher().getDisplayedState(ClientTicker.ticksInGame);
				alpha = 0.6F + (float) (Math.sin(ClientTicker.total * 0.3F) + 1F) * 0.1F;
			}

			if (r.getStateMatcher() != StateMatcher.ANY) {
				boolean air = r.getStateMatcher() == StateMatcher.AIR;
				if (!air) {
					blocks++;
				}

				if (!r.test(world, facingRotation)) {
					BlockState renderState = r.getStateMatcher().getDisplayedState(ClientTicker.ticksInGame).rotate(facingRotation);
					float scale = 1;
					if (renderState.getBlock() == Blocks.AIR) {
						renderState = Blocks.RED_CONCRETE.defaultBlockState();
						scale = 0.3F;
					}
					submitNodeStorage.submitCustomGeometry(
							ms,
							RenderTypes.translucentMovingBlock(),
							new GhostBlockGeometry(r.getWorldPosition(), renderState, alpha, scale));

					if (air) {
						airFilled++;
					}
				} else if (!air) {
					blocksDone++;
				}
			}
		}

		if (!isAnchored) {
			blocks = blocksDone = 0;
		}

		ms.popPose();
		ms.popPose();
	}

public static void onTooltip(GuiGraphicsExtractor graphics, ItemStack stack, int mouseX, int mouseY) {
		Minecraft mc = Minecraft.getInstance();
		int tooltipX = mouseX;
		int tooltipY = mouseY - 4;

		if (mc.player != null && !(mc.screen instanceof GuiBook)) {
			int lexSlot = -1;
			ItemStack lexiconStack = ItemStack.EMPTY;
			Pair<BookEntry, Integer> lexiconEntry = null;

			for (int i = 0; i < Inventory.getSelectionSize(); i++) {
				ItemStack stackAt = mc.player.getInventory().getItem(i);
				if (!stackAt.isEmpty()) {
					Book book = ItemStackUtil.getBookFromStack(stackAt);
					if (book != null) {
						Pair<BookEntry, Integer> entry = book.getContents().getEntryForStack(stack);

						if (entry != null && !entry.getFirst().isLocked()) {
							lexiconStack = stackAt;
							lexSlot = i;
							lexiconEntry = entry;
							break;
						}
					}
				}
			}

			if (lexSlot > -1) {
				int x = tooltipX - 34;

				graphics.fill(x - 4, tooltipY - 4, x + 20, tooltipY + 26, 0x44000000);
				graphics.fill(x - 6, tooltipY - 6, x + 22, tooltipY + 28, 0x44000000);

				if (PatchouliConfig.get().useShiftForQuickLookup() ? mc.hasShiftDown() : mc.hasControlDown()) {
					lexiconLookupTime += ClientTicker.delta;

					int cx = x + 8;
					int cy = tooltipY + 8;
					float r = 12;
					float requiredTime = PatchouliConfig.get().quickLookupTime();
					float angles = lexiconLookupTime / requiredTime * 360F;

					IClientXplatAbstractions.INSTANCE.submitGuiElement(graphics, new TooltipRenderState(graphics.pose(), cx, cy, angles, r));

					if (lexiconLookupTime >= requiredTime) {
						mc.player.getInventory().setSelectedSlot(lexSlot);
						int spread = lexiconEntry.getSecond();
						ClientBookRegistry.INSTANCE.displayBookGui(lexiconEntry.getFirst().getBook().id, lexiconEntry.getFirst().getId(), spread * 2);
					}
				} else {
					lexiconLookupTime = 0F;
				}

				graphics.pose().pushMatrix();
				//graphics.pose().translate(0, 0, 300);
				graphics.item(lexiconStack, x, tooltipY);
				graphics.itemDecorations(mc.font, lexiconStack, x, tooltipY);
				graphics.pose().popMatrix();

				graphics.pose().pushMatrix();
				//graphics.pose().translate(0, 0, 500);
				graphics.text(mc.font, "?", x + 10, tooltipY + 8, 0xFFFFFFFF, true);

				graphics.pose().scale(0.5F, 0.5F);
				boolean mac = Util.getPlatform() == Util.OS.OSX;
				Component key = Component.literal(PatchouliConfig.get().useShiftForQuickLookup() ? "Shift" : mac ? "Cmd" : "Ctrl")
						.withStyle(ChatFormatting.BOLD);
				graphics.text(mc.font, key, (x + 10) * 2 - 16, (tooltipY + 8) * 2 + 20, 0xFFFFFFFF, true);
				graphics.pose().popMatrix();
			} else {
				lexiconLookupTime = 0F;
			}
		} else {
			lexiconLookupTime = 0F;
		}
	}

