public static void extractRenderState(GuiGraphicsExtractor graphics, DeltaTracker deltaTracker) {
		MultiblockVisualizationHandler handler = MultiblockVisualizationHandler.INSTANCE;
		if (!handler.hasMultiblock()) {
			return;
		}

		int waitTime = 40;
		int fadeOutSpeed = 4;
		int fullAnimTime = waitTime + 10;
		float animTime = handler.getTimeComplete() + (handler.getTimeComplete() == 0 ? 0 : deltaTracker.getGameTimeDeltaPartialTick(false));

		if (animTime > fullAnimTime) {
			handler.setHasMultiblock(false);
			return;
		}

		graphics.pose().pushMatrix();
		graphics.pose().translate(0, -Math.max(0, animTime - waitTime) * fadeOutSpeed);

		Minecraft mc = Minecraft.getInstance();
		int x = mc.getWindow().getGuiScaledWidth() / 2;
		int y = 12;

		graphics.centeredText(mc.font, handler.name(), x, y, 0xFFFFFF);

		int width = 180;
		int height = 9;
		int left = x - width / 2;
		int top = y + 10;

		if (handler.getTimeComplete() > 0) {
			graphics.pose().pushMatrix();
			graphics.pose().translate(0, Math.min(height + 5, animTime));
			graphics.centeredText(mc.font, Component.translatable("patchouli.gui.lexicon.structure_complete"), x, top + height - 10, 0x00FF00);
			graphics.pose().popMatrix();
		}

		graphics.fill(left - 1, top - 1, left + width + 1, top + height + 1, 0xFF000000);
		graphics.fillGradient(left, top, left + width, top + height, 0xFF666666, 0xFF555555);

		float fract = handler.getProgress();
		int progressWidth = (int) ((float) width * fract);
		int color = Mth.hsvToRgb(fract / 3.0F, 1.0F, 1.0F) | 0xFF000000;
		int color2 = new Color(color).darker().getRGB();
		graphics.fillGradient(left, top, left + progressWidth, top + height, color, color2);

		if (!handler.isAnchored()) {
			graphics.centeredText(mc.font, Component.translatable("patchouli.gui.lexicon.not_anchored"), x, top + height + 8, 0xFFFFFF);
		} else {
			BlockState lookingState = handler.getLookingState();
			if (lookingState != null) {
				// try-catch around here because the state isn't necessarily present in the world in this instance,
				// which isn't really expected behavior for getPickBlock
				try {
					ItemStack stack = lookingState.getCloneItemStack(mc.level, handler.getLookingPos(), false);

					if (!stack.isEmpty()) {
						graphics.text(mc.font, stack.getHoverName(), left + 20, top + height + 8, 0xFFFFFF, true);
						graphics.item(stack, left, top + height + 2);
					}
				} catch (Exception ignored) {}
			}

			if (handler.getTimeComplete() == 0) {
				color = 0xFFFFFF;
				int posx = left + width;
				int posy = top + height + 2;
				int mult = 1;
				String progress = handler.getProgressString();

				if (handler.isComplete()) {
					progress = I18n.get("patchouli.gui.lexicon.needs_air");
					color = 0xDA4E3F;
					mult *= 2;
					posx -= width / 2;
					posy += 2;
				}

				graphics.text(mc.font, progress, posx - mc.font.width(progress) / mult, posy, color, false);
			}
		}

		graphics.pose().popMatrix();
	}

@Override
	public void render(PoseStack.Pose pose, VertexConsumer builder) {
		final var mc = Minecraft.getInstance();
		final BlockColors colors = mc.getBlockColors();

		var model = mc.getModelManager().getBlockStateModelSet().get(state);

		float offset = (1 - scale) / 2f;

		final var realPosition = Vec3.atLowerCornerWithOffset(position, offset, offset, offset).toVector3f();
		pose.translate(realPosition.x, realPosition.y, realPosition.z);
		pose.scale(scale, scale, scale);

		List<BlockStateModelPart> parts = new ArrayList<>();
		model.collectParts(RandomSource.create(), parts);

		parts.forEach(part -> {
			for (var dir : Direction.values()) {
				for (var quad : part.getQuads(dir)) {
					addQuad(state, pose, colors, builder, quad, alpha);
				}
			}

			for (var quad : part.getQuads(null)) {
				addQuad(state, pose, colors, builder, quad, alpha);
			}
		});
	}

@Override
	protected void renderToTexture(MultiblockPiPRenderState renderState, PoseStack poseStack) {
		poseStack.pushPose();
		poseStack.mulPose(renderState.viewMatrix());
		Minecraft minecraft = Minecraft.getInstance();
		GameRenderer gameRenderer = minecraft.gameRenderer;
		FeatureRenderDispatcher featureRenderDispatcher = gameRenderer.getFeatureRenderDispatcher();
		SubmitNodeStorage submitNodeStorage = featureRenderDispatcher.getSubmitNodeStorage();
		gameRenderer.getLighting().setupFor(Lighting.Entry.ITEMS_3D);
		for (var block : renderState.multiblock()) {
			poseStack.pushPose();
			poseStack.translate(block.pos().getCenter());
			block.blockModelRenderState().submit(poseStack, submitNodeStorage, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, 0);
			poseStack.popPose();
		}
		featureRenderDispatcher.renderAllFeatures();
		this.bufferSource.endBatch();
		poseStack.popPose();
	}

public MutableComponent getSubtitle() {
		Component editionStr;

		try {
			int ver = Integer.parseInt(version);
			if (ver == 0) {
				return Component.translatable(subtitle);
			}

			editionStr = Component.literal(numberToOrdinal(ver));
		} catch (NumberFormatException e) {
			editionStr = Component.translatable("patchouli.gui.lexicon.dev_edition");
		}

		return Component.translatable("patchouli.gui.lexicon.edition_str", editionStr);
	}

