public static void appendRuneTooltip(ItemStack stack, List<Component> components) {
        ArmorTrim trim = stack.get(DataComponents.TRIM);
		RuneColor color = ColorRunesModule.getAppliedStackColor(stack);

        if (trim != null && !((AccessorArmorTrim) trim).showInTooltip()) {
			//There IS a trim on this item and showInTooltip is false
            return;
        }
		else {
			//there is NOT a trim on this item, or there is a trim but showInTooltip is true
            //Also this item is not an overleveled enchanted book
			if (color != null && stack.getItem() != Items.ENCHANTED_BOOK) {
				if (!components.contains(AccessorArmorTrim.getUPGRADE_TITLE())) {
					components.add(AccessorArmorTrim.getUPGRADE_TITLE());
				}
				//only add Upgrade: if it's not already there

				MutableComponent baseComponent = Component.translatable("rune.quark." + color.getName());
				if (color == RuneColor.RAINBOW) {
					components.add(CommonComponents.space().append(ColorRunesModule.extremeRainbow(baseComponent)));
				} else {
					components.add(CommonComponents.space().append(baseComponent.withStyle((style) -> style.withColor(color.getTextColor()))));
				}
			}
		}
    }

public static Ingredient createBaseIngredient() {
		if (used == null) {
			Stream<ItemStack> displayItems;
			if (Quark.ZETA.modules.isEnabled(ImprovedTooltipsModule.class) && ImprovedTooltipsModule.enchantingTooltips) {
				displayItems = EnchantedBookTooltips.getTestItems().stream();
			} else {
				displayItems = Stream.of(Items.DIAMOND_SWORD, Items.DIAMOND_PICKAXE, Items.DIAMOND_AXE,
					Items.DIAMOND_SHOVEL, Items.DIAMOND_HOE, Items.DIAMOND_HELMET, Items.DIAMOND_CHESTPLATE,
					Items.DIAMOND_LEGGINGS, Items.DIAMOND_BOOTS, Items.ELYTRA, Items.SHIELD, Items.BOW, Items.CROSSBOW,
					Items.TRIDENT, Items.FISHING_ROD, Items.SHEARS, PickarangModule.pickarang).map(ItemStack::new);
			}

			used = Ingredient.of(displayItems
				.filter(it -> !(it.getItem() instanceof IDisableable<?> dis) || dis.isEnabled())
				.map(SmithingRuneRecipe::makeEnchantedDisplayItem));
		}

		return used;
	}

public void rotateAndOffset(PoseStack stack, Player player) {
		if(states.length == 0)
			return;

		float rotX = states[ModelAccessor.MODEL_X];
		float rotY = states[ModelAccessor.MODEL_Y];
		float rotZ = states[ModelAccessor.MODEL_Z];

		float height = player.getBbHeight();

		stack.translate(0, height / 2, 0);

		if(rotY != 0)
			stack.mulPose(Axis.YP.rotation(rotY));
		if(rotX != 0)
			stack.mulPose(Axis.XP.rotation(rotX));
		if(rotZ != 0)
			stack.mulPose(Axis.ZP.rotation(rotZ));

		stack.translate(0, -height / 2, 0);
	}

