@Override
	public void render(@NotNull PoseStack pose, @NotNull MultiBufferSource buffer, int light, @NotNull ArmorStand armor, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
		if(!UsesForCursesModule.staticEnabled || !UsesForCursesModule.bindArmorStandsWithPlayerHeads) return;

		ItemStack head = armor.getItemBySlot(EquipmentSlot.HEAD);
		if(head.is(Items.PLAYER_HEAD) && EnchantmentHelper.has(head, EnchantmentEffectComponents.PREVENT_ARMOR_CHANGE)) {

            RenderType rendertype;
            boolean slim = true;
            if (head.has(DataComponents.PROFILE)) {
                GameProfile profile = head.get(DataComponents.PROFILE).gameProfile();
                rendertype = SkullBlockRenderer.getRenderType(SkullBlock.Types.PLAYER, new ResolvableProfile(profile));
                PlayerSkin playerSkin = Minecraft.getInstance().getSkinManager().getInsecureSkin(profile);
                slim = playerSkin.model().equals(PlayerSkin.Model.SLIM);
            } else {
                rendertype =  RenderType.entityTranslucent(DefaultPlayerSkin.getDefaultTexture());
            }
            pose.pushPose();

            if (armor.isBaby()) {
                float s = 1F;
                pose.translate(0F, 0F, 0F);
                pose.scale(s, s, s);
            } else {
                float s = 2F;
                pose.translate(0F, -1.5F, 0F);
                pose.scale(s, s, s);
            }

            PlayerModel<?> model = slim ? playerModelSlim : playerModel;


            model.head.visible = false;
            model.hat.visible = false;

            rotateModel(model.leftArm, armor.getLeftArmPose());
            rotateModel(model.rightArm, armor.getRightArmPose());
            rotateModel(model.leftSleeve, armor.getLeftArmPose());
            rotateModel(model.rightSleeve, armor.getRightArmPose());

            rotateModel(model.leftLeg, armor.getLeftLegPose());
            rotateModel(model.rightLeg, armor.getRightLegPose());
            rotateModel(model.leftPants, armor.getLeftLegPose());
            rotateModel(model.rightPants, armor.getRightLegPose());

            model.renderToBuffer(pose, buffer.getBuffer(rendertype), light, OverlayTexture.NO_OVERLAY, -1);

            pose.popPose();

        }
	}

@Override
	public void render(@NotNull DyedItemFrame frame, float p_115077_, float p_115078_, @NotNull PoseStack poseStack, @NotNull MultiBufferSource multiBufferSource, int p_115081_) {
		super.render(frame, p_115077_, p_115078_, poseStack, multiBufferSource, p_115081_);
		poseStack.pushPose();
		Direction direction = frame.getDirection();
		Vec3 vec3 = this.getRenderOffset(frame, p_115078_);
		poseStack.translate(-vec3.x(), -vec3.y(), -vec3.z());
		poseStack.translate((double) direction.getStepX() * 0.46875D, (double) direction.getStepY() * 0.46875D, (double) direction.getStepZ() * 0.46875D);
		poseStack.mulPose(Axis.XP.rotationDegrees(frame.getXRot()));
		poseStack.mulPose(Axis.YP.rotationDegrees(180.0F - frame.getYRot()));
		boolean flag = frame.isInvisible();
		ItemStack itemstack = frame.getItem();
		if(!flag) {
			ModelManager modelmanager = this.blockRenderer.getBlockModelShaper().getModelManager();
			boolean map = frame.getItem().getItem() instanceof MapItem;
			ModelResourceLocation modelresourcelocation = map ? MAP_FRAME_LOCATION : FRAME_LOCATION;

			poseStack.pushPose();
			poseStack.translate(-0.5D, -0.5D, -0.5D);

			int color = frame.getColor();
			float r = ((float) ((color >> 16) & 0xFF)) / 255F;
			float g = ((float) ((color >> 8) & 0xFF)) / 255F;
			float b = ((float) ((color) & 0xFF)) / 255F;

			blockRenderer.getModelRenderer().renderModel(poseStack.last(), multiBufferSource.getBuffer(Sheets.solidBlockSheet()), (BlockState) null, modelmanager.getModel(modelresourcelocation), r, g, b, p_115081_, OverlayTexture.NO_OVERLAY);
			poseStack.popPose();
		}

		if(!itemstack.isEmpty()) {
			MapItemSavedData data = MapItem.getSavedData(itemstack, frame.level());
			if(flag) {
				poseStack.translate(0.0D, 0.0D, 0.5D);
			} else {
				poseStack.translate(0.0D, 0.0D, 0.4375D);
			}

			int j = data != null ? frame.getRotation() % 4 * 2 : frame.getRotation();
			poseStack.mulPose(Axis.ZP.rotationDegrees((float) j * 360.0F / 8.0F));
			if(data != null) {
				poseStack.mulPose(Axis.ZP.rotationDegrees(180.0F));
				poseStack.scale(0.0078125F, 0.0078125F, 0.0078125F);
				poseStack.translate(-64.0D, -64.0D, 0.0D);
				poseStack.translate(0.0D, 0.0D, -1.0D);
                int i = this.getLightVal(frame, 15728850, p_115081_);
                Minecraft.getInstance().gameRenderer.getMapRenderer().render(poseStack, multiBufferSource, frame.getFramedMapId(itemstack), data, true, i);
            } else {
				int k = this.getLightVal(frame, 15728880, p_115081_);
				poseStack.scale(0.5F, 0.5F, 0.5F);
				this.itemRenderer.renderStatic(itemstack, ItemDisplayContext.FIXED, k, OverlayTexture.NO_OVERLAY, poseStack, multiBufferSource, Minecraft.getInstance().level, frame.getId());
			}
		}

		poseStack.popPose();
	}

