                                    renderType);
                        poseStack.popPose();
                        AnimBlockRenderer.buffer.endBatch();
//                        buffer = this.bufferSource.getBuffer(RenderType.entityCutoutNoCull(TEXTURE));
                    }
                } catch (Exception e) {
                    // We typically don't render non-models like this, so catch our shenanigans.
                }
            }
        }
    }

