@SuppressWarnings({"rawtypes", "unchecked"})
	@Override
	public void render(DrawContext raw, int mouseX, int mouseY, float delta) {
		EmiDrawContext context = EmiDrawContext.wrap(raw);
		this.renderInGameBackground(context.raw());
		context.resetColor();
		EmiRenderHelper.drawNinePatch(context, TEXTURE, x, y, backgroundWidth, backgroundHeight, 0, 0, 4, 1);

		int tp = tabPage * tabPageSize;
		int off = 0;
		for (int i = tp; i < tabs.size() && i < tp + tabPageSize; i++) {
			RecipeTab tab = tabs.get(i);
			int sOff = (i == this.tab ? 2 : 0);
			EmiRenderHelper.drawNinePatch(context, TEXTURE, x + tabOff + off * 24 + 16, y - 24 - sOff, 24, 27 + sOff,
				i == this.tab ? 9 : 18, 0, 4, 1);
			tab.category.render(context.raw(), x + tabOff + off++ * 24 + 20, y - 20 - (i == this.tab ? 2 : 0), delta);
		}

		EmiRenderHelper.drawNinePatch(context, TEXTURE, x + 19 + buttonOff, y + 5, minimumWidth - 38, 12, 0, 16, 3, 6);
		//EmiRenderHelper.drawScroll(context, x + 19 + buttonOff, y + 5 + 10, minimumWidth - 38, 2, tab, tabs.size(), -1);
		EmiRenderHelper.drawNinePatch(context, TEXTURE, x + 19 + buttonOff, y + 19, minimumWidth - 38, 12, 0, 16, 3, 6);
		//EmiRenderHelper.drawScroll(context, x + 19 + buttonOff, y + 19 + 10, minimumWidth - 38, 2, page, tabs.get(tab).getPageCount(), -1);

		boolean categoryHovered = mouseX >= x + 19 + buttonOff && mouseY >= y + 5 && mouseX < x + minimumWidth + buttonOff - 19 && mouseY < y + 5 + 12;
		int categoryNameColor = categoryHovered ? 0x22ffff : 0xffffff;

		RecipeTab tab = tabs.get(this.tab);
		Text text = tab.category.getName();
		if (client.textRenderer.getWidth(text) > minimumWidth - 40) {
			int extraWidth = client.textRenderer.getWidth("...");
			text = EmiPort.literal(client.textRenderer.trimToWidth(text, (minimumWidth - 40) - extraWidth).getString() + "...");
		}
		context.drawCenteredTextWithShadow(text, x + backgroundWidth / 2, y + 7, categoryNameColor);
		context.drawCenteredTextWithShadow(EmiRenderHelper.getPageText(this.page + 1, tab.getPageCount(), minimumWidth - 40),
			x + backgroundWidth / 2, y + 21, 0xffffff);

		List<EmiIngredient> workstations = EmiApi.getRecipeManager().getWorkstations(tab.category);
		int workstationAmount = Math.min(workstations.size(), getMaxWorkstations());
		if (workstationAmount > 0 || resolve != null) {
			Bounds bounds = getWorkstationBounds(-1);
			int offset = getResolveOffset();
			if (workstationAmount <= 0) {
				offset = 18;
			}
			if (EmiConfig.workstationLocation == SidebarSide.LEFT) {
				EmiRenderHelper.drawNinePatch(context, TEXTURE, bounds.x() - 5, bounds.y() - 5, 28, 10 + 18 * workstationAmount + offset, 36, 0, 5, 1);
			} else if (EmiConfig.workstationLocation == SidebarSide.RIGHT) {
				EmiRenderHelper.drawNinePatch(context, TEXTURE, bounds.x() - 5, bounds.y() - 5, 28, 10 + 18 * workstationAmount + offset, 47, 0, 5, 1);
			} else if (EmiConfig.workstationLocation == SidebarSide.BOTTOM) {
				EmiRenderHelper.drawNinePatch(context, TEXTURE, bounds.x() - 5, bounds.y() - 5, 10 + 18 * workstationAmount + offset, 28, 58, 0, 5, 1);
			}
		}
		for (WidgetGroup group : currentPage) {
			int mx = mouseX - group.x();
			int my = mouseY - group.y();
			context.push();
			context.translate(group.x(), group.y());
			EmiPort.applyModelViewMatrix();
			try {
				for (Widget widget : group.widgets) {
					widget.render(context.raw(), mx, my, delta);
				}
			} catch (Throwable e) {
				EmiLog.error("Error rendering widget", e);
				group.error(e);
			}
			for (Widget widget : group.widgets) {
				if (widget instanceof RecipeFillButtonWidget) {
					if (widget.getBounds().contains(mx, my)) {
						HandledScreen hs = EmiApi.getHandledScreen();
						EmiRecipeHandler handler = EmiRecipeFiller.getFirstValidHandler(group.recipe, hs);
						if (handler != null) {
							handler.render(group.recipe, new EmiCraftContext(hs, handler.getInventory(hs), EmiCraftContext.Type.FILL_BUTTON), group.widgets, context.raw());
						} else if (EmiScreenManager.lastPlayerInventory != null) {
							StandardRecipeHandler.renderMissing(group.recipe, EmiScreenManager.lastPlayerInventory, group.widgets, context.raw());
						}
						break;
					}
				}
			}
			context.pop();
			EmiPort.applyModelViewMatrix();
		}
		EmiScreenManager.drawBackground(context, mouseX, mouseY, delta);
		EmiScreenManager.render(context, mouseX, mouseY, delta);
		EmiScreenManager.drawForeground(context, mouseX, mouseY, delta);
		super.render(context.raw(), mouseX, mouseY, delta);
		if (categoryHovered) {
			context.raw().drawTooltip(client.textRenderer, List.of(
				tab.category.getName(),
				EmiPort.translatable("emi.view_all_recipes")
			), mouseX, mouseY);
		}
		hoveredWidget = null;
		outer:
		for (WidgetGroup group : currentPage) {
			try {
				int mx = mouseX - group.x();
				int my = mouseY - group.y();
				for (Widget widget : group.widgets) {
					if (widget.getBounds().contains(mx, my)) {
						List<TooltipComponent> tooltip = widget.getTooltip(mx, my);
						if (!tooltip.isEmpty()) {
							EmiRenderHelper.drawTooltip(this, context, tooltip, mouseX, mouseY);
							hoveredWidget = widget;
							break outer;
						}
					}
				}
			} catch (Throwable e) {
				EmiLog.error("Error rendering widget group", e);
				group.error(e);
			}
		}

		RecipeTab rTab = getTabAt(mouseX, mouseY);
		if (rTab != null) {
			EmiRenderHelper.drawTooltip(this, context, rTab.category.getTooltip(), mouseX, mouseY);
		}
	}

public void draw() {
		if (!isEnabled()) {
			return;
		}
		if (sodiumSpriteHandle != null) {
			try {
				for (Sprite sprite : spritesToUpdate) {
					sodiumSpriteHandle.invoke(sprite);
				}
			} catch (Throwable t) {
			}
		}
		if (!populated) {
			bake();
			populated = true;
		}
		RenderSystem.enableDepthTest();
		DiffuseLighting.enableGuiDepthLighting();
		Matrix4f mat = new Matrix4f(RenderSystem.getModelViewMatrix());
		mat.mul(new Matrix4f().translation(x, y, 0));
		for (Map.Entry<RenderLayer, VertexBuffer> en : buffers.entrySet()) {
			en.getKey().startDrawing();
			EmiPort.setShader(en.getValue(), mat);
			en.getKey().endDrawing();
		}
		BufferRenderer.reset();
	}

public void error(Throwable e) {
		widgets.clear();
		widgets.add(new RecipeBackground(-4, -4, width + 8, height + 8));
		widgets.add(new TextWidget(EmiPort.ordered(EmiPort.translatable("emi.error.recipe.render")),
			width / 2, height / 2 - 5, Formatting.RED.getColorValue(), true).horizontalAlign(Alignment.CENTER));
		widgets.add(new DrawableWidget(0, 0, width, height, (raw, mouseX, mouseY, delta) -> {})
			.tooltip((i, j) -> EmiUtil.getStackTrace(e).stream()
				.map(EmiPort::literal).map(EmiPort::ordered).map(TooltipComponent::of).toList()));
	}

public void decorateDevMode() {
		EmiRecipeCategory category = recipe.getCategory();
		Identifier cid = category == null ? null : category.getId();
		Identifier id = recipe.getId();
		List<RecipeError> errors = Lists.newArrayList();
		if (id == null) {
			errors.add(new RecipeError(RecipeError.Severity.WARNING, EmiTooltip.splitTranslate("emi.dev.null_recipe_id")));
		} else if (EmiDev.duplicateRecipeIds.contains(id)) {
			List<TooltipComponent> tooltip = Lists.newArrayList();
			if (Objects.equals(id.getNamespace(), "minecraft") || Objects.equals(id.getNamespace(), "emi")) {
				tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.duplicate_vanilla_recipe_id", id));
			} else {
				tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.duplicate_recipe_id", id));
			}
			if (cid != null) {
				String suggestedPath = cid.getPath() + "/" + id.getNamespace() + "/" + id.getPath();
				if (EmiApi.getRecipeManager().getRecipe(EmiPort.id(cid.getNamespace(), suggestedPath)) == null) {
					tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.suggest_id", cid.getNamespace(), suggestedPath));
				} else {
					tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.synthetic_id"));
				}
			} else {
				tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.synthetic_id"));
			}
			errors.add(new RecipeError(RecipeError.Severity.ERROR, tooltip));
		} else if (EmiDev.incorrectRecipeIds.contains(id)) {
			List<TooltipComponent> tooltip = Lists.newArrayList();
			tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.synthetic_nag_explanation", id));
			tooltip.addAll(EmiTooltip.splitTranslate("emi.dev.synthetic_id"));
			errors.add(new RecipeError(RecipeError.Severity.ERROR, tooltip));
		}

		if (recipe.getInputs() == null || recipe.getOutputs() == null || recipe.getCatalysts() == null) {
			errors.add(new RecipeError(RecipeError.Severity.ERROR, EmiTooltip.splitTranslate("emi.dev.null_input_or_output")));
		} else {
			int nullStacks = 0;
			for (EmiIngredient stack : recipe.getInputs()) {
				if (stack == null) {
					nullStacks++;
				}
			}
			for (EmiIngredient stack : recipe.getCatalysts()) {
				if (stack == null) {
					nullStacks++;
				}
			}
			for (EmiStack stack : recipe.getOutputs()) {
				if (stack == null) {
					nullStacks++;
				}
			}
			if (nullStacks > 0) {
				errors.add(new RecipeError(RecipeError.Severity.ERROR, EmiTooltip.splitTranslate("emi.dev.null_input_or_output")));
			}

			if (!recipe.getOutputs().isEmpty() && recipe.supportsRecipeTree()) {
				int recipeContexts = 0;
				for (Widget widget : widgets) {
					if (widget instanceof SlotWidget sw) {
						if (sw.getRecipe() != null) {
							recipeContexts++;
						}
					}
				}
				if (recipeContexts == 0) {
					errors.add(new RecipeError(RecipeError.Severity.WARNING, EmiTooltip.splitTranslate("emi.dev.no_output_slots")));
				}
			}
		}

		if (!errors.isEmpty()) {
			List<TooltipComponent> tooltip = Lists.newArrayList();
			RecipeError.Severity severity = RecipeError.Severity.WARNING;
			for (RecipeError error : errors) {
				if (error.severity() == RecipeError.Severity.ERROR) {
					severity = RecipeError.Severity.ERROR;
				}
				tooltip.add(switch (error.severity()) {
					case ERROR -> EmiTooltipComponents.of(EmiPort.translatable("emi.dev.severity.error", Formatting.RED));
					case WARNING -> EmiTooltipComponents.of(EmiPort.translatable("emi.dev.severity.warning", Formatting.YELLOW));
				});
				tooltip.addAll(error.tooltip());
			}
			int errorColor = switch (severity) {
				case ERROR -> 0xCCCC0000;
				case WARNING -> 0xCCCCCC00;
			};
			addDrawable(0, 0, width, height, (raw, mouseX, mouseY, delta) -> {
				EmiDrawContext draw = EmiDrawContext.wrap(raw);
				draw.fill(-2, -3, width, 2, errorColor);
				draw.fill(-2, height + 1, width + 4, 2, errorColor);
			});
			addText(EmiPort.literal("!", Formatting.BOLD), width, -2, 0xFF000000 | errorColor, true);
			addTooltip(tooltip, width - 2, -4, 8, 16);
		}
	}

