public static void bake() {
		SuffixArray<SearchStack> names = new SuffixArray<>();
		SuffixArray<SearchStack> tooltips = new SuffixArray<>();
		SuffixArray<SearchStack> mods = new SuffixArray<>();
		SuffixArray<EmiStack> aliases = new SuffixArray<>();
		Set<EmiStack> bakedStacks = Sets.newIdentityHashSet();
		boolean old = EmiConfig.appendItemModId;
		EmiConfig.appendItemModId = false;
		for (EmiStack stack : EmiStackList.stacks) {
			try {
				SearchStack searchStack = new SearchStack(stack);
				bakedStacks.add(stack);
				Text name = NameQuery.getText(stack);
				if (name != null) {
					names.add(searchStack, name.getString().toLowerCase());
				}
				List<Text> tooltip = stack.getTooltipText();
				if (tooltip != null) {
					for (int i = 1; i < tooltip.size(); i++) {
						Text text = tooltip.get(i);
						if (text != null) {
							tooltips.add(searchStack, text.getString().toLowerCase());
						}
					}
				}
				Identifier id = stack.getId();
				if (id != null) {
					mods.add(searchStack, EmiUtil.getModName(id.getNamespace()).toLowerCase());
					mods.add(searchStack, id.getNamespace().toLowerCase());
					names.add(searchStack, id.getPath().toLowerCase());
				}
				if (stack.getItemStack().getItem() == Items.ENCHANTED_BOOK) {
					for (RegistryEntry<Enchantment> e : stack.getOrDefault(DataComponentTypes.ENCHANTMENTS, ItemEnchantmentsComponent.DEFAULT).getEnchantments()) {
						Identifier eid = EmiPort.getEnchantmentRegistry().getId(e.value());
						if (eid != null && !eid.getNamespace().equals("minecraft")) {
							mods.add(searchStack, EmiUtil.getModName(eid.getNamespace()).toLowerCase());
						}
					}
				}
			} catch (Exception e) {
				EmiLog.error("EMI caught an exception while baking search for " + stack, e);
			}
		}
		for (Supplier<EmiAlias> supplier : EmiData.aliases) {
			EmiAlias alias = supplier.get();
			for (String key : alias.keys()) {
				if (!I18n.hasTranslation(key)) {
					EmiReloadLog.warn("Untranslated alias " + key);
				}
				String text = I18n.translate(key).toLowerCase();
				for (EmiIngredient ing : alias.stacks()) {
					for (EmiStack stack : ing.getEmiStacks()) {
						aliases.add(stack.copy().comparison(EmiPort.compareStrict()), text);
					}
				}
			}
		}
		for (EmiAlias.Baked alias : EmiStackList.registryAliases) {
			for (Text text : alias.text()) {
				for (EmiIngredient ing : alias.stacks()) {
					for (EmiStack stack : ing.getEmiStacks()) {
						aliases.add(stack.copy().comparison(EmiPort.compareStrict()), text.getString().toLowerCase());
					}
				}
			}
		}
		EmiConfig.appendItemModId = old;
		names.build();
		tooltips.build();
		mods.build();
		aliases.build();
		EmiSearch.names = names;
		EmiSearch.tooltips = tooltips;
		EmiSearch.mods = mods;
		EmiSearch.aliases = aliases;
		EmiSearch.bakedStacks = bakedStacks;
	}

public RegexTagQuery(String name) {
		Pattern p = null;
		try {
			p = Pattern.compile(name, Pattern.CASE_INSENSITIVE);
		} catch (Exception e) {
		}
		if (p == null) {
			valid = Set.of();
		} else {
			final Pattern pat = p;
			valid = Stream.<EmiTagKey<?>>concat(
				EmiTags.TAGS.stream(),
				EmiTagKey.fromRegistry(EmiPort.getBlockRegistry())
			).filter(t -> {
				if (t.hasTranslation()) {
					if (pat.matcher(t.getTagName().getString().toLowerCase()).find()) {
						return true;
					}
				}
				if (pat.matcher(t.id().toString()).find()) {
					return true;
				}
				return false;
			}).flatMap(v -> v.stream()).collect(Collectors.toSet());
		}
	}

public TagQuery(String name) {
		String lowerName = name.toLowerCase();
		valid = Stream.<EmiTagKey<?>>concat(
			EmiTags.TAGS.stream(),
			EmiTagKey.fromRegistry(EmiPort.getBlockRegistry())
		).filter(t -> {
			if (t.hasTranslation()) {
				if (t.getTagName().getString().toLowerCase().contains(lowerName)) {
					return true;
				}
			}
			if (t.id().toString().contains(lowerName)) {
				return true;
			}
			return false;
		}).flatMap(v -> v.stream()).collect(Collectors.toSet());
	}

public TooltipQuery(String name) {
		EmiSearch.tooltips.findAll(name.toLowerCase()).forEach(s -> valid.add(s.stack));
		this.name = name.toLowerCase();
	}

@Override
	public List<TooltipComponent> getTooltip(int mouseX, int mouseY) {
		List<TooltipComponent> list = Lists.newArrayList();
		switch(BoM.getRecipeStatus(recipe)) {
			case PARTIAL:
				List<EmiStack> stacks = Lists.newArrayList();
				for (EmiStack stack : recipe.getOutputs()) {
					if (BoM.getRecipe(stack) == recipe) {
						stacks.add(stack);
					}
				}
				if (stacks.size() > 0) {
					list.add(TooltipComponent.of(EmiPort.ordered(EmiPort.translatable("tooltip.emi.set_default"))));
					list.add(TooltipComponent.of(EmiPort.ordered(EmiPort.translatable("tooltip.emi.current_defaults"))));
					list.add(new IngredientTooltipComponent(stacks));
					break;
				}
			case EMPTY:
				list.add(TooltipComponent.of(EmiPort.ordered(EmiPort.translatable("tooltip.emi.set_default"))));
				break;
			case FULL:
				list.add(TooltipComponent.of(EmiPort.ordered(EmiPort.translatable("tooltip.emi.unset_default"))));
				break;
		}
		if (recipe.getOutputs().size() > 1 && EmiConfig.helpLevel.has(HelpLevel.NORMAL) && EmiConfig.defaultStack.isBound()) {
			list.add(TooltipComponent.of(EmiPort.ordered(EmiPort.translatable("tooltip.emi.set_default_stack", EmiConfig.defaultStack.getBindText()))));
		}
		return list;
	}

