            poseStack.pushPose();
            poseStack.translate(BLADE_OFFSET);
            MekanismRenderer.rotate(poseStack, state.direction, 0, 180, 90, 270);
            poseStack.rotateDegrees(Axis.ZP, state.rotation % 360);
            submitBreakableBlockModel(nodeCollector, poseStack, Sheets.cutoutBlockItemSheet(), GeneratorsModelCache.INSTANCE.WIND_GENERATOR_BLADES.getBakedModel(), state);
            poseStack.popPose();
        }
    }

@Override
    public Collection<Line> applyTransformAndGetFrame(BlockEntity tile, float partialTick, PoseStack poseStack, LevelRenderState levelRenderState) {
        if (!(tile instanceof TileEntityWindGenerator generator)) {
            return Collections.emptyList();
        } else if (lines == null) {
            lines = Outlines.extract(GeneratorsModelCache.INSTANCE.WIND_GENERATOR_BLADES.getBakedModel());
        }
        poseStack.translate(BLADE_OFFSET);
        MekanismRenderer.rotate(poseStack, generator.getDirection(), 0, 180, 90, 270);
        float angle;
        if (generator.getActive() && partialTick > 0) {
            angle = (generator.getAngle() + generator.getHeightSpeedRatio() * partialTick) % 360;
        } else {
            angle = generator.getAngle();
        }
        poseStack.rotateDegrees(Axis.ZP, angle % 360);
        return lines;
    }

@Override
    public void submit(@Nullable GeneratorState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, int overlayCoords, boolean hasFoil, int outlineColor) {
        if (state == null) {
            return;
        }
        if (hasFoil) {
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor, true);
        } else {
            //Use vanilla's normal rendering submit chain so that if something breaks when updating, we only have things break when using glint
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor);
        }
        poseStack.pushPose();
        poseStack.translate(RenderWindGenerator.BLADE_OFFSET);
        poseStack.rotateDegrees(Axis.ZP, state.rotation % 360);
        int[] tints = state.blockRenderState.tintLayers().toArray(BlockModelRenderState.EMPTY_TINTS);
        List<BlockStateModelPart> blades = GeneratorsModelCache.INSTANCE.WIND_GENERATOR_BLADES.getBakedModel();
        nodeCollector.submitBlockModel(poseStack, Sheets.cutoutBlockItemSheet(), blades, tints, lightCoords, overlayCoords, outlineColor);
        if (hasFoil) {
            nodeCollector.order(1).submitBlockModel(poseStack, Sheets.cutoutBlockItemGlintSheet(), blades, BlockModelRenderState.EMPTY_TINTS, lightCoords,
                  OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
        }
        poseStack.popPose();
    }

private static void registerTooltipAppenders(RegisterTooltipAppendersEvent event) {
        event.registerComponentAppenderAfter(FISSION_LOGIC_TYPE, MekanismDataComponents.FACTORY_TYPE.get(), ItemTooltipUtils.createTrivialAppender(FISSION_LOGIC_TYPE,
              logicType -> GeneratorsLang.REACTOR_LOGIC_REDSTONE_MODE.translate(logicType.getColor(), logicType)
        ));
        event.registerComponentAppenderAfter(FUSION_LOGIC_TYPE, FISSION_LOGIC_TYPE.get(), ItemTooltipUtils.createTrivialAppender(FUSION_LOGIC_TYPE,
              logicType -> GeneratorsLang.REACTOR_LOGIC_REDSTONE_MODE.translate(logicType.getColor(), logicType)
        ));
        event.registerComponentAppenderAfter(ACTIVE_COOLED, FUSION_LOGIC_TYPE.get(), ItemTooltipUtils.createTrivialAppender(ACTIVE_COOLED,
              activeCooled -> GeneratorsLang.REACTOR_LOGIC_ACTIVE_COOLING.translate(EnumColor.RED, OnOff.of(activeCooled))
        ));
        event.registerComponentAppenderAfter(REACTION_STARTER, MekanismDataComponents.ATTACHED_CHEMICALS.get(), ItemTooltipUtils.createSimpleAppender(REACTION_STARTER, (stack, _, _, _, _, _, builder) -> {
            //Display hohlraum's ready for reaction *after* the stored chemical
            ResourceHandler<ChemicalResource> handler = Capabilities.CHEMICAL.getQueryOnlyCapability(stack);
            if (handler != null && ResourceHandlerUtil.isFull(handler)) {
                builder.accept(GeneratorsLang.READY_FOR_REACTION.translateColored(EnumColor.DARK_GREEN));
            } else {
                builder.accept(GeneratorsLang.INSUFFICIENT_FUEL.translateColored(EnumColor.DARK_RED));
            }
        }));
    }

