@Override
    public List<Component> getTooltip(ChemicalStack stack, Item.TooltipContext tooltipContext, @Nullable Player player, TooltipFlag tooltipFlag) {
        if (stack.isEmpty()) {
            return new ArrayList<>();
        }
        List<Component> tooltips = new ArrayList<>(stack.getTooltipLines(tooltipContext, player, tooltipFlag));
        if (tooltipMode == TooltipMode.SHOW_AMOUNT_AND_CAPACITY) {
            tooltips.add(MekanismLang.JEI_AMOUNT_WITH_CAPACITY.translateColored(EnumColor.GRAY, TextUtils.format(stack.amount()), TextUtils.format(capacityMb)));
        } else if (tooltipMode == TooltipMode.SHOW_AMOUNT) {
            tooltips.add(MekanismLang.GENERIC_MB.translateColored(EnumColor.GRAY, TextUtils.format(stack.amount())));
        }
        return tooltips;
    }

private <INGREDIENT> void addAliases(IIngredientType<INGREDIENT> type, List<INGREDIENT> stacks, Function<INGREDIENT, String> ingredientToString,
          IHasTranslationKey... aliases) {
        if (aliases.length == 0) {
            Mekanism.logger.warn("Expected to have at least one alias for ingredients of type: {}. Ingredients: {}", type.getUid(), stacks.stream()
                  .map(ingredientToString)
                  .collect(Collectors.joining(", "))
            );
        } else {
            List<String> aliasesAsString = Arrays.stream(aliases)
                  .map(IHasTranslationKey::getTranslationKey)
                  .toList();
            registration.addAliases(type, stacks, aliasesAsString);
        }
    }

private <TYPE, INGREDIENT> void addRawAliases(IIngredientTypeWithSubtypes<TYPE, INGREDIENT> type, List<TYPE> raw, IHasTranslationKey... aliases) {
        if (aliases.length == 0) {
            Mekanism.logger.warn("Expected to have at least one alias for raw ingredients of type: {}. Ingredients: {}", type.getUid(), raw.stream()
                  .map(Object::toString)
                  .collect(Collectors.joining(", "))
            );
        } else {
            List<String> aliasesAsString = Arrays.stream(aliases)
                  .map(IHasTranslationKey::getTranslationKey)
                  .toList();
            for (TYPE baseIngredient : raw) {
                registration.addAliases(type, baseIngredient, aliasesAsString);
            }
        }
    }

