public final void onRenderForeground(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float partialTicks) {
        if (visible) {
            // render background overlay and children above everything else
            renderBackgroundOverlay(guiGraphics, mouseX, mouseY);
            // render children just above background overlay
            for (GuiElement guiElement : children) {
                guiElement.renderShifted(guiGraphics, mouseX, mouseY, partialTicks);
            }
            for (GuiElement guiElement : children) {
                guiElement.onDrawBackground(guiGraphics, mouseX, mouseY, partialTicks);
            }
            renderForeground(guiGraphics, mouseX, mouseY, partialTicks);
            // translate forward to render child foreground
            for (GuiElement child : children) {
                // Note: Does not apply to compounding with grandchildren as we want those to compound
                child.onRenderForeground(guiGraphics, mouseX, mouseY, partialTicks);
            }
        }
    }

@Override
    public void extractWidgetRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float partialTicks) {
        //Note: Vanilla ensures visibility is checked before calling this method
        Matrix3x2fStack matrix = guiGraphics.pose();
        matrix.pushMatrix();
        // fix render offset to be as we expect things to be for how we implement our render methods (based on relatives)
        matrix.translate(getGuiLeft(), getGuiTop());
        renderShifted(guiGraphics, mouseX, mouseY, partialTicks);
        matrix.popMatrix();
    }

protected List<Component> getContentsTooltips(RESOURCE type, long amount, TooltipContext context, @Nullable Player player, TooltipFlag tooltipFlag) {
        List<Component> tooltips = new ArrayList<>();
        if (type.isEmpty()) {
            tooltips.add(MekanismLang.EMPTY.translate());
        } else if (amount == Long.MAX_VALUE) {
            tooltips.add(MekanismLang.GENERIC_STORED.translate(type, MekanismLang.INFINITE));
        } else {
            tooltips.add(MekanismLang.GENERIC_STORED_MB.translate(type, TextUtils.format(amount)));
        }
        return tooltips;
    }

