        ItemStack stack = gui().getCarriedItem();
        EnumColor color = getGaugeColor().getColor();
        List<Component> list;
        if (!stack.isEmpty() && stack.getItem() instanceof ItemConfigurator && color != null) {
            if (gui() instanceof GuiMekanismTile<?, ?> gui && gui.getTileEntity() instanceof ISideConfiguration sideConfig && getTransmission() != null) {
                DataType dataType = null;
                ConfigInfo config = sideConfig.getConfig().getConfig(getTransmission());
                if (config != null) {
                    for (DataType type : config.getSupportedDataTypes()) {
                        if (type.getColor() == color) {
                            dataType = type;
                            break;
                        }
                    }
                }
                if (dataType == null) {
                    list = List.of(MekanismLang.GENERIC_PARENTHESIS.translateColored(color, color.getName()));
                } else {
                    list = List.of(MekanismLang.GENERIC_WITH_PARENTHESIS.translateColored(color, dataType, color.getName()));
                }
            } else {
                list = Collections.emptyList();
            }
        } else {
            list = new ArrayList<>(getTooltipText());
            Component label = getLabel();
            if (label != null) {
                list.addFirst(label);
            }
        }
        if (!list.equals(lastInfo)) {
            lastInfo = list;
            lastTooltip = TooltipUtils.create(list);
        }
        setTooltip(lastTooltip);
    }

@Override
    public void updateTooltip(int mouseX, int mouseY) {
        if (currentContainer != null && mouseX >= getX() + 1 && mouseX < getX() + barXShift - 1) {
            int currentSelection = getCurrentSelection();
            for (int i = 0, focused = getFocusedElements(); i < focused; i++) {
                int index = currentSelection + i;
                if (index > currentList.size() - 1) {
                    break;
                }
                ModuleData<?> module = currentList.get(index);
                int installed = currentContainer.installedCount(module);
                int multipliedElement = elementHeight * i;
                if (installed > 0 && mouseY >= getY() + 1 + multipliedElement && mouseY < getY() + 1 + multipliedElement + elementHeight) {
                    Component info = MekanismLang.MODULE_INSTALLED.translate(MekanismLang.GENERIC_FRACTION.translateColored(EnumColor.GRAY, installed, module.getMaxStackSize()));
                    if (!info.equals(lastInfo)) {
                        lastInfo = info;
                        lastTooltip = TooltipUtils.create(info);
                    }
                    cachedTooltipRect = new ScreenRectangle(getX() + 1, getY() + 1 + multipliedElement, barXShift - 2, elementHeight);
                    setTooltip(lastTooltip);
                    return;
                }
            }
        }
        cachedTooltipRect = null;
        lastInfo = null;
        setTooltip(lastTooltip = null);
    }

@Override
    public void drawBackground(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float partialTicks) {
        super.drawBackground(guiGraphics, mouseX, mouseY, partialTicks);
        List<ResourceKey<RobitSkin>> skins = getUnlockedSkins();
        if (skins != null) {
            //Every ten ticks consider the skin to change
            int index = ticks / MekanismUtils.TICKS_PER_HALF_SECOND;
            float rot = Mth.rotLerp(partialTicks, rotation - ROTATION_INCREMENT, rotation);
            Quaternionf rotation = Axis.YP.rotationDegrees(rot);
            int slotStart = scrollBar.getCurrentSelection() * SLOT_COUNT, max = SLOT_COUNT * SLOT_COUNT;
            for (int i = 0; i < max; i++) {
                int slotX = (i % SLOT_COUNT) * SLOT_DIMENSIONS, slotY = (i / SLOT_COUNT) * SLOT_DIMENSIONS;
                int slot = slotStart + i;
                if (slot < skins.size()) {
                    ResourceKey<RobitSkin> skin = skins.get(slot);
                    if (skin == selectedSkin) {
                        renderSlotBackground(guiGraphics, slotX, slotY, GuiInnerScreen.SCREEN);
                    } else {
                        renderSlotBackground(guiGraphics, slotX, slotY, GuiElementHolder.HOLDER);
                    }
                    SkinLookup skinLookup = MekanismRobitSkins.lookup(gui().registryAccess(), skins.get(slot));
                    List<Identifier> textures = skinLookup.textures();
                    //Translate to the proper position and do our best job at centering it
                    Identifier texture = MathUtils.getByIndexMod(textures, index);
                    guiGraphics.submitPictureInPictureRenderState(new RobitSkinPreviewPiP.State(
                          getX() + slotX, getY() + slotY,
                          SLOT_DIMENSIONS,
                          guiGraphics.peekScissorStack(),
                          rotation,
                          RobitSkinManager.get().getBaked(skinLookup.skin(), texture)
                    ));
                } else {
                    renderSlotBackground(guiGraphics, slotX, slotY, GuiElementHolder.HOLDER);
                }
            }
        }
    }

@Override
    public void updateTooltip(int mouseX, int mouseY) {
        ResourceKey<RobitSkin> skin = getSkin(mouseX, mouseY, true);
        if (skin == null) {
            lastTooltip = null;
        } else if (lastSkin != skin) {
            lastTooltip = TooltipUtils.create(MekanismLang.ROBIT_SKIN.translate(RobitSkin.getTranslatedName(skin)));
        }
        lastSkin = skin;
        setTooltip(lastTooltip);
    }

private void renderSlotTooltip(GuiGraphicsExtractor guiGraphics, IScrollableSlot slot, int slotX, int slotY) {
        ItemStack stack = slot.itemType().toStack();
        if (stack.isEmpty()) {//Sanity check
            return;
        }
        long count = slot.count();
        if (count < 10_000) {
            guiGraphics.setTooltipForNextFrame(font(), stack, slotX, slotY);
        } else {
            //If the slot's displayed count is truncated, make sure we also add the actual amount to the tooltip
            gui().renderItemTooltipWithExtra(guiGraphics, stack, slotX, slotY, Collections.singletonList(MekanismLang.QIO_STORED_COUNT.translateColored(EnumColor.GRAY,
                  EnumColor.INDIGO, TextUtils.format(count))));
        }
    }

private void renderSlotText(GuiGraphicsExtractor guiGraphics, Component text, int x, int y) {
        float scale = 0.6F;
        float scaledWidth = font().width(text) * scale;
        if (scaledWidth >= INNER_SIZE) {
            //If we need a lower scale slightly due to having a lot of text, calculate it
            //Note: If it would still overflow, then we just let the scrolling text handle it
            scale = 0.5F;
        }
        //TODO - 26.3: gui zindex
        //PoseStack pose = guiGraphics.pose();
        //pose.pushPose();
        //pose.translate(0, 0, 200);
        drawScaledScrollingString(guiGraphics, text, x, y + 9, TextAlignment.RIGHT, CommonColors.WHITE, INNER_SIZE, 0, true, scale);
        //pose.popPose();
    }

@Override
    public void updateTooltip(int mouseX, int mouseY) {
        if (mouseX >= getX() + 1 && mouseX < getX() + barXShift - 1) {
            List<Holder<Upgrade>> currentInstalled = getCurrentInstalled();
            int currentSelection = getCurrentSelection();
            for (int i = 0, focused = getFocusedElements(); i < focused; i++) {
                int index = currentSelection + i;
                if (index > currentInstalled.size() - 1) {
                    break;
                }
                Holder<Upgrade> upgrade = currentInstalled.get(index);
                int multipliedElement = elementHeight * i;
                if (mouseY >= getY() + 1 + multipliedElement && mouseY < getY() + 1 + multipliedElement + elementHeight) {
                    cachedTooltipRect = new ScreenRectangle(getX() + 1, getY() + 1 + multipliedElement, barXShift - 2, elementHeight);
                    setTooltip(tooltips.computeIfAbsent(upgrade, u -> TooltipUtils.create(u.value().description())));
                    return;
                }
            }
        }
        cachedTooltipRect = null;
        clearTooltip();
    }

@Override
    public void updateTooltip(int mouseX, int mouseY) {
        ItemStack stack = gui().getCarriedItem();
        List<Component> list = Collections.emptyList();
        if (onHover != null) {
            list = onHover.apply(this);
        }
        if (list.isEmpty() && !stack.isEmpty() && stack.getItem() instanceof ItemConfigurator && gui() instanceof GuiMekanismTile<?, ?> gui &&
            gui.getTileEntity() instanceof ISideConfiguration config && gui.getHoveredSlot() instanceof InventoryContainerSlot slot) {
            ConfigInfo info = config.getConfig().getConfig(TransmissionType.ITEM);
            if (info != null) {
                IInventorySlot inventorySlot = slot.getInventorySlot();
                for (DataType type : info.getSupportedDataTypes()) {
                    if (info.getSlotInfo(type) instanceof InventorySlotInfo slotInfo && slotInfo.hasSlot(inventorySlot)) {
                        EnumColor color = type.getColor();
                        list = List.of(MekanismLang.GENERIC_WITH_PARENTHESIS.translateColored(color, type, color.getName()));
                        break;
                    }
                }
            }
        }
        if (!list.equals(lastInfo)) {
            lastInfo = list;
            lastTooltip = TooltipUtils.create(list);
        }
        setTooltip(lastTooltip);
    }

public GuiEnergyTab(IGuiWrapper gui, MachineEnergyContainer<?> energyContainer, BooleanSupplier isActive) {
        this(gui, () -> {
