@Override
    protected void drawForegroundText(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY) {
        renderTitleTextWithOffset(guiGraphics, ITEM_NAME_X, ITEM_NAME_X + ITEM_NAME_WIDTH + 4, 0, TextAlignment.CENTER);
        renderInventoryText(guiGraphics);
        int maximumCost = menu.getCost();
        if (maximumCost > 0) {
            if (msDisplayCost == 0) {
                msDisplayCost = Util.getMillis();
            }
            int textColor = 0xFF80FF20;
            Component component = MekanismLang.REPAIR_COST.translate(maximumCost);
            if (maximumCost >= 40 && !player.hasInfiniteMaterials()) {
                component = AnvilScreen.TOO_EXPENSIVE_TEXT;
                textColor = 0xFFFF6060;
            } else {
                Slot slot = menu.getSlot(AnvilMenu.RESULT_SLOT);
                if (!slot.hasItem()) {
                    component = null;
                    msDisplayCost = 0;
                } else if (!slot.mayPickup(player)) {
                    textColor = 0xFFFF6060;
                }
            }

            if (component != null) {
                int min = Math.max(ITEM_NAME_X, imageWidth - font().width(component) - 10);
                int max = imageWidth - 8;
                guiGraphics.fill(min, 67, max, 79, 0x4F000000);
                drawScrollingString(guiGraphics, component, min, 69, TextAlignment.RIGHT, textColor, max - min, 1, true, msDisplayCost);
            }
        } else {
            msDisplayCost = 0;
        }
        super.drawForegroundText(guiGraphics, mouseX, mouseY);
    }

@Nullable
    public static Tooltip create(ILangEntry... langEntries) {
        Objects.requireNonNull(langEntries);
        if (langEntries.length == 0) {
            throw new IllegalArgumentException("Messages cannot be null or empty");
        } else if (langEntries.length == 1) {
            //Note: This should never happen unless we are manually called with an explicit array
            return create(langEntries[0]);
        }
        List<Component> messages = new ArrayList<>(langEntries.length);
        for (ILangEntry langEntry : langEntries) {
            messages.add(langEntry.translate());
        }
        return create(messages);
    }

@Override
    public ParticleGroupRenderState extractRenderState(Frustum frustum, Camera camera, float partialTickTime) {
        return new LaserParticleGroup.State(this.particles.stream()
              //Ensure the laser is in the view, otherwise we don't need to bother rendering it
              .filter(particle -> frustum.isVisible(particle.getBoundingBox()))
              .<LaserFeatureRenderer.Submit>mapMulti((particle, consumer) -> {
                  PoseStack poseStack = new PoseStack();
                  Vec3 shift = particle.getPos().subtract(camera.position());
                  poseStack.translate(shift.x, shift.y, shift.z);
                  poseStack.rotate(particle.direction().getRotation());

                  poseStack.rotate(Axis.YP, RADIAN_45);
                  consumer.accept(new LaserFeatureRenderer.Submit(poseStack, particle));

                  poseStack.pushPose();
                  poseStack.rotate(Axis.YP, Mth.HALF_PI);
                  consumer.accept(new LaserFeatureRenderer.Submit(poseStack, particle));
              }).toList()
        );
    }

@Override
    protected void renderToTexture(CompassPiP.State state, PoseStack poseStack, SubmitNodeCollector nodeCollector) {
        Font font = Minecraft.getInstance().font;
        int color = HUDColor.REGULAR.getColorARGB();
        poseStack.translate(50, 50, 0);

        poseStack.pushPose();
        poseStack.scale(0.7F, 0.7F, 0.7F);
        nodeCollector.submitText(poseStack, -font.width(state.coords()) / 2F, -4, state.coords(), false, Font.DisplayMode.NORMAL, LightCoordsUtil.FULL_BRIGHT,
              color, 0, EntityRenderState.NO_OUTLINE);
        poseStack.popPose();

        poseStack.rotate(Axis.XN, ONE_THIRD_PI);
        poseStack.rotate(Axis.ZP, state.angle());

        rotateStr(poseStack, nodeCollector, MekanismLang.NORTH_SHORT, state.angle(), 0, color);
        rotateStr(poseStack, nodeCollector, MekanismLang.EAST_SHORT, state.angle(), Mth.HALF_PI, color);
        rotateStr(poseStack, nodeCollector, MekanismLang.SOUTH_SHORT, state.angle(), Mth.PI, color);
        rotateStr(poseStack, nodeCollector, MekanismLang.WEST_SHORT, state.angle(), -Mth.HALF_PI, color);

        poseStack.translate(-50, -50, 0);
        nodeCollector.submitCustomGeometry(poseStack, MekanismRenderType.GUI_SPRITES, (pose, buffer) -> {
            TextureAtlasSprite sprite = Minecraft.getInstance().getAtlasManager().getAtlasOrThrow(AtlasIds.GUI).getSprite(COMPASS);
            int argb = HUDColor.REGULAR.getColorARGB();
            Matrix4f matrix = pose.pose();
            buffer.addVertex(matrix, 0, 0, 0).setUv(sprite.getU0(), sprite.getV0()).setColor(argb);
            buffer.addVertex(matrix, 0, 100, 0).setUv(sprite.getU0(), sprite.getV1()).setColor(argb);
            buffer.addVertex(matrix, 100, 100, 0).setUv(sprite.getU1(), sprite.getV1()).setColor(argb);
            buffer.addVertex(matrix, 100, 0, 0).setUv(sprite.getU1(), sprite.getV0()).setColor(argb);
        });
    }

private void rotateStr(PoseStack pose, SubmitNodeCollector nodeCollector, ILangEntry langEntry, float rotation, float shift, int color) {
        pose.pushPose();
        pose.rotate(Axis.ZP, shift);
        pose.translate(0, -50, 0);
        pose.rotate(Axis.ZN, rotation + shift);
        nodeCollector.submitText(pose, -2.5F, -4, langEntry.translate().getVisualOrderText(), false, Font.DisplayMode.NORMAL, LightCoordsUtil.FULL_BRIGHT,
              color, 0, EntityRenderState.NO_OUTLINE);
        pose.popPose();
    }

public static IBarInfoHandler barProgressHandler(int processTime) {
        Component tooltip = MekanismLang.TICKS_REQUIRED.translate(processTime);
        int time = SharedConstants.MILLIS_PER_TICK * processTime;
        return new IBarInfoHandler() {
            @Override
            public Component getTooltip() {
                return tooltip;
            }

            @Override
            public double getLevel() {
                double subTime = Util.getMillis() % time;
                return subTime / time;
            }
        };
    }

