@Override
    public boolean render(BlockOutlineRenderState state, SubmitNodeCollector nodeCollector, PoseStack poseStack, LevelRenderState levelRenderState) {
        poseStack.pushPose();
        Vec3 viewPosition = levelRenderState.cameraRenderState.pos;
        poseStack.translate(pos.getX() - viewPosition.x, pos.getY() - viewPosition.y, pos.getZ() - viewPosition.z);

        //if top/bottom face, try to rotate so the bottom is as close to screen bottom as we can get
        if (face == Direction.UP || face == Direction.DOWN) {
            Direction cameraFacing = Direction.fromYRot(levelRenderState.cameraRenderState.yRot);
            if (cameraFacing != Direction.NORTH) {
                poseStack.rotateAround(V_ROT[cameraFacing.ordinal() - V_ROT_OFFSET], 0.5F, 1, 0.5F);
            }
        }

        if (isDiversion) {
            poseStack.scale(0.5F, 0.5F, 0.5F);
            poseStack.translate(0.5, 0.5, 0.5);
        }
        RenderPhaseKey<SubmitNode> phase = state.isTranslucent() ? RenderPhaseKeys.AFTER_TERRAIN : RenderPhaseKeys.SHAPE_OUTLINES;
        nodeCollector.submitSpecial(phase, new CustomFeatureRenderer.Submit(poseStack.last().copy(), RenderTypes.eyes(sprite.atlasLocation()), this));
        poseStack.popPose();
        return !isDiversion;
    }

public void renderHUD(Minecraft minecraft, Player player, GuiGraphicsExtractor guiGraphics, Font font, DeltaTracker delta, int screenWidth, int screenHeight,
          int maxTextHeight, boolean reverseHud) {
        update(minecraft.level, player);
        if (MekanismConfig.client.hudOpacity.get() < 0.05F) {
            return;
        }
        Matrix3x2fStack matrix = guiGraphics.pose();
        matrix.pushMatrix();
        float yawJitter = -absSqrt(player.yHeadRot - prevRotationYaw);
        float pitchJitter = -absSqrt(player.getXRot() - prevRotationPitch);
        matrix.translate(yawJitter, pitchJitter);
        int audibleSubtitlesWidth = MekanismConfig.client.hudAvoidSoundSubtitleOverlay.get() ? getAudibleSubtitlesWidth(minecraft, font) : 0;
        if (MekanismConfig.client.hudCompassEnabled.get()) {
            matrix.pushMatrix();
            //Reversed hud causes the compass to render on the right side of the screen
            int posX = reverseHud ? screenWidth - 125 - audibleSubtitlesWidth : 25;
            //Pin the compass above the bottom of the screen and also above the text hud that may render below it
            int posY = Math.min(screenHeight - 20, maxTextHeight) - 80;
            matrix.translate(posX - 125, posY - 125);
            guiGraphics.submitPictureInPictureRenderState(new CompassPiP.State(new Matrix3x2f(matrix), guiGraphics.peekScissorStack(),
                  MekanismLang.GENERIC_BLOCK_POS.translate(player.getBlockX(), player.getBlockY(), player.getBlockZ()),
                  Mth.PI - Mth.DEG_TO_RAD * player.getViewYRot(delta.getGameTimeDeltaPartialTick(true))
            ));
            matrix.popMatrix();
        }

        renderMekaSuitEnergyIcons(player, font, guiGraphics);
        renderMekaSuitModuleIcons(player, font, guiGraphics, screenWidth, screenHeight, reverseHud, audibleSubtitlesWidth);

        matrix.popMatrix();
    }

private void renderMekaSuitEnergyIcons(Player player, Font font, GuiGraphicsExtractor guiGraphics) {
        Matrix3x2fStack pose = guiGraphics.pose();
        pose.pushMatrix();
        pose.translate(10, 10);
        int posX = 0;
        Predicate<TypedInstance<Item>> showArmorPercent = item -> item.is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR);
        for (int i = 0; i < ARMOR_SLOTS.length; i++) {
            posX += renderEnergyIcon(player, font, guiGraphics, posX, ARMOR_ICONS[i], ARMOR_SLOTS[i], showArmorPercent);
        }
        Predicate<TypedInstance<Item>> showToolPercent = item -> item.is(MekanismAPITags.Items.MODULE_CONTAINERS_HELD);
        for (EquipmentSlot hand : EquipmentSlotGroup.HAND) {
            posX += renderEnergyIcon(player, font, guiGraphics, posX, TOOL_ICON, hand, showToolPercent);
        }
        pose.popMatrix();
    }

default void drawScrollingString(GuiGraphicsExtractor graphics, Component text, int minX, int minY, int maxX, int maxY, TextAlignment alignment, int color, boolean shadow,
          long msVisible) {
        Font font = font();
        int textWidth = font.width(text);
        int areaWidth = maxX - minX;
        boolean isScrolling = textWidth > areaWidth;
        //Note: Instead of doing what vanilla does, we divide to float, and don't add one
        // That way if min and max are not just lineHeight away they will be more accurate, and otherwise it won't render one line below where it should be
        float targetY = (minY + maxY - font.lineHeight) / 2F;
        float targetX;
        if (isScrolling) {
            targetX = prepScrollingString(graphics, font, textWidth, areaWidth, minX, minY, maxX, maxY, Util.getMillis() - msVisible);
        } else {
            targetX = alignment.getTarget(font, minX, maxX, textWidth);
        }
        Matrix3x2fStack pose = graphics.pose();
        pose.pushMatrix();
        pose.translate(targetX, targetY);
        graphics.text(font, text.getVisualOrderText(), 0, 0, color, shadow);
        pose.popMatrix();
        if (isScrolling) {
            graphics.disableScissor();
        }
    }

private static Matrix3x2fStack prepTextScale(GuiGraphicsExtractor graphics, Font font, float x, float y, float scale) {
        Matrix3x2fStack matrix = graphics.pose();
        matrix.pushMatrix();
        float halfLineHeight = font.lineHeight / 2F;
        float yAdd = halfLineHeight - halfLineHeight * scale;
        matrix.translate(x, y + yAdd);
        matrix.scale(scale, scale);
        return matrix;
    }

private void render(GuiGraphicsExtractor graphics, int x, int startY, int maxLength, TextAlignment alignment, int color, float scale) {
            if (ARGB.alpha(color) == 0) {
                Mekanism.logger.warn("Alpha not supplied?", new Exception());
            }
            Font font = fontRenderer.font();
            //Divide by scale for calculating actual max length so that when the text is scaled it has the proper total space available
            calculateLines(font, scale == 1 ? maxLength : Mth.floor(maxLength / scale));
            int maxX = x + maxLength;
            Matrix3x2fStack pose = graphics.pose();
            for (FormattedCharSequence line : linesToDraw) {
                pose.pushMatrix();
                pose.translate(alignment.getTarget(font, x, maxX, Math.round(scale * font.width(line))), startY);
                graphics.text(font, line, 0, 0, color, false);
                pose.popMatrix();
                startY += font.lineHeight;
            }
        }

private static void renderValve(Vec3 camPos, PoseStack matrix, RenderType renderType, SubmitNodeCollector nodeCollector, BlockPos rendererPos, int overlay,
          ValveRenderData valveRenderData, int glow, FaceDisplay faceDisplay, TexturePicker valveTexture, int fluidColor, float mainFluidHeight, int physicalHeight) {
        Direction side = valveRenderData.getSide();
        if (ModelRenderer.shouldSkipValveRender(mainFluidHeight, side, physicalHeight, valveRenderData.getValveFluidHeight())) {
            return;
        }
        matrix.pushPose();
        BlockPos valveLocation = valveRenderData.getValveLocation();
        matrix.translate(valveLocation.getX() - rendererPos.getX(), valveLocation.getY() - rendererPos.getY(), valveLocation.getZ() - rendererPos.getZ());
        renderCube(valveRenderData.renderCheck, valveRenderData.minX, valveRenderData.minY, valveRenderData.minZ, valveRenderData.maxX, valveRenderData.maxY, valveRenderData.maxZ,
              matrix, renderType, nodeCollector, fluidColor, glow, overlay, faceDisplay, camPos, Vec3.atLowerCornerOf(valveLocation), valveTexture);
        matrix.popPose();

    }

public static void renderObject(Vec3 camPos, PoseStack matrix, RenderType renderType, SubmitNodeCollector nodeCollector, @SideRender.SideRenderFlags byte sideRenderCheck,
          float cubeMinX, float cubeMinY, float cubeMinZ, float cubeMaxX, float cubeMaxY, float cubeMaxZ, TexturePicker spriteFromDirection, int overlay, int glowLight,
          int scaledColor, BlockPos terPos, BlockPos renderStartPos, int physicalLength, int physicalWidth) {
        matrix.pushPose();
        matrix.translate(renderStartPos.getX() - terPos.getX(), renderStartPos.getY() - terPos.getY(), renderStartPos.getZ() - terPos.getZ());
        FaceDisplay faceDisplay = getFaceDisplay(camPos, renderStartPos, physicalLength, physicalWidth, cubeMaxY);
        renderCube(sideRenderCheck, cubeMinX, cubeMinY, cubeMinZ, cubeMaxX, cubeMaxY, cubeMaxZ, matrix, renderType, nodeCollector, scaledColor, glowLight, overlay, faceDisplay,
              camPos, Vec3.atLowerCornerOf(renderStartPos), spriteFromDirection);
        matrix.popPose();
    }

@SubscribeEvent
    public void submitCustomGeometry(SubmitCustomGeometryEvent event) {
        if (boltRenderer.hasBoltsToRender()) {
            LevelRenderState levelState = event.getLevelRenderState();
            List<BoltRenderState> boltRenderStates = boltRenderer.collectBoltStates(levelState.gameTime, MekanismRenderer.getPartialTick());
            if (!boltRenderStates.isEmpty()) {

                PoseStack poseStack = event.getPoseStack();
                SubmitNodeCollector nodeCollector = event.getSubmitNodeCollector();
                poseStack.pushPose();
                Vec3 cameraPos = levelState.cameraRenderState.pos;
                poseStack.translate(-cameraPos.x, -cameraPos.y, -cameraPos.z);

                PoseStack.Pose pose = poseStack.last().copy();
                for (BoltRenderState state : boltRenderStates) {
                    nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, state));
                }
                poseStack.popPose();
            }
        }
    }

@Override
    public <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector collector, int lightCoords, STATE state,
          boolean isBaby, ItemStack stack) {
        ItemStackRenderState bodyItem = state.getRenderData(CHEST_CONTEXT);
        if (bodyItem != null) {
            poseStack.pushPose();
            baseModel.body.translateAndRotate(poseStack);
            if (isBaby) {
                poseStack.scale(state.ageScale, state.ageScale, state.ageScale);
                if (jetpack) {
                    poseStack.translate(0, -0.05, 0);
                }
            } else if (jetpack) {
                poseStack.translate(0, 0.3, 0);
            } else {
                poseStack.translate(0, 0.41, 0);
            }
            if (jetpack) {
                poseStack.translate(0, 0, 0.145);
                poseStack.scale(1.02F, -1.02F, -1.02F);
            } else {
                poseStack.translate(0, 0, 0.28);
                poseStack.scale(1, -1, -1);
            }
            bodyItem.submit(poseStack, collector, lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor);
            poseStack.popPose();
        }
    }

private void applyTransforms(PoseStack poseStack, ModelPart leg, boolean isBaby, HumanoidRenderState state, double xo) {
        leg.translateAndRotate(poseStack);
        if (isBaby) {
            poseStack.scale(state.ageScale, state.ageScale, state.ageScale);
            poseStack.translate(0, -0.2, 0);
        }
        poseStack.translate(xo, 1, 0.525);
        poseStack.scale(1.02F, -1.02F, -1.02F);
    }

default <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords,
          STATE state, ItemStack stack) {
        //If the model isn't meant to be shown don't bother rendering anything
        if (isVisible(baseModel, state)) {
            poseStack.pushPose();
            baseModel.setupAnim(state);
            baseModel.root().translateAndRotate(poseStack);
            //Similar to HumanoidArmorLayer, we don't want to rescale for small armor stands as they just have their overall scale changed
            boolean isBaby = state.isBaby && state.entityType != EntityTypes.ARMOR_STAND;
            render(baseModel, poseStack, nodeCollector, lightCoords, state, isBaby, stack);
            poseStack.popPose();
        }
    }

public void renderArm(AvatarRenderState avatarRenderState, ModelPart armPart, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, boolean rightHand) {
        ModelPos armPos = rightHand ? ModelPos.RIGHT_ARM : ModelPos.LEFT_ARM;
        Map<ModelPos, PartData> armorQuads = cache.getUnchecked(key(avatarRenderState));
        PartData armData = armorQuads.get(armPos);
        if (armData != null) {
            poseStack.pushPose();
            armPart.translateAndRotate(poseStack);
            armPos.translateModel(poseStack);
            armData.render(poseStack, nodeCollector, lightCoords, avatarRenderState.outlineColor, getColor(avatarRenderState.chestEquipment), avatarRenderState.chestEquipment.hasFoil());
            poseStack.popPose();
        }
    }

@Override
    public <STATE extends HumanoidRenderState> void render(HumanoidModel<STATE> baseModel, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords,
          STATE state, boolean isBaby, ItemStack stack) {
        Map<ModelPos, PartData> armorQuads = cache.getUnchecked(key(state));
        boolean renderFoil = stack.hasFoil();

        if (!armorQuads.isEmpty()) {
            int tintColor = getColor(stack);
            for (Map.Entry<ModelPos, PartData> entry : armorQuads.entrySet()) {
                ModelPos modelPos = entry.getKey();
                poseStack.pushPose();
                modelPos.translate(baseModel, poseStack, state);
                if (isBaby) {
                    modelPos.scaleBaby(poseStack, state);
                }
                modelPos.translateModel(poseStack);
                entry.getValue().render(poseStack, nodeCollector, lightCoords, state.outlineColor, tintColor, renderFoil);
                poseStack.popPose();
            }
        }


        if (type == EquipmentSlot.CHEST) {
            UUID entityUUID = state.getRenderData(UUID_CONTEXT);
            if (entityUUID != null) {
                long gameTime = Minecraft.getInstance().level == null ? 0L : Minecraft.getInstance().level.getGameTime();
                BoltRenderer boltRenderer = boltRenderMap.computeIfAbsent(entityUUID, _ -> new BoltRenderer());
                if (IModuleHelper.INSTANCE.isEnabled(state.chestEquipment, MekanismModules.GRAVITATIONAL_MODULATING_UNIT)) {
                    boltRenderer.update(0, LEFT_GRAV_BOLT, gameTime, state.partialTick);
                    boltRenderer.update(1, RIGHT_GRAV_BOLT, gameTime, state.partialTick);
                }
                List<BoltRenderState> boltRenderStates = boltRenderer.collectBoltStates(gameTime, state.partialTick);
                if (!boltRenderStates.isEmpty()) {
                    //Adjust the poseStack so that we render the lightning in the correct spot if the player is crouching
                    poseStack.pushPose();
                    ModelPos.BODY.translate(baseModel, poseStack, state);
                    PoseStack.Pose pose = poseStack.last().copy();
                    for (BoltRenderState boltState : boltRenderStates) {
                        nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, boltState));
                    }
                    poseStack.popPose();
                }
            }
        }
    }

public <STATE extends HumanoidRenderState> void scaleBaby(PoseStack poseStack, STATE state) {
            if (this != HEAD) {
                poseStack.scale(state.ageScale, state.ageScale, state.ageScale);
            }
            switch (this) {
                case BODY -> poseStack.translate(0, -0.55, 0);
                case LEFT_ARM, LEFT_WING -> poseStack.translate(-0.15625, 0, 0);
                case RIGHT_ARM, RIGHT_WING -> poseStack.translate(0.15625, 0, 0);
                case LEFT_LEG -> poseStack.translate(-0.0625, -0.25, 0);
                case RIGHT_LEG -> poseStack.translate(0.0625, -0.25, 0);
            }
        }

public <STATE extends HumanoidRenderState> void translate(HumanoidModel<STATE> baseModel, PoseStack poseStack, STATE state) {
            switch (this) {
                case HEAD -> baseModel.head.translateAndRotate(poseStack);
                case BODY -> baseModel.body.translateAndRotate(poseStack);
                case LEFT_ARM -> baseModel.leftArm.translateAndRotate(poseStack);
                case RIGHT_ARM -> baseModel.rightArm.translateAndRotate(poseStack);
                case LEFT_LEG -> baseModel.leftLeg.translateAndRotate(poseStack);
                case RIGHT_LEG -> baseModel.rightLeg.translateAndRotate(poseStack);
                case LEFT_WING, RIGHT_WING -> translateWings(baseModel, poseStack, state);
            }
        }

private <STATE extends HumanoidRenderState> void translateWings(HumanoidModel<STATE> baseModel, PoseStack poseStack, STATE state) {
            baseModel.body.translateAndRotate(poseStack);
            float scale = state.getRenderDataOrDefault(WING_SCALE, 0F);
            // if we don't have any upwards momentum, and we are pointing steeply into the sky then we just fold the wings
            float x = EXPANDED_WING_X * scale;
            float y = EXPANDED_WING_Y * scale;
            float z = EXPANDED_WING_Z * scale;
            float yRot = EXPANDED_WING_Y_ROT * scale;
            float zRot = EXPANDED_WING_Z_ROT * scale;
            if (this == RIGHT_WING) {
                //Invert things that need to be inverted for the right wing to mirror it properly
                x = -x;
                yRot = -yRot;
                zRot = -zRot;
            }
            poseStack.translate(x / 16, y / 16, z / 16);
            if (yRot != 0.0F) {
                poseStack.rotateDegrees(Axis.YP, yRot);
            }
            if (zRot != 0.0F) {
                poseStack.rotateDegrees(Axis.ZP, zRot);
            }
        }

@Override
    public void submit(RobitRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        boolean isBodyVisible = this.isBodyVisible(state);
        boolean forceTransparent = !isBodyVisible && !state.isInvisibleToPlayer;
        //nb: this segment copied from super, bed & layer checks removed, invisibility check moved, and model submit replaced with submitRobitSkin()
        if (!forceTransparent) {
            poseStack.pushPose();
            {
                float scale = state.scale;
                poseStack.scale(scale, scale, scale);
                this.setupRotations(state, poseStack, state.bodyRot, scale);
                poseStack.scale(-1.0F, -1.0F, 1.0F);
                this.scale(state, poseStack);
                poseStack.translate(0.0F, -1.501F, 0.0F);
                //isBodyVisible & forceTransparent moved above
                submitRobitSkin(state, poseStack, nodeCollector);
            }
            poseStack.popPose();
        }
        //allow any layers/nametag/leash states to submit
        super.submit(state, poseStack, nodeCollector, camera);
    }

private void submitRobitSkin(RobitRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector) {
        poseStack.pushPose();
        poseStack.rotate(Axis.XP, Mth.PI);
        poseStack.translate(-0.5, -1.5, -0.5);
        submitRobitSkin(state.model, poseStack, nodeCollector, getOverlayCoords(state, this.getWhiteOverlayProgress(state)), state.lightCoords, state.outlineColor, false);
        poseStack.popPose();
    }

@Override
    public void render(GuiGraphicsExtractor graphics, DeltaTracker delta) {
        Minecraft minecraft = Minecraft.getInstance();
        if (modeSwitchTimer > 1 && minecraft.player != null && !minecraft.player.isSpectator() && !minecraft.gui.hud.isHidden()) {
            ItemStack stack = minecraft.player.getMainHandItem();
            if (IModeItem.isModeItem(stack, EquipmentSlot.MAINHAND)) {
                Component scrollTextComponent = ((IModeItem) stack.getItem()).getScrollTextComponent(stack);
                if (scrollTextComponent != null) {
                    Color color = Color.rgbad(1, 1, 1, modeSwitchTimer / (float) BASE_TIMER);
                    Font font = minecraft.gui.hud.getFont();
                    int componentWidth = font.width(scrollTextComponent);
                    int targetShift = Math.max(59, Math.max(minecraft.gui.hud.leftHeight, minecraft.gui.hud.rightHeight));
                    if (minecraft.gameMode != null && !minecraft.gameMode.canHurtPlayer()) {
                        //Same shift as done in Gui#renderSelectedItemName
                        targetShift -= 14;
                    } else if (minecraft.gui.hud.overlayMessageTime > 0) {
                        //If we are in survival though that means our thing will end up intersecting the subtitle text if there is any,
                        // so we need to check if there is, and if so shift our target further
                        targetShift += 14;
                    }
                    //Shift the rendering to be above the previous line
                    targetShift += 13;
                    Matrix3x2fStack pose = graphics.pose();
                    pose.pushMatrix();
                    pose.translate((graphics.guiWidth() - componentWidth) / 2F, graphics.guiHeight() - targetShift);
                    GuiUtils.drawBackdrop(graphics, minecraft, 0, 0, componentWidth, color.af());
                    graphics.text(font, scrollTextComponent, 0, 0, color.argb());
                    pose.popMatrix();
                }
            }
            //Only decrement the switch timer once a tick
            if (lastTick != minecraft.gui.hud.getGuiTicks()) {
                lastTick = minecraft.gui.hud.getGuiTicks();
                modeSwitchTimer--;
            }
        }
    }

@Override
    public void submit(@Nullable CubeState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, int overlayCoords, boolean hasFoil, int outlineColor) {
        if (state == null) {
            return;
        }
        if (hasFoil) {
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor, true);
        } else {
            //Use vanilla's normal rendering submit chain so that if something breaks when updating, we only have things break when using glint
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor);
        }
        if (state.coreTint != null) {
            float scaledTicks = 4 * state.ticks();
            poseStack.pushPose();
            poseStack.translate(0.5, 0.5, 0.5);
            poseStack.scale(0.4F, 0.4F, 0.4F);
            poseStack.translate(0, Math.sin(Math.toRadians(3 * state.ticks())) / 7, 0);
            poseStack.rotateDegrees(Axis.YP, scaledTicks);
            poseStack.rotateDegrees(RenderEnergyCube.coreVec, 36F + scaledTicks);
            nodeCollector.submitBlockModel(poseStack, Sheets.translucentBlockItemSheet(), MekanismModelCache.INSTANCE.ENERGY_CORE.getBakedModel(),
              new int[]{state.coreTint}, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
            poseStack.popPose();
        }
    }

