@Override
    public Collection<Line> applyTransformAndGetFrame(BlockEntity tile, float partialTick, PoseStack poseStack, LevelRenderState levelRenderState) {
        if (!(tile instanceof TileEntityPigmentMixer mixer)) {
            return Collections.emptyList();
        } else if (lines == null) {
            lines = Outlines.extract(MekanismModelCache.INSTANCE.PIGMENT_MIXER_SHAFT.getBakedModel());
        }
        switch (mixer.getDirection()) {
            case NORTH -> poseStack.translate(7 / 16F, 0, 6 / 16F);
            case SOUTH -> poseStack.translate(7 / 16F, 0, 0.5F);
            case WEST -> poseStack.translate(6 / 16F, 0, 7 / 16F);
            case EAST -> poseStack.translate(0.5F, 0, 7 / 16F);
        }
        float shift = 1 / 16F;
        poseStack.translate(shift, 0, shift);
        poseStack.rotateDegrees(Axis.YN, getAnimationTime(levelRenderState.gameTime, partialTick) * SHAFT_SPEED % 360);
        poseStack.translate(-shift, 0, -shift);
        return lines;
    }

@Override
    public void submit(SPSRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        if (state.center != null) {
            poseStack.pushPose();
            //Render from the center position instead of from the block's position
            poseStack.translate(state.center.x() - state.blockPos.getX(), state.center.y() - state.blockPos.getY(), state.center.z() - state.blockPos.getZ());
            poseStack.rotate(camera.orientation);

            if (state.coreState != null) {
                submitBillboard(poseStack, nodeCollector, CORE_RENDER_TYPE, state.coreState);
            }

            for (BillboardingRenderState orbitEffect : state.orbitEffects) {
                submitBillboard(poseStack, nodeCollector, SPSOrbitEffect.RENDER_TYPE, orbitEffect);
            }
            poseStack.popPose();
        }

        if (!state.boltRenderStates.isEmpty()) {
            Pose pose = poseStack.last().copy();
            for (BoltRenderState boltRenderState : state.boltRenderStates) {
                nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, boltRenderState));
            }
        }
    }

private void submitBillboard(PoseStack poseStack, SubmitNodeCollector nodeCollector, RenderType renderType, BillboardingRenderState state) {
        poseStack.pushPose();
        poseStack.translate(state.pos.x(), state.pos.y(), state.pos.z());
        poseStack.scale(state.scale, state.scale, state.scale);
        nodeCollector.submitSpecial(RenderPhaseKeys.AFTER_TERRAIN, new BillboardingEffectFeatureRenderer.Submit(poseStack.last().copy(), renderType, state));
        poseStack.popPose();
    }

@Override
    public void submit(VibratorRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        poseStack.pushPose();
        poseStack.translate(0, 0.625 * state.piston, 0);
        submitBreakableBlockModel(nodeCollector, poseStack, Sheets.cutoutBlockItemSheet(), MekanismModelCache.INSTANCE.VIBRATOR_SHAFT.getBakedModel(), state);
        poseStack.popPose();
    }

@Override
    public Collection<Line> applyTransformAndGetFrame(BlockEntity tile, float partialTick, PoseStack poseStack, LevelRenderState levelRenderState) {
        if (!(tile instanceof TileEntitySeismicVibrator vibrator)) {
            return Collections.emptyList();
        } else if (lines == null) {
            lines = Outlines.extract(MekanismModelCache.INSTANCE.VIBRATOR_SHAFT.getBakedModel());
        }
        float piston = Math.max(0, (float) Math.sin((vibrator.clientPiston + (vibrator.getActive() ? partialTick : 0)) / 5F));
        poseStack.translate(0, piston * 0.625, 0);
        return lines;
    }

@Override
    public void submit(TransporterRenderState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        //Note: We expect this to not actually render anything, but call it just in case for consistency
        super.submit(state, poseStack, nodeCollector, camera);
        if (!state.stacks.isEmpty()) {
            for (TransporterStackRenderState stackRenderState : state.stacks) {
                poseStack.pushPose();
                poseStack.translate(stackRenderState.stackPos().x(), stackRenderState.stackPos().y(), stackRenderState.stackPos().z());
                if (stackRenderState.color() != null) {
                    poseStack.pushPose();
                    poseStack.translate(-0.5F, -0.25F, -0.5F);
                    nodeCollector.submitBlockModel(poseStack, Sheets.cutoutBlockItemSheet(), MekanismModelCache.INSTANCE.TRANSPORTER_BOX.getBakedModel(),
                          new int[]{stackRenderState.color().getPackedColor()}, state.lightCoords, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
                    poseStack.popPose();
                }
                AABB bb = stackRenderState.item().getModelBoundingBox();
                double maxDimension = Math.max(bb.getXsize(), Math.max(bb.getYsize(), bb.getZsize()));
                //TODO: Do we want to scale up tiny models?
                if (maxDimension > 1) {
                    //Scale any overly large models down to a single unit
                    float scale = (float) (1 / maxDimension);
                    poseStack.scale(scale, scale, scale);
                    poseStack.translate(0, 0.25F, 0);
                }
                poseStack.translate(0, 0.25F, 0);
                poseStack.scale(0.25F, 0.25F, 0.25F);
                stackRenderState.item().submit(poseStack, nodeCollector, state.lightCoords, OverlayTexture.NO_OVERLAY, 0);
                poseStack.popPose();
            }
        }
    }

@Override
    public void submit(STATE state, PoseStack poseStack, SubmitNodeCollector nodeCollector, CameraRenderState camera) {
        if (!state.contentsModel.isEmpty()) {
            poseStack.pushPose();
            poseStack.translate(0.5, 0.5, 0.5);
            nodeCollector.submitBlockModel(poseStack, Sheets.translucentBlockItemSheet(), state.contentsModel, state.modelTint, state.lightCoords, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
            poseStack.popPose();
        }
    }

