public static ConfigurableHeightRange create(IMekanismConfig config, ModConfigSpec.Builder builder, OreVeinConfigTranslations translations, BaseOreConfig baseConfig) {
        CachedEnumValue<HeightShape> shape = CachedEnumValue.wrap(config, translations.distributionShape().applyToBuilder(builder)
              .defineEnum("shape", baseConfig.shape()));
        CachedIntValue plateau = CachedIntValue.wrap(config, MekanismConfigTranslations.WORLD_HEIGHT_RANGE_PLATEAU.applyToBuilder(builder)
              .define("plateau", baseConfig.plateau(), o -> {
                  if (o instanceof Integer value) {
                      if (value == 0) {
                          return true;
                      }
                      return value > 0 && shape.getOrDefault() == HeightShape.TRAPEZOID;
                  }
                  return false;
              }));
        ConfigurableVerticalAnchor minInclusive = ConfigurableVerticalAnchor.create(config, builder, "minInclusive", translations.minInclusive(), baseConfig.min(), null);
        ConfigurableVerticalAnchor maxInclusive = ConfigurableVerticalAnchor.create(config, builder, "maxInclusive", translations.maxInclusive(), baseConfig.max(), minInclusive);
        return new ConfigurableHeightRange(shape, minInclusive, maxInclusive, plateau);
    }

public static ConfigurableVerticalAnchor create(IMekanismConfig config, ModConfigSpec.Builder builder, String path, IConfigTranslation translation, OreAnchor defaultAnchor,
          @Nullable ConfigurableVerticalAnchor minAnchor) {
        translation.applyToBuilder(builder).push(path);
        CachedEnumValue<AnchorType> type = CachedEnumValue.wrap(config, MekanismConfigTranslations.WORLD_ANCHOR_TYPE.applyToBuilder(builder)
              //Note: Add extra comments so that when viewing from the file, people can know what each option does
              .comment(
                    "Absolute (y = value)",
                    "Above Bottom (y = minY + value)",
                    "Below Top (y = depth - 1 + minY - value)"
              ).defineEnum("type", defaultAnchor.type()));
        ConfigValue<Integer> value;
        if (minAnchor == null) {
            value = MekanismConfigTranslations.WORLD_ANCHOR_VALUE.applyToBuilder(builder).define("value", defaultAnchor.value());
        } else {
            value = MekanismConfigTranslations.WORLD_ANCHOR_VALUE.applyToBuilder(builder).define("value", defaultAnchor.value(), o -> {
                if (o instanceof Integer v) {
                    return minAnchor.anchorType.getOrDefault() != type.getOrDefault() || v >= minAnchor.value.getOrDefault();
                }
                return false;
            });
        }
        builder.pop();
        return new ConfigurableVerticalAnchor(type, CachedIntValue.wrap(config, value));
    }

