		if (!visible) {
			return;
		}
		boolean hovered = isMouseOver(mouseX, mouseY);
		boolean pressed = pendingClick != null && hovered;
		Internal.getTextures().getButtonBackground(active, hovered, pressed).draw(graphics, 0, 0, width, height);
