public static void onInitialize() {
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.DeleteItems.TYPE, REIPackets.DeleteItems.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }
            AbstractContainerMenu menu = player.containerMenu;
            if (!menu.getCarried().isEmpty()) {
                menu.setCarried(ItemStack.EMPTY);
                menu.broadcastChanges();
            }
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.CreateItems.TYPE, REIPackets.CreateItems.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();

            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }
            ItemStack stack = payload.stack();
            if (player.getInventory().add(stack.copy())) {
                NetworkManager.sendToPlayer(player, new REIPackets.CreateItemsMessage(stack.copy(), player.getScoreboardName()));
            } else {
                player.sendSystemMessage(Component.translatable("text.rei.failed_cheat_items"));
            }
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.CreateItemsGrab.TYPE, REIPackets.CreateItemsGrab.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }

            AbstractContainerMenu menu = player.containerMenu;
            ItemStack stack = payload.stack().copy();
            if (!menu.getCarried().isEmpty() && ItemStack.isSameItemSameComponents(menu.getCarried(), stack)) {
                stack.setCount(Mth.clamp(stack.getCount() + menu.getCarried().getCount(), 1, stack.getMaxStackSize()));
            } else if (!menu.getCarried().isEmpty()) {
                return;
            }
            menu.setCarried(stack.copy());
            menu.broadcastChanges();
            NetworkManager.sendToPlayer(player, new REIPackets.CreateItemsMessage(stack.copy(), player.getScoreboardName()));
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.CreateItemsHotbar.TYPE, REIPackets.CreateItemsHotbar.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            if (!player.permissions().hasPermission(new Permission.HasCommandLevel(PermissionLevel.GAMEMASTERS))) {
                player.sendSystemMessage(Component.translatable("text.rei.no_permission_cheat").withStyle(ChatFormatting.RED));
                return;
            }
            ItemStack stack = payload.stack();
            int hotbarSlotId = payload.hotbarSlot();
            if (hotbarSlotId >= 0 && hotbarSlotId < 9) {
                AbstractContainerMenu menu = player.containerMenu;
                player.getInventory().setItem(hotbarSlotId, stack.copy());
                menu.broadcastChanges();
                NetworkManager.sendToPlayer(player, new REIPackets.CreateItemsMessage(stack.copy(), player.getScoreboardName()));
            } else {
                player.sendSystemMessage(Component.translatable("text.rei.failed_cheat_items"));
            }
        });
        NetworkManager.registerReceiver(NetworkManager.c2s(), REIPackets.MoveItemsNew.TYPE, REIPackets.MoveItemsNew.STREAM_CODEC, List.of(new SplitPacketTransformer()), (payload, context) -> {
            ServerPlayer player = (ServerPlayer) context.getPlayer();
            CategoryIdentifier<Display> category = CategoryIdentifier.of(payload.category());
            AbstractContainerMenu container = player.containerMenu;
            InventoryMenu playerContainer = player.inventoryMenu;
            try {
                boolean shift = payload.shift();
                try {
                    CompoundTag nbt = payload.data();
                    int version = nbt.getInt("Version").orElse(-1);
                    if (version != 1) throw new IllegalStateException("Server and client REI protocol version mismatch! Server: 1, Client: " + version);
                    List<InputIngredient<ItemStack>> inputs = readInputs(context.registryAccess(), nbt.getListOrEmpty("Inputs"));
                    List<SlotAccessor> input = readSlots(container, player, nbt.getListOrEmpty("InputSlots"));
                    List<SlotAccessor> inventory = readSlots(container, player, nbt.getListOrEmpty("InventorySlots"));
                    NewInputSlotCrafter<AbstractContainerMenu, Container> crafter = new NewInputSlotCrafter<>(container, input, inventory, inputs);
                    crafter.fillInputSlots(player, shift);
                } catch (InputSlotCrafter.NotEnoughMaterialsException e) {
                    if (!(container instanceof RecipeBookMenu)) {
                        return;
                    }
                } catch (IllegalStateException e) {
                    player.sendSystemMessage(Component.translatable(e.getMessage()).withStyle(ChatFormatting.RED));
                } catch (Exception e) {
                    player.sendSystemMessage(Component.translatable("error.rei.internal.error", e.getMessage()).withStyle(ChatFormatting.RED));
                    e.printStackTrace();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });
        if (Platform.getEnvironment() == Env.SERVER) {
            NetworkManager.registerS2CPayloadType(REIPackets.CreateItemsMessage.TYPE, REIPackets.CreateItemsMessage.STREAM_CODEC);
            NetworkManager.registerS2CPayloadType(REIPackets.NotEnoughItems.TYPE, REIPackets.NotEnoughItems.STREAM_CODEC);
            NetworkManager.registerS2CPayloadType(DisplaySyncPacket.TYPE, DisplaySyncPacket.STREAM_CODEC, List.of(new SplitPacketTransformer()));
        }
    }

@Override
    public boolean tryCheatingEntry(EntryStack<?> stack) {
        if (stack.getType() != VanillaEntryTypes.ITEM)
            return false;
        EntryStack<ItemStack> entry = (EntryStack<ItemStack>) stack;
        if (Minecraft.getInstance().player == null) return false;
        if (Minecraft.getInstance().player.getInventory() == null) return false;
        ItemStack cheatedStack = entry.getValue().copy();
        if (ConfigObject.getInstance().isGrabbingItems() && Minecraft.getInstance().gui.screen() instanceof CreativeModeInventoryScreen) {
            AbstractContainerMenu menu = Minecraft.getInstance().player.containerMenu;
            EntryStack<ItemStack> copy = entry.copy();
            if (!menu.getCarried().isEmpty() && EntryStacks.equalsExact(EntryStacks.of(menu.getCarried()), copy)) {
                copy.getValue().setCount(Mth.clamp(copy.getValue().getCount() + menu.getCarried().getCount(), 1, copy.getValue().getMaxStackSize()));
            } else if (!menu.getCarried().isEmpty()) {
                return false;
            }
            menu.setCarried(copy.getValue().copy());
            return true;
        } else if (ClientHelperImpl.getInstance().canUsePackets()) {
            AbstractContainerMenu menu = Minecraft.getInstance().player.containerMenu;
            EntryStack<ItemStack> copy = entry.copy();
            if (!menu.getCarried().isEmpty() && !EntryStacks.equalsExact(EntryStacks.of(menu.getCarried()), copy)) {
                return false;
            }
            try {
                NetworkManager.sendToServer(ConfigObject.getInstance().isGrabbingItems() ? new REIPackets.CreateItemsGrab(cheatedStack) : new REIPackets.CreateItems(cheatedStack));
                return true;
            } catch (Exception exception) {
                return false;
            }
        } else {
            Identifier identifier = entry.getIdentifier();
            if (identifier == null) {
                return false;
            }
            String tagMessage = /* TODO 24w09a: cheatedStack.copy().getTag() != null && !cheatedStack.copy().getTag().isEmpty() ? cheatedStack.copy().getTag().getAsString() :*/ "";
            String og = cheatedStack.getCount() == 1 ? ConfigObject.getInstance().getGiveCommand().replaceAll(" \\{count}", "") : ConfigObject.getInstance().getGiveCommand();
            String madeUpCommand = og.replaceAll("\\{player_name}", Minecraft.getInstance().player.getScoreboardName()).replaceAll("\\{item_name}", identifier.getPath()).replaceAll("\\{item_identifier}", identifier.toString()).replaceAll("\\{nbt}", tagMessage).replaceAll("\\{count}", String.valueOf(cheatedStack.getCount()));
            if (madeUpCommand.length() > 256) {
                madeUpCommand = og.replaceAll("\\{player_name}", Minecraft.getInstance().player.getScoreboardName()).replaceAll("\\{item_name}", identifier.getPath()).replaceAll("\\{item_identifier}", identifier.toString()).replaceAll("\\{nbt}", "").replaceAll("\\{count}", String.valueOf(cheatedStack.getCount()));
                Minecraft.getInstance().player.sendSystemMessage(Component.translatable("text.rei.too_long_nbt"));
            }
            Minecraft.getInstance().player.connection.sendCommand(StringUtils.removeStart(madeUpCommand, "/"));
            return true;
        }
    }

