private static void renderTextScrolling(GuiGraphics graphics, FormattedCharSequence text, int x, int y, int width, int color) {
        try (CloseableScissors scissors = scissor(graphics, new Rectangle(x, y, width, y + 9))) {
            Font font = Minecraft.getInstance().font;
            int textWidth = font.width(text);
            textWidth = MatrixUtils.transform(MatrixUtils.inverse(graphics.pose()), new Rectangle(0, 0, textWidth, 100)).width;
            width = MatrixUtils.transform(MatrixUtils.inverse(graphics.pose()), new Rectangle(0, 0, width, 100)).width;
            if (textWidth > width && !ConfigUtils.isReducedMotion()) {
                graphics.pose().pushMatrix();
                float textX = (System.currentTimeMillis() % ((textWidth + 10) * textWidth / 3)) / (float) textWidth * 3;
                graphics.pose().translate(-textX, 0);
                graphics.drawString(font, text, x + width - textWidth - 10, y, color);
                graphics.drawString(font, text, x + width, y, color);
                graphics.pose().popMatrix();
            } else {
                graphics.drawString(font, text, x, y, color);
            }
        }
    }

public static WidgetWithBounds create(ConfigAccess access, OptionGroup entry, int width, boolean applyPreview) {
        WidgetWithBounds groupTitle = Widgets.createLabel(new Point(0, 3), TextTransformations.highlightText(entry.getGroupName().copy(), entry.getGroupNameHighlight(), style -> style.withColor(0xFFC0C0C0).withUnderlined(true)))
                .leftAligned()
                .withPadding(0, 0, 0, 6);
        WidgetWithBounds contents;

        if (applyPreview) {
            applyPreview = REIRuntime.getInstance().getPreviousContainerScreen() != null && Minecraft.getInstance().getConnection() != null;
        }

        if (applyPreview && SPECIAL_GROUPS.containsKey(entry.getId())) {
            Pair<PreviewLocation, SpecialGroupConstructor> pair = SPECIAL_GROUPS.get(entry.getId());
            PreviewLocation location = pair.getLeft();
            int halfWidth = width * 6 / 10 - 2;
            if (halfWidth <= 200 && location == PreviewLocation.RIGHT) location = PreviewLocation.TOP;

            if (location == PreviewLocation.RIGHT) {
                WidgetWithBounds original = _create(access, entry, halfWidth);
                Widget background = createBackgroundSlot(() -> new Rectangle(halfWidth + 2, 0, width - halfWidth - 4, original.getBounds().height));
                Widget right = Widgets.withTranslate(pair.getRight().create(access, entry, width - halfWidth - 4, () -> original.getBounds().height), halfWidth + 2, 0);
                contents = Widgets.concatWithBounds(() -> new Rectangle(0, 0, width, original.getBounds().height), original, background, right);
            } else {
                WidgetWithBounds original = _create(access, entry, width);

                WidgetWithBounds widget = pair.getRight().create(access, entry, width, null);
                Widget background = createBackgroundSlot(widget::getBounds);

                if (location == PreviewLocation.TOP) {
                    WidgetWithBounds translatedOriginal = Widgets.withTranslate(original, () -> new Matrix3x2f().translate(0, widget.getBounds().height + 4));
                    contents = Widgets.concatWithBounds(() -> new Rectangle(0, 0, width, widget.getBounds().height + 4 + translatedOriginal.getBounds().height), translatedOriginal, background, widget);
                } else {
                    contents = Widgets.concatWithBounds(() -> new Rectangle(0, 0, width, original.getBounds().getMaxY() + 2 + widget.getBounds().height), original,
                            Widgets.withTranslate(Widgets.concat(background, widget), () -> new Matrix3x2f().translate(0, original.getBounds().getMaxY() + 4)));
                }
            }
        } else {
            contents = _create(access, entry, width);
        }

        return Widgets.concatWithBounds(
                () -> new Rectangle(0, 0, width, groupTitle.getBounds().getMaxY() + contents.getBounds().height),
                groupTitle,
                Widgets.withTranslate(contents, () -> new Matrix3x2f().translate(0, groupTitle.getBounds().getMaxY()))
        );
    }

public static WidgetComposite of(WidgetWithBounds widget) {
            Matrix3x2f translation = new Matrix3x2f();
            return new WidgetComposite(Widgets.withTranslate(widget, translation),
                    () -> MatrixUtils.transform(translation, widget.getBounds()), translation);
        }

private static void recalculateHeight(List<WidgetComposite> widgets, IntConsumer setHeight) {
        int height = 0;
        for (WidgetComposite widget : widgets) {
            widget.translation().set(new Matrix3x2f().translate(0, height));
            height = Math.max(height, widget.bounds().get().getMaxY());
        }
        setHeight.accept(height);
    }

public static <T> WidgetWithBounds create(ConfigAccess access, CompositeOption<T> option, int width) {
        Font font = Minecraft.getInstance().font;
        Component[] text = {null};
        Consumer<Component> setText = t -> {
            if (access.getFocusedKeycode() == option) {
                text[0] = literal("> ").withStyle(ChatFormatting.YELLOW)
                        .append(t.copy().withStyle(ChatFormatting.YELLOW))
                        .append(literal(" <").withStyle(ChatFormatting.YELLOW));
            } else if (!(option.getEntry() instanceof OptionValueEntry.Configure<T>) && access.get(option).equals(Objects.requireNonNullElseGet(option.getDefaultValue(), () -> access.getDefault(option)))) {
                text[0] = translatable("config.rei.value.default", t);

                if (font.width(text[0]) > width) {
                    int trimTo = width - font.width("...") - (font.width(text[0]) - font.width(t));
                    FormattedText trimmed = font.substrByWidth(t, trimTo);
                    FormattedText composite = FormattedText.composite(trimmed, literal("..."));
                    text[0] = literal(composite.getString());
                    text[0] = translatable("config.rei.value.default", text[0]);
                }
            } else if (font.width(t) > width) {
                int trimTo = width - font.width("...");
                FormattedText trimmed = font.substrByWidth(t, trimTo);
                FormattedText composite = FormattedText.composite(trimmed, literal("..."));
                text[0] = literal(composite.getString());
            } else {
                text[0] = t;
            }
        };

        setText.accept(option.getEntry().getOption(access.get(option)));

        Label label = Widgets.createLabel(new Point(), text[0]).rightAligned()
                .color(0xFFE0E0E0)
                .hoveredColor(0xFFE0E0E0)
                .onRender((poses, l) -> {
                    if (MatrixUtils.transform(poses.pose(), l.getBounds()).contains(PointHelper.ofMouse())) {
                        l.setMessage(text[0].copy().withStyle(ChatFormatting.UNDERLINE));
                    } else {
                        l.setMessage(text[0]);
                    }
                });

        if (option.getEntry() instanceof OptionValueEntry.Selection<T> selection) {
            applySelection(access, option, selection, label, setText);
        } else if (access.get(option) instanceof ModifierKeyCode) {
            applyKeycode(access, option, label, setText);
        } else if (option.getEntry() instanceof OptionValueEntry.Configure<T>) {
            label.clickable().onClick($ -> {
                ((OptionValueEntry.Configure<T>) option.getEntry()).configure(access, option, () -> {
                    Minecraft.getInstance().setScreenAndShow((Screen) access);
                    setText.accept(option.getEntry().getOption(access.get(option)));
                });
            });
        }

        return Widgets.concatWithBounds(() -> new Rectangle(-label.getBounds().width, 0, label.getBounds().width + 8, 14),
                label,
                Widgets.withTranslate(Widgets.createTexturedWidget(Identifier.parse("roughlyenoughitems:textures/gui/config/selector.png"),
                        new Rectangle(1, 1, 4, 6), 0, 0, 1, 1, 1, 1), 0, 0.5)
        );
    }

private static <T> void applySelection(ConfigAccess access, CompositeOption<T> option, OptionValueEntry.Selection<T> selection, Label label, Consumer<Component> setText) {
        Rectangle bounds = new Rectangle();
        BiConsumer<GuiGraphics, Label> render = label.getOnRender();
        label.onRender((poses, $) -> {
            render.accept(poses, $);
            bounds.setBounds(MatrixUtils.transform(poses.pose(), label.getBounds()));
        });
        int noOfOptions = selection.getOptions().size();
        if (noOfOptions == 2) {
            label.clickable().onClick($ -> {
                access.set(option, selection.getOptions().get((selection.getOptions().indexOf(access.get(option)) + 1) % 2));
                setText.accept(selection.getOption(access.get(option)));
            });
        } else if (noOfOptions >= 2) {
            label.clickable().onClick($ -> {
                Menu menu = new Menu(bounds, CollectionUtils.map(selection.getOptions(), opt -> {
                    Component selectionOption = selection.getOption(opt);
                    if (opt.equals(access.getDefault(option))) {
                        selectionOption = translatable("config.rei.value.default", selectionOption);
                    }

                    return ToggleMenuEntry.of(selectionOption, () -> false, o -> {
                        ((REIConfigScreen) Minecraft.getInstance().gui.screen()).closeMenu();
                        access.set(option, opt);
                        setText.accept(selection.getOption(opt));
                    });
                }), false);
                access.closeMenu();
                access.openMenu(menu);
            });
        }
    }

private static <T> void applyKeycode(ConfigAccess access, CompositeOption<T> option, Label label, Consumer<Component> setText) {
        label.clickable().onClick($ -> {
            access.closeMenu();
            access.focusKeycode((CompositeOption<ModifierKeyCode>) option);
        });
        BiConsumer<GuiGraphics, Label> render = label.getOnRender();
        label.onRender((poses, $) -> {
            render.accept(poses, $);
            setText.accept(((ModifierKeyCode) access.get(option)).getLocalizedName());
        });
    }

public static <T> WidgetWithBounds create(ConfigAccess access, CompositeOption<T> option, int width) {
        List<Widget> widgets = new ArrayList<>();
        int[] stableHeight = {12};
        int[] height = {12};
        Label fieldNameLabel;
        widgets.add(fieldNameLabel = Widgets.createLabel(new Point(0, 0), TextTransformations.highlightText(option.getName().copy(), option.getOptionNameHighlight(), style -> style.withColor(0xFFC0C0C0)))
                .leftAligned()
                .rainbow(Objects.equals(option.getId(), AllREIConfigOptions.RAINBOW.getId())));
        WidgetWithBounds optionValue = ConfigOptionValueWidget.create(access, option, width - 10 - fieldNameLabel.getBounds().width);
        widgets.add(Widgets.withTranslate(optionValue, () -> new Matrix3x2f().translate(width - optionValue.getBounds().width - optionValue.getBounds().x, 0)));
        widgets.add(new WidgetWithBounds() {
            final MutableComponent description = Util.make(() -> {
                MutableComponent description = option.getDescription().copy();
                if (description.getString().endsWith(".desc")) {
                    return literal("");
                } else {
                    return TextTransformations.highlightText(description, option.getOptionDescriptionHighlight(), style -> style.withColor(0xFF757575));
                }
            });

            final List<FormattedCharSequence> split = Minecraft.getInstance().font.split(description, width);
            final boolean hasPreview = option.hasPreview();
            final Label previewLabel = Widgets.createLabel(new Point(), translatable("config.rei.texts.preview"))
                    .color(0xFFA5F4FF)
                    .hoveredColor(0xFFD1FAFF)
                    .noShadow()
                    .clickable()
                    .onClick($ -> clickPreview())
                    .rightAligned();
            @Nullable
            WidgetWithBounds preview = null;
            boolean previewVisible = false;
            Matrix3x2f previewTranslation = new Matrix3x2f();
            final NumberAnimator<Float> previewHeight = ValueAnimator.ofFloat()
                    .withConvention(() -> previewVisible ? preview.getBounds().getHeight() : 0f, ValueAnimator.typicalTransitionTime());
            boolean nextLinePreview = false;

            {
                stableHeight[0] += 12 * split.size();
                if (hasPreview) {
                    int lastWidth = Minecraft.getInstance().font.width(split.get(split.size() - 1));
                    if (lastWidth + this.previewLabel.getBounds().width + 10 > width) {
                        nextLinePreview = true;
                        stableHeight[0] += 12;
                    }
                }
            }

            @Override
            public Rectangle getBounds() {
                return new Rectangle(0, 12, width, 12 + 12 * split.size());
            }

            @Override
            public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
                this.previewHeight.update(delta);
                if (ConfigUtils.isReducedMotion()) this.previewHeight.completeImmediately();
                height[0] = stableHeight[0] + Math.round(this.previewHeight.value());

                for (int i = 0; i < split.size(); i++) {
                    graphics.drawString(Minecraft.getInstance().font, split.get(i), 0, 12 + 12 * i, -1, false);
                }

                if (hasPreview) {
                    if (nextLinePreview) {
                        this.previewLabel.setPoint(new Point(width, 12 + 12 * split.size()));
                    } else {
                        this.previewLabel.setPoint(new Point(width, 12 + 12 * split.size() - 12));
                    }

                    this.previewLabel.render(graphics, mouseX, mouseY, delta);

                    if (this.preview != null && this.previewHeight.value() > 0.1f) {
                        Rectangle rectangle = new Rectangle(0, 24 + 12 * split.size() - (nextLinePreview ? 0 : 12), width, this.previewHeight.value());
                        graphics.enableScissor(rectangle.x, rectangle.y, rectangle.getMaxX(), rectangle.getMaxY());
                        this.previewTranslation = new Matrix3x2f().translate(0, 12 + 12 * split.size());
                        this.preview.render(graphics, mouseX, mouseY, delta);
                        graphics.disableScissor();
                    }
                }
            }

            private void clickPreview() {
                if (this.preview == null) {
                    this.preview = option.getPreviewer().preview(width, () -> access.get(option));
                    this.preview = Widgets.withTranslate(this.preview, () -> this.previewTranslation);
                }

                this.previewVisible = !this.previewVisible;
            }

            @Override
            public List<? extends GuiEventListener> children() {
                if (this.preview != null && this.previewHeight.value() > 0.1f) return List.of(this.previewLabel, this.preview);
                return List.of(this.previewLabel);
            }
        });

        height[0] = stableHeight[0];
        return Widgets.concatWithBounds(() -> new Rectangle(0, 0, width, height[0]), widgets);
    }

