public static AutoCraftingResult evaluateAutoCrafting(boolean actuallyCrafting, boolean stackedCrafting, Display display, Supplier<Collection<Identifier>> idsSupplier) {
        AbstractContainerScreen<?> containerScreen = REIRuntime.getInstance().getPreviousContainerScreen();
        AutoCraftingResult result = new AutoCraftingResult();
        final List<Tooltip.Entry> errorTooltip = new ArrayList<>();
        result.tooltipRenderer = (pos, sink) -> {
            List<Tooltip.Entry> str = new ArrayList<>(errorTooltip);

            if (ConfigObject.getInstance().isFavoritesEnabled()) {
                str.add(Tooltip.entry(Component.literal(" ")));
                str.add(Tooltip.entry(Component.translatable("text.rei.save.recipes", Component.literal(ConfigObject.getInstance().getFavoriteKeyCode().getLocalizedName().getString().toUpperCase(Locale.ROOT)).withStyle(ChatFormatting.BOLD)).withStyle(ChatFormatting.GRAY)));
            }

            if (Minecraft.getInstance().options.advancedItemTooltips && idsSupplier != null) {
                Collection<Identifier> locations = idsSupplier.get();
                if (!locations.isEmpty()) {
                    str.add(Tooltip.entry(Component.literal(" ")));
                    for (Identifier location : locations) {
                        String t = I18n.get("text.rei.recipe_id", "", location.toString());
                        if (t.startsWith("\n")) {
                            t = t.substring("\n".length());
                        }
                        str.add(Tooltip.entry(Component.literal(t).withStyle(ChatFormatting.GRAY)));
                    }
                }
            }

            sink.accept(Tooltip.from(pos, str));
        };

        if (containerScreen == null) {
            errorTooltip.add(Tooltip.entry(Component.translatable("error.rei.not.supported.move.items").withStyle(ChatFormatting.RED)));
            return result;
        }

        List<TransferHandler.Result> errors = new ArrayList<>();
        TransferHandler.Result successfulResult = null;
        TransferHandler.Context context = TransferHandler.Context.create(actuallyCrafting, stackedCrafting, containerScreen, display);

        for (TransferHandler transferHandler : TransferHandlerRegistry.getInstance()) {
            try {
                TransferHandler.ApplicabilityResult applicabilityResult = transferHandler.checkApplicable(context);
                if (!applicabilityResult.isApplicable()) continue;
                TransferHandler.Result transferResult;

                if (applicabilityResult.isSuccessful()) {
                    transferResult = transferHandler.handle(context);
                } else {
                    transferResult = applicabilityResult.getError();
                }

                if (transferResult.isBlocking() && actuallyCrafting) {
                    if (transferResult.isReturningToScreen()) {
                        Minecraft.getInstance().setScreenAndShow(containerScreen);
                        REIRuntime.getInstance().getOverlay().ifPresent(ScreenOverlay::queueReloadOverlay);
                    }

                    break;
                }

                if (transferResult.isApplicable()) {
                    result.hasApplicable = true;
                    result.tint = transferResult.getColor();

                    TransferHandlerRenderer transferHandlerRenderer = transferResult.getRenderer(transferHandler, context);
                    if (transferHandlerRenderer != null) {
                        result.renderer = transferHandlerRenderer;
                    }

                    if (transferResult.getTooltipRenderer() != null) {
                        BiConsumer<Point, TransferHandler.Result.TooltipSink> tooltipRenderer = transferResult.getTooltipRenderer();
                        result.tooltipRenderer = (point, tooltipConsumer) -> tooltipRenderer.accept(point, tooltipConsumer::accept);
                    }

                    if (transferResult.isSuccessful()) {
                        errors.clear();
                        successfulResult = transferResult;
                        result.successful = true;
                        result.successfulHandler = transferHandler;
                        break;
                    }

                    errors.add(transferResult);

                    if (transferResult.isBlocking()) {
                        break;
                    }
                }
            } catch (Throwable e) {
                e.printStackTrace();
            }
        }

        if (!result.hasApplicable) {
            errorTooltip.clear();
            errorTooltip.add(Tooltip.entry(Component.translatable("error.rei.not.supported.move.items").withStyle(ChatFormatting.RED)));
            return result;
        }

        if (errors.isEmpty()) {
            errorTooltip.clear();
            errorTooltip.add(Tooltip.entry(Component.translatable("text.auto_craft.move_items")));

            if (successfulResult != null) {
                successfulResult.fillTooltip(errorTooltip);
            }
        } else {
            errorTooltip.clear();
            List<Tooltip.Entry> tooltipsFilled = new ArrayList<>();
            for (TransferHandler.Result error : errors) {
                error.fillTooltip(tooltipsFilled);
            }

            if (errors.size() == 1) {
                for (Tooltip.Entry tooltipFilled : tooltipsFilled) {
                    if (tooltipFilled.isText()) {
                        MutableComponent colored = tooltipFilled.getAsText().copy().withStyle(ChatFormatting.RED);
                        if (!CollectionUtils.anyMatch(errorTooltip, ss -> ss.isText() && ss.getAsText().getString().equalsIgnoreCase(colored.getString()))) {
                            errorTooltip.add(Tooltip.entry(colored));
                        }
                    } else {
                        errorTooltip.add(tooltipFilled);
                    }
                }
            } else {
                errorTooltip.add(Tooltip.entry(Component.translatable("error.rei.multi.errors").withStyle(ChatFormatting.RED)));
                for (Tooltip.Entry tooltipFilled : tooltipsFilled) {
                    if (tooltipFilled.isText()) {
                        MutableComponent colored = Component.literal("- ").withStyle(ChatFormatting.RED)
                                .append(tooltipFilled.getAsText().copy().withStyle(ChatFormatting.RED));
                        if (!CollectionUtils.anyMatch(errorTooltip, ss -> ss.isText() && ss.getAsText().getString().equalsIgnoreCase(colored.getString()))) {
                            errorTooltip.add(Tooltip.entry(colored));
                        }
                    } else {
                        errorTooltip.add(tooltipFilled);
                    }
                }
            }
        }

        return result;
    }

public static void handleThrowable(Throwable throwable, String task) {
        CrashReport report = CrashReportUtils.essential(throwable, task);
        File reportsFolder = new File(Minecraft.getInstance().gameDirectory, "crash-reports");
        SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd_HH.mm.ss");
        File crashReportFile = new File(reportsFolder, "crash-" + format.format(new Date()) + "-client.txt");
        report.saveToFile(crashReportFile.toPath(), ReportType.CRASH);
        Bootstrap.realStdoutPrintln(report.getFriendlyReport(ReportType.CRASH));
        List<Object> components = new ArrayList<>();
        components.add(Component.literal(I18n.get("text.rei.crash.description", report.getTitle())));
        components.add((Function<Integer, ErrorsEntryListWidget.Entry>) width -> new ErrorsEntryListWidget.LinkEntry(Component.translatable("text.rei.crash.crash_report"), crashReportFile.toURI().toString(), width));
        components.add(Component.empty());
        components.add(Component.literal(report.getFriendlyReport(ReportType.CRASH).replace("\t", "    ")));
        Minecraft.getInstance().setScreenAndShow(new ErrorsScreen(Component.translatable("text.rei.crash.title"), components, null, false));
    }

