public void render(GuiGraphics graphics, Iterable<EntryListStackEntry> entries, Object2IntMap<CollapsedStack> collapsedStackIndicesGlobal) {
        if (collapsedStackIndicesGlobal.isEmpty()) return;
        LongSet edgeSet = new LongOpenHashSet();
        int entrySize = entrySize();
        // bit 0-1: direction
        // bit 2 occupied: has edge
        // bit 3-14: collapsed stack index
        // bit 15-30: y
        // bit 31-46: x
        for (EntryListStackEntry entry : entries) {
            if (entry.getCollapsedStack() != null && entry.getCollapsedStack().isExpanded()) {
                Rectangle entryBounds = entry.getBounds();
                int collapsedStackIndices = collapsedStackIndicesGlobal.getInt(entry.getCollapsedStack());
                long base = getPackedLong(entryBounds.getCenterX() + 100, entryBounds.getCenterY() + 100, collapsedStackIndices, 0, false);
                if (!edgeSet.add(base | TOP)) edgeSet.add(base | TOP_O);
                if (!edgeSet.add(base | BOTTOM)) edgeSet.add(base | BOTTOM_O);
                if (!edgeSet.add(base | LEFT)) edgeSet.add(base | LEFT_O);
                if (!edgeSet.add(base | RIGHT)) edgeSet.add(base | RIGHT_O);
                // to left (base - ((long) entrySize << 31)) | RIGHT)
                long nL = withDirD(shiftLongX(base, -entrySize), RIGHT, false);
                if (edgeSet.contains(nL)) {
                    edgeSet.add(occupiedLong(nL));
                    edgeSet.add(base | LEFT_O);
                }
                // to right
                nL = withDirD(shiftLongX(base, entrySize), LEFT, false);
                if (edgeSet.contains(nL)) {
                    edgeSet.add(occupiedLong(nL));
                    edgeSet.add(base | RIGHT_O);
                }
                // to top
                nL = withDirD(shiftLongY(base, -entrySize), BOTTOM, false);
                if (edgeSet.contains(nL)) {
                    edgeSet.add(occupiedLong(nL));
                    edgeSet.add(base | TOP_O);
                }
                // to bottom
                nL = withDirD(shiftLongY(base, entrySize), TOP, false);
                if (edgeSet.contains(nL)) {
                    edgeSet.add(occupiedLong(nL));
                    edgeSet.add(base | BOTTOM_O);
                }
            }
        }

        LongIterator iterator = edgeSet.iterator();
        LongList toRemove = new LongArrayList();
        while (iterator.hasNext()) {
            long l = iterator.nextLong();
            if ((l & 0b100) != 0) {
                toRemove.add(l);
                toRemove.add(l & ~0b100);
            }
        }
        edgeSet.removeAll(toRemove);

        graphics.pose().pushMatrix();
        graphics.pose().translate(-100, -100);

        iterator = edgeSet.iterator();
        while (iterator.hasNext()) {
            long l = iterator.nextLong();
            int x = (int) (l >> 31);
            int y = (int) ((l >> 15) & 0xFFFF);
            int collapsedStackIndices = (int) ((l >> 3) & 0b111111111111);
            int x1 = x - entrySize / 2;
            int y1 = y - entrySize / 2;
            int x2 = x1 + entrySize;
            int y2 = y1 + entrySize;
            int direction = (int) (l & RIGHT);
            switch (direction) {
                case 0 -> { // top
                    int fStart = edgeSet.contains(shiftLongX(l, -entrySize)) || edgeSet.contains(withDirD(l, LEFT, false)) ? 0 : 1;
                    int fEnd = edgeSet.contains(shiftLongX(l, entrySize)) || edgeSet.contains(withDirD(l, RIGHT, false)) ? 0 : 1;
                    if (fStart == 1 && edgeSet.contains(getPackedLong(x - entrySize, y - entrySize, collapsedStackIndices, RIGHT, false))) fStart = -1;
                    if (fEnd == 1 && edgeSet.contains(getPackedLong(x + entrySize, y - entrySize, collapsedStackIndices, LEFT, false))) fEnd = -1;
                    graphics.fillGradient(x1 + fStart, y1, x2 - fEnd, y1 + 1, 0x67FFFFFF, 0x67FFFFFF);
                }
                case 1 -> { // bottom
                    int fStart = edgeSet.contains(shiftLongX(l, -entrySize)) || edgeSet.contains(withDirD(l, LEFT, false)) ? 0 : 1;
                    int fEnd = edgeSet.contains(shiftLongX(l, entrySize)) || edgeSet.contains(withDirD(l, RIGHT, false)) ? 0 : 1;
                    if (fStart == 1 && edgeSet.contains(getPackedLong(x - entrySize, y + entrySize, collapsedStackIndices, RIGHT, false))) fStart = -1;
                    if (fEnd == 1 && edgeSet.contains(getPackedLong(x + entrySize, y + entrySize, collapsedStackIndices, LEFT, false))) fEnd = -1;
                    graphics.fillGradient(x1 + fStart, y2 - 1, x2 - fEnd, y2, 0x67FFFFFF, 0x67FFFFFF);
                }
                case 2 -> { // left
                    int fStart = edgeSet.contains(shiftLongY(l, -entrySize)) ? 0 : 1;
                    int fEnd = edgeSet.contains(shiftLongY(l, entrySize)) ? 0 : 1;
                    if (fStart == 1 && edgeSet.contains(getPackedLong(x - entrySize, y - entrySize, collapsedStackIndices, BOTTOM, false))) fStart = 0;
                    if (fEnd == 1 && edgeSet.contains(getPackedLong(x - entrySize, y + entrySize, collapsedStackIndices, TOP, false))) fEnd = 0;
                    graphics.fillGradient(x1, y1 + fStart, x1 + 1, y2 - fEnd, 0x67FFFFFF, 0x67FFFFFF);
                }
                case 3 -> { // right
                    int fStart = edgeSet.contains(shiftLongY(l, -entrySize)) ? 0 : 1;
                    int fEnd = edgeSet.contains(shiftLongY(l, entrySize)) ? 0 : 1;
                    if (fStart == 1 && edgeSet.contains(getPackedLong(x + entrySize, y - entrySize, collapsedStackIndices, BOTTOM, false))) fStart = 0;
                    if (fEnd == 1 && edgeSet.contains(getPackedLong(x + entrySize, y + entrySize, collapsedStackIndices, TOP, false))) fEnd = 0;
                    graphics.fillGradient(x2 - 1, y1 + fStart, x2, y2 - fEnd, 0x67FFFFFF, 0x67FFFFFF);
                }
            }
        }

        graphics.pose().popMatrix();
    }

@Override
    public void extractImage(Font font, int x, int y, int weight, int height, GuiGraphicsExtractor graphics) {
        GuiGraphics guiGraphics = GuiGraphics.of(graphics);
        int entrySize = EntryListWidget.entrySize();
        int w = Math.max(1, MAX_WIDTH / entrySize);
        int i = 0;
        for (EntryStack<?> entry : stack.getIngredient()) {
            int x1 = x + (i % w) * entrySize;
            int y1 = y + (i / w) * entrySize;
            i++;
            if (i / w > 3 - 1) {
                Component text = Component.literal("+" + (stack.getIngredient().size() - w * 3 + 1)).withStyle(ChatFormatting.GRAY);
                guiGraphics.pose().pushMatrix();
                guiGraphics.pose().translate(x1 + entrySize / 2 - font.width(text) / 2, y1 + entrySize / 2 - 1);
                guiGraphics.drawString(font, text, 0, 0, -1);
                guiGraphics.pose().popMatrix();
                break;
            } else {
                entry.render(guiGraphics, new Rectangle(x1, y1, entrySize, entrySize), -1000, -1000, 0);
            }
        }
    }

@Override
    @Nullable
    public Tooltip getCurrentTooltip(TooltipContext context) {
        if (this.collapsedStack != null) {
            if (!this.collapsedStack.isExpanded()) {
                Tooltip tooltip = Tooltip.create(context.getPoint(), Component.translatable("text.rei.collapsed.entry", collapsedStack.getName()));
                tooltip.add(new CollapsedEntriesTooltip(collapsedStack));
                tooltip.add(Component.translatable(Util.getPlatform() == Util.OS.OSX ? "text.rei.collapsed.entry.hint.expand.macos" : "text.rei.collapsed.entry.hint.expand", collapsedStack.getName(), collapsedStack.getIngredient().size())
                        .withStyle(ChatFormatting.GRAY, ChatFormatting.ITALIC));
                ClientHelper.getInstance().appendModIdToTooltips(tooltip, collapsedStack.getModId());
                return tooltip;
            }
        }

        Tooltip tooltip = super.getCurrentTooltip(context);
        if (tooltip != null && this.collapsedStack != null) {
            tooltip.entries().add(Mth.clamp(tooltip.entries().size() - 1, 0, tooltip.entries().size() - 1), Tooltip.entry(Component.translatable(Util.getPlatform() == Util.OS.OSX ? "text.rei.collapsed.entry.hint.collapse.macos" : "text.rei.collapsed.entry.hint.collapse", collapsedStack.getName(), collapsedStack.getIngredient().size())
                    .withStyle(ChatFormatting.GRAY, ChatFormatting.ITALIC)));
        }
        return tooltip;
    }

@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        if (!hasSpace()) return;

        renderEntries(graphics, mouseX, mouseY, delta);

        debugger.render(graphics, bounds.x, bounds.y, delta);

        if (containsChecked(mouseX, mouseY, false) && ClientHelper.getInstance().isCheating() && !(Minecraft.getInstance().gui.screen() instanceof DisplayScreen) && !minecraft.player.containerMenu.getCarried().isEmpty() && ClientHelperImpl.getInstance().canDeleteItems()) {
            EntryStack<?> stack = EntryStacks.of(minecraft.player.containerMenu.getCarried().copy());
            if (stack.getType() != VanillaEntryTypes.ITEM) {
                EntryStack<ItemStack> cheatsAs = stack.cheatsAs();
                stack = cheatsAs.isEmpty() ? stack : cheatsAs;
            }
            for (Widget child : children()) {
                if (child.containsMouse(mouseX, mouseY) && child instanceof EntryWidget widget) {
                    if (widget.cancelDeleteItems(stack)) {
                        return;
                    }
                }
            }
            Tooltip.create(Component.translatable("text.rei.delete_items")).queue();
        }

        scaleIndicator.update(delta);
        if (scaleIndicator.value() > 0.04) {
            Component component = Component.literal(Math.round(ConfigObject.getInstance().getEntrySize() * 100) + "%");
            int width = font.width(component);
            int backgroundColor = ((int) Math.round(0xa0 * Mth.clamp(scaleIndicator.value(), 0.0, 1.0))) << 24;
            int textColor = ((int) Math.round(0xdd * Mth.clamp(scaleIndicator.value(), 0.0, 1.0))) << 24;
            graphics.fillGradient(bounds.getCenterX() - width / 2 - 2, bounds.getCenterY() - 6, bounds.getCenterX() + width / 2 + 2, bounds.getCenterY() + 6, backgroundColor, backgroundColor);
            graphics.drawString(font, component, bounds.getCenterX() - width / 2, bounds.getCenterY() - 4, 0xFFFFFF | textColor, false);
        }
    }

