@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        boolean stable = isStable();
        this.bounds.update(delta);
        FloatingRectangle target = this.bounds.target();
        FloatingRectangle bounds = this.bounds.value();

        if (!reachedStable && Math.abs(bounds.x - target.x) <= 0.5 && Math.abs(bounds.y - target.y) <= 0.5 && Math.abs(bounds.width - target.width) <= 0.5 && Math.abs(bounds.height - target.height) <= 0.5) {
            reachedStable = true;
        }

        if (stable && (bounds.getMaxX() + xOffset < parent.getBounds().x || bounds.x + xOffset > parent.getBounds().getMaxX())) {
            return;
        }

        graphics.pose().pushMatrix();
        graphics.pose().translate(xOffset(), yOffset());
        graphics.pose().scale(xScale(), yScale());

        for (Widget widget : widgets.get()) {
            widget.render(graphics, transformMouseX(mouseX), transformMouseY(mouseY), delta);
        }
        graphics.pose().popMatrix();

        {
            graphics.pose().pushMatrix();
            if (stable && target.equals(bounds)) {
                graphics.pose().translate((float) this.xOffset, 0);
            }
            Vector3f mouse = new Vector3f((float) mouseX, (float) mouseY, 1);
            graphics.pose().transform(mouse);

            AutoCraftingEvaluator.AutoCraftingResult result = this.autoCraftingResult.get();

            plusButton.setEnabled(result.successful);
            plusButton.setTint(result.tint);
            plusButton.getBounds().setBounds(new Rectangle(bounds.getMaxX() - 14, bounds.getMaxY() - 14, 10, 10));

            if (result.hasApplicable) {
                plusButton.setText(Component.literal("+"));
                plusButton.render(graphics, Math.round(mouse.x()), Math.round(mouse.y()), delta);
                graphics.pose().popMatrix();

                if (plusButton.containsMouse(Math.round(mouse.x()), Math.round(mouse.y()))) {
                    result.tooltipRenderer.accept(new Point(mouseX, mouseY), Tooltip::queue);
                }

                if (result.renderer != null) {
                    graphics.pose().pushMatrix();
                    graphics.pose().translate(xOffset(), yOffset());
                    graphics.pose().scale(xScale(), yScale());

                    Rectangle transformedBounds = MatrixUtils.transform(MatrixUtils.inverse(graphics.pose()), getBounds());
                    result.renderer.render(graphics, mouseX, mouseY, delta, widgets.get(), transformedBounds, display);
                    graphics.pose().popMatrix();
                }
            } else {
                graphics.pose().popMatrix();
            }
        }
    }

private void drawHorizontalDashedLine(GuiGraphics graphics, int x1, int x2, int y, int color, boolean reverse) {
        float[] offset = {(System.currentTimeMillis() % 700) / 100.0F};
        if (ConfigObject.getInstance().isReducedMotion()) offset[0] = 0;
        if (!reverse) offset[0] = 7 - offset[0];

        for (float x = x1 - offset[0]; x < x2; x += 7) {
            graphics.pose().pushMatrix();
            graphics.pose().translate(Mth.clamp(x, x1, x2), 0);
            graphics.fillGradient(0, y, 4, y + 1, color, color);
            graphics.pose().popMatrix();
        }
    }

private void drawVerticalDashedLine(GuiGraphics graphics, int x, int y1, int y2, int color, boolean reverse) {
        float[] offset = {(System.currentTimeMillis() % 700) / 100.0F};
        if (ConfigObject.getInstance().isReducedMotion()) offset[0] = 0;
        if (!reverse) offset[0] = 7 - offset[0];

        for (float y = y1 - offset[0]; y < y2; y += 7) {
            graphics.pose().pushMatrix();
            graphics.pose().translate(0, Mth.clamp(y, y1, y2));
            graphics.fillGradient(x, 0, x + 1, 4, color, color);
            graphics.pose().popMatrix();
        }
    }

