@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        if (updateBounds(delta)) {
            float opacity = (Mth.cos((float) (System.currentTimeMillis() % 2000 / 1000F * Math.PI)) + 1) / 2;
            if (ConfigObject.getInstance().isReducedMotion()) opacity = 0.75F;
            int alpha = 0x12 + (int) (0x22 * lastProgress * opacity);
            graphics.fillGradient(this.bounds.x, this.bounds.y, this.bounds.getMaxX(), this.bounds.getMaxY(), 0xFFFFFF | (alpha << 24), 0xFFFFFF | (alpha << 24));
            int lineColor = (int) (0x60 * lastProgress) << 24 | 0xFFFFFF;
            graphics.fillGradient(this.bounds.x, this.bounds.y, this.bounds.getMaxX(), this.bounds.y + 1, lineColor, lineColor);
            graphics.fillGradient(this.bounds.x, this.bounds.getMaxY() - 1, this.bounds.getMaxX(), this.bounds.getMaxY(), lineColor, lineColor);

            graphics.fillGradient(this.bounds.x, this.bounds.y + 1, this.bounds.x + 1, this.bounds.getMaxY() - 1, lineColor, lineColor);
            graphics.fillGradient(this.bounds.getMaxX() - 1, this.bounds.y + 1, this.bounds.getMaxX(), this.bounds.getMaxY() - 1, lineColor, lineColor);

            Component text = Component.translatable("text.rei.dispose_here");
            if (0xAA * lastProgress > 0x4) {
                graphics.drawString(font, text, this.bounds.getCenterX() - font.width(text) / 2, this.bounds.getCenterY() - 4, (int) (0xAA * lastProgress) << 24 | 0xFFFFFF, false);
            }
        }
    }

@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        this.scroll.setTarget(ScrollingContainer.handleBounceBack(scroll.target(), this.contentHeight - (this.bounds.height - 8 - 9) - 9, delta, .08));
        this.scroll.update(delta);

        int background = 0xf0100010;
        int color1 = 0x505000ff;
        int color2 = color1;
        int x = this.bounds.x, y = this.bounds.y, width = this.bounds.width, height = this.bounds.height;
        graphics.fillGradient(x, y - 1, x + width, y, background, background);
        graphics.fillGradient(x, y + height, x + width, y + height + 1, background, background);
        graphics.fillGradient(x, y, x + width, y + height, background, background);
        graphics.fillGradient(x - 1, y, x, y + height, background, background);
        graphics.fillGradient(x + width, y, x + width + 1, y + height, background, background);
        graphics.fillGradient(x, y + 1, x + 1, y + height - 1, color1, color2);
        graphics.fillGradient(x + width - 1, y + 1, x + width, y + height - 1, color1, color2);
        graphics.fillGradient(x, y, x + width, y + 1, color1, color1);
        graphics.fillGradient(x, y + height - 1, x + width, y + height, color2, color2);
        int lineY = y + 4;

        try (CloseableScissors scissors = Widget.scissor(graphics, new Rectangle(x + 4, y + 4, width - 8, height - 8 - 9 - 2))) {
            for (List<FormattedCharSequence> block : wrapped) {
                for (FormattedCharSequence line : block) {
                    graphics.drawString(font, line, x + 4, lineY - scroll.intValue(), 0xFFFFFFFF);
                    lineY += 9;
                }

                lineY += 2;
            }
        }

        MutableComponent okay = Component.translatable("gui.ok");
        int okayWidth = font.width(okay);
        int midPoint = x + 4 + (width - 4) / 2;
        this.okayBounds.setBounds(midPoint - okayWidth / 2, lineY, okayWidth, 9);
        if (this.okayBounds.contains(mouseX, mouseY)) {
            okay = okay.withStyle(ChatFormatting.UNDERLINE);
        }
        graphics.drawString(font, okay, this.okayBounds.x, this.okayBounds.y, 0xFF999999);

        if (this.bounds.contains(mouseX, mouseY)) {
            ScreenOverlayImpl.getInstance().clearTooltips();
        }
    }

