@Override
    public List<Component> provide() {
        List<ReloadStage> stages = Arrays.asList(ReloadStage.values());
        Set<ReloadStage> notVisited = notVisited();
        int allManagers = PluginManager.getActiveInstances().size();
        DoubleIntPair[] progresses = new DoubleIntPair[allManagers];
        Triple<PluginManager<?>, ReloadStage, Reloadable<?>> current = null;
        int i = 0;

        for (PluginManager<? extends REIPlugin<?>> manager : PluginManager.getActiveInstances()) {
            PluginManagerData data = allStages.get(manager);
            int index = i++;

            if (data == null) {
                progresses[index] = DoubleIntPair.of(0, 0);
                continue;
            }

            boolean allDone = data.finishedStages.size() == stages.size();
            if (allDone) {
                progresses[index] = DoubleIntPair.of(stages.size(), stages.size());
            } else {
                DoubleIntMutablePair pair = new DoubleIntMutablePair(0, 0);
                for (ReloadStage stage : stages) {
                    List<Reloadable<?>> reloadables = data.beganStages.get(stage);
                    pair.right(pair.rightInt() + 1);

                    if (reloadables == null) {
                        continue;
                    }

                    boolean finished = data.finishedStages.contains(stage);

                    if (finished) {
                        pair.left(pair.leftDouble() + 1);
                    } else {
                        pair.left(pair.leftDouble() + (reloadables.size() / (double) manager.getReloadables().size()));

                        if (!reloadables.isEmpty()) {
                            Reloadable<?> currentReloadable = Iterables.getLast(reloadables);
                            current = Triple.of(manager, stage, currentReloadable);
                        }
                    }
                }
                for (Map.Entry<ReloadStage, List<Reloadable<?>>> stageSetEntry : data.beganStages.entrySet()) {
                    ReloadStage stage = stageSetEntry.getKey();

                }
                progresses[index] = pair;
            }
        }

        if (notVisited.isEmpty()) {
            lastProgress = null;
            return Collections.emptyList();
        } else {
            double total = 0;
            int j = 0;
            for (DoubleIntPair pair : progresses) {
                total += pair == null || pair.rightInt() == 0 ? 0 : pair.leftDouble() / pair.rightInt();
            }
            double average = total / progresses.length;
            lastProgress = average;
            String progress;
            String currentTask;
            if (current != null) {
                int managerIndex = PluginManager.getActiveInstances().indexOf(current.getLeft());
                lastStep = managerIndex + 1 + current.getMiddle().ordinal() * allManagers;
            }
            progress = String.format("Step %d/%d (%s%%):", lastStep, allManagers * stages.size(), Math.round(average * 100));
            if (current == null) {
                currentTask = "Waiting";
            } else {
                currentTask = getSimpleName(current.getRight().getClass());
            }
            return ImmutableList.of(Component.translatable("text.rei.not.fully.initialized"),
                    Component.literal(progress), Component.literal(currentTask));
        }
    }

@Override
    public List<Component> provide() {
        lastProcess = null;
        try {
            ArgumentCache cache = Argument.cache;
            if (cache.currentStep != null && cache.prepareStacks != null && cache.prepareStacks.size() > 100
                    && cache.prepareStart != null) {
                if (Util.getEpochMillis() - cache.prepareStart < 100) return Collections.emptyList();
                int prepareStageCurrent = cache.currentStep.step;
                int prepareStageTotal = cache.currentStep.totalSteps;
                ArgumentCache.CurrentStep.Step currentStage = ArrayUtils.get(cache.currentStep.steps, prepareStageCurrent - 1);
                int currentStageCurrent = currentStage == null ? 0 : currentStage.stacks;
                int currentStageTotal = currentStage == null ? 0 : currentStage.totalStacks;
                double prepareStageProgress = prepareStageTotal == 0 ? 0 : prepareStageCurrent / (double) prepareStageTotal;
                double currentStageProgress = currentStageTotal == 0 ? 0 : currentStageCurrent / (double) currentStageTotal;
                double lastProcess = prepareStageTotal == 0 ? 0 : Math.max(0, prepareStageProgress - (1 - currentStageProgress) / prepareStageTotal);
                if (lastProcess < 0.05 || lastProcess > 0.95) return Collections.emptyList();
                this.lastProcess = lastProcess;
                return ImmutableList.of(Component.translatable("text.rei.caching.search"),
                        Component.translatable("text.rei.caching.search.step", prepareStageCurrent, prepareStageTotal, Math.round(lastProcess * 100)));
            }
        } catch (NullPointerException ignored) {
        }
        return Collections.emptyList();
    }

@Override
    public List<Component> provide() {
        lastProcess = null;
        try {
            AsyncSearchManager searchManager = EntryListSearchManager.INSTANCE.getSearchManager();
            if (searchManager.executor != null) {
                if (searchManager.executor.future().isDone()) return Collections.emptyList();
                if (searchManager.executor.future().isCancelled()) return Collections.emptyList();
                if (searchManager.executor.future().isCompletedExceptionally()) return Collections.emptyList();
                AsyncSearchManager.Steps steps = searchManager.executor.steps();
                if (steps.startTime == 0 || steps.totalPartitions == 0) return Collections.emptyList();
                if (Util.getEpochMillis() - steps.startTime < 1000) return Collections.emptyList();
                lastProcess = steps.partitionsDone.get() / (double) steps.totalPartitions;
                return ImmutableList.of(Component.translatable("text.rei.searching"),
                        Component.translatable("text.rei.searching.step", Math.round(lastProcess * 100)));
            }
        } catch (NullPointerException ignored) {
        }
        return Collections.emptyList();
    }

@Override
    public Screen get() {
        T config = manager.getConfig();
        T defaults = manager.getSerializer().createDefault();

        String i18n = i18nFunction.apply(manager);

        ConfigBuilder builder = ConfigBuilder.create().setParentScreen(parent).setTitle(Component.translatable(String.format("%s.title", i18n))).setSavingRunnable(manager::save);

        Class<T> configClass = manager.getConfigClass();

        if (configClass.isAnnotationPresent(Config.Gui.Background.class)) {
            String bg = configClass.getAnnotation(Config.Gui.Background.class).value();
            ResourceLocation bgId = ResourceLocation.tryParse(bg);
            if (TRANSPARENT_BACKGROUND.equals(bgId))
                builder.transparentBackground();
            else
                builder.setDefaultBackgroundTexture(bgId);
        }

        Map<String, ResourceLocation> categoryBackgrounds =
                Arrays.stream(configClass.getAnnotationsByType(Config.Gui.CategoryBackground.class))
                        .collect(
                                toMap(
                                        Config.Gui.CategoryBackground::category,
                                        ann -> new ResourceLocation(ann.background())
                                )
                        );

        Arrays.stream(configClass.getDeclaredFields())
                .collect(
                        groupingBy(
                                field -> getOrCreateCategoryForField(field, builder, categoryBackgrounds, i18n),
                                LinkedHashMap::new,
                                toList()
                        )
                )
                .forEach(
                        (key, value) -> value.forEach(
                                field -> {
                                    String optionI13n = optionFunction.apply(i18n, field);
                                    registry.getAndTransform(optionI13n, field, config, defaults, registry)
                                            .forEach(key::addEntry);
                                }
                        )
                );

        return buildFunction.apply(builder);
    }

private ConfigCategory getOrCreateCategoryForField(
            Field field,
            ConfigBuilder screenBuilder,
            Map<String, ResourceLocation> backgroundMap,
            String baseI13n
    ) {
        String categoryName = "default";

        if (field.isAnnotationPresent(ConfigEntry.Category.class))
            categoryName = field.getAnnotation(ConfigEntry.Category.class).value();

        Component categoryKey = Component.translatable(categoryFunction.apply(baseI13n, categoryName));

        if (!screenBuilder.hasCategory(categoryKey)) {
            ConfigCategory category = screenBuilder.getOrCreateCategory(categoryKey);
            if (backgroundMap.containsKey(categoryName)) {
                category.setCategoryBackground(backgroundMap.get(categoryName));
            }
            return category;
        }

        return screenBuilder.getOrCreateCategory(categoryKey);
    }

